object Main extends App {
  val in = new InputReader(System.in)
  val pw = new PrintWriter(System.out)

  val MOD = 1e9.toInt + 7

  val n, k = in.next().toInt

  val mc = new ModComb(n, MOD)
  var ans = 0L

  for (i <- 1 to (k min (n-1))) {

    val ball = i
    val stick = (n-i)-1
    ans += mc.comb(n, i) * mc.comb(ball+stick, stick)
