using namespace std;
int MAX_ANS = 1000000000+7;

long pow_(long x, int n) {
	long ans = 1;
    while (n > 0) {
		if ((n & 1) == 1) {
			ans = (ans * x) % MAX_ANS;
		}
        x = (x * x) % MAX_ANS;
		n >>= 1;
	}
    return ans;
}

int main() {
    int n, k;
    cin >> n >> k;

    long ans = 1; // m=0でans=1
    long xc = 1, xh = 1, y = 1; // yは共通
    for(int m=1; m<min(n, k)+1; m++) {
        xc = (xc * (n-m+1)) % MAX_ANS;
        xh = (xh * (n-m)) % MAX_ANS;
        y = (y * pow_(m, MAX_ANS-2) ) % MAX_ANS;
        long c = (xc * y) % MAX_ANS; // nCm
        long h = (xh * y) % MAX_ANS; // n-mHm = n-1Cm
        ans = (ans + c * h) % MAX_ANS;
    }
    cout << ans << endl;
}

