int C(int n, int k) {
  return dvd(f[n], mul(f[n - k], f[k]));
}

int solve(int n, int s) {
  return C(n + s - 1, s);
}

int main() {
  ios::sync_with_stdio(0);
  cin.tie(0), cout.tie(0);

  f[0] = iv[0] = 1;
  for (int i = 1; i < N; ++i) {
    f[i] = mul(f[i - 1], i);
    iv[i] = dvd(iv[i - 1], i);
  }
  int n, k;
  cin >> n >> k;
  if (k >= n - 1) {
    cout << solve(n, n);
  } else {
    int ans = 0;
    for (int i = k; i >= 0; --i) {
      inc(ans, mul(solve(n - i, i), C(n, i)));
