int pow(int a, int b, int m)
{
	int ans=1;
	while(b)
	{
		if(b&1)
			ans=(ans*a)%m;
		b/=2;
		a=(a*a)%m;
	}
	return ans;
}

int modinv(int k)
{
	return pow(k, MOD-2, MOD);
}

void precompute()
{
	fact[0]=fact[1]=1;
	for(int i=2;i<N;i++)
	{
		fact[i]=fact[i-1]*i;
		fact[i]%=MOD;
	}
	invfact[N-1]=modinv(fact[N-1]);
	for(int i=N-2;i>=0;i--)
	{
		invfact[i]=invfact[i+1]*(i+1);
		invfact[i]%=MOD;
	}
}

int nCr(int x, int y)
{
	if(y>x)
		return 0;
	int num=fact[x];
	num*=invfact[y];
	num%=MOD;
	num*=invfact[x-y];
	num%=MOD;
	return num;
}

void solve()
{
	precompute();
	int n, k;
	cin >> n >> k;
	int ret = 0;
	int rooms = min(n - 1, k);
	for(int i = 0; i <= rooms; i++)
	{
		int nn = n;
		int kk = n - i;
		int no = nCr(n, i);
		int temp = no * nCr(nn - 1, kk - 1);
		ret += temp;
		ret %= MOD;
	}
	cout << ret << endl;
}

