ll n, k, Ans = 0, fac[N], inv[N];

inline ll power(ll a, ll b, ll res = 1) {
	for (; b; b >>= 1, a = a * a % P) 
		res = (b & 1)? res * a % P: res;
	return res;
}

inline ll C(ll n, ll m) {
	if (n < m) return 0;
	if (n == m || !m) return 1;
	return fac[n] * inv[n - m] % P * inv[m] % P;
}

