        if (k == 1) {
            ans = n * (n - 1) % mod;
        } else {
            for (int i = 0; i <= k; i++) {
               ans = (ans + Lucas(n, i, mod) * Lucas(n - 1, n - i - 1, mod) % mod) % mod;
            }
        }
    }
    printf("%lld", ans);
    return 0;
}

