long long power_mod_q(long long x, long long n, long long q)
{
    if(n == 0)
        return 1;
    if(n % 2 == 0)
        return power_mod_q((x * x) % q, n / 2, q);
    else 
        return (x * power_mod_q((x * x) % q, n / 2, q)) % q; 
}

long long inverse_mod_q(long long n, long long q)
{
    return power_mod_q(n, q-2, q);
}

vector<long long> fact(200001);

long long nCr_mod_q(long long n, long long r, long long q)
{
    return (((fact[n] * inverse_mod_q(fact[r], q)) % R) * inverse_mod_q(fact[n-r], q)) % R;
}

long long term(long long n, long long i)
{
    return (nCr_mod_q(n, i, R) * nCr_mod_q(n - 1, i, R)) % R;
}
struct dsu
{
    vector<int> rank, parent;
    dsu(int n)
    {
        rank.assign(n, 0);
        parent.resize(n);
        for(int i = 0; i < n; i++)
            parent[i] = i;
    }
    int find_set(int i)
    {
        if(i == parent[i])
            return i;
        return parent[i] = find_set(parent[i]);
    }
    bool is_same_set(int i, int j)
    {
        if(find_set(i) == find_set(j))
            return true;
        return false;
    }
    void union_set(int i, int j)
    {
        if(!is_same_set(i, j))
        {
            int u = find_set(i), v = find_set(j);
            if(rank[u] == rank[v])
            {
                parent[v] = u;
                rank[u] += 1;
            }
            else if(rank[u] > rank[v])
                parent[v] = u;
            else 
                parent[u] = v;
        }
    }

};


struct graph
{
