//nCrを1000000007で割った余りを求める。modint依存
modint nCr(ll a, ll b) {
	modint ans = 1;
	for (ll i = 0; i < b; i++) {
		ans *= a - i;
	}
	for (ll i = 1; i <= b; i++) {
		ans /= i;
	}
	return ans;
}


