const int M = 1e9 + 7;

int pw(int a, int n) {
    a %= M;
    int b = 1;
    while (n > 0) {
        if (n & 1) {
            b = b * a % M;
            n--;
        } else {
            a = a * a % M;
            n /= 2;
        }
    }
    return b;
}

int fact[200001], inv[200001];

int C(int n, int k) {
    if (k > n) return 0;
    assert(k >= 0);
    return fact[n] * inv[k] % M * inv[n - k] % M;
}

int32_t main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n, k;
    cin >> n >> k;
    fact[0] = 1;
    for (int i = 1; i <= n; i++) fact[i] = fact[i - 1] * i % M;
    for (int i = 0; i <= n; i++) inv[i] = pw(fact[i], M - 2);
    int ans = 0;
    for (int i = 1; i <= n; i++) {
        if (n - i <= k) {
            ans += C(n, i) * C(n - 1, i - 1) % M;
            if (ans >= M) ans -= M;
        }
    }
    cout << ans;
    return 0;
}

