    if(n < 0 || k < 0 || n < k) return 0;
    if(n == 0 || k == 0) return 1;
    return fact[n] * frev[k] % MOD * frev[n-k] % MOD;
}

int main(){
    ll N, K;
    cin >> N >> K;

    //in main function
    fact[0] = frev[0] = 1;
    for(int i = 1; i <= MAX_N; i++){
        fact[i] = (fact[i-1] * i) % MOD;
        frev[i] = rev(fact[i], MOD-2);
    }

    ll ans = 0;
    if(K >= N-1){
        ans = comb(2*N-1, N);
    }
    else{
        REPi(k,0,K+1){
            ans += comb(N, k) * comb(N-1, k);
            ans %= MOD;
        }
    }

    cout << ans % MOD << endl;
    return 0;
}

