        // ll q = M-q;
        inv[i] = ((M-q)*rinv)%M;
    }
}

ll modexp(ll b, ll p) {
    //invariant: C*base^pow = b^p
    ll C = 1; ll base = b, pow = p;

    while (pow>0) {
        if (pow%2==0) {
            base*=base;
            base%=M;
            pow/=2;
        } else {
            C*=base;
            C%=M;
            --pow;
        }
    }

    return C;
}

ll choose(int n, int k) {

    if (k==n) return (ll)1;
    ll num = 1;
    ll denom = 1;

    for (ll i = 1; i<=(ll)k; ++i) {
        num *= ((ll)n+1-i);
        num %= M;

        denom *= i;
        denom %= M;
    }

    ll denominv = modexp(denom,M-2);

    num *= denominv;
    num %= M;
    return num;


}
