void solve() {
	ll N,K;
	cin>>N>>K;
	if(N-1<=K){
		p(nCk(N+N-1,N-1));return;
	}

	Modint ans=0;
	for(ll i=N-K;i<=N;i++){
		ll y=i-1;
		ll x=N-i+y;		
		Modint t=nCk(x,y)*nCk(N,i);
