#include <bits/stdc++.h>

template<int N, typename T, T M>
struct factorial_mod
{
	T mod[N + 1];
	T inv_mod[N + 1];

	constexpr factorial_mod() : mod(), inv_mod()
	{
		mod[0] = 1;
		for (int i = 0; i < N; ++i)
		{
			mod[i + 1] = (mod[i] * (i + 1)) % M;
		}
		inv_mod[N] = power(mod[N], M - 2);
		for (int i = N - 1; i >= 0; --i)
		{
			inv_mod[i] = (inv_mod[i + 1] * (i + 1)) % M;
		}
	}

	constexpr T power(T a, T b) const
	{
		T r = 1;
		while (b > 0)
		{
			if ((b & 1) != 0) r = (r * a) % M;
			a = (a * a) % M;
			b >>= 1;
		}
		return r;
	}

	constexpr T comb(T n, T r) const
	{
		if (r < 0 || r > n || n < 0) return 0;
		return (((mod[n] * inv_mod[r]) % M) * inv_mod[n - r]) % M;
	}

	constexpr T H(T n, T r) const
	{
		return comb(n + r - 1, r);
	}
};

constexpr long long MOD = 1000000007;
constexpr factorial_mod<500000, long long, MOD> fmod;

int main()
{
	long long n, k;
	scanf("%lld%lld", &n, &k);
	long long zeromax = std::min(n, k);
	long long ans = 0;
	for (long long i = 1; i <= zeromax; ++i)
	{
		long long room = n - i;
		long long nn = n - room;
		ans = (ans + fmod.comb(n, room) * fmod.H(room, nn)) % MOD;
	}
	if (k >= 2)
	{
		ans = (ans + 1) % MOD;
	}
	printf("%lld\n", ans);
	return 0;
}

