    return (val * val) % MOD;
}

ll power(ll val, ll step) {
    if (step == 0) return 1ll;
    return (step % 2 == 0 ?  sqr(power(val, step / 2)) :
                             sqr(power(val, step / 2)) * val ) % MOD;
}

