    ll N, K;
    cin >> N >> K;
    combination c = combination(MAX * 2);
    mint ans = c(N + N - 1, N - 1);
    if (K >= N - 1) {
        cout << ans << '\n';
        return 0;
    }
    for (int i = N - 2; i >= K; i--) {
        int human = N - 2 - i;
        ans -= c.fact[human + 1 + N - 1] * c.ifact[N - 1] * c.ifact[human] * c.ifact[1];
    }
    cout << ans << '\n';
}

