int power(int x, int y, int p) 
{ 
    int res = 1;      // Initialize result 

    x = x % p;  // Update x if it is more than or 
                // equal to p 

    while (y > 0) 
    { 
        // If y is odd, multiply x with result 
        if (y & 1) 
            res = (res*x) % p; 

        // y must be even now 
        y = y>>1; // y = y/2 
        x = (x*x) % p; 
    } 
    return res; 
} 

// Returns n^(-1) mod p 
int modInverse(int n, int p) 
{ 
    return power(n, p-2, p); 
} 

// Returns nCr % p using Fermat's little 
// theorem. 
int nCrModPFermat(int n, int r, int p) 
{ 
   // Base case 
   if (r==0) 
      return 1; 

    // Fill factorial array so that we 
    // can find all factorial of r, n 
    // and n-r 
    int fac[n+1]; 
    fac[0] = 1; 
    for (int i=1 ; i<=n; i++) 
        fac[i] = fac[i-1]*i%p; 

    return (fac[n]* modInverse(fac[r], p) % p * 
            modInverse(fac[n-r], p) % p) % p; 
} 

void solve()
{
    int ans = 0;
    int n,k;
    cin>>n>>k;

    if ( k == 1 )
    {
        ans -= 1;
    }

    int i = 0;
    while ( (2*n-i*k-2*i-1) >= 0 && (n-i*k-i*2) >= 0 )
    {
        ans += nCrModPFermat(n,i,mod)*nCrModPFermat(2*n-i*k-2*i-1,n-i*k-i*2,mod)*((i%2==0)?1:-1);
        ans %= mod;
        i++;
    }

    cout<<ans<<endl;
}

