const ll MAX = 1000001;
const ll MOD = 1000000007;

ll fac[MAX], finv[MAX], inv[MAX];

// コンビネーションのテーブルを作る前処理
// ll COMとワンセット
void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

// 二項係数計算
ll COM(int n, int k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

int main(void){
    COMinit();
    ll n, k;
    cin >> n >> k;
    ll ans = 0;
    if (k % 2 == 0)
        ans++;
    for (ll i = 1; i < n; i++) {
        if (i > k)
            break;
        ans = (ans + COM(n, i)*COM(n-1, n-i-1)%MOD) % MOD;
    }
    cout << ans;
}

