const ll MOD = 1000000007;
using mint = Fp<MOD>;

struct combination_table {
  // i! % MOD M
  V<ll> fact;
  // (i!)^(-1) MOD M
  V<ll> finv;
  // i^(-1) MOD M
  V<ll> inv;

  ll mod;
};

// ref: http://drken1215.hatenablog.com/entry/2018/06/08/210000
combination_table prepare_combination(ll max, ll mod) {
  V<ll> fact(max + 1);
  V<ll> finv(max + 1);
  V<ll> inv(max + 1);

  fact[0] = 1;
  fact[1] = 1;
  finv[0] = 1;
  finv[1] = 1;
  inv[1] = 1;

  for (ll i = 2; i <= max; i++) {
    fact[i] = fact[i - 1] * i % mod;
    inv[i] = mod - inv[mod % i] * (mod / i) %
                       mod;  // a^(-1) ≡ -(p % a)^(-1) * (p/a) MOD p
    finv[i] = finv[i - 1] * inv[i] % mod;
  }

  combination_table res = {
      fact,
      finv,
      inv,
      mod,
  };

  return res;
}

ll c_m(ll n, ll k, combination_table& ct) {
  if (n < k) return 0;
  if (n < 0 || k < 0) return 0;
  return ct.fact[n] * (ct.finv[k] * ct.finv[n - k] % ct.mod) % ct.mod;
}

void solve() {
  ll N, K;
  cin >> N >> K;

  mint res = 0;
  auto ct = prepare_combination(2 * N, MOD);

  if (K >= N) {
    ll res = c_m(N + (N - 1), N, ct);
    drop(res);
  }

  if (K == 1) {
    ll res = N * (N - 1);
    drop(res);
  }

  ll max_v = min(N - 1, K);

  rep(rest, max_v + 1) {
    ll non_zero_ct = N - rest;
    ll zero_ct = N - non_zero_ct;
    ll _res = c_m(rest + (non_zero_ct - 1), rest, ct) * c_m(N, zero_ct, ct);
    res += _res;
  }

  cout << res << endl;
}

