ll nCr(vl &f, ll n, ll r) {
  if (n < r)
    return 0LL;
  if (r > n / 2LL)
    r = n - r;
  ll res = (f[n] * MODPOW(f[n - r], MOD - 2LL)) % MOD;
  res = (res * MODPOW(f[r], MOD - 2LL)) % MOD;
  return res;
}
ll nHr(vl &f, ll n, ll m) { return nCr(f, n + m - 1, m); }

