int addMod(int a, int b) {
    a += b;
    if (a >= mod)
        a -= mod;
    return a;
}

int divMod(int n, int d) { return (1ll * n * modInv(d)) % mod; }

int choose(int n, int k) { return (1ll * f[n] * modInv((1ll * f[k] * f[n - k]) % mod)) % mod; }

int dist(int n, int r) { return choose(n + r - 1, r - 1); }

