int mul(int a, int b) {
  return a * (ll) b % mod;
}

int pw(int a, int b) {
  int r = 1;
  while (b) {
    if (b & 1) r = mul(r, a);
    a = mul(a, a);
    b /= 2;
  }
  return r;
}

int dv(int a, int b) {
  return mul(a, pw(b, mod - 2));
}

int f(int a, int b) {
  int r = 1;
  for (int i = a; i <= b; i++)
    r = mul(r, i);
  return r;
}

int co(int n, int a) {
  int up = f(n - a + 1, n), down = f(1, a);
  return dv(up, down);
}

