constexpr int64_t MOD = 1e9 + 7;

int64_t MODpow(int64_t n, int64_t m) {
    int64_t result = 1;
    while (m) {
        if (m % 2 == 1) {
            result *= n;
            result %= MOD;
        }

        m /= 2;
        n *= n;
        n %= MOD;
    }

    return result;
}

class Combination {
public:
    Combination(int64_t max_num, int64_t mod) {
        fact_.resize(max_num + 1, 1);
        inv_fact_.resize(max_num + 1, 1);
        mod_ = mod;
        for (int64_t i = 2; i <= max_num; i++) {
            fact_[i] = i * fact_[i - 1] % mod_;
            inv_fact_[i] = MODpow(fact_[i], mod_ - 2);
            assert(fact_[i] * inv_fact_[i] % mod_ == 1);
        }
    }
    int64_t operator()(int64_t n, int64_t m) const {
        if (m < 0 || m > n) return 0;
        return fact_[n] * inv_fact_[n - m] % mod_ * inv_fact_[m] % mod_;
    }
private:
    int64_t MODpow(int64_t n, int64_t m) const {
        int64_t result = 1;
        while (m) {
            if (m % 2 == 1) {
                result *= n;
                result %= mod_;
            }

            m /= 2;
            n *= n;
            n %= mod_;
        }

        return result;
    }

    vector<int64_t> fact_, inv_fact_;
    int64_t mod_;
};

int main() {
    int64_t n, k;
    cin >> n >> k;

    Combination comb(n, MOD);
    int64_t ans = 0;
    for (int64_t i = 0; i < min(n, k + 1); i++) {
        //0人となる部屋がi個である場合の数を計算
        //0人となる部屋の選び方 -> n_C_i
        //i人がn - iの部屋のどこかへ移動 -> {n - 1}_C_{i}
        (ans += comb(n, i) * comb(n - 1, i) % MOD) %= MOD;
    }

    cout << ans << endl;
}

