ll fac[N],infac[N];

ll me(ll a,ll b)
{
	ll res=1;

	while(b)
	{
		if(b&1)
		res=(res*a)%mod;

		a=(a*a)%mod;

		b>>=1;
	}

	return res;
}

ll mi(ll n)
{
	return me(n,mod-2);
}

void factorial()
{
	fac[0]=1;

	for(ll i=1;i<N;i++)
	fac[i]=(i*fac[i-1])%mod;

	//modular inverse factorial array in O(logn+n)=O(n) time

	infac[N-1]=mi(fac[N-1]); //O(logn)

	for(ll i=N-1;i>0;i--)
	infac[i-1]=(i*infac[i])%mod;
}

ll ncr(int n,int r)
{
	if(n<r)
	return 0;

	ll res=fac[n];

	res=(res*infac[r])%mod;

	res=(res*infac[n-r])%mod;

	return res;
}

int main()
{
	factorial();

	int n,k; scn(n); scn(k); k = min(k,n-1);

	ll ans = 0;

	for(int zeroes = 0;zeroes <= k;zeroes++)
	{
		ll here = ncr(n,zeroes);

		int balls = n, boxes = n-zeroes;

		//no. of positive solutions
		ll temp = ncr(balls-1,boxes-1);

		here = (here*temp)%mod;

		ans = (ans+here)%mod;
	}

	lpri(ans);

	return 0;
}

