	template <typename T>
	std::vector<T> Factorize2Vector(T x) {
		if (x <= 1) return std::vector<T>();
		std::vector<T> r; T x0 = x;
		while (x % 2 == 0)
			x /= 2, r.push_back(2);
		for (long long f = 3; f * f <= x0; f += 2)
			while (x % f == 0)
				x /= f, r.push_back(f);
		if (x > 1) r.push_back(x);
		return r;
	}
	template<typename T>
	std::map<T, T> Factorize2Map(T x) {
		if (x <= 1) return std::map<T, T>();
		std::map<T, T> mp;
		for (T i = 2; i * i <= x; ++i) {
			while (x % i == 0) {
				x /= i;
				mp[i]++;
			}
		}
		if (x != 1) {
			mp[x]++;
		}
		return mp;
	}

