using namespace std;

class Solution {
public:
    int solve(int n, int K) {
        const int MOD = 1e9 + 7;
        auto norm = [&](long long a) {
            a %= MOD;
            if (a < 0) {
                a += MOD;
            }
            if (a >= MOD) {
                a -= MOD;
            }
            return a;
        };

        auto power = [&](long long x, long long e) {
            long long res = 1;
            while (e > 0) {
                if (e & 1) {
                    res = (res * x) % MOD;
                }
                e >>= 1;
                x = (x * x) % MOD;
            } 
            return res;
        };
        auto inverse = [&](long long a) {
            long long b = MOD;
            long long u = 0, v = 1;
            a = norm(a);
            while (a != 0) {    
                long long d = b / a;
                b -= d * a;
                u -= d * v;
                swap(a, b);
                swap(u, v);
            }

            u = norm(u);
            return u;
        };

        const int N = n + 100;
        vector<long long> F(N + 1, 1);
        vector<long long> IF(N + 1, 1);
        for (int i = 1; i <= N; ++i) {
            F[i] = F[i - 1] * i % MOD;
        }
        IF[N] = inverse(F[N]);
        for (int i = N - 1; i > 0; --i) {
            IF[i] = IF[i + 1] * (i + 1) % MOD;
        }

        auto nCr = [&](int n, int r) -> long long {
            long long res = F[n] * IF[r] % MOD * IF[n - r] % MOD;
            return res;
        };

        auto ok = [&](int m) {
            if (n - m <= K) {
                return true;
            }
            return false;
        };

        long long res = 0;
        for (int i = 1; i <= n; ++i) {
            if (ok(i)) {
                res += (nCr(n, i) * nCr(n - 1, i - 1)) % MOD;
                res %= MOD; 
            }
        }
        return res;
    }
};

int main(int argc, char** argv) {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n, k;
    cin >> n >> k;
    Solution sol;

    cout << sol.solve(n, k) << "\n";

    return 0;
}

