typedef long long ll;
ll MOD = 1000000007LL;
ll inv(ll K) {
  ll A = MOD - 2;
  ll ret = 1;
  ll D = K;
  while (A > 0) {
    if (A % 2 == 1) {
      ret = (ret * D) % MOD;
    }
    D = (D * D) % MOD;
    A /= 2;
  }
  return ret;
}
ll FC[400005];
ll IFC[400005];
ll initFC(int N) {
  FC[0] = 1;
  for (ll i=1; i<=N; i++) {
    FC[i] = (FC[i-1] * i) % MOD;
  }
  IFC[N] = inv(FC[N]);
  for (ll i=N; i>=0; i--) {
    IFC[i-1] = (IFC[i] * i) % MOD;
  }
}

ll combFC(ll N, ll K) {
  ll ret = (FC[N] * IFC[K]) % MOD;
  ret = (ret * IFC[N-K]) % MOD;
  return ret;
}

ll modSum(ll& N, ll B) {
  N = (N + B % MOD + MOD) % MOD;
}
