const int mod = 1e9 + 7;

int solve(int n, int size, int zero_cnt, vector<vector<vector<int>>> &memo) {
  if (size == 1) {
    return n != 0 || zero_cnt > 0 ? 1 : 0;
  } else if (size - n > zero_cnt) {
    return 0;
  }

  if (memo[n][size][zero_cnt] < 0) {
    int ans = 0;
    for (int i = (zero_cnt > 0 ? 0 : 1); i <= n; i++) {
      ans = (ans + (solve(n - i, size - 1, i == 0 ? zero_cnt - 1 : zero_cnt, memo) % mod)) % mod;
    }

    memo[n][size][zero_cnt] = ans;
  }

  return memo[n][size][zero_cnt];
}

