#include<bits/stdc++.h>
using namespace std;
typedef long long LL;
const LL M = 200020;
LL f[M];
LL exgcd(LL a, LL b, LL& x, LL& y){
    LL d = a;
    if(b != 0){
        d = exgcd(b, a % b, y, x);
        y -= (a / b) * x;
    }
    else{
        x = 1; y = 0;
    }
    return d;
}
LL inv(LL a, LL P){
    LL x, y;
    exgcd(a, P, x, y);
    return (P + x % P) % P;
}
void calc_factorial(int P){
    // 预处理阶乘
    f[1] = 1; // m 为组合数中x的最大值
    for(LL i = 2; i < M; i++){
        f[i] = i* f[i - 1];
        f[i] %= P;
    }
    return ;
}
LL mod_fact(LL x, LL& e, LL P){
    // 计算阶乘逆元
    e = 0;
    if(x == 0) return 1;
    LL res = mod_fact(x / P, e, P);
    e += x / P;
    if(x / P % 2 != 0) return res * (P - f[x % P]) % P;
    return res * f[x % P] % P;
}
LL mod_comb(LL x, LL k, LL P){
    if(x < 0 || k < 0 || x < k) return 0;
    LL e1, e2, e3;
    LL a1 = mod_fact(x, e1, P);
    LL a2 = mod_fact(k, e2, P);
    LL a3 = mod_fact(x - k, e3, P);
    if(e1 > e2 + e3) return 0;
    return a1 * inv(a2 * a3 % P, P) % P;
}
const LL P = 1E9 + 7;
LL n, k;
LL quickpow(LL a, LL b, LL c){
    LL ans = 1LL;
    while(b > 0){
        if(b & 1LL) ans = (ans * a) % c;
        a = (a * a) % c;
        b >>= 1LL;
    }
    return ans;
}
void solve(){
    calc_factorial(P);
    LL ans = 1LL;
    for(LL i = 1; i <= k; i++){
        ans = (ans + mod_comb(n - 1, n - i - 1, P) * mod_comb(n, i, P)) % P;
    }
    cout<<ans<<endl;
    return ;
}
int main(){

    cin>>n>>k;
    k = min(n - 1, k);
    solve();
    return 0;
}

