//mod逆元を使ったnCkの計算(速)
const int64_t MAX = 510000;
const int64_t MOD = 1000000007;

int64_t fac[MAX], finv[MAX], inv[MAX];

// テーブルを作る前処理
void COMinit() {
  fac[0] = fac[1] = 1;
  finv[0] = finv[1] = 1;
  inv[1] = 1;
  for (int i = 2; i < MAX; i++){
    fac[i] = fac[i - 1] * i % MOD;
    inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
    finv[i] = finv[i - 1] * inv[i] % MOD;
  }
}

// 二項係数計算
int64_t COM(int64_t n, int64_t k){
  if (n < k) return 0;
  if (n < 0 || k < 0) return 0;
  return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}


int main(){
  int N, K;
  cin >> N >> K;
  int64_t ans = 0;
  COMinit();
  if(K == 1){
    ans = N*(N-1);
    ans %= MOD;
  }
  else if(K >= N-1){
    ans = COM(2*N-1,N);
  }
  else{
    for(int i=K+1; i<N; i++){
      ans += COM(N,i)*COM(N-1,N-i-1);
      ans %= MOD;
    }
    ans = COM(2*N-1,N) - ans;
    if(ans < 0){
      ans += MOD;
    }
    ans %= MOD;
  }
  cout << ans << endl;
}

