	Factorial f(n);
	ll sum = 0;
	rep(i, min(k,n)+1) {
		ll nci = f.cmb(n, i) % mod;
		ll take = f.cmb(n - 1, n - i - 1) % mod;
		sum += nci * take;
		sum %= mod;
	}
	cout << sum << endl;
	return 0;
}

