int64_t modpow(int64_t a, int64_t b, int64_t MOD) {
	int64_t ret = 1;
	while (b > 0) {
		if (b & 1) { (ret *= a) %= MOD; }
		(a *= a) %= MOD;
		b >>= 1;
	}
	return ret % MOD;
}

const Int MOD = 1e9 + 7;
Int func(Int a, Int b) {
	Int x = 1, y = 1;
	b = min(b, a - b);
	for (Int i = 0; i < b; ++i) {
		(x *= (a - i)) %= MOD;
	}
	for (Int i = 1; i <= b; ++i) {
		(y *= i) %= MOD;
	}
	Int ret = (x * modpow(y, MOD - 2, MOD)) % MOD;
	return ret;
}

