typedef int64_t I;
const I M = 1000000007;

I inv(I a, I b) {
  I x0 = 1, y0 = 0, x1 = 0, y1 = 1;
  while (b != 0) {
    I q = a / b, nb = a % b;
    a = b;
    b = nb;
    I nx1 = x0 - q * x1, ny1 = y0 - q * y1;
    x0 = x1;
    x1 = nx1;
    y0 = y1;
    y1 = ny1;
  }
  while (x0 < 0) {
    x0 += M;
  }
  return x0;
}

I comb(I n, I k) {
  I r1 = 1;
  I r2 = 1;
  for (I i = 0; i < k; i++) {
    r1 = (r1 * (n - i)) % M;
    r2 = (r2 * (i + 1)) % M;
  }
  return (r1 * inv(r2, M)) % M;
}

I h(I n, I k) {
  return comb(n + k - 1, k);
}

I solve(I n, I k) {
  if (k >= n) return h(n, n);
  I r = 0;
  for (I i = 0; i < k + 1; i++) {
    r = (r + comb(n, i) * h(n - i, i)) % M;
  }
  while (r < 0) {
    r += M;
  }
  return r;
}

int main() {
  I n, k;
  cin >> n >> k;
  cout << solve(n, k) << endl;
}

