    }
}

int64_t comb(int n, int k) {
    int64_t c = 1;
    for (int i = 1; i <= k; ++i) {
        c = (((n - i + 1) * inv(i)) % M * c) % M;
    }
    return c;
}

int64_t H(int64_t n, int64_t m) {
    return comb(n - 1 + m, m);
}

