const long long MOD = (long long)1e9 + 7;

int n, k;
long long fac[400009], ans;

long long quickpow(long long b, int e)
{
	return e ? ((e & 1 ? b : 1)*quickpow(((b%MOD)*(b%MOD)) % MOD, e >> 1)) % MOD : 1;
}

long long fun(int a, int b)
{
	long long ret = fac[b];
	ret *= quickpow(fac[a], MOD - 2);
	ret %= MOD;
	ret *= quickpow(fac[b - a], MOD - 2);
	ret %= MOD;
	return ret;
}

int main()
{
	ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);
	fac[0] = 1;
	for (int i = 1; i <= 400000; i++) {
		fac[i] = i * fac[i - 1];
		fac[i] %= MOD;
	}
	cin >> n >> k;
	if (k >= n - 1) {
		ans = fun(n, n + n - 1);
	}
	else {
		for (int i = 0; i <= k; i++) {
			//if ((k - i) % 2 && i == 1) continue;
			long long tmp = fun(i, n);
			tmp *= fun(i, n - 1);
			tmp %= MOD;
			ans += tmp;
			ans %= MOD;
		}
	}
	cout << ans << E;
	//system("pause");
	return 0;
}

