const long long MOD = 1e9 + 7;
typedef pair<int, int> P;

const int MAX = 1000001;
long long fac[MAX], finv[MAX], inv[MAX];

// テーブルを作る前処理
void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

// 二項係数計算
long long COM(int n, int k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

int main()
{
    ll N, K;
    cin >> N >> K;

    COMinit();

    ll ans = COM(N + N - 1, N - 1);
    repd(i, K + 1, N) {
        ans -= COM(N, i) * COM(N - i - 1 + i, N - i - 1);
    }

    if (K % 2) ans--;
    if (ans < 0) ans += MOD;
    cout << ans << endl;
    return 0;
}

#include<bits/stdc++.h>
