using namespace std;
typedef long long LL;
const int INF = 0x3f3f3f3f;
const int MOD = 1e9 + 7;
const int maxn = 2e5 + 10;
int n, k;
LL fact[maxn], fact_inv[maxn];
LL qpow(LL a, LL b)
{
    LL res = 1;
    a %= MOD;
    while(b)
    {
        if(b & 1)
            res = res * a % MOD;
        a = a * a % MOD;
        b >>= 1;
    }
    return res;
}
void preprocess()
{
    fact[0] = 1;
    for(int i = 1; i < maxn; i++)
        fact[i] = fact[i-1] * i % MOD;
    fact_inv[maxn-1] = qpow(fact[maxn-1], MOD - 2);
    for(int i = maxn - 2; i >= 0; i--)
        fact_inv[i] = fact_inv[i+1] * (i + 1) % MOD;
}
LL comb(int m, int n)   // n选m
{
    return fact[n] * fact_inv[m] % MOD * fact_inv[n-m] % MOD;
}
int main()
{
    preprocess();
    scanf("%d %d", &n, &k);
    LL ans = 0;
    for(int i = 0; i <= min(n - 1, k); i++)
        ans = (ans + comb(i, n) * comb(n - i - 1, n - 1) % MOD) % MOD;
    printf("%lld\n", ans);
    return 0;
}

