const ll mod = 1000000007;

ll n, k;

ll ans[MAX];

ll fac[MAX], finv[MAX], inv[MAX];

void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % mod;
        inv[i] = mod - inv[mod%i] * (mod / i) % mod;
        finv[i] = finv[i - 1] * inv[i] % mod;
    }
}

ll rui(ll a, ll b){
    ll ans=1;
    while (b > 0) {
        if(b & 1) ans = ans * a % mod;
        a = a * a % mod ;
        b /= 2;
    }
    return ans;
}


ll comb(int n, int k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % mod) % mod;
}

void solve() {

    ans[0] = 1;
    ans[1] = (n * (n - 1)) % mod;
    ans[2] = (1 + n * (n - 1) + comb(n, 2) * comb(n - 1, n - 3)) % mod;
    for (int i = 2; i < n - 1; i++) {
        ans[i + 1] = (ans[i] + comb(n, i + 1) * comb(n - 1, n - i - 2)) % mod;
    }

    if (n <= k) printf("%lld\n", ans[n - 1]);
    else printf("%lld\n", ans[k]);
}

