        cout << com(n + (n - 1), n - 1) << endl;
        return;
    }

    // 最初0の個数0
    // k回の移動で最大k個0にできる
    mint ans = 0;
    rep(i, k + 1) { // 0の個数
        // n-i個非0
        // n個の○とn-i-1個の仕切り, ただし0個の場所なし
        int x = n - (n - i); // 先に各場所に1つ配る
        ans += com(x + (n - i - 1), x) * com(n, i); // 0の場所の選び方も忘れずに
    }
    cout << ans << endl;
}

