int N, K;

ll cpow (ll b, int e)
{
    if (e == 1) return b % MOD;
    if (e == 0) return 1;

    ll v = cpow (b, e / 2);
    v = (v * v) % MOD;
    if (e & 1) v = (v * b) % MOD;
    return v;
}

ll inv (ll b)
{
    return cpow (b, MOD - 2);
}

ll fac[200100];
ll ifac[200100];

int main()
{
    ios_base::sync_with_stdio(0);

    cin >> N >> K;
    K = min (K, N - 1);

    fac[0] = 1;
    for (int i = 1; i <= N; i++)
        fac[i] = (fac[i-1] * i) % MOD;
    ifac[N] = inv (fac[N]);
    for (int i = N - 1; i >= 0; i--)
    {
        ifac[i] = (ifac[i+1] * (i + 1)) % MOD;
    }

    ll ans = 0;
    for (int i = N - K; i <= N; i++)
    {
        // N choose i * (N - 1) choose i - 1
        ll res = fac[N] * ifac[i];
        res = ((res % MOD) * ifac[N-i]) % MOD;
        ll res2 = (fac[N-1] * ifac[i-1]) % MOD;
        res2 = (res2 * ifac[N-i]) % MOD;
        ans += (res * res2) % MOD;
    }
    cout << ans % MOD << "\n";
}

