int nck(int n, int k) {
    int num = 1, den = 1;
    for (int i = 0; i < k; i++) {
        num = (num * (n - i)) % HELL;
        den = (den * (i + 1)) % HELL;
    }
    return (num * fastpow(den, HELL - 2, HELL)) % HELL;
}

