int egcd(int a, int b, int &x, int &y) {
	if (a == 0) {
		x = 0;
		y = 1;
		return b;
	}
	int x1, y1;
	int g = egcd(b % a, a, x1, y1);
	x = y1 - (b / a) * x1;
	y = x1;
	return g;
}

int mod_inverse(int a, int m) {
	int x, y;
	int g = egcd(a, m, x, y);
	return g != 1 ? -1 : (x % m + m) % m;
}

int cnk(int n, int k) {
	int res = 1;
	for (int i = n - k + 1; i <= n; ++i)
		res = (res * 1ll * i) % mod;
	for (int i = 2; i <= k; ++i)
		res = res * 1ll * mod_inverse(i, mod) % mod;
	return res;
}

