	modint<P> ans = 0;
	make_table<P>(200000);
	for (int i = 0; i <= std::min(k, n - 1); i++) {
		ans += combination<P>(n, i) * combination<P>(i + n - i - 1, n - i - 1);
	}
	std::cout << ans << '\n';
}

