void build_factorial_table(int N) {
   F[0] = 1;
   for (int i = 1; i <= N; ++i)
      F[i] = (F[i-1] * 1LL * i) % MOD;
}

int inv[MAXN+4]; 
int invF[MAXN+4];
void build_inverse_factorial_table(int N) {
   inv[0]  = inv[1] = 1;
   invF[0] = invF[1] = 1;
   for (int i = 2; i <= N; ++i) {
      inv[i] = (MOD - (MOD / i) * 1LL * inv[MOD % i] % MOD) % MOD;
      invF[i] = (invF[i-1] * 1LL * inv[i]) % MOD;
   }
}

int nCk(int n, int k) {
   if (n < 0 || k < 0 || k > n)  // invalid n or k
      return 0;
   long long res = F[n];
   res = (res * invF[k]) % MOD;
   res = (res * invF[n-k]) % MOD;
   return res;
}


