signed main(){
    int START_TIME = clock();
    cin.tie(nullptr);
    ios::sync_with_stdio(false);   //cin cout 高速化
//    cout << fixed << setprecision(15);

    i32 n,k; cin >> n >> k;
    nCr comb(510000, mod);

    mint ans = 0;

    for(i32 i = 0; i <= min(n-1, k); ++i) {
        mint tmp = 1;
        // nCiをかける。0になるiこの部屋を決める。
        tmp *= comb.calc(n, i);
        // n-iHiをかける。0にならない残りn-i個のに、0になる部屋から来た1を振り分ける->重複組み合わせ
        tmp *= comb.calc(n-i+i-1, n-i-1);
        ans += tmp;
    }

    cout << ans << '\n';

    // printf("ExecutionTime: %d /ms\n",1000*(int)((clock()-START_TIME)/CLOCKS_PER_SEC));
}

