		empty_memo[0] = 1;
		for (int i = 1; i <= K; i++)
		{
			human_memo[i] = human_memo[i - 1] * (N - i) % INV * Modinv(i) % INV;
			human_memo[i] %= INV;
			empty_memo[i] = empty_memo[i - 1] * (N + 1 - i) % INV * Modinv(i) % INV;
