  K = min(N, K);
  fact[0] = 1;
  invfact[0] = 1;
  repi(i, 1, N + 1) {
    fact[i] = fact[i - 1] * i % MOD;
    invfact[i] = invfact[i - 1] * powMod(i, MOD - 2) % MOD;
  }

  ll ans = 0;
  // ゼロが入る位置の組み合わせを数え上げる
  // nCm * (n-m)Hm = nCm * (n - m + m - 1)Cm = nCm * (n-1)Cm
  // via xHy = (x + y - 1)Cy
  rep(i, K + 1) {
    ll tmp = combMod(N, i) * combMod(N - 1, i) % MOD;
    ans = (ans + tmp) % MOD;
  }

