    {
        c1 = (c1 * (n - i + 1)) % mod;
        c2 = c2 * i % mod;
    }
    return c1 * qpow(c2,mod-2) % mod;
}

ll c1[N],c2[N];

ll a[N],b[N];

void init1(int n)
{
    a[0] = 1;
    b[0] = 1;
    for (int i = 1;i<=n;i++)
    {
        a[i] = a[i-1] * i % mod;
        b[i] = qpow(a[i],mod-2);
    }
}

void init(ll *t,int n)
{
    t[0] = 1;
    for (int i = 1;i<=n;i++)
        t[i] = a[n] * b[i] % mod * b[n - i] % mod;
}

int main()
{
    ll n,m;
    cin>>n>>m;
    ll ans = 0;
    m = min(m,200000LL);
    init1(n);
    init(c2,n-1);
    init(c1,n);

    for (int i = 0;i<=m;i++) 
    {
        // ans = (ans + C(n-1,i) * C(n,n-i) % mod) % mod;
        ans = (ans + c2[i] * c1[n-i] % mod) % mod;
    }
    cout<<ans;
    return 0;
}

