vector<bool> binaryBackwards(ll n) {
    // returns binary representation of the vector backwards
    vector<bool> ans;
    while (n > 0) {
        ans.push_back(n%2);
        n /= 2;
    }
    return ans;
}

ll emod(ll base, ll exponent) {
    vector<bool> bb = binaryBackwards(exponent);
    ll ans = 1;
    ll bp = base % mod;
    for (int i = 0; i < bb.size(); i++) {
        if (bb[i]) {
            ans *= bp;
            ans %= mod;
        }
        bp = (bp * bp) % mod;
    }
    return ans;
}


