vector<int> mf(N, -1);

int modfact(int n) {
  if (mf[n] != -1) return mf[n];
  if (n == 0) return mf[0] = 1;
  return mf[n] = (ll)n * modfact(n-1) % MOD;
}

int modinv(int a) {
  int b = MOD, u = 1, v = 0;
  while (b) {
    int t = a / b;
    a -= t * b; swap(a, b);
    u -= t * v; swap(u, v);
  }
  u %= MOD;
  if (u < 0) u += MOD;
  return u;
}

vector<int> mif(N, -1);

int modinvfact(int n) {
  if (mif[n] != -1) return mif[n];
  if (n == 0) return mif[0] = 1;
  return mif[n] = (ll)modinv(n) * modinvfact(n-1) % MOD;
}

int modcomb(int n, int k) {
  return (ll)modfact(n) * modinvfact(k) % MOD * modinvfact(n-k) % MOD;
}

int f(int k) {
  if (k >= n) return f(n-1);
  if (k == 0) return 1;
  int res = (ll)modcomb(n, k) * modcomb(n-1, k) % MOD;
  res = (res + f(k-1)) % MOD;
  return res;
}

