int fac[maxn];
int Pow(int a,int n) {
	int ret = 1 , base = a;
	while(n) {
		if(n&1)	ret = Val(ret * base);
		base = Val(base * base);
		n >>= 1;
	}
	return ret;
}
int inv(int val) {
	return Pow(val,Mod-2);
}
int C(int n,int m) {
	return Val(Val(fac[n]*inv(fac[m]))*inv(fac[n-m]));
}
