#define WARU 1000000007
using namespace std;
using ll=long long;
ll RepeatSquare(ll x,ll y,ll mod){
    if(y==0) return 1;
    if(y%2==0){
        ll a=RepeatSquare(x,y/2,mod);
        return a*a%mod;
    }
    if(y%2==1){
        return x*RepeatSquare(x,y-1,mod)%mod;
    }
}

int main(){
    ll n,k;
    cin >> n >> k;
    ll answer=0;
    if(k>n-1) k=n-1;
    ll com0,com1;
    rp(i,k+1){
        if(i==0) {
            com0=1; com1=1;
            answer += 1;
            continue;
        }
        com0 *= n+1-i; com1 *= n-i;
        com0 %= WARU; com1 %=WARU;
        com0 *= RepeatSquare(i,WARU-2,WARU);
        com1 *= RepeatSquare(i,WARU-2,WARU);
        com0 %=WARU; com1 %= WARU;
        answer += com0 * com1;
        answer %= WARU;
    }
    cout << answer << endl;
    return 0;
}

