using namespace::std;

typedef long long LL;
const int MOD = 1e9 + 7;

LL pot(int base,int exp){
	if(exp == 1)
		return base;
	if(exp % 2 == 0){
		LL aux = pot(base,exp / 2);
		return aux * aux % MOD;
	}
	return pot(base,exp - 1) * base % MOD;
}

// long long fact(int ini,int fin){
// 	LL r = 1;
// 	while(ini <= fin)
// 		r = r * ini++ % MOD;
// 	return r;
// }

LL C(int N,int K,std::vector<LL> &F){
	return F[N] * pot(F[K],MOD - 2) % MOD * pot(F[N - K],MOD - 2) % MOD;
}

int main(){
	ios_base::sync_with_stdio(0);
	cin.tie(0); cout.tie(0);

	// freopen("milkvisits.in","r",stdin);
	// freopen("milkvisits.out","w",stdout);

	int N,K;
	cin >> N >> K;

	K = min(K,N - 1);

	std::vector<LL> F(N + 1);
	F[0] = 1;
	for(int i = 1;i <= N;i++)
		F[i] = F[i - 1] * i % MOD;

	long long sol = 0;
	for(int i = N - K;i <= N;i++){
		sol += C(N,i,F) * C(N - 1,i - 1,F) % MOD;
		sol %= MOD;
	}

	cout << sol << '\n';

	return 0;
}

