s64 mypow(s64 x, s64 n)
{
    s64 ret = 1;
    while (n)
    {
        if (n & 1) ret = (ret * x) % MOD;
        x = (x * x) % MOD;
        n >>= 1;
    }
    return ret;
}

void init()
{
    fac[0] = finv[0] = 1;
    rep (i, N)
    {
        fac[i + 1] = (fac[i] * (i + 1)) % MOD;
    }
    finv[N] = mypow(fac[N], MOD - 2);
    for (int i = N; i > 0; --i)
    {
        finv[i - 1] = (finv[i] * i) % MOD;
    }    
}

s64 com(s64 n, s64 r)
{
    if (n < r || n < 0 || r < 0) return 0;
    return fac[n] * finv[n - r] % MOD * finv[r] % MOD;
}

