const long MOD = 1000000007;

long mult(long a, long b) {
    return a * b % MOD;
}

long power(long a, long b) {
    long res = 1;
    while (b > 0) {
        if (b & 1) res = mult(res, a);
        a = mult(a, a);
        b /= 2;
    }
    return res;
}

long inv(long a) {
    return power(a, MOD - 2);
}

vector<long> fact, inv_fact;

long calc_c(long n, long k) {
    long res = mult(fact[n], inv_fact[n - k]);
    res = mult(res, inv_fact[k]);
    return res;
}

int main() {
    ios::sync_with_stdio(false);

    long n, k;
    cin >> n >> k;

    fact.resize(n + 1);
    inv_fact.resize(n + 1);
    fact[0] = inv_fact[0] = 1;
    for (int i = 1; i <= n; i++) {
        fact[i] = mult(fact[i - 1], i);
        inv_fact[i] = inv(fact[i]);
    }

    long res = 0;
    for (int z = 0; z < n; z++) {
        if (z > k) break;
        long s = calc_c(n, z);
        s = mult(s, calc_c(n - 1, n - z - 1));
        res += s;
        res %= MOD;
    }
//    if (res < 0) res += MOD;
    cout << res;

    return 0;
}

