    ll n, k;
    cin >> n >> k;

    k = min(n-1, k);

    vector<md> kaijo(500000);
    kaijo[0] = 1;
    for (int i = 1; i < kaijo.size(); i++) {
        kaijo[i] = kaijo[i - 1] * i;
    }

    auto nCr = [&kaijo](ll n, ll k) {
        return kaijo[n] / (kaijo[n - k] * kaijo[k]);
    };

    auto nHr = [&nCr](ll n, ll k) {
        return nCr(n + k - 1, k);
    };


    md ret = 0;
    for (int i = 0; i <= k; i++) {
        md r = 1;
        r *= nCr(n, i);
        r *= nHr(n-i, i);
        ret += r;
    }
    cout << ret.value() << endl;

    return 0;
}

