int modexp(int b, int e, int mod) {
    int a = 1;
    while (e > 0) {
        if (e & 1) a = ll(1) * a * b % mod;
        b = ll(1) * b * b % mod;
        e >>= 1;
    }
    return a;
}

int nCr(int n, int r) {
    if (n < r) return 0;
    return ll(1) * fac[n] * ifac[n - r] % MOD * ifac[r] % MOD;
}

void solve() {
