template<typename T>
struct combinatorics {
    vector<T> fac;

    combinatorics(i32 n): fac(2*n+1) {
        fac[0] = 1;
        for (i32 i = 1; i <= 2*n; i++) fac[i] = fac[i-1] * i;
    }

    T p(i32 n, i32 k) const {
        if (k < 0 || n < k) return 0;
        return fac[n] / fac[n-k];
    }

    T c(i32 n, i32 k) const {
        if (k < 0 || n < k) return 0;
        return fac[n] / (fac[k] * fac[n-k]);
    }

    T h(i32 n, i32 k) const {
        return c(n+k-1, k);
    }
};

