template<int M = 1000000007>
struct ModInt {
    int data;

    ModInt(int data) : data(data) {}

    ModInt() : data(0) {}

    inline ModInt<M> operator+(ModInt<M> const &right) const {
        int temp = data + right.data;
        return ModInt(temp > M ? temp - M : temp);
    }

    inline ModInt<M> &operator+=(ModInt<M> const &right) {
        data += right.data;
        data = data > M ? data - M : data;
        return *this;
    }

    inline ModInt<M> operator-(ModInt<M> const &right) const {
        int temp = data - right.data;
        return ModInt(temp < 0 ? temp + M : temp);
    }

    inline ModInt<M> &operator-=(ModInt<M> const &right) {
        data -= right.data;
        data = data < 0 ? data + M : data;
        return *this;
    }

    inline ModInt<M> operator*(ModInt<M> const &right) const {
        int temp = data * right.data % M;
        return ModInt(temp < 0 ? temp + M : temp);
    }

    inline ModInt<M> &operator*=(ModInt<M> const &right) {
        data = data * right.data % M;
        data = data < 0 ? data + M : data;
        return *this;
    }

    inline bool operator==(ModInt<M> const &right) const {
        return data == right.data;
    }

    inline bool operator!=(ModInt<M> const &right) const {
        return data != right.data;
    }

    inline operator int() const {
        return data;
    }
};

template<int M = 1000000007>
inline ostream &operator<<(ostream &os, const ModInt<M> mi) {
    os << mi.data;
    return os;
}

template<int M = 1000000007>
ModInt<M> powm(int a, int b) {
    ModInt<M> res = 1;
    while (b) {
        if (b & 1)res *= a;
        b >>= 1;
        a *= a;
        a %= M;
    }
    return res;
}

constexpr int mod = 1000000007;

ModInt<mod> fact[200200];
ModInt<mod> fact_inv[200200];

ModInt<mod> comb(int n, int r) {
    if (n - r > r)return comb(n, n - r);
    ModInt<mod> nn = fact[n];
    ModInt<mod> rr = fact_inv[r];
    ModInt<mod> nr = fact_inv[n - r];
    return nn * rr * nr;
}

void preCalc() {
    fact[0] = 1;
    fact_inv[0] = 1;
    for (int i = 1; i < 200200; ++i) {
        fact[i] = fact[i - 1] * ModInt<mod>(i);
        fact_inv[i] = powm(fact[i], mod - 2);
    }
}

signed main() {
    preCalc();
    int N, K;
    cin >> N >> K;
    ModInt<mod> ans = 0;
    //空き部屋がi個になる
    for (int i = 0; i <= N - 1; ++i) {
        if (i > K)break;
        int j = N - i;
        //NCi*(i+j-1)!/i!/(j-1)!
        //NCi*(N-1)Ci
        ans += comb(N, i) * comb(N - 1, i);
    }
    cout << ans << endl;
    return 0;
}

