//形式的冪級数
//https://ei1333.github.io/luzhiled/snippets/math/formal-power-series.html
template< typename T >
struct FormalPowerSeries : vector< T > {
	using vector< T >::vector;
	using P = FormalPowerSeries;
	using MULT = function< P(P, P) >;

	static MULT &get_mult() {
		static MULT mult = nullptr;
		return mult;
	}

	static void set_fft(MULT f) {
		get_mult() = f;
	}

	FormalPowerSeries(const vector< T > &v) : FormalPowerSeries(v.begin(), v.end()) {}

	P operator+(const P &r) const { return P(*this) += r; }

	P operator-(const P &r) const { return P(*this) -= r; }

	P operator*(const P &r) const { return P(*this) *= r; }

	P operator*(const T &v) const { return P(*this) *= v; }

	P operator/(const P &r) const { return P(*this) /= r; }

	P &operator+=(const P &r) {
		if(r.size() > this->size()) this->resize(r.size());
		for(int i = 0; i < r.size(); i++) (*this)[i] += r[i];
		return *this;
	}

	P &operator-=(const P &r) {
		if(r.size() > this->size()) this->resize(r.size());
		for(int i = 0; i < (int)r.size(); i++) (*this)[i] -= r[i];
		return *this;
	}

	P &operator*=(const T &v) {
		const int n = (int) this->size();
		for(int k = 0; k < n; k++) (*this)[k] *= v;
		return *this;
	}

	P &operator*=(const P &r) {
		if(this->empty() || r.empty()) {
			this->clear();
			return *this;
		}
		assert(get_mult() != nullptr);
		auto ret = get_mult()(*this, r);
		this->resize(ret.size());
		for(int k = 0; k < (int)ret.size(); k++) (*this)[k] = ret[k];
		return *this;
	}

	P operator-() const {
		P ret(this->size());
		for(int i = 0; i < this->size(); i++) ret[i] = -(*this)[i];
		return ret;
	}

	P &operator/=(const P &r) {
		return *this *= r.inverse();
	}

	P pre(int sz) const {
		return P(begin(*this), begin(*this) + min((int) this->size(), sz));
	}

	P rev() const {
		P ret(*this);
		reverse(begin(ret), end(ret));
		return ret;
	}

	P diff() const {
		const int n = (int) this->size();
		P ret(max(0, n - 1));
		for(int i = 1; i < n; i++) ret[i] = (*this)[i] * T(i);
		return ret;
	}

	P integral() const {
		const int n = (int) this->size();
		P ret(n + 1);
		ret[0] = T(0);
		for(int i = 0; i < n; i++) ret[i + 1] = (*this)[i] / T(i + 1);
	}

	// F(0) must not be 0
	P inv(int deg = -1) const {
		assert(((*this)[0]) != T(0));
		const int n = (int) this->size();
		if(deg == -1) deg = n;
		P ret({T(1) / (*this)[0]});
		for(int i = 1; i < deg; i <<= 1) {
			ret = (ret * T(2) - ret * ret * pre(i << 1)).pre(i << 1);
		}
		return ret.pre(deg);
	}

	// F(0) must be 1
	P log(int deg = -1) const {
		assert((*this)[0] == 1);
		const int n = (int) this->size();
		if(deg == -1) deg = n;
		return (this->diff() * this->inv(deg)).integral().pre(deg);
	}

	// F(0) must be 1
	P sqrt(int deg = -1) const {
		assert((*this)[0] == T(1));
		const int n = (int) this->size();
		if(deg == -1) deg = n;
		P ret({T(1)});
		T inv2 = T(1) / T(2);
		for(int i = 1; i < deg; i <<= 1) {
			ret = (ret + pre(i << 1) * ret.inv(i << 1)).pre(i << 1) * 2;
		}
		return ret.pre(deg);
	}

	// F(0) must be 0
	P exp(int deg) const {
		assert((*this)[0] == T(0));
		const int n = (int) this->size();
		P ret({T(1)}), g({T(1)});
		for(int i = 1; i < deg; i <<= 1) {
			ret = (ret * (pre(1 << i) + g) - ret.log(1 << i)).pre(1 << i);
		}
		return ret.pre(deg);
	}
};

namespace FastFourierTransform {
	using real = double;

	struct C {
		real x, y;
		C() : x(0), y(0) {}
		C(real x, real y) : x(x), y(y) {}
		inline C operator+(const C &c) const { return C(x + c.x, y + c.y); }
		inline C operator-(const C &c) const { return C(x - c.x, y - c.y); }
		inline C operator*(const C &c) const { return C(x * c.x - y * c.y, x * c.y + y * c.x); }
		inline C conj() const { return C(x, -y); }
	};

	int base = 1;
	vector< C > rts = {{0, 0},
						{1, 0}};
	vector< int > rev = {0, 1};

	void ensure_base(int nbase) {
		if(nbase <= base) return;
		rev.resize(1 << nbase);
		rts.resize(1 << nbase);
		for(int i = 0; i < (1 << nbase); i++) {
			rev[i] = (rev[i >> 1] >> 1) + ((i & 1) << (nbase - 1));
		}
		while(base < nbase) {
			real angle = M_PI * 2.0 / (1 << (base + 1));
			for(int i = 1 << (base - 1); i < (1 << base); i++) {
				rts[i << 1] = rts[i];
				real angle_i = angle * (2 * i + 1 - (1 << base));
				rts[(i << 1) + 1] = C(cos(angle_i), sin(angle_i));
			}
			++base;
		}
	}

	void fft(vector< C > &a, int n) {
		assert((n & (n - 1)) == 0);
		int zeros = __builtin_ctz(n);
		ensure_base(zeros);
		int shift = base - zeros;
		for(int i = 0; i < n; i++) {
			if(i < (rev[i] >> shift)) {
				swap(a[i], a[rev[i] >> shift]);
			}
		}
		for(int k = 1; k < n; k <<= 1) {
			for(int i = 0; i < n; i += 2 * k) {
				for(int j = 0; j < k; j++) {
					C z = a[i + j + k] * rts[j + k];
					a[i + j + k] = a[i + j] - z;
					a[i + j] = a[i + j] + z;
				}
			}
		}
	}

	template<typename T>
	vector< int64_t > multiply(vector< T > &a, vector< T > &b) {
		int need = (int) a.size() + (int) b.size() - 1;
		int nbase = 1;
		while((1 << nbase) < need) nbase++;
		ensure_base(nbase);
		int sz = 1 << nbase;
		vector< C > fa(sz);
		for(int i = 0; i < sz; i++) {
			real x = (i < (int) a.size() ? a[i] : 0);
			real y = (i < (int) b.size() ? b[i] : 0);
			fa[i] = C(x, y);
		}
		fft(fa, sz);
		C r(0, -0.25 / (sz >> 1)), s(0, 1), t(0.5, 0);
		for(int i = 0; i <= (sz >> 1); i++) {
			int j = (sz - i) & (sz - 1);
			C z = (fa[j] * fa[j] - (fa[i] * fa[i]).conj()) * r;
			fa[j] = (fa[i] * fa[i] - (fa[j] * fa[j]).conj()) * r;
			fa[i] = z;
		}
		for(int i = 0; i < (sz >> 1); i++) {
			C A0 = (fa[i] + fa[i + (sz >> 1)]) * t;
			C A1 = (fa[i] - fa[i + (sz >> 1)]) * t * rts[(sz >> 1) + i];
			fa[i] = A0 + A1 * s;
		}
		fft(fa, sz >> 1);
		vector< int64_t > ret(need);
		for(int i = 0; i < need; i++) {
			ret[i] = llround(i & 1 ? fa[i >> 1].y : fa[i >> 1].x);
		}
		return ret;
	}
};

template< typename T >
struct ArbitraryModConvolution {
	using real = FastFourierTransform::real;
	using C = FastFourierTransform::C;

	ArbitraryModConvolution() = default;

	vector< T > multiply(const vector< T > &a, const vector< T > &b, int need = -1) {
		if(need == -1) need = a.size() + b.size() - 1;
		int nbase = 0;
		while((1 << nbase) < need) nbase++;
		FastFourierTransform::ensure_base(nbase);
		int sz = 1 << nbase;
		vector< C > fa(sz);
		for(int i = 0; i < (int)a.size(); i++) {
			fa[i] = C(a[i]._num & ((1 << 15) - 1), a[i]._num >> 15);
		}
		fft(fa, sz);
		vector< C > fb(sz);
		if(a == b) {
			fb = fa;
		} else {
			for(int i = 0; i < (int)b.size(); i++) {
				fb[i] = C(b[i]._num & ((1 << 15) - 1), b[i]._num >> 15);
			}
			fft(fb, sz);
		}
		real ratio = 0.25 / sz;
		C r2(0, -1), r3(ratio, 0), r4(0, -ratio), r5(0, 1);
		for(int i = 0; i <= (sz >> 1); i++) {
			int j = (sz - i) & (sz - 1);
			C a1 = (fa[i] + fa[j].conj());
			C a2 = (fa[i] - fa[j].conj()) * r2;
			C b1 = (fb[i] + fb[j].conj()) * r3;
			C b2 = (fb[i] - fb[j].conj()) * r4;
			if(i != j) {
				C c1 = (fa[j] + fa[i].conj());
				C c2 = (fa[j] - fa[i].conj()) * r2;
				C d1 = (fb[j] + fb[i].conj()) * r3;
				C d2 = (fb[j] - fb[i].conj()) * r4;
				fa[i] = c1 * d1 + c2 * d2 * r5;
				fb[i] = c1 * d2 + c2 * d1;
			}
			fa[j] = a1 * b1 + a2 * b2 * r5;
			fb[j] = a1 * b2 + a2 * b1;
		}
		fft(fa, sz);
		fft(fb, sz);
		vector< T > ret(need);
		for(int i = 0; i < need; i++) {
			int64_t aa = llround(fa[i].x);
			int64_t bb = llround(fb[i].x);
			int64_t cc = llround(fa[i].y);
			aa = T(aa)._num, bb = T(bb)._num, cc = T(cc)._num;
			ret[i] = T(aa + (bb << 15) + (cc << 30));
		}
		return ret;
	}
};

//partition(N): [0,N] の分割数を返す。
//計算量：O(NlogN)
template< typename T >
FormalPowerSeries< T > partition(int N) {
	ArbitraryModConvolution< Modint > fft;
	using FPS = FormalPowerSeries< Modint >;
	auto mult = [&](const FPS::P &a, const FPS::P &b) { return fft.multiply(a, b); };
	FPS::set_fft(mult);

	FormalPowerSeries< T > po(N + 1);
	po[0] = 1;
	for(int k = 1; k <= N; k++) {
		if(1LL * k * (3 * k + 1) / 2 <= N) po[k * (3 * k + 1) / 2] += (k % 2 ? -1 : 1);
		if(1LL * k * (3 * k - 1) / 2 <= N) po[k * (3 * k - 1) / 2] += (k % 2 ? -1 : 1);
	}
	return po.inv();
}

