  cin.tie(0);
  ios::sync_with_stdio(false);

  int n, k;
  cin >> n >> k;

  if(k > n) k = n - 1;

  COMinit();

  ll ans = 0;
  for(int i = 0; i <= min<int>(k, n - 1); i++){
    int zero = i, occupied = n - i;
    if(i == 0){
      ans++;
      continue;
    }
    ans += COM(n, zero) * COM((n - occupied) + (occupied - 1), n - occupied);
    ans %= MOD;
    //cout << ans << endl;
  }

  cout << ans << '\n';
}

