struct Factorial {
    static vector<modint> fact, finv;
    static void init(int n){
        fact.resize(n+1);
        finv.resize(n+1);
        fact[0] = 1;
        repe(i, 1, n) fact[i] = modint(i)*fact[i-1];
        finv[n] = fact[n].inverse();
        repr(i, n, 0) finv[i] = modint(i+1)*finv[i+1];
    }
    static modint comb(int n, int k){
        if(n < k) return 0;
        if(n < 0 or k < 0) return 0;
        return fact[n]*finv[k]*finv[n-k];
    }
    static modint perm(int n, int k){
        if(n < k) return 0;
        if(n < 0 or k < 0) return 0;
        return fact[n]*finv[n-k];
    }
};
