// MOD
ll pow(ll a, ll n, ll m) {
  if (n == 0)
    return 1;
  if (n & 1)
    return ((a % m) * pow(a, n - 1, m)) % m;
  auto b = pow(a, n / 2, m);
  return (b * b) % m;
}
ll inv(ll a, ll p) { return pow(a, p - 2, p); }
template <ll N, ll M> struct Factrial {
  Factrial() {
    fact[0] = 1;
    for (int i = 1; i <= N; ++i)
      fact[i] = (fact[i - 1] * i) % M;
    finv[N] = inv(fact[N], M);
    for (int i = N; i > 0; --i)
      finv[i - 1] = (finv[i] * i) % M;
  }
  array<ll, N + 1> fact;
  array<ll, N + 1> finv;
  ll comb(ll n, ll m) const {
    if (m < 0 || n < m)
      return 0LL;
    return (fact[n] * ((finv[m] * finv[n - m]) % M)) % M;
  }
  ll perm(ll n, ll m) const {}
};

constexpr ll MOD = 1e9 + 7;
Factrial</**/ 1'000'000LL /*/ 20 //*/
         ,
         MOD> const factorial;

void solve() {
  ll n, k;
  input(n, k);
  dump(n, k);
  // dump(factorial.finv);
  ll ans = 0;
  for (auto &&m : range(min(n - 1, k) + 1)) {
    ll a = factorial.comb(n, m) * factorial.comb(n - 1, m);
    a %= MOD;
    // dump(m, factorial.comb(n, m), factorial.comb(n - 1, m));
    ans += a;
    ans %= MOD;
  }
  print(ans);
}

int main() {
  ll t = 1;
  /** input(t); /**/
  for (auto &&i : range(t)) {
    solve();
  }
}

