	if(n <= k){
		cout << divide(n, n) << endl;
		return 0;
	}

	llint ans = 0;
	for(int i = 0; i <= k; i++){
		ans += comb(n, i) * divide(i, n-i) % mod;
		ans %= mod;
	}
	cout << ans << endl;

	return 0;
}

