    for(int i=1; i<=min(n, k); i++){
        int y = n-i;
        if(y < 1) break;
        int a = n-y;
        mint res = COM(a+y-1, a);
        res *= COM(n, y);
        ans += res;
    }

    cout << ans << endl;
}

