ll modinv(ll a, ll m) {
  if (modinv_already.at(a) != -1) {
    return modinv_already.at(a);
  }
    ll b = m, u = 1, v = 0;
    while (b) {
        ll t = a / b;
        a -= t * b; swap(a, b);
        u -= t * v; swap(u, v);
    }
    u %= m;
    if (u < 0) u += m;
    return modinv_already.at(a) = u;
}
