    ll m;

    mcomb(ll n, ll m_=1e9+7): fact(n+1, 1), ifact(n+1), m(m_) {
        rep(i,n) fact[i+1] = (fact[i]*(i+1)) % m;
        ifact[n] = minv(fact[n]);
        rep(i,n) ifact[n-1-i] = (ifact[n-i]*(n-i)) % m;
    }

    ll operator()(ll n, ll k) {
        if(k < 0 || k > n) return 0;
        return (((ifact[k]*ifact[n-k]) % m)*fact[n]) % m;
    }

    ll minv(ll a) {
        ll b = m, u = 1, v = 0;
        while (b) {
            ll t = a / b;
            a -= t * b; swap(a, b);
            u -= t * v; swap(u, v);
        }
        u %= m;
        if (u < 0) u += m;
        return u;
    }    
};

int main()
{
    const ll m = 1e9+7;
    ll n,k;
    cin >> n >> k;

    k = min(k, n-1);
    mcomb mc(n, m);
    ll ans = 0;
    rep(i,k+1) {
        ans += (mc(n,i) * mc(n-1,i)) % m;
        ans %= m;
    }

    cout << ans << endl;
    return 0;
}

