long long exp(long long b, long long e){
    if(e == 0) return 1;
    long long ee = exp(b, e / 2);
    long long ans = ee * ee;
    ans %= MOD;
    if(e % 2 == 1) ans *= b;
    return ans % MOD;
}

long long inv(long long n){
    return exp(n, MOD - 2);
}

long long fact(long long n){
    if(memo[n] != 0) return memo[n];
    long long ans = 1;
    for(long long m = 1; m <= n; m++){
        ans *= m;
        ans %= MOD;
    }
    return memo[n] = ans;
}

long long comb(long long n, long long k){
    long long ans = fact(n);
    ans *= inv(fact(n - k));
    ans %= MOD;
    ans *= inv(fact(k));
    ans %= MOD;
    return ans;
}

long long P(long long n, long long k){
    return comb(n + k - 1, k);
}

