using namespace std;


ll fermat(ll base, ll exp)
{
	ll result = 1;
	while(exp > 0)
	{
		if(exp % 2 == 1)
			result = ((result % mod) * (base % mod)) % mod; 
		base = ((base % mod) * (base % mod)) % mod; 
		exp /= 2;
	}

	return result;
}

