    for(i = 0; i < min(n - 1, k); i ++)
    {
    	ll num1 = fact[n]; 
    	ll den1 = ((fact[i + 1] % mod) * (fact[n - i - 1] % mod)) % mod;
    	ll denInv1 = fermat(den1, mod - 2) % mod;

    	ll num2 = fact[n - 1];
    	ll den2 = ((fact[i + 1] % mod) * (fact[n - i - 2] % mod)) % mod;
