	for (ll i = 1; i < n && i <= k; ++i){
		c_1 = c_1*(n - i) % MOD;
		c_1 = c_1*RepeatSquaring(i, MOD - 2) % MOD;
		c_2 = c_2*(n - i + 1) % MOD;
		c_2 = c_2*RepeatSquaring(i, MOD - 2) % MOD;
		answer = (answer + c_1*c_2) % MOD;
	}
	printf("%lld\n", answer);
	return 0;
}

