long long Kurikaeshi(long long a, long long N, long long p){
  if( N == 0) return 1;
  long long rt;
  if(N % 2 == 0){
    rt = Kurikaeshi(a, N / 2, p);
    rt = rt * rt % p;
    return rt;
  }
  if(N % 2 == 1){
    rt = Kurikaeshi(a, N - 1, p);
    rt = a * rt % p;
    return rt;
  }
}
