const int MAX = 2 * 1e5 + 5;
const int INF = 1001001001;
const int MOD = 1e9 + 7;

struct Combination{
    private:
        vector<long long> fac, finv, inv;

    public:
        Combination(){
            fac = finv = inv = vector<long long> (MAX);

            fac[0] = fac[1] = 1;
            finv[0] = finv[1] = 1;
            inv[1] = 1;
            for (int i = 2; i < MAX; i++){
                fac[i] = fac[i - 1] * i % MOD;
                inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
                finv[i] = finv[i - 1] * inv[i] % MOD;
            }
        }

        long long getCom(int n, int k){
            if (n < k) return 0;
            if (n < 0 || k < 0) return 0;
            return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
        }
};

int main(){
    int N, K;
    cin >> N >> K;

    Combination com = Combination();

    ll ans = 0;
    rep(i, min(K + 1, N)) {
        int m = N - i;
        ans += com.getCom(N, i) * com.getCom(N-1, m-1) % MOD;
        ans %= MOD;
    }

    cout << ans << endl;
}

