class combination {
private:
    bool has_inited = false;
    i64 p;

    i64 extgcd(i64 a, i64 b, i64 &x, i64 &y) {
        i64 d = a;
        if (b != 0) {
            d = extgcd(b, a % b, y, x);
            y -= (a / b) * x;
        } else {
            x = 1;
            y = 0;
        }
        return d;
    }

    i64 mod_inverse(i64 a, i64 m) {
        i64 x, y;
        if (extgcd(a, m, x, y) == 1) return (x + m) % m;
        return 0;
    }

    vector<i64> fact, ifact;

    void init_fact(i64 n, i64 m) {
        fact.resize(n + 1);
        ifact.resize(n + 1);
        fact[0] = fact[1] = 1;
        ifact[0] = ifact[1] = 1;
        for (i64 i = 2; i <= n; ++i) {
            fact[i] = (i * fact[i - 1]) % m;
            ifact[i] = mod_inverse(fact[i], m);
        }
    }

public:
    combination(i64 p) : p(p) {}

    combination(i64 n, i64 p) : p(p) {
        init(n);
    }

    /*
     * n以下の階乗の値を前計算する
     * O(nlog(p))
     */
    void init(i64 n) {
        has_inited = true;
        init_fact(n, p);
    }

    /*
     * 階乗の値を前計算しておいた場合はO(1)
     * 前計算していない場合はO(k+log(p))
     * */
    i64 comb(i64 n, i64 k) {
        if (n < 0 or k < 0 or n < k) return 0;
        if (has_inited) return fact[n] * ifact[n - k] % p * ifact[k] % p;

        i64 num = 1, den = 1;
        for (i64 i = 0; i < k; ++i) {
            num = num * ((n - i) % p) % p;
            den = den * (i + 1) % p;
        }
        return num * mod_inverse(den, p) % p;
    }
};


void solve() {
    constexpr i64 mod = 1'000'000'007;
    constexpr i64 maxn=200000;
    combination comb(2*maxn+1, mod);

    i64 n,k;
    cin >> n >> k;

    if(k>=n-1){
        cout << comb.comb(2*n-1,n-1) << endl;
    }else{
        fp<mod> ans=0;
        rep(w,n-k,n) ans+=comb.comb(n,w)*comb.comb((n-w)+w-1,w-1);
        if(k>=2) ans+=1;
        cout << ans << endl;
    }
}

int main() {
    std::cin.tie(0);
    std::ios::sync_with_stdio(false);
    cout.setf(ios::fixed);
    cout.precision(16);
    solve();
    return 0;
}

