  if (K >= N - 1) {
    std::cout << fact(N + N - 1, N) << '\n';
    return 0;
  }
  modint ans;
  if (K >= 2) {
    ans += 1;
  }
  for (int i: range(1, K + 1)) {
    int p = (N - i);
    int t = N - p;
    ans += fact(t + p - 1, t) * fact(N, p);
  }
  std::cout << ans << '\n';
  return 0;
}

