// n 個の配列に、mod p で前処理する
void init(int n, int p){
	fac[0] = fac[1] = 1;
	finv[0] = finv[1] = 1;
	inv[1] = 1;
	rp(i,2,n+1){
		fac[i] = fac[i-1] * i % p;
		inv[i] = p - inv[p%i] * (p/i) % p;
		finv[i] = finv[i-1] * inv[i] % p;
	}
}

// 二項係数計算 nCr(mod m)
ll nCr(int n, int r, int m){
	if(n<r || n<0 || r<0) return 0;
	return fac[n] * (finv[n-r] * finv[r] % m) % m;
}

ll solve(){
	init(N, MOD);
	K = min(K, N-1);
	ll ans = 0;
	rp(k,0,K+1){
		ll x = nCr(N, k, MOD) * nCr(N-1, k, MOD) % MOD;
		ans = (ans + x) % MOD;
	}
	return ans;
}

int main(){
	cin>>N>>K;
	cout<< solve() <<endl;
}

