	for(ll i=0;i<min(n,k+1);i++) {
		// 0人となる部屋がi個である場合の数
		// 0人となる部屋の選び方 -> nCi
		// i人がn-iの部屋のどこかへ移動 -> {n-1}C{i}
		(ans += comb(n,i) * comb(n-1, i) % MOD) %= MOD;
	}
	cout << ans << endl;
}

