mint mfact(int n) { // n! (mod MOD)
  static vector<mint> fact(1, 1);
  int pn = fact.size();
  if (pn < n + 1) {
    fact.resize(n + 1);
    for (int i = pn; i <= n; i++) fact[i] = fact[i - 1] * i;
  }
  return fact[n];
}
mint mifact(int n) { // n! (mod MOD)
  static vector<mint> ifact(1, 1);
  int pn = ifact.size();
  if (pn < n + 1) {
    ifact.resize(n + 1);
    ifact[n] = mfact(n).inv();
    for (int i = n; i >= pn; --i) ifact[i - 1] = ifact[i] * i;
  }
  return ifact[n];
}
mint nPk(int n, int k) {
  if (n < 0 || k < 0 || n < k) return 0;
  if (k == 0) return 1;
  return mfact(n) * mfact(n - k).inv();
}
mint nCk(int n, int k) {
  if (n < 0 || k < 0 || n < k) return 0;
  if (k == 0) return 1;
  // return mfact(n) * mfact(k).inv() * mfact(n - k).inv();
  return mfact(n) * mifact(k) * mifact(n - k);
}

