ll powe(ll m, ll N){
    if (N == 0){
        return 1;
    } else if (N % 2 == 1){
        ll tmp = m * powe(m,N - 1);
        tmp = m * powe(m,N - 1) % 1000000007;
        if (tmp < 0) tmp += 1000000007;
