template <long long N>
class Modulo {
 public:
  using Type = decltype(N);
  // constructor
  constexpr Modulo (Type n = 0) : number_((N + n) % N) {}
  // unary operator
  constexpr auto operator - () const {
    return Modulo(-number_);
  }
  constexpr auto operator ~ () const {
    // Only if N is prime, and number_ and N are coprime
    return power(*this, N - 2);
  }
  // compound assign operator
  constexpr auto & operator += (const Modulo & m) {
    number_ = (number_ + m.number_) % N;
    return *this;
  }
  constexpr auto & operator -= (const Modulo & m) {
    return *this += -m;
  }
  constexpr auto & operator *= (const Modulo & m) {
    number_ = (number_ * m.number_) % N;
    return *this;
  }
  constexpr auto & operator /= (const Modulo & m) {
    return *this *= ~m;
  }
  // binary operator with type conversion
  constexpr friend auto operator + (Modulo lhs, const Modulo & rhs) {
    return lhs += rhs;
  }
  constexpr friend auto operator - (Modulo lhs, const Modulo & rhs) {
    return lhs -= rhs;
  }
  constexpr friend auto operator * (Modulo lhs, const Modulo & rhs) {
    return lhs *= rhs;
  }
  constexpr friend auto operator / (Modulo lhs, const Modulo & rhs) {
    return lhs /= rhs;
  }
  // friend function
  constexpr friend auto power (const Modulo & m, Type exponent) {
    constexpr auto unit = Modulo(1);
    if ( exponent == 0 ) return unit;
    return (exponent & 1 ? m : unit) * power(m*m, exponent >> 1);
  }
  constexpr friend auto number (const Modulo & m) {
    return m.number_;
  }
  // stream operator
  friend auto & operator << (std::ostream & os, const Modulo & m) {
    return os << number(m);
  }
 private:
  Type number_;
};

