  if (N <= K) {
    ans = fact.combination(2 * N - 1, N);
  } else {
    auto f = [&](int x) -> Mint { return fact.combination(N - 1, x); };
    int x = K;
    while (x >= 0) {
      ans += fact.combination(N, x) * f(x);
      x -= 1;
    }
  }
  cout << ans.value() << endl;
  return (0 ^ _ ^ 0);
}

