// Combination
void COMinit(vector<int64_t>& fac, vector<int64_t>& finv, vector<int64_t>& inv) {
  fac[0] = fac[1] = 1;
  finv[0] = finv[1] = 1;
  inv[1] = 1;
  for (int32_t i = 2; i < (int32_t)fac.size(); i++){
      fac[i] = fac[i - 1] * i % MOD;
      inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
      finv[i] = finv[i - 1] * inv[i] % MOD;
  }
  return;
}

int64_t COM(int32_t n, int32_t k, vector<int64_t>& fac, vector<int64_t>& finv) {
  if (n < k) return 0;
  if (n < 0 || k < 0) return 0;
  return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

