    temp *= COM(n, zeros);

    int use = n - zeros;
    temp *= COM(n - use + use - 1, use - 1);
    ans -= temp;
  }

  cout << ans << endl;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
