constexpr ModInt Mr(ll p){
    p%=MOD;
    if(p<0) p+=MOD;
    return ModInt(p);
}

struct Binominal{
    vector<ModInt> fac,finv,inv;

    Binominal(int n){
        fac.resize(n+1,1);
        finv.resize(n+1,1);
        inv.resize(n+1,1);
        for(int i=2;i<=n;i++){
            fac[i]=fac[i-1]*Mr(i);
            inv[i]=Mr(MOD)-inv[MOD%i]*Mr(MOD/i);
            finv[i]=finv[i-1]*inv[i];
        }
    }
    ModInt com(int n,int k){
        if(n<k) return ModInt(0);
        if(n<0 || k<0) return ModInt(0);
        return fac[n]*finv[k]*finv[n-k];
    }
};



