	cin >> N >> K;
	K = min(N-1, K);
	C.init(N);

	ll ans = 0;
	for(ll i=0; i<=K; i++){ // 空き部屋数
		ll tmp1 = C.comb(N, i); // どこを空きにする？
		ll tmp2 = C.comb(i+N-i-1, i); // 余剰の i 人をどうやって N-i 個の部屋に割り振る？
		// 〇が i 個，｜が N-i-1 個
		ans += tmp1*tmp2;
		ans %= MOD;
	}
	cout << ans << endl;
}

