// mod. m での a の逆元 a^{-1} を計算する
long long modinv(long long a, long long m) {
	long long b = m, u = 1, v = 0;
	while (b) {
		long long t = a / b;
		a -= t * b; swap(a, b);
		u -= t * v; swap(u, v);
	}
	u %= m;
	if (u < 0) u += m;
	return u;
}

//aCbを1000000007で割った余りを求める
llint convination(llint a, llint b) {
	llint ans = 1;
	for (llint i = 0; i < b; i++) {
		ans *= a - i;
		ans %= 1000000007;
	}
	for (llint i = 1; i <= b; i++) {
		ans *= modinv(i, 1000000007);
		ans %= 1000000007;
	}
	return ans;
}

//aのb乗をmodで割った余りを求める
llint power(llint a, llint b) {
	if (b == 1)return a;
	if (b == 0)return 1;
	llint tmp = power(a, (llint)b / 2);
	tmp *= tmp;
	tmp %= mod;
	if (b % 2 == 1) {
		tmp *= a;
		tmp %= mod;
	}
	return tmp;
}

int main() {
	llint n, k;
	cin >> n >> k;
	if (n - 1 <= k)cout << convination((llint)2 * n - 1, (llint)n - 1) << endl;
	else {
		llint ans = 0;
		//table[i]はi!をmodで割った余り
		vllint table(n + 1, 1);
		for (llint i = 0; i < n; i++) {
			if (i == 0)continue;
			table[i + 1] = (llint)table[i] * (i + 1);
			table[i + 1] %= mod;
		}

		for (int i = n - k; i <= n; i++) {
			llint tmp = table[n - 1] * table[n];
			tmp %= mod;
			llint tmp2 = table[i - 1] * table[i];
			tmp2 %= mod;
			tmp2 *= table[n - i];
			tmp2 %= mod;
			tmp2 *= table[n - i];
			tmp2 %= mod;
			tmp *= modinv(tmp2, mod);
			while (tmp < 0)tmp += mod;
			tmp %= mod;
			ans += tmp;
		}
		cout << ans << endl;
	}
	return 0;
}

