    int n, k;
    cin >> n >> k;

    ll ret = 0;
    for (int i = 0; i <= min(k, n - 1); i++) {
        ret += calc_comb(n, i) * calc_comb(n - 1, i) % MOD, ret %= MOD;
    }
    cout << ret << endl;
    return 0;
}

