#define N 200010
#define MOD 1000000007

int fac[N], inv[N], finv[N];

void comp()
{
	fac[0] = fac[1] = 1;
	inv[0] = inv[1] = 1;
	finv[0] = finv[1] = 1;

	for (int i = 2; i < N; ++i)
	{
		fac[i] = fac[i - 1] * i % MOD;
		inv[i] = MOD - (MOD / i) * inv[MOD % i] % MOD;
		finv[i] = finv[i - 1] * inv[i] % MOD;
	}
}

int ncr(int n, int r)
{
	if (n < r)
		return 0;

	return fac[n] * finv[r] % MOD * finv[n - r] % MOD;
}

