{
	ios::sync_with_stdio(false);
	cin.tie(NULL);
	cout.precision(10);

	int n, k;
	cin >> n >> k;

	comp();

	int ans = 0;
	for (int i = 0; i <= min(n, k); ++i)
	{
		ans = (ans + ncr(n, i) * ncr(n - 1, n - i - 1) % MOD) % MOD;
	}

	cout << ans << endl;
	return 0;
}

