class Combination {
public:
    vector<ll> fc, fci;
    int n;
    Combination(int n): n(n) {
        fc.resize(n+1, 1);
        for (int i=2; i<n+1; ++i) {
            fc[i] = (fc[i-1] * i) % mod;
        }
        fci.resize(n+1, 1);
        for (int i=2; i<n+1; ++i) {
            fci[i] = (fci[i-1] * modpow(i, mod-2)) % mod;
        }
    }
    ll operator()(ll n, ll k) {
        if (k == 0 || n == k) return 1;
        return (fc[n] * fci[k] % mod) * fci[n-k] % mod;
    }
    ll modpow(ll a, ll b) {
        if ( ! b) return 1;
        if (b % 2) return (a * modpow(a, b-1)) % mod;
        ll t = modpow(a, b/2);
        return (t * t) % mod;
    }
};

int main() {
    Combination C(200010);
    ll n, k;
    cin >> n >> k;
    ll ans = 0;
    for (int i=0; i<=min(k, n-1); ++i) {
        ans += (C(n, i) * C(n-1, n-i-1)) % mod;
        ans %= mod;
    }
    cout << ans << endl;
    return 0;
}

