    }

    if(k == 0) {
      E = 1;
    }
    else {
      x *= N - k;
      x %= NUM;
      y *= k;
      y %= NUM;
      i64 y_inv = mod_pow(y, NUM - 2);
      E = (x * y_inv) % NUM;
    }

    //cout << C << " " << E << " " << C * E << endl;

    ans += (C * E) % NUM;
    ans %= NUM;
  }
