ll ksm (ll a, ll b)
{
    ll ans = 1 , base = a;
    while (b)
    {
        if (b & 1) ans = ans * base % mod;
        b >>= 1;
        base = base * base % mod;
    }
    return ans;
}
ll inv[maxn] , fact[maxn];
ll C (ll a , ll b)
{
    ll res = fact[a] * inv[b] % mod;
    res = res * inv[a - b] % mod;
    return res;
}
int main()
{
    ios::sync_with_stdio(false);
    ll n , k ; cin >> n >> k;
    fact[0] = 1;
    inv[0] = 1;
    for (int i = 1 ; i <= 2 * n ; i++){
        fact[i] = fact[i - 1] * i % mod;
        inv[i] = ksm(fact[i] , mod - 2) % mod;
    }
    ll ans = C(2 * n - 1 , n - 1);
    ll res = 0;
    for (int i = min(n  , k + 1) ; i <= n - 1 ; i++){
        res = (res + C(n , i) * C(n - 1 , n - i - 1)%mod)%mod;
    }
    cout << (ans - res + mod) % mod << endl;
    return 0;
}

