int qmul(int x, int k) {
	if (k == 0) return 1;
	int t = qmul(x, k / 2);
	t = 1LL * t * t % MOD;
	if (k & 1) t = 1LL * t * x % MOD;
	return t;
}

int get(int n, int x) {
	int u = 1, d = 1;
	for (int i = 0; i < x; i++) {
		u = 1LL * u * (n - i) % MOD;
		d = 1LL * d * (i + 1) % MOD;
	}
	d = qmul(d, MOD - 2);
	return 1LL * u * d % MOD;
}

