}

ll nCr(ll N,ll K){
  if(K<0||K>N)return 0;
  return fact[N]*fact_inv[K]%MAX*fact_inv[N-K]%MAX;
}

ll nHr(ll N,ll K){
  if(!N&&!K)return 1;
  if(!N)return 0;
  return nCr(N+K-1, K);
}

