#include<bits/stdc++.h>

using namespace std;

const long long p=1000000007;

long long modPow(long long a, long long x, long long p) {
    //calculates a^x mod p in logarithmic time.
    long long res = 1;
    while(x > 0) {
        if( x % 2 != 0) {
            res = (res * a) % p;
        }
        a = (a * a) % p;
        x /= 2;
    }
    return res;
}

long long modInverse(long long a, long long p) {
    //calculates the modular multiplicative of a mod m.
    //(assuming p is prime).
    return modPow(a, p-2, p);
}
long long modBinomial(long long n, long long k, long long p) {
// calculates C(n,k) mod p (assuming p is prime).

    long long numerator = 1; // n * (n-1) * ... * (n-k+1)
    for (int i=0; i<k; i++) {
        numerator = (numerator * (n-i) ) % p;
    }

    long long denominator = 1; // k!
    for (int i=1; i<=k; i++) {
        denominator = (denominator * i) % p;
    }

    // numerator / denominator mod p.
    return ( numerator* modInverse(denominator,p) ) % p;
}

int main() {
    long long n,k;
    cin>>n>>k;
    if(k>=n)k=n-1;
    long long ans=1;
    vector<long long>fact1(300000);
    vector<long long>fact2(300000);
    for(long long i=1;i<n;i++){
        fact1[i]=modBinomial(n,i,p);
        fact2[i]=modBinomial(n-1,i,p);
    }
    for(long long i=1;i<=k;i++){
        ans+=(fact1[i]*fact2[i])%p;
    }
    ans%=p;
    cout<<ans<<endl;
}

