	if (k == 0) return ll(1);
	if (k == 1) return ll(n);

	if (k % 2 == 1)
	{
		return pow(n,k-1) * n % MOD;
	}
	else
	{
		ll p = pow(n,k/2);
		return p * p % MOD;
	}
}

