  vector<mod::MInt> f;
public:
  BinCoef(int n): f(n + 1) {
    f[0] = f[1] = 1;
    for (int i = 2; i <= n; i++) {
      f[i] = i * f[i - 1];
    }
  }

  mod::MInt NCM(int n, int m) {
    return f[n] * mod::Inv(f[m] * f[n - m]);
  }
};

