const long long MOD = 1000000007;
typedef long long LL;
LL mof = MOD;
inline LL pow_mod(LL a,LL k,LL mo)
{
    LL ans=1;
    while(k)
    {
        if(k%2) ans=ans*a%mo;
        a=a*a%mo;
        k>>=1;
    }
    return ans%mo;
}
const int maxn = 2e5+7;
LL jc[maxn+7];
inline LL inv(LL x)
{
    return pow_mod(x,mof-2,mof);
}
LL Inv[maxn+7];
LL C(LL N,LL k)
{
    if(k>N||k<0)return 0;
    if(k==0||k==N)return 1;
    LL ans=1;
    ans=ans*jc[N]*Inv[k]%mof*Inv[N-k]%mof;
    return ans;
}
void init()
{
    jc[1]=jc[0]=1;
    for(LL i=2; i<=maxn; ++i) jc[i]=jc[i-1]*i%mof;
    for(int i=0; i<=maxn; ++i) Inv[i]=inv(jc[i]);
}
void solve(long long n, long long k){
    if(k >= n) k = n-1;
    LL ret = 0;
    for(int i=k;i>=0;--i)
    {
        ret += C(n,i)*C(n-1,n-i-1) % MOD;
        ret %= MOD;
    }
    cout<< ret << endl;
}

