ll fast(ll x,ll y){
    ll res = 1;
    while(y){
        if(y&1)
            res  = (res*x)%mod;

        y>>=1;
        x = (x*x)%mod;
    }
    return res;
}

ll inv(ll n){
    return fast(n,mod-2);
}

ll fact[maxs];
ll ifact[maxs];

void pre(){

    fact[0] = 1;
    ifact[0] = 1;

    for(ll i=1;i<maxs;i++){
        fact[i] = (fact[i-1]*i)%mod;
        ifact[i] = inv(fact[i]);
    }

}


ll ncr(ll n,ll r){
    return (fact[n]*ifact[n-r])%mod*ifact[r]%mod;
}

