template<class T>auto set_factorial(std::size_t N)
{
	std::vector<T> ret(N + 1);
	ret[0] = 1;
	for (auto i : boost::irange<index_t>(0, N))
	{
		ret[i + 1] = ret[i] * (i + 1);
	}
	return ret;
}
template<class T>auto set_inverted(std::vector<T>const& vec)
{
	std::vector<T> ret(vec.size());
	for (auto i : boost::irange<index_t>(0, vec.size()))
	{
		ret[i] = 1 / vec[i];
	}
	return ret;
}

void Main()
{
	int N, K;
	std::cin >> N >> K;
	K = std::min(N, K + 1);
	auto fac = set_factorial<mod_t>(N + K);
	auto inv = set_inverted(fac);
	auto comb = [&](int n, int k)
	{
		return fac[n] * inv[k] * inv[n - k];
	};
	auto combR = [&](int n, int k)
	{
		return fac[n + k - 1] * inv[n - 1] * inv[k];
	};
	mod_t ret = 0;
	for (auto i : boost::irange(0, K))
	{
		ret += comb(N, i) * combR(N - i, i);
	}
	std::cout << ret << std::endl;
}

int main()
{
	std::cin.tie(nullptr);
	std::ios_base::sync_with_stdio(false);
	std::cout << std::fixed << std::setprecision(15);
	Main();
}

