ll extGCD(ll a, ll b, ll &x, ll &y){
    if(b == 0){
        x = 1;
        y = 0;
        return a;
    }
    ll g = extGCD(b, a%b, y, x);
    y -= a/b * x;
    return g;
}

ll MOD = 1000000007;

vector<ll> mfact(1,1);

ll minv(ll a){
    ll x;ll y;
    extGCD(a, MOD, x, y);
    if(x<0)x+=MOD;
    return x;
}
ll mod(ll val, ll m) {
  ll res = val % m;
  if (res < 0) res += m;
  return res;
}


ll mpow(ll a,ll b){
    ll res = 1;
    while(b >= 1){
        if(b%2==1)res=(res*a)%MOD;
        b/=2;
        a = (a*a)%MOD;
    }
    return res;
}

ll mfactorial(ll a){
    if(mfact.size()-1 >= a)return mfact[a];
    for(ll i = mfact.size();i<=a;i++){
        mfact.push_back((i * mfact[i-1])%MOD);
    }
    return mfact[a];
}

ll mcomb(ll n, ll r){
    return (((mfactorial(n) * minv(mfactorial(r)))%MOD) * minv(mfactorial(n-r)))%MOD;
}


int main(){
    ll n,k;
    cin>>n>>k;
    ll ans = 1; // 最初の状態（k>=3より常に再現可能）
    for(ll i = min(n-1,k);i > 0;i--){
        ans = (ans + (mcomb(n - 1, i) * mcomb(n,i)) % MOD) % MOD;
    }
    cout<<ans<<endl;
}

