const int Mod = 1000000007;
class mll {
public:
	long long x;
	mll(long long x = 0) : x((x% Mod + Mod) % Mod) {};
	void operator += (const mll& a) {
		if ((x += a.x) >= Mod) x -= Mod;
	}
	void operator -= (const mll& a) {
		if ((x += Mod - a.x) >= Mod) x -= Mod;
	}
	void operator *= (const mll& a) {
		(x *= a.x) %= Mod;
	}
	void operator /= (const mll& a) {
		mll b = a.inv();
		(x *= b.x) %= Mod;
	}
	mll operator * (const mll& a) const {
		mll ans = *this;
		ans *= a;
		return ans;
	}
	mll inv() const {
		long long a = x, b = Mod, u = 1, v = 0;
		while (b) {
			long long t = a / b;
			a -= t * b; swap(a, b);
			u -= t * v; swap(u, v);
		}
		u %= Mod;
		if (u < 0) u += Mod;
		a = u;
		return mll(a);
	}
};
mll comb(long long n, long long m) {
	mll ans = 1;
	for (long long i = n; i > n - m; i--) ans *= i;
	for (long long i = 1; i <= m; i++) ans /= i;
	return ans;
}

int main() {
	long long n, k;
	cin >> n >> k;
	mll ans = comb(n + n - 1, n - 1);
	if (k < n - 1) {
		mll dif = 0;
		for (long long i = k + 1; i < n; i++) dif += comb(n, i) * comb(n - 1, i);
		ans -= dif;
	}
	cout << ans.x << endl;
}

