template<ll _M=1000000007>
class FactorialProvider{
public:
    FactorialProvider(){};
    ~FactorialProvider(){};

    ll operator() (ll x) {
        ll ret = 1;
        for(ll i = 1; i <= x; i++){
            ret = (ret*i%_M)%_M;
        }
        return ret;
    }
