template<ll _M=1000000007>
class PrecomputedFactorialProvider{
public:
    PrecomputedFactorialProvider():_max(0){
        _facto.push_back(1);
        _factoinv.push_back(1);
    };

    ~PrecomputedFactorialProvider(){};

    ll operator() (ll x) {
        return facto(x);
    }

    ll facto(ll x){
        if( x > _max ){
            ll cur = _facto[_max];
            _facto.resize(x+1);
            _factoinv.resize(x+1);
            for( ll i = _max+1; i <= x; i++ ){
                cur = (cur * i)%_M;
                _facto[i] = cur;

                ll a, b;
                extgcd(cur, _M, a, b);
                _factoinv[i] = (a+_M)%_M;
            }
            _max = x;
        }
        return _facto[x];
    }

    ll inv(ll x){
        if( x > _max){
            facto(x);
        }
        return _factoinv[x];
    }
private:
    vector<ll> _facto;
    vector<ll> _factoinv;
    ll _max;
};

template<ll _M=1000000007, class FProvider=PrecomputedFactorialProvider<_M>>
class Modulo{
public:
    Modulo():_num(0){}
    Modulo(ll num):_num(num%_M){};
    ~Modulo(){};

    ll num(){ return _num;};
    explicit operator ll() { return _num;};

    Modulo<_M>& add(const Modulo<_M>& rhs){
        // TODO: check overflow
        _num = (_num + rhs._num)%_M;
        return *this;
    }

    Modulo<_M>& sub(const Modulo<_M>& rhs){
        // TODO: check overflow
        _num = ((_num - rhs._num)%_M + _M)%_M;
        return *this;
    }

    Modulo<_M>& mul(const Modulo<_M>& rhs){
        // TODO: check overflow
        _num = (_num * rhs._num)%_M;
        return *this;
    }

    Modulo<_M>& div(const Modulo<_M>& rhs){
        // TODO: check overflow
        // mod inv
        this->mul(rhs.inv());
        return *this;
    }

    Modulo<_M>& pow(ll n){
        ll cur = _num;
        _num = 1;
        while( n != 0 ){
            if( n & 1 ) _num = (_num * cur)%_M;
            cur = (cur * cur)%_M;
            n>>=1;
        }
        return *this;
    }

    Modulo<_M> inv() const{
        ll x, y;
        extgcd(_num, _M, x, y);
        return (x+_M)%_M;
    }

    Modulo<_M> facto() const{
        return _fprovider(_num);
    }

    Modulo<_M> factoinv() const{
