int main() {
  nCr_init();
  ll n, k;
  cin >> n >> k;
  ll ans = 0;
  for (int x = 0; x <= min(n - 1, k); x++) {  // 人数0の部屋の数がxのとき
    ans = (ans + nCr(n, x) * nHr(n - x, x) % MOD) % MOD;
  }
  cout << ans << endl;
}

