constexpr modint pow(modint base, size_t exp) {
  modint res = 1;
  while (exp) {
    if (exp % 2) res *= base;
    base *= base;
    exp /= 2;
  }
  return res;
}

constexpr modint powm(ll base, size_t exp) {
  return pow((modint)base, exp);
}

// O(r + log MOD)
modint choose(int n, int r) {
  chmin(r, n-r);
  if (r < 0) return modint(0);
  modint nu = 1, de = 1;
  rep(i, r) nu *= n-i, de *= i+1;
  return nu / de;
}

struct binomial {
  vector<modint> fact, invfact;
  // O(n)
  binomial(int n): fact(n+1), invfact(n+1) {
    fact[0] = 1;
    rep(i, n) fact[i+1] = fact[i] * modint(i+1);
    invfact[n] = modint(1) / fact[n];
    repr(i, n) invfact[i] = invfact[i+1] * modint(i+1);
  }
  // O(1)
  modint operator()(int n, int r) {
    chmin(r, n-r);
    if (r < 0) return modint(0);
    return fact[n] * invfact[r] * invfact[n-r];
  }
};

int main() {
  int n = IN, k = IN;
  binomial binom(n);
  modint res = 0;
  rep(m, max(0,n-k), n+1) res += binom(n,m) * binom(n-1,n-m);
  OUT(res);
}

