const int mod = 1000000007;

inline LL qpow(LL a, LL b)
{
	LL res = 1;
	while (b)
	{
		if (b & 1) res = (res * a) % mod;
		a = a * a % mod, b >>= 1;
	}
	return res % mod;
}

const int M=1e9+7;
int n,m;
LL ans=1,f[1000005]={1},g[1000005]={1};
LL ksm(LL x,LL y)
{
    LL s=1;
    while(y)
	{
        if(y&1)s=(s*x)%M;
        x=(x*x)%M;
        y>>=1;
    }
    return s;
}
LL work(int x,int y)
{
    return f[x]%M*g[y]%M*g[x-y]%M;
}
int main(){
	cin >> n >> m;
    for(int i=1;i<=n;i++)
{
        f[i]=f[i-1]*i%M;
        g[i]=ksm(f[i],M-2);
    }
    int k=min(n-1,m);
    for(int i=1;i<=k;i++)
{
        LL x=work(n,i);
        LL y=work(n-1,i);
        ans=(ans+x*y%M)%M;
    }
    cout<<ans<<endl;
	return 0;
}

