ll fac[500005],inv[500005];
ll power(ll base,ll n)
{
   ll r=1;
   while(n)
   {
       if(n&1) r=r*base%mod;
       base=base*base%mod;
       n/=2;
   }
   return r;
}
void pre()
{
    fac[0]=1;
    for(int i=1;i<=500000;i++)
    {
        fac[i]=fac[i-1]*i%mod;
    }
    inv[500000]=power(fac[500000],mod-2);
    for(int i=499999;i>=0;i--)
    {
        inv[i]=inv[i+1]*(i+1)%mod;
    }
}
ll C(ll m,ll n)
{
    return fac[n]*inv[n-m]%mod*inv[m]%mod;
}
