template <ll mod>
struct ModInt {
    ll x;

    ModInt() : x(0) {}

    ModInt(ll y) : x(y >= 0 ? y % mod : (mod - (-y) % mod) % mod) {}

    ModInt &operator+=(const ModInt &p) {
        if ((x += p.x) >= mod) x -= mod;
        return *this;
    }

    ModInt &operator-=(const ModInt &p) {
        if ((x += mod - p.x) >= mod) x -= mod;
        return *this;
    }

    ModInt &operator*=(const ModInt &p) {
        x = (int)(1LL * x * p.x % mod);
        return *this;
    }

    ModInt &operator/=(const ModInt &p) {
        *this *= p.inverse();
        return *this;
    }

    ModInt operator-() const { return ModInt(-x); }

    ModInt operator+(const ModInt &p) const { return ModInt(*this) += p; }

    ModInt operator-(const ModInt &p) const { return ModInt(*this) -= p; }

    ModInt operator*(const ModInt &p) const { return ModInt(*this) *= p; }

    ModInt operator/(const ModInt &p) const { return ModInt(*this) /= p; }

    bool operator==(const ModInt &p) const { return x == p.x; }

    bool operator!=(const ModInt &p) const { return x != p.x; }

    ModInt inverse() const {
        int a = x, b = mod, u = 1, v = 0, t;
        while (b > 0) {
            t = a / b;
            swap(a -= t * b, b);
            swap(u -= t * v, v);
        }
        return ModInt(u);
    }

    ModInt pow(ll n) const {
        ModInt ret(1), mul(x);
        while (n > 0) {
            if (n & 1) ret *= mul;
            mul *= mul;
            n >>= 1;
        }
        return ret;
    }

    friend ostream &operator<<(ostream &os, const ModInt &p) {
        return os << p.x;
    }

    friend istream &operator>>(istream &is, ModInt &a) {
        ll t;
        is >> t;
        a = ModInt<mod>(t);
        return (is);
    }

    static int get_mod() { return mod; }
};


template <typename MODINT, ll maxim>
class Combinatorics {
    private:
        MODINT fact[maxim];
        MODINT invfact[maxim];

    public:
        Combinatorics() {
            fact[0] = 1;
            REP(i,1,maxim+1) {
                fact[i] = fact[i-1] * i;
            }
            ll mod = MODINT().get_mod();
            invfact[maxim] = MODINT(fact[maxim]).pow(mod-2);
            REP(i,1,maxim+1) {
                ll j = maxim-i;
                invfact[j] = invfact[j+1] * (j+1);
            }
        }

        MODINT nCk(ll n,ll r) {
            if (n < 0 || n < r) return 0;
            return fact[n] * invfact[r] * invfact[n-r];
        }

        MODINT nPk(ll n,ll r) {
            if (n < 0 || n < r) return 0;
            return fact[n] * invfact[n-r];
        }

};

