    template <typename T>
    Mod &operator-=(const T x)
    {
        set_value(this->value - (long long)x + mod);
        return *this;
    }

    template <typename T>
    Mod &operator*=(const T x)
    {
        set_value(this->value * (long long)x);
        return *this;
    }

    template <typename T>
    Mod &operator/=(const T x)
    {
        long long a = (long long)x;
        long long b = mod;
        long long u = 1;
        long long v = 0;
        while (b)
        {
            long long t = a / b;
            a -= t * b;
            swap(a, b);
            u -= t * v;
            swap(u, v);
        }
        u %= mod;
        if (u < 0)
            u += mod;
        *this *= Mod(u);
        return *this;
    }

    template <typename T>
    Mod operator&(const T x) const
    {
        return Mod(*this) &= x;
    }

    template <typename T>
    Mod operator|(const T x) const
    {
        return Mod(*this) |= x;
    }

    template <typename T>
    Mod operator^(const T x) const
    {
        return Mod(*this) ^= x;
    }

    template <typename T>
    Mod operator<<(const T x) const
    {
        return Mod(*this) <<= x;
    }

    template <typename T>
    Mod operator>>(const T x) const
    {
        return Mod(*this) >>= x;
    }

    template <typename T>
    Mod operator+(const T x) const
    {
        return Mod(*this) += x;
    }

    template <typename T>
    Mod operator-(const T x) const
    {
        return Mod(*this) -= x;
    }

    template <typename T>
    Mod operator*(const T x) const
    {
        return Mod(*this) *= x;
    }

    template <typename T>
    Mod operator/(const T x) const
    {
        return Mod(*this) /= x;
    }

    Mod &operator++()
    {
        *this += 1;
        return *this;
    }

    Mod &operator--()
    {
        this->set_value(--this->value);
        return *this;
    }

    Mod operator++(auto)
    {
        Mod ret(*this);
        ++*this;
        return ret;
    }

    Mod operator--(auto)
    {
        Mod ret(*this);
        --*this;
        return ret;
    }
};

template <long long mod>
Mod<mod> calc_combination(long long x, long long y)
{
    if (x < y)
    {
        return 0ll;
    }

    y = min(y, x - y);
    Mod<mod> ans = 1;
    for (long long i = 1; i <= y; i++)
    {
        ans *= x;
        ans /= i;
        x--;
    }
    return ans;
}
template <long long mod>
class ModCombination
{
    vector<Mod<mod>> fact, ifact;

public:
    ModCombination(long long n) : fact(n + 1), ifact(n + 1)
    {
        assert(n < mod);
        fact[0] = 1;
        for (int i = 1; i <= n; ++i)
        {
            fact[i] = fact[i - 1] * i;
        }
        ifact[n] = Mod<mod>(1) / fact[n];
        for (int i = n; i >= 1; --i)
        {
            ifact[i - 1] = ifact[i] * i;
        }
    }
    Mod<mod> operator()(long long n, long long k)
    {
        if (k < 0 || k > n)
        {
            return 0;
        }
        return fact[n] * ifact[k] * ifact[n - k];
    }
};

int main()
{
    const long long MOD = 1'000'000'007ll;
    long long n, k;
    cin >> n >> k;
    ModCombination<MOD> comb((long long)2e5);

    if (k >= n - 1)
    {
        cout << calc_combination<MOD>(n + (n - 1), n - 1) << endl;
        return 0;
    }

    Mod<MOD> ans = 0;
    for (int i = 0; i <= k; i++)
    {
        ans += comb(n, i) * comb((n - i - 1) + i, i);
    }
    cout << ans << endl;
}

