#define int long long
const int mod = 1e9 + 7;
const int N = 2e5 + 10;

int fact[N];

void start(){

	fact[0] = 1;
	for(int i = 1 ; i < N ; ++i)
		fact[i] = (fact[i-1]*i)%mod;
}

int power(int a , int n , int mod){

    int res = 1;
    while(n){

        if(n&1)
            res*=a , res%=mod ;
        a*=a;
        a%=mod;
        n/=2;
    }

    return res;
}

int ncr(int n , int r){

	int res = fact[n];

	int val = fact[r]*fact[n-r];
	val%=mod;
	res*=power(val , mod-2 , mod);
	res%=mod;
	return res;
}

int get(int n , int k){

	int res = ncr(n , k);

	int rem = n - k;
	int nn = n - rem;
	//debug(nn+rem-1 , nn);
	int val = ncr(nn + rem - 1 , nn);
	res*=val;
	res%=mod;

	return res;
}

void solve(){

	int n , k;
	cin>>n>>k;

	start();

	if(k >= n )
		k = n - 1;

	int ans = 1;

	for(int i = 1 ; i <= k ; ++i){

		ans += get(n , i);
		ans%=mod;
	}

	cout<<ans<<endl;
}

