static int MOD = 1000000007;

ll modadd(ll x, ll y) {
	int xp = x % MOD;
	if (x < 0) x += MOD;
	int yp = y % MOD;
	if (y < 0) y += MOD;
	return (x + y) % MOD;
}

ll modsub(ll x, ll y) {
	return modadd(x, -y);
}

ll modmul(ll x, ll y) {
	return x * y % MOD;
}

// power(mod) x^n
ll modpow(ll x, ll n) {
	ll res = 1;
	while (n > 0) {
		if (n & 1) res = modmul(res, x);
		x = modmul(x, x);
		n >>= 1;
	}
	return res;
}

// inverse(mod) x^(-1)
ll inv(ll x) {
	return modpow(x, MOD - 2);
}

ll moddiv(ll x, ll y) {
	return modmul(x, inv(y));
}

// factorial(mod) n!
ll fact(ll n) {
	ll res = 1;
	while (n > 1) {
		res = modmul(res, n);
		n--;
	}
	return res;
}

// permutation(mod) nPr
ll permu(ll n, ll r) {
	if (r < 0 || n < r) return 0;
	else {
		ll res = fact(n);
		res = moddiv(res, fact(n - r));
		return res;
	}
}

// combination(mod) nCr
ll combi(ll n, ll r) {
	ll res = permu(n, r);
	res = moddiv(res, fact(r));
	return res;	
}

ll myfact(int n, int k) {
	ll res = 1;
	rep(i, k) {
		res = modmul(res, n - i);
	}
	return res;
}

ll mycombi(int n, int r) {
	ll res = 1;
	res = moddiv(myfact(n, r), myfact(r, r));
	return res;
}

int main () {
	int n, k; cin >> n >> k;
	vector<ll> f(n), g(n), h(n);
	f.at(0) = 1; g.at(0) = n; h.at(0) = n - 1;
	rep2(i, 1, n) {
		f.at(i) = modmul(f.at(i - 1), i);
		g.at(i) = moddiv(modmul(g.at(i - 1), n - i), i + 1);
		h.at(i) = moddiv(modmul(h.at(i - 1), n - 1 - i), i + 1);
	}

	ll ans = mycombi(2 * n - 1, n -1);

	auto sub = [&](int n, int x) {
		ll res = 1;
		res = modmul(res, moddiv(g.at(x), f.at(x)));
		res = modmul(res, moddiv(h.at(x), f.at(x)));
		return res;
	};

	if (k < n - 1) {
		rep2(x, k + 1, n) {
			ans = modsub(ans, sub(n, x));
		}
	}

	cout << ans << endl;
}

