ll MOD=1000000000+7;
ll pow_mod(ll a, ll n){//aのn乗を計算します。
  ll x = 1;
  ll k=a;
  ll m=n;
  while(m > 0){//全てのbitが捨てられるまで。
    if(m&1){//1番右のbitが1のとき。
      x = (x*k)%MOD;
    }
    k = (k*k)%MOD;
    m >>= 1;//bit全体を右に1つシフトして一番右を捨てる。
  }
  return x%MOD;
}
ll comb_mod(ll n, ll a){
  ll m=n;
  ll k=a;
  ll prod=1;
  ll frac=1;
  for(ll i=0;i<=k-1;i++){
    prod=(prod*(m-i))%MOD;
  }
  for(ll i=1;i<=k;i++){
    frac=(frac*i)%MOD;
  }
  prod=(prod*pow_mod(frac, MOD-2))%MOD;
  return prod;
}
