#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll MOD = 1e9 + 7;

// 組合せを素数で割った値を求める
const int MAX = 510000;
long long fac[MAX], finv[MAX], inv[MAX];

// テーブルを作る前処理
void COMinit() {
  fac[0] = fac[1] = 1;
  finv[0] = finv[1] = 1;
  inv[1] = 1;
  for (int i = 2; i < MAX; i++) {
    fac[i] = fac[i - 1] * i % MOD;
    inv[i] = MOD - inv[MOD % i] * (MOD / i) % MOD;
    finv[i] = finv[i - 1] * inv[i] % MOD;
  }
}

// 二項係数計算
long long COM(int n, int k) {
  if (n < k || n < 0 || k < 0) return 0;
  return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);

  int n, k;
  cin >> n >> k;

  COMinit();

  /*if (k >= n - 1) {
    cout << COM(2 * n - 1, n) << '\n';
    return 0;
  }*/

  ll ans = 0;
  for (int empty = 0; empty <= min(k, n); empty++) {
    ll keep;
    keep = COM(n, empty);
    keep *= COM(empty + (n - empty - 1), empty);
    ans += (keep % MOD);
    ans %= MOD;
  }

  cout << ans << '\n';
}

