template<typename T = int64_t>
struct Combination
{
public:

  /** 符号付き整数を推奨 */
  using com_int = T;

  /** 特に必要はない */
  int mInf;

  /** modを取るので */
  com_int mMod;

  /** (n!)のメモ帳 */
  vector<com_int> fac;

  /** modinvするので */
  vector<com_int> inv;

  /** (k!)^-1のメモ帳 */
  vector<com_int> finv;

  /**
   * @param N nCkで指定するnの最大（デフォルト値は何となく）
   * @param m modを取るので（デフォルト値は10^9 + 7）
   */
  Combination(int N = 10^5, int m = MOD)
    : mInf(N)
    , mMod(m)
    , fac(N+1)
    , inv(N+1)
    , finv(N+1)
  {
    init();
  }

  /**
   * 二項係数を計算する
   * @param n
   * @param k
   * @return nCk (mod m)
   */
  com_int operator()(int n, int k) {
    if (n < k) {
      return com_int(0);
    }
    if (n < 0 || k < 0) {
      return com_int(0);
    }
    if (n > mInf) {
      throw std::runtime_error("nが大きすぎる");
    }
    com_int ret{1};
    ret *= fac[n];
    ret %= mMod;
    ret *= finv[k];
    ret %= mMod;
    ret *= finv[n - k];
    ret %= mMod;
    return ret;
  }

  /**
   * 前計算を行う.
   * operator()呼び出しの前に必ず実行すること.
   */
private:
  void init() {
    fac[0]  = fac[1]  = com_int(1);
    finv[0] = finv[1] = com_int(1);
    inv[0] = -1;
    inv[1] = com_int(1);

    for (int i = 2; i < (int)fac.size(); ++i) {
      fac[i] = (fac[i - 1] * i) % mMod;
      inv[i] = mMod - (inv[mMod % i] * (mMod / i)) % mMod;
      finv[i] = (finv[i - 1] * inv[i]) % MOD;
    }
  }
};

void solve(void)
{
  int n, k; cin >> n >> k;
  Combination<> c(n, MOD);
  auto M = std::min(n, k);
  int ans{};
  for (int m = 0; m <= M; ++m) {
    auto res = c(n, m) * c(n-1, m);
    res %= MOD;
    ans += res;
    ans %= MOD;
  }
  cout << ans << CRLF;
  return;
}

int main(void)
{
  std::ios_base::sync_with_stdio(false);
  std::cin.tie(0);

  solve();

  return 0;
}

