const int mod = 1e9 + 7;
#define ll long long
ll n, k, res;
inline ll Pow (ll a, ll b) {
    ll t = 1;
    while (b) {
        if (b & 1) t = t * a % mod;
        a = a * a % mod, b >>= 1;
    } return t;
}
ll C (ll n, ll m) {
    if (n < m) return 0;
    ll res = 1;
    for (int i = 1; i <= m; i++) {
        ll a = (n + i - m) % mod;
        ll b = i % mod;
        res = res * (a * Pow (b, mod - 2) % mod) % mod;
    } return res;
}
ll Lucas (ll n, ll m) {
    if (m == 0) return 1;
    return C (n % mod, m % mod) * Lucas (n / mod, m / mod) % mod;
}
signed main() {
    scanf ("%lld %lld", &n, &k);
    for (int i = 1; i <= min (n - 1, k); ++i)
        res = (res + Lucas (n, i) * Lucas (n - 1, n - i - 1) % mod) % mod;
    return printf ("%lld\n", res), 0;
}

