	scanf("%d %d", &n, &k);
	Combination comb;
	ll ans = 0;
	REP(i, 0, std::min(n, k+1)){
		ans += comb.C(n, i) * comb.H(n-i, i) % MOD;
		ans %= MOD;
	}
	printf("%ld\n", ans);
	return 0;
}

