template< class T >
struct Poly{
    vector< T > A;

    Poly(){}
    Poly( int n ) {
        A.assign(n,0);
    }

    void adjust(){
        int di = A.size()-1;
        while( di && A[di].a == 0 ){
            di--;
        }
        A.resize(di+1);
    }

    int dim(){
        adjust();
        int dime = A.size()-1;
        return (dime);
    }

    inline T &operator[]( int k ) {
        return (A.at(k));
    }

    inline const T &operator[]( int k ) const {
        return (A.at(k));
    }

    // 単位多項式(1)
    static Poly E(){
        Poly pol(1);
        pol[0] = 1;
        return pol;
    }

    Poly &operator+=( Poly &B ){
        int n = B.dim();
        if( n >= dim() ) A.resize(n+1);
        for( int i = 0; i <= n; i++ ) (*this)[i] += B[i];
        return (*this);
    }

    Poly &operator-=( Poly &B ){
        int n = B.dim();
        if( n >= dim() ) A.resize(n+1);
        for( int i = 0; i <= n; i++ ) (*this)[i] -= B[i];
        return (*this);
    }

    Poly &operator*=( Poly &B ){
        int n = dim(), m = B.dim();
        vector< T > C( n+m+1,0 );
        for( int i = 0; i <= n; i++ )
            for( int j = 0; j <= m; j++ )
                C[i+j] += (*this)[i] * B[j];
        A.swap(C);
        return (*this);
    }
    Poly power( ll k ){
        Poly B = Poly::E();
        while( k > 0 ){
            if( k&1 ) B *= *this;
            *this *= *this;
            k >>= 1;
        }
        A.swap(B.A);
        return *this;
    }
    Poly powerMod( ll k, Poly &mod ){
        Poly B = Poly::E();
        while( k > 0 ){
            if( k&1 ) B *= *this, B %= mod;
            *this *= *this;
            *this %= mod;
            k >>= 1;
        }
        A.swap(B.A);
        return *this;
    }

    // TODO
    // polmod(%=) 多項式剰余
    Poly &operator%=( Poly &B ){
        int n = dim(), m = B.dim();
        for( int i = n-m; i >= 0; i-- ){
            T res = A[i+m] / B[m];
            for( int j = m; j >= 0; j-- ){
                A[i+j] - B[j] * res;
            }
        }
        A.resize(m);
        return (*this);
    }

    // divider(/=) 多項式除算
    // Poly &operator/=( const Poly &B );

    Poly operator+(const Poly &B ) const {
        return (Poly(*this) += B );
    }
    Poly operator-(const Poly &B ) const {
        return (Poly(*this) -= B );
    }
    Poly operator*(const Poly &B ) const {
        return (Poly(*this) *= B );
    }


    // digup けた上げ
    void digup( int di = 10 ){
        int n = dim();
        for( int i = 0; i < n; i++ ){
            A[i+1] += A[i]/di;
            A[i] %= di;
        }
        while( A[n] >= di ){
            A.push_back(A[n]/di);
            A[n++] %= di;
        }
    }

    void Print(){
        int m = dim();
        printf ("[");
        for( int j = 0; j <= m; j++ ){
            printf ("%lld%s", (*this)[j], j == m ? "]\n" : "," );
        }
    }
    void RevPrint(){
        int m = dim();
        printf ("[");
        for( int j = 0; j <= m; j++ ){
            printf ("%lld%s", (*this)[m-j], j == m ? "]\n" : "," );
        }
    }
    void DigiticPrint(){
        int m = dim();
        for( int j = m; j >= 0; j-- ){
            printf ("%lld%s", (*this)[j], j == 0 ? "\n" : "" );
        }
    }
};
