ll extgcd(ll a, ll b, ll &x, ll &y){
    if(b == 0){
        x = 1; y = 0;
        return a;
    }
    ll d = extgcd(b, a % b, y, x);
    y -= (a / b) * x;
    return d;
}

//* calculate a^-1 mod m
ll mod_inverse(ll a, ll m){
    ll x, y;
    extgcd(a, m, x, y);
    return(m + x%m) % m;
}

//* calculate C(n, 0), C(n, 1), ... C(n, n) mod p in O(n) 
vll mod_comb_list(ll n, ll p){
    vll res(n+1, 1);
    for(ll k=1; k <= n; k++){
        res[k] = (res[k-1] * (n - k + 1)) % p;
        res[k] = (res[k] * mod_inverse(k, p)) % p;
    }
    return res;
}

const long long MOD = 1000000007;

void solve(long long n, long long k){
    vll clist1 = mod_comb_list(n, MOD);
    vll clist2 = mod_comb_list(n-1, MOD);
    ll ans = 0;
    REP(t, min(n, k+1)){
        ll tmp = (clist1[t]*clist2[n-t-1]) % MOD;
        ans = (ans + tmp) % MOD;
    }
    cout<<ans<<endl;
}

int main(){
    long long n;
    scanf("%lld",&n);
    long long k;
    scanf("%lld",&k);
    solve(n, k);
    return 0;
}

