ll exgcd(ll a, ll b, ll &x, ll &y)
{
    if(b == 0)
    {
        x = 1, y = 0;
        return a;
    }
    ll res = exgcd(b, a % b, y, x);
    y -= (a / b) * x;

    return res;
}

ll Inv(ll a)
{
    ll d, x, y;
    d = exgcd(a, mod, x, y);
    if(d == 1)
