    return -1;
}

ll qpow(ll a, ll b)
{
    ll base = a;
    ll ans = 1;

    while(b)
    {
        if(b & 1)
            ans = (ans * base) % mod;

        b >>= 1;
        base = (base * base) % mod;
    }

    return ans;
}

