template <ull M> struct modular {
  using m = modular;
  ull v;
  modular() : v(0) {}
  template <typename T> modular(T a) : v((a %= M) < 0 ? a + M : a) {}
  m operator-() const { return m() -= *this; }
  template <typename T> m& operator+=(T r) { if ((v += m(r).v) >= M) v -= M; return *this; }
  template <typename T> m& operator-=(T r) { if (v < m(r).v) v += M; v -= m(r).v; return *this; }
  template <typename T> m& operator*=(T r) { v = (v * m(r).v) % M; return *this; }
  template <typename T> m& operator/=(T r) { return *this *= power(m(r), M - 2); }
  template <typename T> m operator+(T r) { m l = *this; return l += r; }
  template <typename T> m operator-(T r) { m l = *this; return l -= r; }
  template <typename T> m operator*(T r) { m l = *this; return l *= r; }
  template <typename T> m operator/(T r) { m l = *this; return l /= r; }
  template <typename T> bool operator==(T r) { return v == m(r).v; }
  friend ostream& operator<<(ostream& os, m r) { os << r.v; return os; }
  static m power(m b, ll e) {
    if (e == 0) { return 1; }
    m x = power(b * b, e / 2);
    return (e % 2) ? b * x : x;
  }
};

