typedef long long ll;

const int INF = 1e9 + 7;
const int MOD = 1e9 + 7;
const int MAXN = 2e5 + 7;

ll f[MAXN];

ll bin_pow(ll x, ll k) {
    if (k == 0) {
        return 1;
    }
    if (k % 2 == 0) {
        ll res = bin_pow(x, k / 2);
        return (res * res) % MOD;
    } else {
        return (bin_pow(x, k - 1) * x) % MOD;
    }
}

ll C(ll n, ll k) {
    ll res = (f[n] * bin_pow(f[n - k], MOD - 2) % MOD) * bin_pow(f[k], MOD - 2) % MOD;
}

