const int N = (int)2e5 + 3;
const int MOD = (int)1e9 + 7;

int n, k, sil[N], inv[N], wyn;

int fpow(int x, int y) {
  if (y == 0)
    return 1;
  if (y&1)
    return x*fpow(x, y-1)%MOD;
  int res = fpow(x, y/2);
  return res*res%MOD;
}

int ne(int x, int y) {
  if (y == 0 || y == x)
    return 1;
  if (y < 0 || y > x)
    return 0;
  return sil[x]*inv[y]%MOD*inv[x-y]%MOD;
}

