  inv[N-1] = fpow(sil[N-1], MOD-2);
  for (int i = N-2; i >= 0; --i)
    inv[i] = (i+1)*inv[i+1]%MOD;
  wyn = (1+n*(n-1))%MOD;
  for (int i = 2; i <= k; ++i)
    wyn = (wyn+ne(n, i)*ne(n-1, n-1-i)%MOD)%MOD;
  cout<<wyn<<"\n";
}

