const int MAX = 510000;

long long fac[MAX], finv[MAX], inv[MAX];
void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}
long long COM(int n, int k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}
signed main(void) { cin.tie(0); ios::sync_with_stdio(false);
    int n,k; cin>>n>>k;
    COMinit();
    if(n <= k){
        print(COM(n-1+n, n));
        return 0;
    }
    int ans = 0;
    for(int i=0;i<=k;i++){
        if(i == 0) ans++;
        else if(i == 1) ans += COM(n,2)*2;
        else{
            ans += COM(n, i)*COM(n-i-1 + i, i);
        }
        ans %= MOD;
    }
    print(ans);
}

