const ll mod = 1e9 + 7;





ll pow_mod(ll b,ll e){
  ll ac = 1;
  ll x = e;
  ll apow=b;
  while(x){
    if(x%2 == 1){
      ac = (ac*apow)%mod;
    }
    x>>=1;
    apow = (apow*apow)%mod;
  }
  return ac;
}

ll C(ll n, ll k) {
  ll res = 1;
  for (int i = n - k + 1; i <= n; ++i)
    res = (res * i) % mod;
  for (int i = 2; i <= k; ++i)
    res = (res * pow_mod(i, mod - 2)) % mod;

  return res;
}

int main(){
  ll n, k;
  cin >> n >> k;
  cout << C(2*n+1, n+1) << '\n'; 

}

#include <bits/stdc++.h>
using namespace std;

vector<long long> fac, fac_inv;

long long modpow(long long a, long long b, long long p) {
  if (b == 0) return 1;
  long long res = modpow(a, b / 2, p);
  if (b % 2 == 0) res = (res * res) % p;
  else res = (((res * res) % p) * a) % p;
  return res;
}

long long inverse(long long a, long long p) {
  return modpow(a, p-2, p);
}

void comInit(int n, int p) {
  fac.resize(n+1);
  fac_inv.resize(n+1);
  fac.at(0) = fac.at(1) = 1;
  fac_inv.at(0) = fac_inv.at(1) = 1;
  for (int i = 2; i <= n; i++) {
    fac.at(i) = fac.at(i-1) * i % p;
    fac_inv.at(i) = fac_inv.at(i-1) * inverse(i, p) % p;
  }
}

long long com(int n, int k, int p) {
  if (n < k || n < 0 || k < 0) return 0;
  return fac.at(n) * (fac_inv.at(k) * fac_inv.at(n-k) % p) % p;
}

int main() {
  const int MOD = 1000000007;
  int n, k; cin >> n >> k;
  comInit(2*n, MOD);
  // { n, 0, 0, ..., 0 } は n-1 回の移動で可能
  if (k >= n-1) {
    // n 個のボール、n-1 個の仕切りの並べかえ
    cout << com(2*n-1, n-1, MOD) << endl;
  }
  else {
    long long ans = 0;
    // 0 は k 個以下、和は n となるような数列
    for (int i = 0; i <= k; i++) {
      ans = (ans + (com(n, i, MOD) * com(n-1, i, MOD) % MOD)) % MOD;
    }
    cout << ans << endl;
  }
}

