const int N = 2e5 + 10;
ll fac[N] , inv[N] ;
ll qpow(ll a , ll b)
{
	ll ans = 1 ;
	a %= MOD ;
	while(b)
	{
		if(b & 1)  ans = (ans * a) % MOD ;
		b >>= 1 , a = (a * a) % MOD ;
	}
	return ans % MOD ;
}
ll C(ll n , ll m)
{
	return fac[n] * inv[n - m] % MOD * inv[m] % MOD ;
}
ll solve(ll n , ll m)
{
	return C(n + m - 1 , m - 1) ;
}
int main()
{
	ios;
	ll n , k ;
	ll ans = 1 ;
	fac[0] = fac[1] = inv[0] = inv[1] = 1 ;
	rep(i , 2 , N - 1)
	{
		fac[i] = fac[i - 1] * i % MOD ;
		inv[i] = -inv[MOD % i] * (MOD / i) % MOD ;
		while(inv[i] < 0) inv[i] += MOD ;
	}
	rep(i , 2 , N - 1)
	inv[i] = inv[i] * inv[i - 1] % MOD ;
	cin >> n >> k;
	k = min(k , n) ;
	rep(i , 1 , n - 1)
	{
		if(i > k)  break ;
		ans += C(n , i) * solve(i , n - i) ;
		ans %= MOD ;
	}
	cout << ans << '\n';
	return 0 ;
}

