        facts[i] = facts[i - 1] * i;

    Mint ans = 0;
    for (int i = 0; i <= std::min(k, n); ++i) {
        Mint comb = facts[n] / (facts[n - i] * facts[i]);
        ans += Mint(n - i) / n * comb * comb;
    }

    std::cout << ans.a << std::endl;
}

