const int N = 100001;

int factorialNumInverse[N + 1]; 

// array to precompute inverse of 1! to N! 
int naturalNumInverse[N + 1]; 

// array to store factorial of first N numbers 
int fact[N + 1]; 

// Function to precompute inverse of numbers 
void InverseofNumber(int p) 
{ 
    naturalNumInverse[0] = naturalNumInverse[1] = 1; 
    for (int i = 2; i <= N; i++) 
        naturalNumInverse[i] = naturalNumInverse[p % i] * (p - p / i) % p; 
} 
// Function to precompute inverse of factorials 
void InverseofFactorial(int p) 
{ 
    factorialNumInverse[0] = factorialNumInverse[1] = 1; 

    // precompute inverse of natural numbers 
    for (int i = 2; i <= N; i++) 
        factorialNumInverse[i] = (naturalNumInverse[i] * factorialNumInverse[i - 1]) % p; 
} 

// Function to calculate factorial of 1 to N 
void factorial(int p) 
{ 
    fact[0] = 1; 

    // precompute factorials 
    for (int i = 1; i <= N; i++) { 
        fact[i] = (fact[i - 1] * i) % p; 
    } 
} 

// Function to return nCr % p in O(1) time 
int Binomial(int N, int R, int p) 
{ 
    // n C r = n!*inverse(r!)*inverse((n-r)!) 
    int ans = ((fact[N] * factorialNumInverse[R]) 
              % p * factorialNumInverse[N - R]) 
             % p; 
    return ans; 
} 

void solve()
{
    int ans = 0;
    int n,k;
    cin>>n>>k;

    InverseofNumber(mod); 
    InverseofFactorial(mod); 
    factorial(mod);

    if ( k == 1 )
    {
        ans -= 1;
    }

    int i = 0;
    while ( (2*n-i*k-2*i-1) >= 0 && (n-i*k-i*2) >= 0 )
    {
        ans += Binomial(n,i,mod)*Binomial(2*n-i*k-2*i-1,n-i*k-i*2,mod)*((i%2==0)?1:-1);
        ans %= mod;
        i++;
    }

    cout<<ans<<endl;
}

