// ******* LIB: C(k, n) mod MOD, using normal factorial and Mod Inverse ***************
//const int MOD = 1e9+7;
int fac(int n) { int ans = 1; FORE(i, 1, n) ans = (ans * i) % MOD; return ans; } // tinh tich tu 1 den n
int fac2(int st, int ed) {int ans=1; FORE(i, st, ed) ans = (ans*i)%MOD; return ans;} // tinh tich tu st den ed

int gcdExtended(int a, int b, int *x, int *y) {
    if (a == 0) { *x = 0, *y = 1; return b; }
    int x1, y1; int gcd = gcdExtended(b%a, a, &x1, &y1);
    *x = y1 - (b/a) * x1;    *y = x1;
    return gcd;
}
int modInverse(int a) { // not for a = 0
    int x, y;    int g = gcdExtended(a, MOD, &x, &y);
    if (g != 1) return -1;   else return (x%MOD + MOD) % MOD;
}
int C(int k, int n) { // k should be <= 10^6, but n an be 10^9
	if(k==n) return 1;
	// C(k,n) = n! / k! / (n - k)! = n*(n-1)*...*(n-k+1)/k!
	return ( fac2(n-k+1, n)*modInverse(fac(k)) )%MOD;  //this is O(k)
}
//*******************END LIB ******************
// PreCalculate C(k, n), n = const, k <= 1e6 ******
// C(k,n) = n! / k! / (n - k)! = n*(n-1)*...*(n-k+1)/k!  ==> C(k, n) = C(k-1, n) * (n-k+1)/k
// C(k-1,n) = n! / (k-1)! / (n - k + 1)! = n*(n-1)*...*(n-k+2)/(k-1)!
const int MAXK = 1e6;
int CN[MAXK];
void preCalc(int N) {
	CN[0] = 1L;
	for(int k = 1; k<=min(N, MAXK); ++k) CN[k] = ( (CN[k-1] * (N-k+1)) % MOD ) * modInverse(k);
}

// ************* END LIB ****************

// *********** PreCalculate C(k, n) using Pascal Triangle ************
//const int MOD = 1e9+7;
const int maxn = 5000; // thuat toan O(n^2), nhung neu n qua lon thi C vuot qua long long
long long CP[maxn + 1][maxn + 1];

void preCalcPascal() {
	CP[0][0] = 1L;
	for (int n = 1; n <= maxn; ++n) {
		CP[n][0] = CP[n][n] = 1L;
		for (int k = 1; k < n; ++k)
			CP[n][k] = ( CP[n - 1][k - 1] + CP[n - 1][k] ) % MOD;
	}
}
//****************************

// ************* END LIB **********************
/* Function to calculate x raised to the power y in O(logn)*/
//int const MOD = (int) 1e9+7;
int power(int x, unsigned int y) {
    if(y == 0) return 1;
    int temp = power(x, y/2);
    if (y%2 == 0) return (temp*temp)%MOD; else return (x*((temp*temp) % MOD)) % MOD;
}

// Neu can tinh x^y(n) voi y(n) phai tinh theo n, y(n) rat lon: KHONG DUOC TINH y(n) %MOD
// ma phai tinh y(n) % (MOD-1), vi theo Fermat: x^(MOD-1) % MOD = 1!!!

int n, k;

void solve() {
	cin >> n >> k;
	if(k>=n) {
		cout << C(n, 2*n-1) << endl; return; // C(k, n+k-1): xep k bong vao n ro
	}

	preCalc(n);

	int ans = 0;
	FORE(i, 0, k) { // co i phong khong nguoi
		int way = CN[i]; // so cach chon i phong khong nguoi = C(i, n)
		//int m = n - i = so phong phai co nguoi >=1, tong so nguoi = n => sau khi bo di m
		// nguoi thi phai xep n-m nguoi nay vao n-i phong => C(n-m, n-m+n-i-1) = C(i, n-1)
		// C(i, n-1) = ( C(i, n)/n ) * (n-i) suy ra;
		int conguoi = ( ( ( CN[i] * (n-i) )%MOD ) * modInverse(n) ) % MOD;
		ans = (ans + (way * conguoi)%MOD) % MOD;
	}
	cout << ans << endl;
}

