ll modnum = 1e9+7;

const int MAX = 200000 + 5;

long long fac[MAX], finv[MAX], inv[MAX];
// テーブルを作る前処理
void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % modnum;
        inv[i] = modnum - inv[modnum%i] * (modnum / i) % modnum;
        finv[i] = finv[i - 1] * inv[i] % modnum;
    }
}

// 二項係数計算
long long COM(int n, int k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % modnum) % modnum;
}


int main() {
    ll n,k; cin >> n >> k;


    // 二項係数を前処理で作っておく
    COMinit();

    // N個からi個の部屋を空きにする nCi
    // 残りの部屋(N-i)にi人の人を振り分ける (n-i)Hi -> (n-i+i-1)Ci -> n-1Ci
    // 空きの部屋がkより大だったら作れないのでそこで打ち切り
    ll ans = 0;
    rep(i, k+1) {
        // 全ての部屋を空にはできない
        if(i >= n) break;
        ans += COM(n, i) * COM(n-1, i);
        ans %= modnum;
    }
    cout << ans << endl;
    return 0;
}

