int modpower(int num, int mod, int to) {
  long ntemp = num;
  int ret = 1;
  for (int pow = 0; pow < 32; pow++) {
    if (to >> pow == 0) {
      return ret;
    }
    if ((to | 1 << pow) == to) {
      ret = (long)(ret * ntemp) % mod;
    }
    ntemp = (long)(ntemp * ntemp) % mod;
  }
  return ret;
}
