long long exp_mod(int a, int b, int m) {  // return a^b mod m
    long long ans = 1;
    long long tmp = a;
    while (b) {
        if (b & 1) {
            ans = (ans * tmp) % m;
        }
        b >>= 1;
        tmp = (tmp * tmp) % m;
    }
