const ll mod = 1e9 + 7;
const ll nmax = 4e5 + 5;
ll facts[nmax];

void calc_fact() {
  facts[0] = 1;
  for (ll i = 1; i < nmax; i++) {
    facts[i] = facts[i - 1] * i % mod;
  }
}

ll powmod(ll a, ll b) {
  ll ans = 1;
  while (b) {
    if (b % 2) {
      ans *= a;
      ans %= mod;
    }
    a *= a;
    a %= mod;
    b /= 2;
  }
  return ans;
}

ll comb(ll a, ll b) {
  return facts[a] * powmod(facts[b], mod - 2) % mod
                  * powmod(facts[a - b], mod - 2) % mod;
}

int main() {
  ll n, k;
  cin >> n >> k;

  calc_fact();

  ll ans = 0;
  if (n - 1 <= k) {
    ans = comb(2 * n - 1, n);
  } else {
    for (ll i = 0; i <= k; i++) {
      ans += (comb(n, i) * comb(n - 1, i)) % mod;
      ans %= mod;
    }
  }
  cout << ans << endl;
}

