inline int quickmul(int x, int y) {
    int ret = 1, mul = x;
    while (y) {
        if (y & 1) {
            ret = (LL)ret * mul % mod;
        }
        mul = (LL)mul * mul % mod;
        y >>= 1;
    }
    return ret;
}

inline int C(int n, int k) {
    return (LL)fac[n] * facinv[k] % mod * facinv[n - k] % mod;
}

inline void init() {
    fac[0] = facinv[0] = 1;
    for (int i = 1; i <= n + k; ++i) {
        fac[i] = (LL)fac[i - 1] * i % mod;
        facinv[i] = quickmul(fac[i], mod - 2) % mod;
    }
}

