#define MOD 1000000007LL
#define endl "\n"

ll modncr(ll n, ll r){
  auto modbeki = [](ll x, ll nn){
    ll res = 1;
    while(nn > 0){
      if(nn & 1) res = res * x % MOD;
      x = x * x % MOD;
      nn >>= 1;
    }
    return res;
  };

  if(n < r) return 0;
  if(r == 0 || r == n) return 1;
  if(r > n-r) r = n-r;

  ll a = 1, b = 1;
  for(int i = 0; i < r; i++){
    a *= (n - i);
    a %= MOD;
  }
  for(int i = 0; i < r; i++){
    b *= (i + 1);
    b %= MOD;
  }
  ll c = modbeki(b, MOD-2);
  return a * c % MOD;
}

ll nhr(ll n, ll r){return modncr(n+r-1, r);}

int main(){
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  ll n, k;
  cin >> n >> k;
  if(k >= n-1){
    cout << nhr(n+1, n-1) << endl;
    return 0;
  }
  if(k == 1){
    cout << modncr(n, 1LL) * modncr(n-1LL, 1LL) << endl;
  }
  ll ans = 0LL;
  if(k < n/2){
    for(ll i = 0LL; i <= k; i++){
      ans += modncr(n, i) * nhr(n-i, i) % MOD;
      ans %= MOD;
    }
  }
  else{
    ans = nhr(n+1, n-1);
    for(ll i = n-1LL; i >= k+1; i--){
      ans -= modncr(n, i) * nhr(n-i, i) % MOD;
      ans %= MOD;
    }
  }
  if(ans < 0) ans += MOD;
  cout << ans << endl;
}

