#include <bits/stdc++.h>

using namespace std;

const int N = 2e5+5;

const int mod = 1e9+7;

long long inv[N];
long long fac[N];
long long finv[N];

void cominit(){
    fac[0] = fac[1] =1;
    finv[0] = finv[1] =1;
    inv[1] = 1;
    for(int i = 2; i < N; i++){
        fac[i] = fac[i - 1] * i % mod;
        inv[i]= mod - inv[mod % i] * (mod / i) % mod;
        finv[i]= finv[i - 1] * inv[i] % mod;
    }
}

long long nCr(long long n , long long r){
    if(n == r)
        return 1;
    if(r == 0)
        return 1;
    if(n < r)
        return 0;
    if(n < 0 || r < 0)
        return 0;
    return fac[n] * (finv[r] * finv[n - r] % mod) %mod;
}

void add_self(int & ans , int add){
    long long tmp = ans;
    tmp += add;
    tmp %= mod;
    ans = tmp;
}

int main(){
    cominit();
    int n , k;
    scanf("%d%d" , &n , &k);
    int ans = 0;
    for(int i = 0; i <= min(n-1 , k); i++){
        add_self(ans , nCr(n , i) * nCr(n - 1 , n - i - 1) % mod);
    }
    printf("%d\n" , ans);
}

