{
    SQWORD sqN = inputSQWORD();
    SQWORD sqK = inputSQWORD();

    MODINT miComb1 = 1;
    MODINT miComb2 = 1;

    MODINT miAns(0);
    SQWORD sqLoopMax = min(sqN - 1, sqK);
    for (SQWORD sqIdx = 0; sqIdx <= sqLoopMax; sqIdx++) {
        miAns += miComb1 * miComb2;

        if (sqIdx != sqLoopMax) {
            miComb1 *= (sqN - sqIdx);
            miComb1 /= (sqIdx + 1);

            miComb2 *= (sqN - 1 - sqIdx);
            miComb2 /= (sqIdx + 1);
        }
    }
    printf("%lld\n", miAns);

    return 0;
