lint pow(lint num, lint e, lint MOD) {
    lint res = 1;
    lint cur_num = num;
    while (e) {
        if (e & 1) {
            res *= cur_num;
            res %= MOD;
        }
        cur_num *= cur_num;
        cur_num %= MOD;
        e >>= 1;
    }
    return res;
}

int main() {
    cin.tie(0); cout.tie(0);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(10);
    const lint MOD = 1e9 + 7;
    lint n, k; cin >> n >> k;
    vec<lint> factorial(2 * n + 10, 1), inv_factorial(2 * n + 10, 1);
    range(i, 1, 2 * n + 10) {
        factorial.at(i) = factorial.at(i - 1) * i % MOD;
        inv_factorial.at(i) = pow(factorial.at(i), MOD - 2, MOD);
    }
    auto comb = [&](lint n, lint m) {
        return factorial.at(n) * inv_factorial.at(m) % MOD * inv_factorial.at(n - m) % MOD;
    };
    lint ans;
    if (k >= n - 1) ans = factorial.at(2 * n - 1) 
                        * inv_factorial.at(n) % MOD
                        * inv_factorial.at(n - 1) % MOD;
    else {
        ans = 0;
        range(d, 0, k + 1) {
            ans += comb(n, d) * comb(n - d + d - 1, n - d - 1) % MOD;
            ans %= MOD;
        }
    }
    if (k % 2) ans -= 1;
    if (ans < 0) ans += MOD;
    cout << ans << "\n";
}

