ll mod_pow(ll x, ll n, ll mod){
    //xのn乗を計算するのにn乗を2進表記にして計算
    //x^22 = x^16 + x^4 + x^2
    ll ret=1;
    while(n>0){
        if(n&1){
            ret=(ret*x)%mod;//答えに付加
        }
        x=(x*x)%mod;//2乗
        n >>=1;
    }
    return ret;
}
ll cmb(ll nn, ll kk){
    ll bunsi=1;
    ll bunbo=1;
    for(int i=0;i<kk;i++){
        bunsi*=(nn-i);
        bunsi%=1000000007;
        bunbo*=(kk-i);
        bunbo%=1000000007;
    }
    //((A%MOD)*modpow(B,MOD-2))%MOD
    return bunsi%1000000007*mod_pow(bunbo,1000000007-2,1000000007)%1000000007;
}
