int quick_power(int a,int b)
{
	int res=1;
	for (;b;b=b>>1,a=(a*a)%mod)
	{
		if (b&1)  res=(res*a)%mod;
	}
	return res;
}

int ny(int n)
{
	return quick_power(n,mod-2)%mod;
}

int C(int n,int k)
{
	if (k<=0||n==k)  return 1;
	if (2*k>n)  k=n-k;

	return ((jc[n]*ny(jc[n-k])%mod)*ny(jc[k]))%mod;
}

