    vector<ModInt> f = factorial(1000000);
    ModInt ans = 1; // k >= 2
    for(LL i = 1; i <= k && i <= n-1; ++i){
        ModInt cnt = combination(n, i, f);
        cnt *= combination(n-i+i-1, i-1, f);
        ans += cnt;
    }
    cout << ans.get() << endl;
    return 0;
}

