		finv[i] = finv[i-1] * inv[i] % p;
	}
}

// 組み合わせ nCr(mod m)
ll nCr(int n, int r){
	int m = MOD;
	if(n<r || n<0 || r<0) return 0;
	return fac[n] * (finv[n-r] * finv[r] % m) % m;
}

// 重複組合せ nHr(mod m)
// {n}_H_{r} = {n+r-1}_C_{r}
// ll nHr(int n, int r){return nCr(n+r-1,r);}
#define nHr(n,r) nCr((n)+(r)-1,(r))

ll solve(){
	init(N);
	K = min(K, N-1);
	ll ans = 0;
	rp(k,0,K+1){
		ll x = nCr(N,k) * nHr(N-k,k) % MOD;
		ans = (ans + x) % MOD;
	}
	return ans;
}

int main(){
	cin>>N>>K;
	cout<< solve() <<endl;
}

