Fp solve() {
  ll N, K; cin >> N >> K;

  if (N == 2 && K == 2) return 1;
  Comb cb(2*N);
  if (K >= N) return cb.comb(2*N-1, N);
  Fp tot = 0;
  for (ll k = 0; k <= K; k++) {
    tot += cb.comb(N, k) * cb.comb(N-1, k);
  }
  return tot;
}

