    nCk1[0]=1;
    REP2(i,1,n+1){
        nCk1[i]=((nCk1[i-1]*((n-i+1)%MOD))%MOD*mod_pow((ll)i,MOD-2,MOD))%MOD;
    }

    //nCk列挙
    n=N-1;
    vector<int> nCk2(n+1);
    nCk2[0]=1;
    REP2(i,1,n+1){
        nCk2[i]=((nCk2[i-1]*((n-i+1)%MOD))%MOD*mod_pow((ll)i,MOD-2,MOD))%MOD;
    }

    REP(i,min(n+1,k+1)){
        ans+=(((ll)nCk1[i]*(ll)nCk2[i])%MOD);
        ans%=MOD;
    }

