using namespace std;
using i64 = long long;

i64 p = 1000000007LL;

i64 powmod(i64 x, i64 y)
{
    if (y == 1)
        return x % p;
    if (y % 2 == 1)
        return (x * powmod(x, y - 1)) % p;

    i64 pwmd = powmod(x, y / 2) % p;
    return (pwmd * pwmd) % p;
}

i64 bicomod(int n, int a)
{
    if (n == a)
        return 1;
    if (a > n / 2)
        return bicomod(n, n - a);
    i64 anom = 1;
    i64 adom = 1;
    for (int i = 1; i <= a; i++)
        anom = anom * i % p;
    for (int i = n - a + 1; i <= n; i++)
        adom = adom * i % p;

    return (adom * powmod(anom, p - 2)) % p;
}

int main()
{
    i64 n, k;
    cin >> n >> k;

    i64 mmax = min(n - 1, k);
    i64 result = 0;
    vector<i64> bincoe(mmax + 20);
    bincoe[1] = n;

    for (i64 m = 1; m <= mmax; m++)
    {
        if (m > n / 2LL)
        {
            bincoe[m] = bincoe[n - m];
            result += ((bincoe[m] * bincoe[m] % p) * ((n - m) * powmod(n, p - 2) % p)) % p;
            result %= p;
            continue;
        }
        result += ((bincoe[m] * bincoe[m] % p) * ((n - m) * powmod(n, p - 2) % p)) % p;
        result %= p;
        bincoe[m + 1] = ((bincoe[m] * (n - m) % p) * powmod(m + 1, p - 2)) % p;
    }

    cout << result + 1 << endl;

    return 0;
}

