struct nCk{
	long long pow(long long x,long long n){
		long long ret=1;
		if(n>0){
			ret=pow(x,n/2);
			if(n%2==0){
				(ret=(ret*ret))%=mod;
			}else{
				(ret=((ret*ret)%mod)*x)%=mod;
			}
		}
		return ret;
	}
	long long inv(long long n){
		return pow(n,mod-2);
	}
	long long nck(long long n,long long k){
		long long ret=1;
		for(int i=n;i>n-k;i--){
			(ret*=i)%=mod;
		}
		for(int i=k;i>=1;i--){
			(ret*=inv(i))%=mod;
		}
		return ret;
	}
};
int main(){
	long long n,k;
	cin>>n>>k;
	 nCk nii;
	if(k>=n-1){
		cout<<nii.nck(2*n-1,n)<<endl;
	}else{
		long long ans=0;
		for(int i=0;i<=k;i++){
			(ans+=(nii.nck(n,i)*nii.nck(n-1,i)))%=mod;
		}
		cout<<ans<<endl;
	}
	return 0;
}

