constexpr long long int MOD = 1000000007;
static std::vector<long long int> factorial, inverse_factorial;
long long int power(long long int base, long long int exp) {
	switch (exp) {
	case 0: return 1;
	case 1: return base % MOD;
	default: return power(base, exp & 1) * power(base * base % MOD, exp >> 1) % MOD;
	}
}
long long int combination(int n, int r) {
	return factorial[n] * inverse_factorial[n - r] % MOD * inverse_factorial[r] % MOD;
}
long long int make_empty(long long int n, long long int empty) {
	return combination(n, empty) * combination(n - 1, n - empty - 1) % MOD;
}
