#include <iostream>
#include <vector>

long long modinv(long long n, long long P) {
	long long a = P, u = 1, v = 0;
	while (a) {
		long long t = n / a;
		n -= t * a;
		std::swap(n, a);
		u -= t * v;
		std::swap(u, v);
	}
	u %= P;
	if (u < 0) u += P;
	return u;
}

template<long long MOD> struct modint {
	long long value;
	void f() {
		if (0 <= value && value < MOD) return;
		value %= MOD;
		if (value < 0) value += MOD;
	}
	modint(long long n) : value(n) {f();}
	modint<MOD> operator+(modint<MOD> right) {
		modint<MOD> ret = (this -> value) + right.value;
		return ret;
	}
	modint<MOD> operator-(modint<MOD> right) {
		modint<MOD> ret = (this -> value) - right.value;
		return ret;
	}
	modint<MOD> operator*(modint<MOD> right) {
		modint<MOD> ret = (this -> value) * right.value;
		return ret;
	}
	modint<MOD> operator/(modint<MOD> right) {
		modint<MOD> ret = (this -> value) * modinv(right.value, MOD);
		return ret;
	}
	modint<MOD> operator+=(modint<MOD> right) {return *this = *this + right;}
	modint<MOD> operator-=(modint<MOD> right) {return *this = *this - right;}
	modint<MOD> operator*=(modint<MOD> right) {return *this = *this * right;}
	modint<MOD> operator/=(modint<MOD> right) {return *this = *this / right;}
	bool operator==(modint<MOD> right) {return ((this -> value) == right.value);}
	bool operator!=(modint<MOD> right) {return ((this -> value) != right.value);}
};
template<long long MOD> modint<MOD> operator+(long long left, modint<MOD> right) {
	return right + left;
}
template<long long MOD> modint<MOD> operator-(long long left, modint<MOD> right) {
	return right * -1 + left;
}
template<long long MOD> modint<MOD> operator*(long long left, modint<MOD> right) {
	return right * left;
}
template<long long P> modint<P> operator/(long long left, modint<P> right) {
	return modinv(right.value, P) * (left % P);
}

template<long long MOD> modint<MOD> modpow(modint<MOD> a, long long n) {
	if (n == 0) return 1;
	if (a == 0) return 0;
	modint<MOD> ret = a;
	long long cnt = 1;
	while (cnt * 2 <= n) {
		ret *= ret;
		cnt *= 2;
	}
	return ret * modpow(a, n - cnt);
}

std::vector<long long> factorial;
std::vector<long long> factorial_inv;

template<long long P> void make_table(int n) {
	factorial.resize(n + 1, 1); factorial_inv.resize(n + 1, 1);
	for (int i = 1; i <= n; i++) factorial[i] = factorial[i - 1] * i % P;
	factorial_inv[n] = modinv(factorial[n], P);
	for (int i = n - 1; i >= 0; i--) factorial_inv[i] = factorial_inv[i + 1] * (i + 1) % P;
}

template<long long P> modint<P> permutation(int n, int r) {
	if (n <= factorial.size()) return factorial[n] * factorial_inv[n - r];
	std::cerr << "attention : factorial table is not constructed" << std::endl;
	r = std::min(r, n - r);
	modint<P> ret = 1;
	for (int i = 0; i < r; i++) ret *= n - i;
	return ret;
}

template<long long P> modint<P> combination(int n, int r) {
	if (n <= factorial.size()) return permutation<P>(n, r) * factorial_inv[r];
	std::cerr << "attention : factorial table is not constructed" << std::endl;
	r = std::min(r, n - r);
	modint<P> ret = 1;
	for (int i = 0; i < r; i++) {
		ret *= n - i;
		ret /= i + 1;
	}
	return ret;
}

template<long long MOD> std::ostream& operator<<(std::ostream& os, const modint<MOD>& target) {
	os << target.value; return os;
}

int main() {
	constexpr int P = 1000000007;
	int n, k;
	std::cin >> n >> k;
	modint<P> ans = 0;
	make_table<P>(200000);
	for (int i = 0; i <= std::min(k, n - 1); i++) {
		ans += combination<P>(n, i) * combination<P>(i + n - i - 1, n - i - 1);
	}
	std::cout << ans << '\n';
}

