using namespace std;
using ll = long long;
using ii = pair<ll, ll>;

const int MAX { 200010 };
const ll MOD { 1000000007 }, oo { 1LL << 62 };

ll mod_pow(ll a, ll n)
{
    ll res = 1, base = a;

    while (n)
    {
        if (n & 1)
            res = (res * base) % MOD;

        base = (base * base) % MOD;
        n >>= 1;
    }

    return res;
}

ll mod(ll a)
{
    return (((a % MOD) + MOD) % MOD);
}

ll binom(ll n, ll m)
{
    ll a = min(m, n - m);
    ll b = max(m, n - m);

    ll num = 1;

    for (ll i = n; i > b; --i)
        num = mod(num * i);

    ll den = 1;

    for (ll i = 2; i <= a; ++i)
        den = mod(den * i);

    auto inv = mod_pow(den, MOD - 2);

#ifdef DEBUG
//cout << "a = " << a << ", b = " << b << endl;
//cout << "num = " << num << ", den = " << den << endl;
//cout << "inv = " << inv << endl;
#endif
    return mod(num * inv);
}

ll solve(ll N, ll K)
{
    if (K >= N - 1)
        return binom(2*N - 1, N - 1);

    ll ans = 0;

    for (int i = 0; (K + 2)*i <= N; ++i)
    {
        ll x = i ? -1 : 1;

#ifdef DEBUG
    cout << "x = " << x << endl;
    cout << "binom(" << N << ", " << i << ") = " << binom(N, i) << endl;
    cout << "binom(" << N  + (N - (K + 2)*i) - 1 << ", " << N - (K + 2)*i << ") = " << binom(N + (N - (K + 2)*i) - 1, N - (K + 2)*i) << endl;
#endif
        x = mod(x * binom(N, i));
        x = mod(x * binom(N + (N - (K + 2)*i) - 1, N - (K + 2)*i));

        ans = mod(ans + x);
    }

    return ans;                
}

int main()
{
    ios::sync_with_stdio(false);

    ll N, K;
    cin >> N >> K;

    auto ans = solve(N, K);

    cout << ans << '\n';

    return 0;
}

