    ll n,k;cin>>n>>k;
    ll ans=0;
    rep(i,min(n+1,k+1)){
        ll s=modcom(n,i);
        ans+=s*modcom(n-(n-i)+(n-i-1),(n-i-1))%mod;
        ans%=mod;
    }
    out(ans);
}

