void treeDFS(int from, int current, int dist, int &maxDist, int &maxVertex)
{
    if (dist > maxDist)
    {
        maxDist = dist;
        maxVertex = current;
    }

    for (auto to : G[current])
    {
        if (to == from)
            continue;
        treeDFS(current, to, dist + 1, maxDist, maxVertex);
    }
}

pair<int, int> getTreeDiameter()
{
    int start = 0, end = 0, maxDist = 0;
    treeDFS(-1, start, 0, maxDist, end);
    start = end, end = 0, maxDist = 0;
    treeDFS(-1, start, 0, maxDist, end);
    return make_pair(start, end);
}

void solve(long long n, long long k)
{
    ll ans = 0;
    COMinit();
    for (int i = 0; i < n; i++)
    {
        //i は人がいない部屋の数
        if (i == 0)
        {
            ans = (ans + 1) % MOD;
        }
        else if (i == (n - 1))
        {
            if (i <= k)
            {
                ans = (ans + n) % MOD;
            }
        }
        else
        {

            if (i <= k)
            {
                ll tmp = 0;
                tmp = COM(n - 1, n - i - 1);
                tmp = mulMod(tmp, COM(n, i));
                ans = (ans + tmp) % MOD;
            }
        }
    }
    cout << ans % MOD << endl;
}

