int N, K;
unordered_map<int, long long> cache;

long long exp_mod(int a, int b, int m) {  // return a^b mod m
    long long ans = 1;
    long long tmp = a;
    while (b) {
        if (b & 1) {
            ans = (ans * tmp) % m;
        }
        b >>= 1;
        tmp = (tmp * tmp) % m;
    }
    return ans;
}

long long inv(int a, int m) {  // return a-1
    return exp_mod(a, m - 2, m);
}

long long ncr_mod(int n, int r, int m) {  // return nCr mod m
    if (n == N) {
        return cache[r];
    } else if (n == N - 1) {
        return cache[r] * (N - r) * inv(N, MOD) % MOD;
    }
    long long ret = 1;
    for (int i = 0; i < r; ++i) {
        ret = (ret * (n - i)) % m;
        ret = (ret * inv(1 + i, m)) % m;
    }
    return ret;
}

long long nhr_mod(int n, int r, int m) {  // return nHr mod m
    return ncr_mod(n + r - 1, r, m);
}

void preprocess() {  // preprocess NC1, NC2, ... NCN
    for (int i = 1; i <= N; ++i) {
        if (i == 1) {
            cache[i] = N;
        } else {
            cache[i] = cache[i - 1] * (N - i + 1) * inv(i, MOD) % MOD;
        }
    }
}

int main() {
