LL modpow(LL base, LL p) {
	if (p == 0)return 1;
	if (p == 1)return base;
	LL temp = modpow(base, p / 2);
	temp = (temp * temp) % MOD;
	if (p & 1)temp = (temp * base) % MOD;
	return temp;
}

