/*
 * 首先, 如果 k>=n 的话, 显然我们可以构造出所有状态, 相当于n个相同球放到
 * n个相同盒中, 盒子可以空. 即 C(n+n-1,n) (by start and bar).
 *
 * k<n 的情况即必须要有 n-k 个盒子非空, 我们把所有情况算出来去掉不合法情
 * 况即可. 不合法情况: 仅有x个盒子非空 x∈[1,n-k-1], 相当于n个球放到x个盒
 * 子里每个盒子都非空的情况, 算一算即可.
 */

const int mod = 1e9+7;
const int maxn = 5e5;
int fac[maxn], inv[maxn];

int pow(const int a, const int p)
{
    int x = a, ans = 1;
    FOR(i,0,31) {
        if (p & (1<<i)) {
            ans = 1LL * ans * x % mod;
        }
        x = 1LL * x*x % mod;
    }
    return ans;
}

int cnk(const int n, const int k)
{ return 1LL * fac[n] * inv[n-k] % mod * inv[k] % mod; }

int main()
{
#ifdef foo_
    freopen("foo", "rt", stdin);
#endif
    ios::sync_with_stdio(false);
    fac[0] = inv[0] = 1;
    FOR(i,1,maxn) {
        fac[i] = 1LL*i*fac[i-1] % mod;
        inv[i] = pow(fac[i], mod-2);
    }
    int n,k;
    while (cin >> n >> k) {
        int ans = cnk(n+n-1,n);
        if (k < n) {
            FOR(x,1,n-k) {
                const int y = n-x;
                ans -= 1LL * cnk(n,x) * cnk(x+y-1,y) % mod;
                ans %= mod;
            }
        }
        ans += mod;
        ans %= mod;
        cout << ans << endl;
    }
    return 0;
}

