template <long long Mod = MOD>
class Factorial {
 private:
  int n;

 public:
  vector<long long> fac, inv;

 public:
  Factorial(long long n) : n(n), fac(n + 1), inv(n + 1) {
    fac[0] = 1;
    for (int i = 0; i < n; ++i) fac[i + 1] = fac[i] * (i + 1) % Mod;
    inv[n] = modpow(fac[n], Mod - 2);
    for (int i = n - 1; i >= 0; --i) inv[i] = inv[i + 1] * (i + 1) % Mod;
  };
  long long modpow(long long a, long long n, long long mod = Mod) {
    long long i = 1, ret = 1, p = a;
    while (i <= n) {
      if (i & n) {
        ret = (ret * p) % mod;
      }
      i = (i << 1);
      p = (p * p) % mod;
    }
    return ret;
  }
  long long C(int a, int b) {
    return (fac[a] * inv[b] % Mod) * inv[a - b] % Mod;
  }
  long long P(int a, int b) {
    return (fac[a]) * inv[a - b] % Mod;
  }
  long long H(int a, int b) {  //The number of multisets of length b on a symbols
    return C(a + b - 1, b);
  }
};
class Solver2 {
 public:
  int n, k;
  Factorial<> fac;
  Solver2(LL n, LL k) : n(n), k(k), fac(500000){};

  void solve() {
    Modint<> ans(0);
    for (int emp = 0; emp < n && emp <= k; emp++) {
      if (k == 1 && emp == 0) continue;
      Modint<> tmp(1);
      tmp *= fac.C(n, emp);
      if (emp < 5) DBG(emp, tmp)
      tmp *= fac.H(n - emp, emp);
      ans += tmp;
      if (emp < 5) DBG(emp, tmp)
    }
    cout << ans << endl;
  }
};
