const LL kai_MAX = 400001;
vector<LL> kai(kai_MAX);
vector<LL> kai_inv(kai_MAX);

LL powMod(LL num, LL n, LL mod = (LL)MOD) {//(num**n)%mod
	num %= mod;//
	if (n == 0) {
		return (LL)1;
	}
	LL mul = num;
	LL ans = (LL)1;
	while (n) {
		if (n & 1) {
			ans = (ans * mul) % mod;
		}
		mul = (mul * mul) % mod;
		n >>= 1;
	}
	return ans;
}
LL mod_inverse(LL num, LL mod = MOD) {
	return powMod(num, MOD - 2, MOD);
}

LL nCk(LL N, LL k, LL mod = MOD) {
	LL ans = 1;
	if (k == 0 || k == N) {
		return 1;
	}
	ans = (kai[N] * kai_inv[N - k]) % mod;
	ans = (ans * kai_inv[k]) % mod;
	return ans;
}
void solve() {
	LL N, K;
	cin >> N >> K;

	kai[0] = 1; //kai_inv[0] = mod_inverse(1);
	kai[1] = 1; kai_inv[1] = mod_inverse(1);

	for (int i = 2; i < kai_MAX; ++i) {
		kai[i] = (kai[i - 1] * i) % MOD;
		kai_inv[i] = mod_inverse(kai[i]);
	}

	LL ans;
	if (K >= N) {
		K = N;
		ans = 1;
	}
	else {
		ans = 1;//0人
	}

	for (int k = 1; k <= K; ++k) {
		if (N - 1 < k) {
			continue;
		}
		ans += (nCk(N,k) *nCk((N-k-1)+k, k)) % MOD;
		ans %= MOD;
	}
	cout << ans << endl;
}

