long long quickpow(long long b, int e)
{
	return e ? ((e & 1 ? b : 1)*quickpow(((b%MOD)*(b%MOD)) % MOD, e >> 1)) % MOD : 1;
}

long long gun(int a)
{
	long long ret = 1;
	for (int i = a; i > 0; i--) {
		ret *= i;
		ret %= MOD;
	}
	return ret;
}

long long fun(int a, int b)
{
	long long ret = gun(a);
	ret *= quickpow(gun(b), MOD - 2);
	ret %= MOD;
	ret *= quickpow(gun(a - b), MOD - 2);
	ret %= MOD;
	return ret;
}

int main()
{
