		for (int i = 1; i <= k; i++) {
			int m = n - i;
			int u = n - m;
			long long tmp = fun(u + m - 1, m - 1);
			tmp *= fun(n, i);
			tmp %= MOD;
			ans += tmp;
			ans %= MOD;
		}
	}
