	if ( n < 0 || r < 0 ) return ( 0 );
	if ( r == 0 ) return ( 1 );
	if ( r > n - r ) r = n - r;

	mint f = 1; for ( ll x = 0; x < r; ++x ) f *= ( ( n - x ) % MOD );
	mint t = 1; for ( ll x = 2; x <= r; ++x ) t *= ( x % MOD );
	t = modpow( t, MOD - 2 );

	return ( f * t );
}

