#include <iostream>

namespace cplib {
    template <int64_t mod>
    class ModInt {
        public:
        int64_t val;

        ModInt(): val(0) {}
        ModInt(int64_t init_val): val(
            init_val >= 0? init_val % mod: mod - (-init_val) % mod
        ) {}

        bool operator !() {return val != 0;}
        ModInt operator -() {return ModInt(-val);}
        bool operator ==(ModInt rhs) {return val == rhs.val;}
        bool operator !=(ModInt rhs) {return val != rhs.val;}

        ModInt& operator ++() {
            val++;
            if (val == mod) val = 0;
            return *this;
        }
        ModInt operator ++(int) {
            ModInt res = *this;
            val++;
            if (val == mod) val = 0;
            return res;
        }
        ModInt& operator --() {
            if (val == 0) val = mod;
            val--;
            return *this;
        }
        ModInt operator --(int) {
            ModInt res = *this;
            if (val == 0) val = mod;
            val--;
            return res;
        }

        ModInt& operator +=(ModInt rhs) {
            val += rhs.val;
            if (val >= mod) val -= mod;
            return *this;
        }
        ModInt& operator -=(ModInt rhs) {
            val -= rhs.val;
            if (val < 0) val += mod;
            return *this;
        }
        ModInt& operator *=(ModInt rhs) {
            val = (val * rhs.val) % mod;
            return *this;
        }
        ModInt& operator /=(ModInt rhs) {
            int64_t base = rhs.val, res = 1, pow = mod - 2;
            while (pow > 0) {
                if (pow % 2 == 1) res = (res * base) % mod;
                base = (base * base) % mod;
                pow /= 2;
            }
            val = (val * res) % mod;
            return *this;
        }

        ModInt operator +(ModInt rhs) {return ModInt(*this) += rhs;}
        ModInt operator -(ModInt rhs) {return ModInt(*this) -= rhs;}
        ModInt operator *(ModInt rhs) {return ModInt(*this) *= rhs;}
        ModInt operator /(ModInt rhs) {return ModInt(*this) /= rhs;}

        friend std::istream& operator >>(std::istream& is, ModInt& target) {
            int64_t init_val;
            is >> init_val;
            target = ModInt(init_val);
            return is;
        }
        friend std::ostream& operator <<(std::ostream& os, ModInt source) {
            os << source.val;
            return os;
        }
    };
}

