        inv[i] = MOD - inv[MOD % i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }

    auto C = [&](ll n, ll r) {
        return fact[n] * finv[n-r] % MOD * finv[r] % MOD;
    };
    auto H = [&](ll n, ll r) {
        return C(n+r-1, r);
    };

    ll ans = 0;

    for (int i = 0; i <= min(N-1, K); i++) {
        ans = (ans + C(N, i) * H(N-i, i) % MOD) % MOD;
    }

    cout << ans << endl;
}

