	int fpow(int a, int b, int mod = MOD) {
	    int res = 1;
	    while (b > 0) {
	        if (b & 1) res = res * a % mod;
	        a = a * a % mod;
	        b >>= 1;
	    }
	    return res;
	}
	int sum(int a, int b){
		int res = (a + b)%MOD;
		return res < 0 ? res + MOD: res;
	}
	int mul(int a, int b){
		return (a * b)%MOD;
	}
	void set_factorial(){
		fac[0] = fac[1] = 1;
		for(int i = 2 ; i < MAXN ; i ++)
			fac[i] = fac[i - 1] * i % MOD;
		ifac[MAXN - 1] = fpow(fac[MAXN - 1], MOD - 2);
		for(int i = MAXN - 2 ; i >= 0 ; i --)
			ifac[i] = ifac[i + 1] * (i + 1) % MOD;
	}
	int C(int a, int b){
		return ((fac[b]*ifac[a])%MOD)*ifac[b - a]%MOD;
	}
	int candy(int a, int b, int c){
		// chia a keo cho b nguoi min c
		return C(b - 1, a - b*(c - 1) - 1);
	}
}
