ll MOD = 1000000007;

template<typename T>
T mod_pow(T a, int p)
{
	if (p == 0)return 1;
	else if (p == 1)return a;
	else if (p % 2 == 0)
	{
		ll h = mod_pow(a, p / 2);
		return h * h % MOD;
	}
	else return (mod_pow(a, p - 1) * a) % MOD;
}



void solve()
{	
	ll n,k; cin >> n>>k;
	ll e_max=min(n-1,k);
	ll ans=0;
	vector<ll> fact(n+1,1);
	vector<ll> fact_inv(n+1,1);
	rep(i, n)
	{
		fact[i+1]=(fact[i]*(ll)(i+1))%MOD;
		fact_inv[i+1]=fact_inv[i]*mod_pow((ll)(i+1),MOD-2)%MOD;
	}

	rep(i,e_max+1)
	{
		ll tmp=(((fact[n]*fact_inv[i])%MOD)*fact_inv[n-i])%MOD;
		tmp%=MOD;
		tmp*=(((fact[n-1]*fact_inv[i])%MOD)*fact_inv[n-i-1])%MOD;
		ans+=tmp;
		ans%=MOD;
	}
	cout << ans << endl;
	return;
}

