#define N 200005
#define mod 1000000007
ll powmod(ll a, ll b){
	ll res = 1;
	a %= mod;
	while(b) {
		if(b & 1) {
			res = res * a % mod;
		}
		b >>= 1;
		a = a * a % mod;
	}
	return res % mod;
}
ll fac[N], inv[N];
void init() {
	fac[0] = 1;
	for(int i = 1; i < N; i++) {
		fac[i] = fac[i - 1] * i % mod;
	}
	inv[N - 1] = powmod(fac[N - 1], mod - 2);
	for(int i = N - 2; i >= 0; i--) {
		inv[i] = inv[i + 1] * (i + 1) % mod;
	}
}
ll c(ll n, ll m) {
	if(m > n) {
		return 0;
	}
	if(m == 0) return 1;
	if(n < N) return fac[n] * inv[m] % mod * inv[n - m] % mod;
	//c(m,k) = m!/(k! * (m - k))= m-k+1~m/(k!)
	ll res = inv[m];
	for(int i = n - m + 1; i <= n; i++) {
		res = res * i % mod;
	}
	return res;
}
ll a[200005];
int main() {
	init();
	int n,k;
	scanf("%d%d",&n,&k);
	if(k >= n - 1) {
		printf("%lld\n",c(2 * n - 1, n) % mod);
		return 0;
	}
	ll res = 0;
	a[0] = 1;
	a[1] = n * c(n - 1, 1) % mod;
	if(k >= 2) a[2] = ((a[0] + a[1]) % mod + n * c(n - 1 , 2) % mod) % mod;
	for(int i = 3; i <= min(k, n - 1); i++) {
		a[i] = (a[i - 1] + n * c(n - 1, i - 1) % mod) % mod;
		for(int j = 2; j <= i; j++) {
			if(j > n - j) break;
			a[i] =(a[i] + c(n, j) * c(n - j, j) % mod) % mod; 
		}
	}
	cout<<a[min(k,n - 1)]<<endl;
}

