constexpr int MOD = 1000000007;

int mod(const ll &x){
    return x > 0 ? x % MOD : (x+MOD) % MOD;
}

int modm(const ll &x,const ll &m){
    return (x % MOD) * (m % MOD) % MOD;
}

int modpow(ll x, ll p) {
    int ret = 1;
    while(p > 0) {
        if (p & 1) ret = modm(ret,x);
        x = modm(x,x);
        p >>= 1;
    }
    return ret;
}

// x * modinv(d)
int modd(ll x,ll d) {
    return modm(x,modpow(d,MOD-2));
}

int main(void)
{
    IOS
    constexpr int FACT = 400005;
    int fact[FACT];
    fact[0] = 1;
    FOR(i,1,FACT) fact[i] = modm(fact[i-1],i);
    auto comb = [&](int x,int y) {
    int r = fact[x];r = modd(r,fact[y]);r = modd(r, fact[x-y]);return r;};
    // n種類のものから重複を許してr個配った時の組み合わせ数(重複組み合わせnHr)
    auto multicomb = [&](int n,int r) {return comb(n+r-1,r);};

    int n, k;
    cin >> n >> k;
    int ans = 0;
    if (n-1 <= k) ans = multicomb(n,n);
    else {
        REP(i,k) ans += modm(comb(n,i) , multicomb(n-i,i));
    }

    cout << ans << '\n';

    return 0;
}

