using namespace std;
typedef long long ll;
const ll Mod = (ll) (1e9) + 7;
#define rep(i, n) for (int i = 0; i < (int)(n); ++i)
ll modinv(ll a, ll m) {
  long long b = m, u = 1, v = 0;
  while (b) {
    long long t = a / b;
    a -= t * b;
    swap(a, b);
    u -= t * v;
    swap(u, v);
  }
  u %= m;
  if (u < 0)
    u += m;
  return u;
}
struct combination {
  vector<ll> fact, ifact;
  combination(int n) :
      fact(n + 1), ifact(n + 1) {
    assert(n < Mod);
    fact[0] = 1;
    for (int i = 1; i <= n; i++)
      fact[i] = (fact[i - 1] * i) % Mod;
    ifact[n] = modinv(fact[n], Mod);
    for (int i = n; i >= 1; i--)
      ifact[i - 1] = (ifact[i] * i) % Mod;
  }
  ll operator()(int n, int k) {
    if (k < 0 || k > n)
      return 0;
    return ((fact[n] * ifact[k] % Mod) * ifact[n - k]) % Mod;
  }
};
int main() {
  ll n, k, ans = 0;
  cin >> n >> k;
  k = min(k, n - 1);
  combination c(n);
  rep(i,k+1)
  {
    ans += c(n, i) * c(n - 1, i);
    ans %= Mod;
  }
