    cin >> n >> k;
    combination comb = combination(n);

    k = min(k, n);

    mint ans = 0;
    for (int64 i=0; i<=k; i++) {
        ans += comb.nCr(n,i) * comb.nCr(n-1,i);
    }

    cout << ans << endl;

}

