struct modint{
    //member variable

    long long x;

    //constructor

    modint(long long x = 0):x((x%mod+mod)%mod){}

    //operator

    modint& operator+=(const modint ob){
        if((x += ob.x) >= mod) x -= mod;
        return *this;
    }

    modint& operator-=(const modint ob){
        if((x += mod - ob.x) >= mod) x -= mod;
        return *this;
    }

    modint& operator*=(const modint ob){
        (x *= ob.x) %= mod;
        return *this;
    }

    modint operator+(const modint ob) const {
        modint res(*this);
        return res+=ob;
    }

    modint operator-(const modint ob) const {
        modint res(*this);
        return res-=ob;
    }

    modint operator*(const modint ob) const {
        modint res(*this);
        return res*=ob;
    }

    modint pow(long long index) const {
        if(!index){
            modint ob(1);
            return ob;
        }
        modint ob = pow(index>>1);
        ob *= ob;
        if(index&1) ob *= *this;
        return ob;
    }

    //for prime mod
    modint inverse() const {
        return pow(mod-2);
    }

    modint& operator/=(const modint ob){
        return (*this) *= ob.inverse();
    }

    modint operator/(const modint ob) const {
        modint res(*this);
        return res/=ob;
    }
};

struct combination{
    //member variable
    vector<modint> fact, invfact;

    //constructor
    combination(int n):fact(n+1),invfact(n+1){
        fact[0] = 1;
        for(int i=1; i<=n; i++){
            fact[i] = fact[i-1]*i;
        }
        invfact[n] = fact[n].inverse();
        for(int i=n; i>=1; i--){
            invfact[i-1] = invfact[i]*i;
        }
    }

    modint operator()(int n, int k){
        if(k < 0 || k > n) return 0;
        return fact[n]*invfact[k]*invfact[n-k];
    }
};

