typedef long long ll;

ll n, k, mod = 1000000007;

ll modpow(ll a, ll n, ll mod){
  if(n == 1) return a;
  ll ret = modpow(a, n / 2, mod);
  if(n % 2 == 0) ret = (ret * ret) % mod;
  else ret = (((ret * ret) % mod) * a) % mod;
  return ret;
}

vector<ll> modkaijo(ll n, ll mod){
  vector<ll> k(n + 1);
  k[0] = 1;
  for(int i = 1; i <= n; i++){
    k[i] = (k[i - 1] * i) % mod;
  }
  return k;
}

ll modchoose(ll l, ll r, vector<ll>& kaijo, ll mod){
  ll x = kaijo[l], y = kaijo[r], z = kaijo[l - r], ret;

  y = modpow(y, mod - 2, mod);
  z = modpow(z, mod - 2, mod);
  ret = (((x * y) % mod) * z) % mod;
  return ret;
}

void solve(){
  cin >> n >> k;
  ll ans = 0;
  vector<ll> kaijo = modkaijo(n, mod);
  for(ll i = 0; i <= min(k, n - 1); i++){
    ll x = modchoose(n, i, kaijo, mod), y = modchoose(n - 1, i, kaijo, mod);
    ans = (ans + ((x * y) % mod)) % mod;
  }
  cout << ans << endl;


  return;
}

int main(){
  solve();
  return 0;
}

