ll der(ll a,ll b){
	if(b == 0) return 1;
	ll x = der(a,b / 2);
	if(b % 2) return (((x * x) % mod) * a) % mod;
	return (x * x) % mod;
}

ll C(ll n,ll k){
	return (fact[n] * der((fact[n - k] * fact[k]) % mod,mod - 2)) % mod;
}

ll num(ll n,ll k){
	k -= n;
	return C(n + k - 1,k);
}

