long long mod = 1000000007;
vector<long long> v;

void init(long long n)
{
	for (long long i = 1; i <= n; ++i) {
		v[i] = v[i - 1] * i % mod;
	}
}

// mod. m での a の逆元 a^{-1} を計算する
long long modinv(long long a, long long m) {
	long long b = m, u = 1, v = 0;
	while (b) {
		long long t = a / b;
		a -= t * b; swap(a, b);
		u -= t * v; swap(u, v);
	}
	u %= m;
	if (u < 0) u += m;
	return u;
}

long long comb(long long n, long long r) {
	long long ret = 1;

	ret = v[n] * modinv(v[n - r], mod) % mod;
	ret = ret * modinv(v[r], mod) % mod;

	return ret;
}

int main()
{
	long long n, k;
	cin >> n >> k;

	v.resize(n + 1, 1);

	init(n);

	if (n <= k) {
		k = n - 1;
	}

	long long ret = 1;
	for (long long i = 1; i <= k; ++i) {
		ret = (ret + (comb(n, i) * comb(n - 1,n - i - 1) % mod)) % mod;
	}

	cout << ret << endl;

	return 0;
}

