long long quickpow(long long b, int e)
{
	return e ? ((e & 1 ? b : 1)*quickpow(((b%MOD)*(b%MOD)) % MOD, e >> 1)) % MOD : 1;
}

long long fun(int a, int b)
{
	long long ret = fac[a];
	ret *= quickpow(fac[b], MOD - 2);
	ret %= MOD;
	ret *= quickpow(fac[a - b], MOD - 2);
	ret %= MOD;
	return ret;
}

int main()
{
	ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);
	cin >> n >> k;
	fac[0] = 1;
	for (int i = 1; i <= n + n; i++) {
		fac[i] = fac[i - 1] * i;
		fac[i] %= MOD;
	}
	if (k >= n - 1) {
		ans = fun(n + n - 1, n - 1);
	}
	else {
		ans++;
		for (int i = 1; i <= k; i++) {
			int m = n - i;
			int u = n - m;
			long long tmp = fun(u + m - 1, m - 1);
			tmp *= fun(n, i);
			tmp %= MOD;
			ans += tmp;
			ans %= MOD;
		}
	}
	cout << ans << E;
	//system("pause");
	return 0;
}

