ll gcd(ll a,ll b){ // 高速ユークリッド互除法
    if(a<0) a = -1*a;
    if(b<0) b = -1*b;
    if(a==0) return b;
    if(b==0) return a;
    if(a==b) return a;
    ll c;
    if(a<b){
        c = b-(b/a)*a;
        if(c<a/2) return gcd(a,c);
        else return gcd(a,c-a);
    } else{
        c = a-(a/b)*b;
        if(c<b/2) return gcd(c,b);
        else return gcd(c-b,b);
    }
}

ll binary_method(ll a,ll b,ll m){
    // a^b mod m
    if(b==0) return 1;
    ll ans=1;
    ll ori_b = b;
    ll b_length = 0;
    while(b!=0){
        b = b/2;
        b_length++;
    }

    for(int i=b_length-1;i>-1;i--){
        if((ori_b>>i)&1) ans = (((ans * a) % m) * ans)%m;
        else ans = (ans * ans) % m;
        // cout<<ans<<endl;
    }
    return ans;
}

ll inv(ll a, ll m){
    // a^{-1} mod m, m : 素数
    // cout<<a<<" "<<binary_method(a, m-1, m)<<endl;
    return binary_method(a, m-2, m);
}

ll factorial(ll a, ll m){
    // a! mod m
    if(a<0){
        std::cout<<"factorial error. negative input"<<std::endl;
        return 0;
    }
    ll ans=1;
    for(int i=1;i<a+1;i++){
        ans = (ans * i) % m;
    }
    return ans;
}

ll comb(ll n,ll a,ll m){
    ll bunbo = 1;
    ll bunshi = 1;
    for(ll i=0;i<a;i++){
        bunbo = (bunbo * (n-i))%mod;
        bunshi = (bunshi * (i+1))%mod;
    }
    return (bunbo * inv(bunshi,m))%mod;
}


