ll RepeatSquare(ll n,ll p,ll m){
  if(p==0)
    return 1;
  if(p%2==0){
    ll t = RepeatSquare(n,p/2,m);
    return t*t % m;
  }
  return n*RepeatSquare(n,p-1,m) % m;
}

ll factrial(ll x,ll y,ll m){
  ll ans=1;
  for(ll i=x; i<=y; i++){
    ans *= x;
    ans %= m;
  }
  return ans;
}

ll combination(ll x,ll y,ll m){
  ll ans=factrial(y-x+1,y,m);
  ans *= RepeatSquare(factrial(1,x,m),m-2,m);
  ans %= m;
  return ans;
}
