		fact[i] = (fact[i-1] * i) % m;
		invfact[i] = (invfact[i-1] * invmod(i, m)) % m;
	}
}

int nCrmod(int n, int r, int m){
	return (((fact[n] * invfact[r]) % m) * invfact[n-r]) % m;
}

signed main(void){
	cin.tie(0);
	ios::sync_with_stdio(false);

	int N, K; cin >> N >> K;
	factmod(MOD);
	if(K >= N) cout << nCrmod(2*N-1, N-1, MOD) << endl;
	else {
		int ans = 0;
		for(int zero = 0; zero <= K; zero++){
			int plus = nCrmod(N, zero, MOD);
			plus *= nCrmod(N-1, (N-zero)-1, MOD);
			plus %= MOD;
			ans += plus; ans %= MOD;
		}
		cout << ans << endl;
	}
}

