using i64 = int64_t;

constexpr i64 MOD = 1000000007;

i64 extgcd(i64 a, i64 b, i64 &x, i64 &y) {
    i64 d = a;
    if (b != 0) {
        d = extgcd(b, a % b, y, x);
        y -= (a / b) * x;
    } else {
        x = 1;
        y = 0;
    }
    return d;
}

i64 multi_inv(i64 a, i64 md) {
    i64 x, y;
    extgcd(md, a, x, y);
    return (y > 0 ? y : md + y);
}

vector<i64> set_ncr(i64 n) {
    vector<i64> ncr(n+1);
    ncr[0] = 1;
    for (i64 i = 1; i <= n; i++) {
        i64 inv = multi_inv(i, MOD);
        ncr[i] = (n - i + 1) * ncr[i - 1] % MOD;
        ncr[i] = ncr[i] * inv % MOD;
    }
    return ncr;
}

int main(){
    i64 n, k;
    cin >> n >> k;
    auto ncr = set_ncr(n);
    auto ncr2 = set_ncr(n-1);
    i64 ans = 0;
    for(i64 i=1;i<=min(n-1, k);++i){
        i64 tmp = ncr[i] * ncr2[i];
        tmp %= MOD;
        //cerr << tmp << endl;
        ans += tmp;
        ans %= MOD;
    }
    if(k>1){
        ans++;
        ans %= MOD;
    }

    cout << ans << endl;

    return 0;
}

