ll factorial[maxn];

ll exp(ll b, ll p){

    ll resp = 1;

    b = b % m;

    while(p > 0){
        if(p & 1){
            resp = (resp * b)%m;
        }
        p = p >> 1;
        b = (b * b)%m;
    }

    return resp;
}

ll inverse(ll x){
    return exp(x, m-2);
}

ll ncr(ll n, ll k) {
    return factorial[n] * inverse(factorial[k]) % m * inverse(factorial[n - k]) % m;
}

