const int MAX = 1000000;
const int MOD = 1000000007;

long long fac[MAX], finv[MAX], inv[MAX];

void COMinit(){
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

long long COM(int n, int k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}
//前処理COMinit()忘れずに


void solve() {
    int n, k; cin >> n >> k;

    COMinit();

    if (k >= n-1) {
        cout << COM(2*n-1, n-1) << endl;
        return;
    }

    mint ans = 0;

    for (int i = 0; i <= k; i++) {
        ans += COM(n-1, n-i-1) * COM(n, i);
    }

    cout << ans << endl;
}


int main() {
    solve();
    return 0;
}

