  prepare_fracs(n);

  int maxm = min(n - 1, k);
  int sum = 0;
  for (int m = 0; m <= maxm; m++)
    sum = (sum + (ll)nck(n, m) * nhk(n - m, m) % MOD) % MOD;

  printf("%d\n", sum);
  return 0;
}

