i64 pow_mod(i64 n, i64 k, i64 m){
  i64 r = 1;
  for(;k;k>>=1){
    if(k&1) r=(r*n)%m;
    n=(n*n)%m;
  }
  return r;
}

i64 calc_c(i64 n){
  i64 res = 1;
  rep(i,1,2*n){
    res *= i;
    res %= MOD;
  }
  res *= pow_mod(n,MOD-2,MOD);
  res %= MOD;
  rep(i,1,n){
    res *= pow_mod(i,MOD-3,MOD);
    res %= MOD;
  }
  return res;
}

i64 calc_c2(i64 n, i64 x){
  i64 res = 1;
  rep(i,x){
    res *= n-i;
    res %= MOD;
    res *= pow_mod(i+1,MOD-2,MOD);
    res %= MOD;
  }
  rep(i,1,n){
    res *= i;
    res %= MOD;
  }
  rep(i,x){
    res *= pow_mod(i+1,MOD-2,MOD);
    res %= MOD;
  }
  rep(i,1,n-x){
    res *= pow_mod(i,MOD-2,MOD);
    res %= MOD;
  }
  return res;
}

