using namespace std;

long fac[MAX];
long finv[MAX];

long long modinv(long long a, long long m) {
    long long b = m, u = 1, v = 0;
    while (b) {
        long long t = a / b;
        a -= t * b; swap(a, b);
        u -= t * v; swap(u, v);
    }
    u %= m;
    if (u < 0) u += m;
    return u;
}

void fac_table(){
    fac[0] = 1;
    for(int i=1; i<MAX; i++){
        fac[i] = fac[i-1] * i;
        fac[i] %= MOD;
    }
}

long comb(int n, int k){
    long c = fac[n];
    c *= modinv(fac[k], MOD); c %= MOD;
    c *= modinv(fac[n-k], MOD); c %= MOD;
    return c;
}

int main(){
    long n, k;
    cin >> n >> k;
    fac_table();
    long ans = 0;
    for(long i=0; i<=min(n, k); i++){
        ans += comb(n-1, i) * comb(n, i) ;
        ans %= MOD;
        //cout << comb(n-1, i) * comb(n, i)  << endl;
    }
    cout << ans << endl;
    return 0;
}

