void build(lli p,lli l,lli r)
{
    if(l==r)
    se[p]=a[l];
    else
    {
        build(2*p+1,l,(l+r)/2);
        build(2*p+2,(l+r)/2+1,r);
        se[p]=se[2*p+1]+se[2*p+2];
    }
}

void update(lli p,lli l,lli r,lli i,lli z)
{
    if(l>r||l>i||r<i)
    return ;
    if(l==r&&l==i)
    {
        se[p]=z;
        return;
    }
    update(2*p+1,l,(l+r)/2,i,z);
    update(2*p+2,(l+r)/2+1,r,i,z);
    se[p]=se[2*p+1]+se[2*p+2];
}

lli sum(lli p,lli l,lli r,lli i,lli j)
{
    if(l>r||l>j||r<i)
