struct mint
{
    ll x;
    mint(ll x = 0) : x((x % MOD + MOD) % MOD) {}
    mint &operator+=(const mint a)
    {
        if ((x += a.x) >= MOD)
            x -= MOD;
        return *this;
    }
    mint &operator-=(const mint a)
    {
        if ((x += MOD - a.x) >= MOD)
            x -= MOD;
        return *this;
    }
    mint &operator*=(const mint a)
    {
        (x *= a.x) %= MOD;
        return *this;
    }
    mint operator+(const mint a) const
    {
        mint res(*this);
        return res += a;
    }
    mint operator-(const mint a) const
    {
        mint res(*this);
        return res -= a;
    }
    mint operator*(const mint a) const
    {
        mint res(*this);
        return res *= a;
    }
    // O(log(t))
    mint pow(ll t) const
    {
        if (!t)
            return 1;
        mint a = pow(t >> 1); // ⌊t/2⌋ 乗
        a *= a;               // ⌊t/2⌋*2 乗
        if (t & 1)            // ⌊t/2⌋*2 == t-1 のとき
            a *= *this;       // ⌊t/2⌋*2+1 乗 => t 乗
        return a;
    }

    // for prime mod
    mint inv() const
    {
        return pow(MOD - 2); // オイラーの定理から， x^(-1) ≡ x^(p-2)
    }
    mint &operator/=(const mint a)
    {
        return (*this) *= a.inv();
    }
    mint operator/(const mint a) const
    {
        mint res(*this);
        return res /= a;
    }
    bool operator==(const mint a) const
    {
        return this->x == a.x;
    }
    bool operator==(const ll a) const
    {
        return this->x == a;
    }

    // mint 入力
    friend istream &operator>>(istream &is, mint &x)
    {
        is >> x.x;
        return is;
    }

    // mint 出力
    friend ostream &operator<<(ostream &os, mint x)
    {
        os << x.x;
        return os;
    }
};

class Combinaion
{
private:
    /* テーブルの大きさの既定値．(MAX)! まで計算できる． */
    static constexpr ll MAX = 1e6 + 11;
    /* 実際のテーブルの大きさ． */
    ll max;
    /* 階乗を格納するテーブル．fac[n] := n! % MOD. */
    vc<mint> fac;
    /* 階乗の逆元を格納するテーブル．finv[n] := (fac[n])^(-1). */
    vc<mint> finv;

    /* 各種テーブルを初期化する． */
    void init(int n)
    {
        max = n;
        fac[0] = fac[1] = 1;
        finv[0] = finv[1] = 1;
        REPM(i, 2, n)
        {
            fac[i] = fac[i - 1] * i;
        }
        finv[n] = fac[n].inv();
        REPR(i, n, 2)
        {
            finv[i - 1] = finv[i] * i;
        }
    }

public:
    /* コンストラクタ． */
    Combinaion(int n = MAX) : fac(n + 1), finv(n + 1)
    {
        init(n);
    }

    /* 二項係数 nCk % MOD を計算する． */
    mint operator()(ll n, ll k) const
    {
        assert(n <= max); // ここで詰まると RE
        assert(k <= max);
        if (n < k || n < 0 || k < 0)
            return 0;
        return fac[n] * finv[k] * finv[n - k];
    }
};

/**
Problem
