void solve()
{
    ll n, k;
    cin >> n >> k;

    Combinaion c;
    if (k >= n)
    {
        cout << c(2 * n - 1, n - 1) << endl;
        return;
    }
    mint ret = 1;
    REPM(l, 1, k)
    {
        ret += c(n, l) * c(n - 1, l);
    }
    cout << ret << endl;
}

/**
 * エントリポイント．
 * @return 0.
 */
int main()
{
    solve();
    return 0;
}

