struct Problem {

	static const ULL M = 1000000007;
	static ULL f(ULL a, ULL i) {
		if (i == 0) return 1;
		ULL b = f(a, i / 2), c = (i % 2) ? a : 1;
		return b * b % M * c % M;
	}
	vector<ULL> F, I, iF;
	ULL C(UL n, UL r) {
		return F[n] * iF[r] % M * iF[n - r] % M;
	}

	void Solve() {
		UL N, K; cin >> N >> K;
		UL Z = N * 2;
		F.resize(Z + 1), I.resize(Z + 1), iF.resize(Z + 1);
		F[0] = 1; I[1] = 1; iF[0] = 1;
		rep(i, Z) { F[i + 1] = F[i] * (i + 1) % M; }
		for (UL i = 2; i <= Z; i++) { I[i] = M - M / i * I[M % i] % M; }
		rep(i, Z) { iF[i + 1] = iF[i] * I[i + 1] % M; }

		ULL ans = C(N + N - 1, N - 1);
		for (UL i = 1; i + K < N; i++) {
			ULL buf = C(N, i);
			buf = buf * C(N - 1, i - 1) % M;
			ans += (M - buf);
		}
		ans %= M;
		cout << ans << endl;
	}


	Problem();
};
int main() {
	unique_ptr<Problem> p(new Problem());
	p->Solve();
	return 0;
}
