#include <bits/stdc++.h>

using namespace std;

typedef long long ll;

const ll M = 1e9 + 7;

ll bin_pow(ll a, ll n) {
	if (n == 0) {
		return 1;
	}
	if (n == 1) {
		return a % M;
	}
	if (n % 2 == 0) {
		ll x = bin_pow(a, n / 2) % M;
		x = x * x;
		x %= M;
		return x;
	} else {
		ll x = bin_pow(a, n - 1) % M;
		x = x * (a % M);
		x %= M;
		return x;
	}
}

const int N = 2e5 + 200;

ll fact[N];
ll rev_fact[N];

ll get_rev(ll a, ll p) {
	return bin_pow(a, p - 2);
}

ll get_c(ll n, ll k) {
	ll x = fact[n];
	ll y = fact[n - k] * fact[k];
	y %= M;
	y = get_rev(y, M) % M;
	return (x * y) % M;
}

