        b = b * (ll)(n-i) % MOD;
        c = c * (ll)i % MOD;
      }
      d = mod_pow(c, MOD-2);
      ans += ((a*d)%MOD*(b*d)%MOD)%MOD;
      ans %= MOD;
    }
    cout << ans << endl;
  }
}

