	long long ans = 0;
	for(long long zero = 0; zero <= min(n-1, k); zero++) {
		long long hako = n - zero;
		ans += combination(zero + hako-1, zero) * combination(n, zero);
		ans %= DIV;
	}
	cout << ans << endl;
}

