class Combination_Mod{
    public:
        Combination_Mod(long long MAX, long long MOD) : fact(MAX + 1), inv(MAX + 1), finv(MAX + 1), MAX(MAX + 1), MOD(MOD){
            init();
        }

        void init(){
            fact[0] = fact[1] = 1;
            finv[0] = finv[1] = 1;
            inv[1] = 1;
            for(long long i = 2; i < MAX; ++i){
                fact[i] = fact[i - 1] * i % MOD;
                inv[i] = MOD - inv[MOD % i] *  (MOD / i) % MOD;
                finv[i] = finv[i - 1] * inv[i] % MOD;
            }
        }

        long long bin(long long n, long long r){
            if(n < r || n < 0 || r < 0) return 0;
            return fact[n] * (finv[r] * finv[n - r] % MOD) % MOD;
        }

        long long perm(long long n, long long r){
            return (bin(n, r) * fact[r]) % MOD;
        }

        long long factorial(long long n){
            return fact[n];
        }

        long long modinv(long long n){
            return inv[n];
        }

        long long modfinv(long long n){
            return finv[n];
        }

    private:
        vector<long long> fact;
        vector<long long> inv;
        vector<long long> finv;
        const long long MAX;
        const long long MOD;
};

ll N, K;
Combination_Mod c(400010, MOD);

signed main(){
    cin >> N >> K;
    if(N <= K){
        if(N % 2 == 1) PRINT((c.bin(N + N - 1, N - 1) + MOD - 1) % MOD);
        else PRINT(c.bin(N + N - 1, N - 1));
        return 0;
    }
    ll ans = 0;
    for(ll k = K; k > 0; k--){
        ans = (ans + c.bin(N, k) * c.bin(N - 1, k) % MOD) % MOD;
    }
    if(K % 2 == 0) ans++;
    PRINT(ans % MOD);
    return 0;
}

