const int MOD = 1000000007;
const int N_MAX = 200000;

long long mod(long long a) {
	a %= MOD;
	return a >= 0 ? a : a+MOD;
}

long long inverse[N_MAX+1];
long long factorial[N_MAX+1];
long long factorial_inverse[N_MAX+1];

void calc(int n) {
	inverse[1] = 1;
	factorial[0] = factorial[1] = 1;
	factorial_inverse[0] = factorial_inverse[1] = 1;
	for (int i = 2; i <= n; i++) {
		inverse[i] = MOD - inverse[MOD%i] * (MOD/i) % MOD;
		factorial[i] = i * factorial[i-1] % MOD;
		factorial_inverse[i] = inverse[i] * factorial_inverse[i-1] % MOD;
	}
}

long long comb(long long n, long long k) {
	return factorial[n] * (factorial_inverse[k] * factorial_inverse[n-k] % MOD) % MOD;
}

int main() {
	long long n, k;
	cin >> n >> k;
	if (k > n-1) k = n-1;
	calc(n);
	long long ans = 0;
	ans++;
	for (int i = 1; i <= k; i++) {
		ans = mod(ans + comb(n,i) * comb(n-1,i) % MOD);
	}
	cout << ans << endl;
	return 0;
}

