const LL mod=1e9+7;
const int Max_Num=200010;

LL modinv(LL x){
	LL m=mod, u=1, v=0;
	while(m){
		LL t=x/m;
		x-=t*m; swap(x,m);
		u-=t*v; swap(u,v);
	}
	u%=mod;
	if(u<0) u+=mod;
	return u;
}

int main(){
  LL n, k;
  cin >> n >> k;
  LL F[Max_Num], Finv[Max_Num];
  F[0]=1;
  rep(i,Max_Num-1){
  	F[i+1]=F[i]*(i+1);
  	F[i+1]%=mod;
  }
  rep(i,Max_Num) Finv[i]=modinv(F[i]);
  LL dp[Max_Num]={0};
  dp[0]=1;
  for(LL i=1; i<=min(k,n-1); i++){
    dp[i]=dp[i-1]+(F[n]*Finv[i]%mod*Finv[n-i]%mod)
    *(F[n-1]*Finv[n-i-1]%mod*Finv[i]%mod);
    dp[i]%=mod;
  }
  if(k<=n-1) cout << dp[k] << endl;
  else cout << dp[n-1] << endl;

  return 0;
}

