int neocomb(int x, int y) {
    if (!x) {
        return 0;
    }
    int ans = 1;
    int waru = 1;
    for (int i = x + y - 1; i > y; i--) {
        ans *= i;
        ans %= mod;
        waru *= x + y - i;
        waru %= mod;
    }
    ans *= modpow(waru, mod - 2);
    ans %= mod;
    return ans;
}
