// a^n mod を計算する
long long modpow(long long a, long long n) {
  if (n == 1) return a;
  long long res = modpow(a,n/2) * modpow(a,n/2) % mod;
  if (n % 2 == 1) res *= a % mod;
  return res;
}

// a^{-1} mod を計算する
long long modinv(long long a, long long mod) {
  return modpow(a, mod - 2);
}


