LL C(int n, int k) {
    if (k < 0 || k > n) return 0;
    if (k == 0) return 1;
    if (k == 1) return n;
    LL ret = n;
    for (int i = 2; i <= k; ++i) {
        ret *= (n - i + 1); ret %= mod;
        ret *= inv(i); ret %= mod;
    }
    return ret;
}

LL Cnext(LL n, LL k, LL Cnkm1) {
    LL ret = Cnkm1 * (n - k + 1); ret %= mod;
    ret *= inv(k); ret %= mod;
    return ret;
}

