//割られる数：a
//余りを求めるやつ：valid
long long Modinv(long long a, long long valid = INV)
{
	long long b = valid, u = 1, v = 0;
	while (a)
	{
		if (a < b)
		{
			swap(a, b);
			swap(u, v);
		}
		long long t = a / b;
		a -= t * b;
		u -= t * v;
	}
	v %= valid;
	if (v < 0)
		v += valid;
	return v;
}
//rCnの場合
long long int Combination(long long int r, long long int n)
{
	long long int ans = 1;
	long long int div;

	for (int i = 0; i < n; i++)
	{
		ans *= r - i;
		div = i + 1;

		ans = ans % INV * Modinv(div) % INV;
	}

	return ans;
}

void execute()
{
	lint N, K;
	cin >> N >> K;

	if (N - 1 <= K)
	{
		cout << Combination(N * 2 - 1, N) << endl;
		return;
	}
	else
	{
		lint ans = 0;
		for (int i = 0; i <= K; i++)
		{
			ans += Combination(N, i) % INV * Combination(N - 1, N - 1 - i) % INV;
			ans %= INV;
		}
		cout << ans << endl;
		return;
	}
	return;
}

