int power(int a,int n,int p)
{
    a %= p;
    if(n == 1)return a;
    if(n == 0)return 1;
    if(n%2)return (a*(power((a*a)%p,n/2,p)%p))%p;
    return power((a*a)%p,n/2,p)%p;
}
const int inf = (int) 1e18;

int inverse(int x){
    return power(x,mod-2,mod)%mod;//little fermat....
}

int fact[maxn];

int ncr(int n,int r){
    int num = fact[n];
    int den = (fact[n-r]*fact[r])%mod;
    num *= inverse(den);
    num %= mod;
    return num;
}

void solve(){
    fact[0] = 1;
    FOR(i,1,maxn)fact[i] = (fact[i-1]*i)%mod;
    int n,k;
    cin >> n >> k;
    int ans = 0;
    FOR(i,0,min(k+1,n)){
        ans += (ncr(n,i)*ncr(n-1,i))%mod;
        ans %= mod;
    }
    cout << ans << "\n";
}

