// a^n mod を計算 再帰
ll modpow(ll a,ll n,ll &mod){
  if(!n) return 1;
  ll x = modpow(a,n/2,mod)%mod;
  x *=x;
  if(n%2==1)x*=a;
  return x%mod;
}

// a^n mod を計算する bit
ll modpow2(ll a,ll n,ll &mod){          // n=45,a=3
  ll res = 1;
  while(n>0){                          //桁数比較 with 000001
    if(n & 1) res = res * a%mod;     // flag たってるところで何乗か済のaかける
    a = a*a%mod;                       //毎度倍々
    n >>=1;                            //右シフト
  }
  return res;
}

