//big N like N=10^9 but adding only FEW times
ll modC(ll n,ll a,ll &mod){
  ll fac=1;
  ll ifac=1;
  rep(i,a)fac = (n-i) * fac%mod;
  reps(i,a)ifac= i*ifac%mod;
  return modpow2(ifac,mod-2,mod)*fac%mod;
}

//middle N like N=10^5 but adding MANY times
ll modC2(ll n,ll a,ll &mod){
  ll fac=f[n];         // = n!
  ll ifac=(rf[n-a]*rf[a])%mod; //=(n-a)! a!
  return ifac*fac%mod;
}


