const ll mod = 1000000007;

ll modfact(ll n) {
  ll res = 1LL;
  for(int i = 1; i <= n; i++) res = res * i % mod;
  return res;
}

ll modpow(ll b, ll e) {
  if(e == 0) return 1LL;
  if(e % 2 == 1) return modpow(b, e - 1) * b % mod;
  ll m = modpow(b, e >> 1);
  return m * m % mod;
}

ll inv(ll a) {
  return modpow(a, mod - 2);
}

int main() {
  ll n, k;
  cin >> n >> k;
  ll N = n;
  ll ans = 1LL;
  for(ll r = 1; r <= N; r++)
    ans = ans * (2LL * N - r) % mod;
  ans = ans * inv(modfact(N)) % mod;
  if(k < n) {
    for(ll r = 1; r <= k + 1; r++)
      ans = ans * (n - r + 1) % mod;
    ans = ans * inv(modfact(k)) % mod;
    for(ll r = 1; r <= k + 1; r++)
      ans = ans * (n - r + 1) % mod;
    ans = ans * inv(modfact(k)) % mod;
  }
  cout << ans << endl;
  return 0;
}

