using namespace std;

class Comb {
	vector<SINT64> base;
	SINT64 N;

public:
	Comb (SINT64 n) {
		N = n+5;
		base.resize(N);
		base[0] = 1;
		rep(i,1,N) {
			base[i] = base[i-1]*i;
			base[i] %= MOD;
		}
	}

	SINT64 get_comb(SINT64 a, SINT64 b) {
		SINT64 ans = 0;
		SINT64 aa = base[a] * modpow(base[a-b], MOD - 2) % MOD;
		ans = aa * modpow(base[b], MOD - 2) % MOD;
		return ans;
	}

	SINT64 modpow(SINT64 a, SINT64 p) {
		if (p == 0) return 1;
		if (p % 2 == 0) {
			SINT64 halfP = p / 2;
			SINT64 half = modpow(a, halfP);
			return half * half % MOD;
		} else {
			return a * modpow(a, p - 1) % MOD;
		}
	}
};

int main() {

	SINT64 N;	cin >> N;
	SINT64 M;	cin >> M;

	SINT64 ma = MIN(N-1,M);

	Comb com(N);
	SINT64 ans = 0;

	rep(i,0,ma+1) {
		SINT64 buf = com.get_comb(N,i);
		buf %= MOD;
		buf *= com.get_comb(N-1,N-i-1);
		buf %= MOD;
		ans += buf;
		ans %= MOD;
	}

	put(ans);
	return 0;
}


