    for (int i = 1; i < MAXN; i++) f[i] = (f[i - 1] * i) % mod;
    int n, k;
    cin >> n >> k;
    if (k == 1) {
        int ans = (n - 1) * n;
        cout << ans;
        return 0;
    }
    int ans = 1, cur;
    for (int i = 1; i <= min(n - 1, k); i++) {
        cur = C(n, i) * C(n - 1, i);
        cur %= mod;
        ans += cur;
        ans %= mod;
    }
    cout << ans;
}
