ll mod_pow(ll a, ll n)
{
    ll res = 1, base = a;

    while (n)
    {
        if (n & 1)
            res = (res * base) % MOD;

        base = (base * base) % MOD;
        n >>= 1;
    }

    return res;
}

ll mod(ll a)
{
    return (((a % MOD) + MOD) % MOD);
}

ll binom(ll n, ll m)
{
    ll a = min(m, n - m);
    ll b = max(m, n - m);

    ll num = 1;

    for (ll i = n; i > b; --i)
        num = mod(num * i);

    ll den = 1;

    for (ll i = 2; i <= a; ++i)
        den = mod(den * i);

    auto inv = mod_pow(den, MOD - 2);

#ifdef DEBUG
//cout << "a = " << a << ", b = " << b << endl;
//cout << "num = " << num << ", den = " << den << endl;
//cout << "inv = " << inv << endl;
#endif
    return mod(num * inv);
}

ll solve(ll N, ll K)
{
    if (K >= N - 1)
        return binom(2*N - 1, N - 1);

    ll ans = 0;

    for (int k = 0; k <= K; ++k)
    {
#ifdef DEBUG
//    cout << "x = " << x << endl;
