template<size_t N, int MOD = int(1e9) + 7>
struct InvFact {
    uint_fast64_t inv[N+1];
    uint_fast64_t f[N+1];

    constexpr inline InvFact() : inv{0, 1}, f{1, 1} {
        for (int i = 2; i <= N; ++i) {
            inv[i] = (MOD - MOD/i) * inv[MOD % i] % MOD;
            f[i] = f[i-1] * inv[i] % MOD;
        }
    }

    constexpr inline ModInt<MOD> operator[] (size_t i) const { return f[i]; }
};
