  for(ll i=0;i<=k-1;i++){
    prod=(prod*(m-i))%MOD;
  }
  for(ll i=1;i<=k;i++){
    frac=(frac*i)%MOD;
  }
  prod=(prod*pow_mod(frac, MOD-2))%MOD;
  return prod;
}
