const ll MOD = 1e9 + 7;

const int N = 5e5 + 15;
ll fat[N];

void init(){
    fat[0] = 1LL;
    for(ll i = 1; i < N; i++) fat[i] = (fat[i-1] % MOD * i % MOD) % MOD;
}

ll fastp(ll a, ll p){
    if(p == 1) return a % MOD;
    if(p&1) return (a % MOD * fastp(a, p-1) % MOD) % MOD;
    ll x = p / 2;
    ll t = fastp(a, x) % MOD;
    return (t % MOD * t % MOD) % MOD;
}

ll nck(ll n, ll k){
    if(k < 0 or k > n) return 0;

    ll top = fat[n];
    ll fatk = fastp(fat[k], MOD - 2);
    ll fatnk = fastp(fat[n-k], MOD - 2);

    top = (top % MOD * fatk % MOD) % MOD;
    return (top % MOD * fatnk % MOD) % MOD;
}

