    ll ans = nck(2*n-1, n-1);

    for(ll i = k + 1; i < n; i++){
        ans = (ans + MOD - (nck(n, i) % MOD * nck(n-1, n-i-1) % MOD) % MOD) % MOD;
    }

    cout << ans % MOD << endl;
    return 0;
