ll mod = 1e9 + 7;

struct ModComb {
    vector<long long> fact, rfact;
    long long max, mod;
    ModComb(long long ma = 1, long long mod=1e9+7) :fact(ma, 0), rfact(ma, 0), max(ma), mod(mod) {
        fact[0] = 1;
        for (long long i=1; i<max; ++i) {
            fact[i] = fact[i-1]*i;
            fact[i] %= mod;
        }
        rfact[max-1] = mod_inverse(fact[max-1], mod);
        for (long long i=max-2; i>=0; --i) {
            rfact[i] = rfact[i+1]*(i+1);
            rfact[i] %= mod;
        }
    }
    long long mod_pow(long long x, long long n, long long mod) {
        long long a = 1LL;
        while (n) {
            if (n%2) a = ((a%mod)*(x%mod))%mod;
            x = ((x%mod)*(x%mod))%mod;
            n /= 2LL;
        }
        return a;
    }

    // a / y -> a * y^(-1)
    // y^(m-2) = y^(-1) (mod m)
    long long mod_inverse(long long a, long long m) {
        return mod_pow(a, m-2, m);
    }

    // O(r)で求める方法
    long long calc(ll n, ll r, ll mod) {
        ll ret = 1, k = 0;
        for (ll a=r; a>=1; --a) {
            ll tmp = (n - k) * mod_inverse(a, mod) % mod;
            tmp %= mod;
            ret *= tmp;
            ret %= mod;
            k++;
        }
        return ret;
    }

    // 重複組合せ
    // nHr = n+r-1Cr
    // (n+r-1)まで初期化していないとエラー
    long long nHr(ll n, ll r, ll mod) {
        return (*this)(n+r-1, r);
    }

    long long operator()(long long n, long long r) {
        if (n < r) return 0;
        return (((fact[n] * rfact[r]) % mod) * rfact[n - r]) % mod;
    }
};


int main() {
    ll n, k;
    cin >> n >> k;

    ll ans = 0;
    ModComb mb(n+1, mod);
    for (int i=0; i<min(n, k+1); ++i) {
        ans += (mb(n, i) % mod) * (mb.nHr(n-i, i, mod) % mod) % mod;
        ans %= mod;
    }
    cout << ans << endl;
}

