#define MOD 1000000007
#define INF 2147483647

ll modinv(ll a, ll mod = MOD) {
  ll b = mod, u = 1, v = 0;
  while (b) {
    ll t = a / b;
    a -= t * b;
    swap(a, b);
    u -= t * v;
    swap(u, v);
  }
  u %= mod;
  if (u < 0) u += mod;
  return u;
}

const int COM_MAX = 200010;
ll fac[COM_MAX], finv[COM_MAX], inv[COM_MAX];

void modcom_init(ll mod = MOD) {
  fac[0] = fac[1] = 1;
  finv[0] = finv[1] = 1;
  inv[1] = 1;
  for (int i = 2; i < COM_MAX; i++) {
    fac[i] = fac[i - 1] * i % mod;
    inv[i] = mod - inv[mod % i] * (mod / i) % mod;
    finv[i] = finv[i - 1] * inv[i] % mod;
  }
}

ll n;

ll ans(int m, int rest, int cnow, ll csum, int len) {
  ll r = 0;
  if (rest - m < 0) return 0;
  if (len == 1) {
    r = csum;
    if (m == rest) {
      r = (r + fac[cnow + 1]) % MOD;
      return modinv(r);
    } else {
      r = (r + fac[cnow]) % MOD;
      return modinv(r);
    }
  }
  rep(i, rest - m + 1) {
    if (i == 0) {
      r += ans(m + i, rest - m - i, cnow + 1, csum, len - 1);
    } else {
      r += ans(m + i, rest - m - i, 1, (csum + modinv(cnow)) % MOD, len - 1);
    }
    r %= MOD;
  }
}

int main() {
  modcom_init();
  init();

  ll k;
  cin >> n >> k;

  if (k >= n - 1) k = n - 1;

  ll o = fac[n];
  ll a = 0;
  rep(i, k + 1) {
    a += ans(1, n - i, 0, 0, n - i);
    a %= MOD;
  }
  out(o * a % MOD);
}

