const ll mod = 1e9+7;
const int MAX = 510000;
const int MOD = 1000000007;

long long fac[MAX], finv[MAX], inv[MAX];

// テーブルを作る前処理
void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

// 二項係数計算
long long COM(int n, int k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}
ll ans = 1;
ll N;
vector<vector<bool>> homon(2*(int)1e5+3, vector<bool>(1e5, false));
void dfs(int n, int lock, int k){
  if(n<=0 || k<=0){
    return;
  }
  cerr << "n:" << n << " k:" << k << endl;
  if(homon[n][lock]) return;
  homon[n][lock] = true;
  if(lock != 0){
    ans +=(n * COM(N,lock))%mod;
    ans %=mod;
    dfs(n-1, lock, k-1);
  }
  if(n-2 >= 0){
    ans += (n * (n-1))%mod;
    ans %=mod;
    dfs(n-2, lock+1, k-1);
  }
}

