LL qpow(LL base, LL times)
{
	LL tmp = base % Mod;
	LL Ans = 1;
	while (times)
	{
		if (times & 1) Ans = Ans * tmp % Mod;
		times >>= 1;
		tmp = tmp * tmp % Mod;
	}
	return Ans % Mod;
}
