//n!
Modulo fact(long long n, long long p = default_mod, long long init_size = 1e+6){
    static bool is_init = false;
    static std::vector<long long> dat;
    if(!is_init){
        is_init = true;
        dat.resize(init_size);
        dat[0] = 1;
        for(int i=1; i<init_size; i++) dat[i] = dat[i-1] * i % p;
    }
    return Modulo(dat[n], p);
}

// 1/n!
Modulo ifact(long long n, long long p = default_mod, long long init_size = 1e+6){
    static bool is_init = false;
    static std::vector<long long> dat;
    if(!is_init){
        is_init = true;
        dat.resize(init_size);
        dat[init_size-1] = fact(init_size-1).inverse().n;
        for(int i=init_size-1; i>0; i--) dat[i-1] = dat[i] * i % p;
    }
    return Modulo(dat[n], p);
}

// initialize
void initFact(long long init_size, long long p = default_mod)
{
    fact(0, p, init_size);
    ifact(0, p, init_size);
}

//nCk
Modulo comb(long long n, long long k, long long p = default_mod)
{
    Modulo a = fact(n, p);
    Modulo b = ifact(k, p);
    Modulo c = ifact(n-k, p);
    return a * b * c;
}

// ax + by = d
template <class T>
T ext_gcd(T a, T b, T& x, T& y)
{
    if(b == 0){
        x = 1; y = 0; return a;
    }
    T d = ext_gcd(b, a%b, x, y);
    T x_ = x;
    x = y;
    y = x_ - a/b * y;
    return d;
}

