    {

        x = 1;

        y = 0;



        d = a;

        return;

    }



    lint xx, yy, q = a / b;

    euclid(b, a % b, xx, yy, d);

    x = yy;

    y = xx - yy * q;

}



void poz(lint &n)

{

    if(n < 0)

    {

        n = MOD + n % MOD;

    }

}



lint fact[MAX_LEN + 1];

lint inv[MAX_LEN + 1];
lint invf[MAX_LEN + 1];



void getInv()

{

    fact[0] = inv[0] = invf[0] = 1;

    for(lint i = 1; i <= MAX_LEN; i ++)

        fact[i] = 1LL * fact[i - 1] * i % MOD;



    lint x, y, d;

    euclid(fact[MAX_LEN], MOD, x, y, d);

    poz(x);

    inv[MAX_LEN] = x * fact[MAX_LEN - 1] % MOD;
    invf[MAX_LEN] = x;


    for(lint i = MAX_LEN - 1; i >= 1; i --)

    {

        invf[i] = invf[i + 1] * (i + 1) % MOD;

        x = x * (i + 1) % MOD;

        inv[i] = x * fact[i - 1] % MOD;

    }

}

