mint comb(ll n, ll r) {
  assert(0 <= r && r <= n);
  const int kMax = 2000001;
  static mint fact[kMax + 1], inv[kMax + 1];
  if (fact[0] == 0) {
    fact[0] = 1;
    for(int i = 1; i <= kMax; ++i) fact[i] = fact[i - 1] * i;
    inv[kMax] = fact[kMax].pow(mod - 2);
    for(int i = kMax; i; --i) inv[i - 1] = inv[i] * i;
  }
  return fact[n] * inv[n - r] * inv[r];
}

int main(){
  ll n = in();
