static const int MAX=510000;
const int MAX_N = 5e5 + 10;


ll fact[MAX], fact_inv[MAX];

//繰り返し二乗法
ll power(ll a, ll b){
    ll res = 1;
    while(b > 0){
        if(b & 1) res = res * a % MOD;
        a = a * a % MOD;
        b >>= 1;
    }
    return res;
}

ll comb(ll n, ll r){
    return (fact[n] * fact_inv[r]) % MOD * fact_inv[n-r] % MOD;
}

long long modinv(long long a, long long m) {
    long long b = m, u = 1, v = 0;
    while (b) {
        long long t = a / b;
        a -= t * b; swap(a, b);
        u -= t * v; swap(u, v);
    }
    u %= m;
    if (u < 0) u += m;
    return u;
}//mod mでの逆元aを計算

long long modpow(long long a, long long n, long long mod) {
    long long res = 1;
    while (n > 0) {
        if (n & 1) res = res * a % mod;
        a = a * a % mod;
        n >>= 1;
    }
    return res;
}

int main(){
    fact[0] = 1;
    //階乗計算(O(n))
    for(int i = 0; i < MAX_N; i++) fact[i+1] = fact[i] * (i+1)%MOD;
    fact_inv[MAX_N] = power(fact[MAX_N], MOD - 2);
    //逆元計算(O(logp + n))
    for(int i = MAX_N - 1; i >= 0; i--) fact_inv[i] = fact_inv[i+1]%MOD*(i+1)%MOD;
    //あとはcomb(n,r)に値を突っ込めば良い
    int n, k; cin >> n >> k;
    ll ans = 0;
    if(k >= n - 1)cout << comb(2 * n - 1, n) << endl; 
    else{
        if(k%2 == 1){
            for(int i = 1; i <= k; i += 2){
                ans += comb(n - 1, n - i - 1) * comb(n, i);
                ans %= MOD;
            }
        }else{
            for(int i = 0; i <= k; i += 2){
                ans += comb(n - 1, n - i - 1) * comb(n, i);
                ans %= MOD;
            }
        }
        cout << ans << endl;
    }

}

