m_int factorical(int n){
    m_int tmp=1;
    REP(i,n){
        tmp *= i+1;
    }
    return tmp;
}
m_int modinv(m_int x,int m=max_int){
    int a = x.d;
    int b = m;
    int u = 1;
    int v = 0;
    while(b){
        int t = a/b;
        a -= t*b;
        swap(a,b);
        u -= t*v;
        swap(u,v);
    }
    u %= m;
    if (u < 0) u += m;
    return u;
}
m_int comb(m_int n,m_int r){
    if(r>n || n < 0 || r < 0) return 0;
    /*
    int nterms = min(r.d,n.d-r.d);
    m_int num=1,den=1;
    REP(i,nterms){
