int N,K;
long long comba[200001];
long long combb[200001];
long long comb(int n, int r)
{
    if (n - r < r) r = n - r;
    if (r == 0) return 1;
    if (r == 1) return n;

    int numerator[r];
    int denominator[r];

    for (int k = 0; k < r; k++)
    {
        numerator[k] = n - r + k + 1;
        denominator[k] = k + 1;
    }

    for (int p = 2; p <= r; p++)
    {
        int pivot = denominator[p - 1];
        if (pivot > 1)
        {
            int offset = (n - r) % p;
            for (int k = p - 1; k < r; k += p)
            {
                numerator[k - offset] /= pivot;
                denominator[k] /= pivot;
            }
        }
    }

    long long result = 1;
    for (int k = 0; k < r; k++)
    {
        if (numerator[k] > 1) result = (numerator[k]*result)%1000000007;
    }

    return result;
}


int main(){
    long long ans = 0;
    cin >> N >> K;
    if(K>=N-1){
        ans = comb(2*N-1,N-1);
    } else {
        comba[0] = 1;
        combb[0] = 1;
        for (int i=1;i<=K;i++){
            comba[i] =( comba[i-1]*(N - i + 1)/i)%1000000007;
            combb[i] =( combb[i-1]*(N - i)/i)%1000000007;
        }
        for (int i = 0;i<K+1;i++){
            ans = (ans +(combb[i] * comba[i] % 1000000007))%1000000007;
        }
    }
    cout << ans << endl;
}

