class Math
{
public:
    vector<ll>fact,invfact;
    Math( int n )
    {
        fact.resize(n);
        invfact.resize(n);
        fact[0] = invfact[0] = 1;
        for(int i=1;i<n;i++)
        {
            fact[i] = mod( i * fact[i-1] );
            invfact[i] = modinv( fact[i] );
        }
    }
    ll modinv( ll x, ll m = MOD )
    {
        return expo(x,m-2,m);
    }
    ll expo( ll base, ll exp, ll m = MOD )
    {
        ll res = 1;
        while( exp )
        {
            if( exp&1 )
                res = mod( res*base, m );
            base = mod( base*base, m );
            exp >>= 1;
        }
        return res;
    }
    ll choose( ll n, ll k )
    {
        if( k < 0 || k > n ) return 0;
        ll ans = fact[n];
        ans = mod( ans * invfact[n-k] );
        ans = mod( ans * invfact[k] );
        return ans;
    }
};

