#include <vector>
template <long long MOD> class Combination_calcurator {
  using ll = long long;

private:
  std::vector<ll> fac;
  std::vector<ll> facinv;
  ll MAX;
  ll modpow(ll a, ll p) {
    if (p == 0)
      return 1;
    if (p % 2 == 0) {
      ll d = modpow(a, p / 2);
      return d * d % MOD;
    } else {
      return a * modpow(a, p - 1) % MOD;
    }
  }
  ll modinv(ll a) {
    // require:m is prime and gcd(a,m) = 1
    return modpow(a, MOD - 2);
  }

public:
  Combination_calcurator(ll max) {
    MAX = max;
    fac.resize(MAX + 1);
    facinv.resize(MAX + 1);
    fac[0] = 1;
    for (int i = 1; i <= MAX; i++) {
      fac[i] = fac[i - 1] * i % MOD;
    }
    facinv[MAX] = modinv(fac[MAX]);
    for (int i = MAX - 1; i >= 0; i--) {
      facinv[i] = facinv[i + 1] * (i + 1) % MOD;
    }
  }

  ll calc(ll n, ll r) {
    return (fac[n] * facinv[r]) % MOD * facinv[n - r] % MOD;
  }
};

