// 繰り返し二乗法を用いて a の n 乗を算出する(ただし mod m の空間内)
long long modpow(long long a, long long n, long long mod)
{
    long long ret = 1;
    while (n > 0)
    {
        if (n & 1)
        {
            ret *= a;
            ret = ret % mod;
        }
        a *= a;
        a = a % mod;
        n = (n >> 1);
    }
    return ret;
}

long long modnCk(long long n, long long k, long long mod)
{
    if (k == 0) return 1;
    long long ret = 1, x = 1, y = 1;
    for (long long i = 0; i < k; ++i)
    {
        x *= (n - i);
        x = x % mod;

        y *= (k - i);
        y = y % mod;
    }
    ret = modpow(y, mod - 2, mod) % mod;
    ret = (ret * x) % mod;
    return ret;
}

int main()
{
    long long n, k;
    cin >> n >> k;
    static constexpr long long mod = 1e+9 + 7;

    // 空いている部屋の数に関してループを回す
    long long lmax = k <= n ? k : n - 1;
    long long ans = 1;
    for (long long i = 1; i <= lmax; ++i)
    {
        long long cnt = modnCk(n, i, mod) * modnCk(n - 1, i, mod);
        cnt %= mod;
        if (cnt < 0)
            cnt = (cnt + mod) % mod;
        ans += cnt;
        ans = ans % mod;
        if (ans < 0)
            ans = (ans + mod) % mod;
    }

    cout << ans << endl;
    return 0;
}

