    IF[i] = modinv(F[i], kMod);
  }

  ll ans = 0;
  for (int z = 0; z <= min(K, N - 1); ++z) {
    ll tmp = Count(N, z) * comb(N, z) % kMod;
    ans = (ans + tmp) % kMod;
  }

  cout << ans << endl;
  return 0;
}

