// テーブルを作る前処理
const int MAX = 2 * 1000 * 1000 + 5;
long long fac[MAX], finv[MAX], inv[MAX];
void CombInit() 
{
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

// 二項係数計算(nCk)
long long CombExec(int n, int k)
{
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

int main()
{
	ll n, k;
	cin >> n >> k;

	CombInit();

	ll maxR = min(n, k);
	ll ans = 1;
	REPN(i, 1, maxR + 1) {
		ll zeroCmb = CombExec(n, i);
		ll sikiriNum = n - i - 1;
		ll oneCmb = CombExec(n - 1, sikiriNum);
		ans += (zeroCmb * oneCmb);
		ans %= MOD;
	}

	cout << ans << endl;
	return 0;
}

