  fact_inv[n] = modPow(fact[n], MOD-2, MOD);
  for (int i = n-1; i >= 0; i--) fact_inv[i] = (fact_inv[i+1] * (i+1)) % MOD;

  ll ret = 0;
  for (int m = 0; m <= min(k, n-1); m++) {
    ll n_c_m = (((fact[n] * fact_inv[n-m]) % MOD) * fact_inv[m]) % MOD;
    ll n_h_m = (((fact[n-1] * fact_inv[n-m-1]) % MOD) * fact_inv[m]) % MOD;

