using namespace std;

const int MOD = 1e9 + 7;

class Com{
public:
    int n;
    int mod;

    Com(int n, int mod){
        this->n = n;
        this->mod = mod;

        f.resize(n + 1);
        fInv.resize(n + 1);
        inv.resize(n + 1);

        f[0] = f[1] = 1;
        fInv[0] = fInv[1] = 1;
        inv[1] = 1;

        for(int i = 2; i <= n; i++){
            f[i] = (f[i - 1] * i) % mod;
            inv[i] = mod - (inv[mod % i] * (mod / i)) % mod;
            fInv[i] = (fInv[i - 1] * inv[i]) % mod;
        }
    }

    long long query(int n, int k){
        if(n < k){
            return 0;
        }
        if(n < 0 || k < 0){
            return 0;
        }
        return (((f[n] * fInv[k]) % mod) * fInv[n - k]) % mod;
    }
private:
    vector<long long> f, fInv, inv;
};

int main(){

    int n, k;
    cin >> n >> k;

    Com com(2 * n, MOD);

    if(k >= n - 1){
        cout << com.query(2 * n - 1, n) << endl;
    }
    else{
        long long ans = 0;

        for(int i = 0; i <= k; i++){
            long long temp = (com.query(n, i) * com.query(n - 1, i)) % MOD;
            ans = (ans + temp) % MOD;
        }
