void solve(int N,int M,int n,int a,int res)
{
    if (res==1)
    {
        if (a>n) return;
        mp[n]++;
        LL tmp=A(N,M);
        for (it=mp.begin();it!=mp.end();it++) tmp=tmp*s[it->second]%mod;
        ans=(tmp+ans)%mod;
        mp[n]--;
        return ;
    }
    if (a*res>n) return ;
    if (a*res==n)
    {
        mp[a]+=res-1;
        solve(N,M,a,a,1);
        mp[a]-=res-1;
