    for (int k=1;n-a*k>=a+1;k++)
    {
        mp[a]+=k;
        solve(N,M,n-a*k,a+1,res-k);
        mp[a]-=k;
    }
    for (int i=a+1;i<=n;i++)
    {
        mp[i]++;
        solve(N,M,n-i,i,res-1);
        mp[i]--;
    }
}

