typedef long long ll;
ll qpmod(ll a, ll n, ll MOD)
{
	ll ret = 1;
	while (n)
	{
		if (n & 1)
			ret = (ret * a) % MOD;
		a = (a * a) % MOD;
		n >>= 1;
	}
	return ret;
}
ll C(ll n, ll m, ll MOD)
{
	if (m > n)
		return 0;
	if (m > n - m)
		m = n - m;
	ll a = 1, b = 1;
	while (m)
	{
		a = (a * n) % MOD;
		b = (b * m) % MOD;
		m--;
		n--;
	}
	return a * qpmod(b, MOD - 2, MOD) % MOD;
}
ll Lucas(ll n, ll k, ll MOD)
{
	if (k == 0)
		return 1;
	return C(n % MOD, k % MOD, MOD) * Lucas(n / MOD, k / MOD, MOD) % MOD;
}
int main()
{
	ll n, k;
	ll M = 1e9 + 7;
	cin >> n >> k;
	ll ans;
	ans = Lucas(2 * n - 1, n - 1, M);
	ll mm = n - 1 - k;
	for (ll m = 1; m <= mm; m++)
	{
		ans = ans + M - (Lucas(n, n - m, M) * Lucas(n - 1, m - 1, M)) % M;
		ans %= M;
	}
	cout << ans%M << endl;
}

