ll combination_memo(ll n, ll r, ll pre, ll mod){
    // pre = nCr-1
    // return nCr
    if (n == r && n == 0) return 1;
    else if (n <= 0 || r < 0 || r > n) return 0;
    ll numerator = ll(n - r + 1) % mod;
    ll denomenator = modinv(r, mod) % mod;
    ll val = (numerator * denomenator) % mod;
    val *= pre;
    return val % mod;
}

