  if ( k > n ) { k = n; }

  long long ans = 0;
  for ( int i = 0; i <= k; i++ ) {
    ans += (BC.combination(n, i) * BC.combination(n-1, i)) % mod;
    ans %= mod;
  }

  cout << ans << endl;
  return 0;
}

