#include <bits/stdc++.h>
using namespace std;
using ll = long long;

const int MOD = 1000000007;
const int MAX_SIZE = 200001;

vector<ll> fac(MAX_SIZE);
vector<ll> fac_inv(MAX_SIZE);
vector<ll> inv(MAX_SIZE);

void init_com()
{
    fac.at(0) = fac.at(1) = 1;
    fac_inv.at(0) = fac_inv.at(1) = 1;
    inv.at(1) = 1;
    for (int i = 2; i < MAX_SIZE; i++)
    {
        fac.at(i) = fac.at(i - 1) * i % MOD;
        inv.at(i) = MOD - inv.at(MOD % i) * (MOD / i) % MOD;
        fac_inv.at(i) = fac_inv.at(i - 1) * inv.at(i) % MOD;
    }
}

ll com(int n, int k)
{
    if (n < k)
        return 0;
    if (n < 0 || k < 0)
        return 0;
    return fac.at(n) * (fac_inv.at(k) * fac_inv.at(n - k) % MOD) % MOD;
}

int main()
{
    int n, k;
    cin >> n >> k;

    init_com();

    if (k > n - 1)
        k = n - 1;

    ll res = 0;
    for (int z = 0; z <= k; z++)
    {
        res += com(n, z) * com(n - 1, z) % MOD;
        res %= MOD;
    }
    cout << res << endl;
}

