ll MOD=1000000000+7;
ll pow_mod(ll a, ll n){//aのn乗を計算します。
  ll x = 1;
  ll k=a;
  ll m=n;
  while(m > 0){//全てのbitが捨てられるまで。
    if(m&1){//1番右のbitが1のとき。
      x = (x*k)%MOD;
    }
    k = (k*k)%MOD;
    m >>= 1;//bit全体を右に1つシフトして一番右を捨てる。
  }
  return x%MOD;
}
//---------------------------------------------------------------------------------------------------
ll f[200000], rf[200000];
ll inv(ll x) {
    ll res = 1;
    ll k = MOD - 2;
    ll y = x;
    while (k) {
        if (k & 1) res = (res * y) % MOD;
        y = (y * y) % MOD;
        k /= 2;
    }
    return res;
}
void init() {
    f[0] = 1;
    for(ll i=1;i<200000;i++) f[i] = (f[i - 1] * i) % MOD;
    for(ll i= 0;i< 200000;i++) rf[i] = inv(f[i]);
}
//---------------------------------------------------------------------------------------------------
ll comb_mod(ll n, ll k) {
    ll a = f[n]; // = n!
    ll b = rf[n-k]; // = (n-k)!
    ll c = rf[k]; // = k!

    ll bc = (b * c) % MOD;

    return (a * bc) % MOD;
}
int main(){
  ll n, k;
  cin>>n>>k;
  ll sum=0;
  init();
  if(n-1<k){
    cout<<(comb_mod(2*n-1,n-1));
    return 0;
  }
  for(ll j=0;j<=min(k,n-1);j++){
    ll temp=comb_mod(n-1, j);
    temp=pow_mod(temp,2);
    temp=(temp*n)%MOD;
    temp=(temp*pow_mod(n-j, MOD-2))%MOD;
    sum=(sum+temp)%MOD;
  }
  cout<<sum;
  return 0;
}

