#include <iostream>
using namespace std;

uint64_t powmod(uint64_t x, uint64_t y, uint64_t p)
{
	if(y == 0){
		return 1;
	} else if(y % 2 == 1){
		return (powmod(x, y-1, p) * x) % p;
	} else {
		uint64_t t = powmod(x, y/2, p);
		return (t * t) % p;
	}
}

void fracs(uint64_t n, uint64_t p,
	uint64_t *pnf, uint64_t *ipnf)
{
	pnf[0] = 1;
	for(uint64_t i=0; i<n; i++){
		pnf[i+1] = (pnf[i] * (i+1)) % p;
	}
	ipnf[n] = powmod(pnf[n], p-2, p);
	for(uint64_t i=n; i>0; i--){
		ipnf[i-1] = (ipnf[i] * i) % p;
	}
}

int main()
{
	int n, k;
	cin >> n >> k;

	int p = 1000000007;
	uint64_t
		*pnf = new uint64_t[200001],
		*ipnf = new uint64_t[200001];
	fracs(n, p, pnf, ipnf);
	if(n-1 < k){
		k = n-1;
	}

	uint64_t res = 0;
	for(int i=0; i<k+1; i++){
		uint64_t r = 1;
		r = (pnf[n] * ipnf[n-i]) % p * ipnf[i] % p;
		r *= (pnf[n-1] * ipnf[n-1-i]) % p * ipnf[i] % p;
		r %= p;
		res += r;
	}

	cout << res % p;

	return 0;
}

