const int MOD = 1000000007;
int m_add(int a, int b)
{
	return (a + b) % MOD;
}
int m_sub(int a, int b)
{
	return (a + MOD - b) % MOD;
}
int m_mul(int a, int b)
{
	return (a * b) % MOD;
}
int m_pow(int x, int n)
{
	if (n == 0) return 1;
	ll res = m_pow((x * x) % MOD, n / 2);
	if (n & 1) res = (res * x) % MOD;
	return res;
}
int m_divide(int a, int b)
{
	return m_mul(a, m_pow(b, MOD - 2));
}


//---------- 組み合わせ ----------
int m_comb(int n, int r)
{
	int i;
	int p = 1;
	for (i = 1; i <= r; i++)
	{
		p = m_mul(p, (n - i + 1));
		p = m_divide(p, i);
	}
	return p;
}

int m_comb_with_rep(int n, int r)
{
	return m_comb(n + r - 1, r);
}

int N, K;

signed main()
{
	cin >> N >> K;

	int n = m_comb_with_rep(N, N);
	if (N <= K + 1)
	{
		cout << n << endl;
		return 0;
	}

	int a = N - (K + 1);
	int ans = n;
	for (int i = 0; i <= a; i++)
	{
		int d = m_comb_with_rep(i, N - i);
		int c = m_comb(N, N - i);
		int k = m_mul(d, c);
		ans = m_sub(ans, k);
	}

	cout << ans << endl;
}

