typedef long long ll;

ll modnum = 1000000007;
ll MAX = 510000;
vector<ll> fac(MAX), finv(MAX), inv(MAX);

//繰り返し二乗法
ll RepeatSquaring(ll N, ll P, ll M) {
  if (P == 0) return 1;
  if (P == 1) return N % M;
  if (P % 2 == 1) return (N * RepeatSquaring(N, P-1, M)) % M;
  ll t = RepeatSquaring(N, P/2, M);
  return (t * t) % M;
}

//nCkを計算
ll Combination(ll n, ll k) {
  ll res = fac[n] * (finv[k] * finv[n-k] % modnum) % modnum;
  return res;
}

void Create_Table() {
  fac[0] = fac[1] = 1;
  finv[0] = finv[1] = 1;
  inv[1] = 1;

  for(ll i = 2; i <= MAX; i++) {
    fac[i] = fac[i-1] * i % modnum;
    inv[i] = modnum - inv[modnum%i] * (modnum / i) % modnum;
    finv[i] = finv[i-1] * inv[i] % modnum;
  }
}

int main() {
  ll n, k;
  cin >> n >> k;

  Create_Table();

  ll ans = 0;
  for(ll i = 0; i < n; i++) {
    ans = (ans + Combination(n, i) * Combination(n-1, i)) % modnum;
  }

  while(ans < 0) {
    ans = ans + modnum;
  }
  cout << ans << endl;

  return 0;
}

