// fact(n)%MOD, invFact(n)%MOD, inv(n)%MOD, nCk
// Constructor O(N)
// other O(1)
template<typename T>
class Choose {
public:
	std::vector<T> fact, inv, invFact;

	Choose(T N) :fact(N), inv(N), invFact(N) {
		inv[1] = 1;
        for(int i=2;i<inv.size();++i) inv[i] = MOD - (MOD / i) * inv[MOD % i] % MOD;
		fact[0] = invFact[0] = 1;
        for(int i=1;i<fact.size();++i){
			fact[i] = fact[i - 1] * i % MOD;
			invFact[i] = (invFact[i - 1] * inv[i]) % MOD;
		}
	}

	//Get nCk
	T operator () (T n, T k) const {
		if (not ((T)0 <= k and k <= n)) return 0;
		return (((fact[n] * invFact[k]) % MOD) * invFact[n - k]) % MOD;
	}
};


long long C(Choose<long long> const& choose, int x, int y) {
    // O(1)
    return choose(x, y);
}

int main() {
    int N, K;
    long long ans = 0;
    std::cin >> N >> K;
    Choose<long long> choose(N+1); // O(N)

    for (int k=0; k<=std::min(N, K); k++) {
        // n-k個の部屋にkだけ振り分ける
        const auto x = C(choose, N-1, k);
        const auto y = C(choose, N, k);
        ans += x * y % MOD;
        ans %= MOD;
    }
    std::cout << ans << std::endl;
}

