    if(K>N){
        ans = comb(2*N-1,N-1);
    } else {
        for (int i = 0;i<=K;i++){
            ans = (ans +(comb(N-1,i) * comb(N,i) % 1000000007))%1000000007;
        }
    }
    cout << ans << endl;
}

