long long Combination(int n, int k)
{
  if (n - k < k)
    k = n - k;
  if (k == 0)
    return 1;
  if (k == 1)
    return n;
  vector<int> numerator(k);
  vector<int> denominator(k);
  for (int i = 0; i < k; i++)
  {
    numerator[i] = n - k + i + 1;
    denominator[i] = i + 1;
  }
  for (int i = 2; i <= k; i++)
  {
    int pivot = denominator[i - 1];
    if (pivot > 1)
    {
      int offset = (n - k) % i;
      for (int j = i - 1; j < k; j += i)
      {
        numerator[j - offset] /= pivot;
        denominator[j] /= pivot;
      }
    }
  }
  long long result = 1;
  for (int i = 0; i < k; i++)
  {
    if (numerator[i] > 1)
    {
      result *= numerator[i];
      result %= 1000000007;
    }
  }
  return result;
}

int main()
{
  int n, k;
  cin >> n >> k;
  if (n - 1 <= k)
  {
    cout << Combination(2 * n - 1, n - 1) << endl;
  }
  else
  {
    int count = 0;
    rep(i, k + 1, n)
    {
      count += (Combination(n, i) * Combination(n - 1, i));
    }
    cout << Combination(2 * n - 1, n - 1) - count << endl;
  }
  return 0;
}

