long twon(long n, long mod){
    if(n == 0)
        return 1;
    if(n == 1)
        return 2;
    if(n % 2 == 0){
        long temp;
        temp = twon(n/2, mod);
        temp *= temp;
        temp %= mod;
        return temp;
    }else{
        long temp1, temp2;
        temp1 = twon((n+1)/2, mod);
        temp2 = twon((n-1)/2, mod);
        temp1 *= temp2;
        temp1 %= mod;
        return temp1;
    }
}

