    long long x;
    mint(long long x = 0) : x(x % mod) {
    }

    mint& operator+=(const mint a) {
        if ((x += a.x) >= mod) {
            x -= mod;
        }
        return *this;
    }
    mint& operator-=(const mint a) {
        if ((x += mod-a.x) >= mod) {
            x -= mod;
        }
        return *this;
    }
    mint& operator*=(const mint a) {
        (x *= a.x) %= mod;
        return *this;
    }
    mint operator+(const mint a) const {
        mint res(*this);
        return res+=a;
    }
    mint operator-(const mint a) const {
        mint res(*this);
        return res-=a;
    }
    mint operator*(const mint a) const {
        mint res(*this);
        return res*=a;
    }
    mint pow(long long t) const {
        if (!t) {
            return 1;
        }
        mint a = pow(t>>1);
        a *= a;
        if (t&1) {
            a *= *this;
        }
        return a;
    }

    // for prime mod
    mint inv() const {
        return pow(mod-2);
    }
    mint& operator/=(const mint a) {
        return (*this) *= a.inv();
    }
    mint operator/(const mint a) const {
        mint res(*this);
        return res/=a;
    }
};


long long modpow(long long base, long long exp, long long mod) {
    base %= mod;
    long long result = 1;
    while (exp > 0) {
        if (exp & 1) {
            result = (result * base) % mod;
        }
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

long long combination(long long n, long long r) {
    uint64_t ans = 1;
    for (uint64_t d = 1; d <= r; ++d) {
        ans *= n--;
        ans /= d;
    }
    return ans;
}

class Combination {
public:

    int mod;
    vector<long long> fact;
    vector<long long> inv;

    // O(n)
    Combination(int n, int mod) : mod(mod) {
        assert(0 < n);
        this->fact.resize(n + 1, 1);
        this->inv.resize(n + 1, 1);

        for (int i = 1; i < fact.size(); ++i) {
            this->fact[i] = (i * this->fact[i - 1]) % this->mod;
            this->inv[i] = modpow(this->fact[i], this->mod - 2, this->mod);
        }
    }

    long long nCr(int n, int k) {
        assert(0 <= n and n < this->fact.size() and 0 <= k);
        assert(n >= k);
        auto a = this->fact[n];
        auto b = (this->inv[k] * this->inv[n - k]) % this->mod;
        return (a * b) % this->mod;
    }

    long long nHr(int n, int k) {
        return nCr(n + k - 1, k);
    }
};

const int MOD = 1000000000 + 7;

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    LL N, K;
    cin >> N >> K;

    Combination comb(400100, MOD);

    mint<MOD> ans = 0;
    FOR(k, 0, min(K + 1, N)) {
        ans += comb.nCr(N, k) * comb.nCr(N - k + k - 1, k);
    }
    print(ans.x);

    return 0;
}

