//まず0人になる部屋をi個選び、
//残りのN-i個の部屋にN人を配列する(仕切りを使う)
void solve(){
	k = min(k,n-1);
	combination c(n);
	for(int i=0;i<=k;i++){
		ans += c(n,i)*c(n-1,n-i-1);
	}
}

int main(){
	cin >> n >> k;

	solve();

	cout << ans.x << endl;
	return 0;
}

