class Comb {
private:
	int MOD;
	long long* fac;
	long long* finv;
	long long* inv;
public:
	// 事前にテーブルを作成
	Comb(int MAX, int MOD) {
		this->MOD = MOD;

		fac = new long long[MAX + 1];
		finv = new long long[MAX + 1];
		inv = new long long[MAX + 1];

		fac[0] = fac[1] = 1;
		finv[0] = finv[1] = 1;
		inv[1] = 1;
		for (int i = 2; i <= MAX; i++) {
			fac[i] = fac[i - 1] * i % MOD;
			inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
			finv[i] = finv[i - 1] * inv[i] % MOD;
		}
	}

	~Comb() {
		delete[] fac, finv, inv;
	}

	// 二項係数計算
	long long calc(int n, int k){
		if (n < k) return 0;
		if (n < 0 || k < 0) return 0;
		return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
	}
};

int main() {
	int n, k;
	cin >> n >> k;

	Comb comb = Comb(n * 2, MOD);

	ll ans;

	if (k >= n) {
		ans = comb.calc(n+n-1, n);
	} else {
		ans = 0;
		for (int i=0; i<=k; i++) { // i: 空き部屋の数
			ans = (ans + (comb.calc(n, i) * comb.calc((n-i) + i - 1, i)) % MOD) % MOD;
		}
	}

	cout << ans << endl;

	return 0;
}

