    enter = [&] (int c) {
        if (c == k) {
            all.insert(cur);
            return;
        }
        for (int i = 0; i < n; i++) {
            if (cur[i] == 0) {
                continue;
            }
            for (int j = 0; j < n; j++) {
                if (i != j) {
                    cur[j]++;
                    cur[i]--;
                    enter(c+1);
