int modpow(int a, int k, int p){
    int ans = 1;
    while (k > 0){
        if (k % 2 == 1){
            ans *= a;
            ans %= p;
        }
        a = (a*a) % p;
        k = k / 2;
    }
    return ans;
}

// ax+by=1の解
int extgcd(int a, int b, int& x, int& y){
    int d = a;
    if (b != 0){
        d = extgcd(b, a%b, y, x);
        y -= (a / b)*x;
    }
    else{
        x = 1; y = 0;
    }
    return d;
}

// mod mでのaの逆数
int mod_inv(int a, int m){
    int x, y;
    extgcd(a, m, x, y);
    return (m + x%m) % m;
}

// nの階乗 mod p
int factorial(int n, int p){
    int r = 1;
    for (int i = 1; i <= n; i++)
        r = (r*i) % p;
    return r;
}

// nPr mod p
int permutation(int n, int r, int p){
    int a = 1;
    for (int i = n-r+1; i <= n; i++)
        a = (a*i) % p;
    return a;
}

// nCr mod p
int combination(int n, int r, int p){
    if (r == 0 || r == n) return 1;
    if (r > n) return 0;
    if (r > n / 2) r = n - r;
    int numerator = permutation(n, r, p);
    int denominator = factorial(r, p) % p;
    int inv = mod_inv(denominator, p);
    return (numerator * inv) % p;
}



void solve(){
    int n, k;
    cin >> n >> k;

    if(k>=n){
        cout << combination(2*n-1,n,mod) << endl;
        return;
    }

    int ans=0;
    // zeroの数を固定
    for(int x=0; x<=k; x++){
        ans += combination(n,x,mod) * combination(n-1,n-x-1,mod) % mod;
        ans %= mod;
    }
    cout << ans << endl;

}

signed main(){
    cout << fixed << setprecision(18);
    cerr << fixed << setprecision(18);
    solve();
}

