	void solve()
	{
		auto N = read<int>()();
		auto k = read<int>()();
		// z 0s:
		//   binom(n,z) * binom(n-1,z)
		//   = n * (n-z) * ((n-1) * ... * (n-z+1))^2 / (z!)^2
		// z = 0, 1, ..., min(k, n)
		auto f = get_fact(N, MOD);
		auto fi = get_fact_inv(N, MOD);
		auto binom = [&f, &fi](auto n, auto m) { return m < 0 || n < m ? 0 : f[n] * fi[m] % MOD * fi[n - m] % MOD; };
		int64_t s = 0;
		for (int z = 0; z <= N && z <= k; ++z) s = (s + binom(N, z) * binom(N - 1, z) % MOD) % MOD;
		std::cout << s << std::endl;
	}
