const int MAX = 1e6 + 10;

long long fac[MAX], finv[MAX], inv[MAX];

// テーブルを作る前処理
void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

// 二項係数計算
long long COM(int n, int k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}


int main(){
    ll n,k; cin >> n >> k;
    COMinit();
    mint ans;
    if(k >= n-1)ans = mint(COM(2*n-1, n));
    else{
        ans = mint(COM(2*n-1,n));
        for(int i = k+1; i < n; i++){
            ll j = n-i;
            ans -= mint(COM(n,i)) * mint(COM(i+j-1, i));
        }
    }
    cout << ans << endl;
}

