#define M 1000000007

std::vector<ll> fac(400003); //n!(mod M)
std::vector<ll> ifac(400003); //k!^{M-2} (mod M)

//x^n(mod M)d
ll
mpow(ll x, ll n)
{
    ll ans = 1;
    while (n > 0){
        if (n & 1) ans = ans*x % M;
        x = x*x % M;
        n = n >> 1;
    }
    return ans;
}

void
cominit()
{
    fac[0] = 1;
    ifac[0] = 1;
    for (ll i = 0; i < 400003; i++){
        fac[i+1] = fac[i] * (i+1) % M; // n! mod M
        ifac[i+1] = ifac[i] * mpow(i+1, M-2) % M; // k!^{M-2} mod M
    }
}


ll
comb(ll a, ll b)  // aCb mod M
{
    if (a == 0 && b == 0) return 1;
    if (a < b || a < 0) return 0;
    ll tmp = ifac[a-b] * ifac[b] % M;
    return tmp * fac[a] % M;
}

int main() {
    cominit();
    ll n, k;
    cin >> n >> k;
    ll res;
    if (n < k) {
        res = comb(n + n -1, n);
    } else {
        res = 0;
        for (ll i = 0; i <= k ; ++i) {
            //if (i == 0 && k < 2) continue;
            res += comb(n - 1, n - i - 1) * comb(n, i);
            res %= M;
        }
    }
    cout << res << endl;
}

