using namespace std;
static const int MAX = 1000000;
long long fact[MAX], fact_inv[MAX], inv[MAX];

void InitmodnCk(long long mod)
{
    fact[0] = fact[1] = 1;
    fact_inv[0] = fact_inv[1] = 1;
    inv[0] = inv[1] = 1;
    for (int i = 2; i < MAX; ++i)
    {
        fact[i] = fact[i - 1] * i % mod;
        inv[i] = mod - inv[mod % i] * (mod / i) % mod;
        fact_inv[i] = fact_inv[i - 1] * inv[i] % mod;
    }
}

long long modnCk(long long n, long long k, long long mod)
{
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    long long ret = fact[n] * (fact_inv[k] * fact_inv[n - k] % mod) % mod;
    if (ret < 0) ret = (ret + mod) % mod;
    return ret;
}

int main()
{
    long long n, k;
    cin >> n >> k;
    static constexpr long long mod = 1e+9 + 7;
    InitmodnCk(mod);
    // 空いている部屋の数に関してループを回す
    long long ans = 0;
    if (k >= n - 1)
    {
        ans += modnCk(2 * n - 1, n, mod);
        ans = ans % mod;
        if (ans < 0) ans = (ans + mod) % mod;
        cout << ans << endl;
        return 0;
    }
    ans += 1;
    for (long long i = 1; i <= k; ++i)
    {
        ans += modnCk(n, i, mod) * modnCk(n - 1, i, mod);
        ans = ans % mod;
        if (ans < 0)
            ans = (ans + mod) % mod;
    }

    cout << ans << endl;
    return 0;
}

