	pre();
	int n, k;
	cin >> n >> k;
	int ans = 0;
	for(int i = 0; i <= min(n - 1, k); i++) {
		ans = (ans + ncr(n, i) * ncr(n - 1, n - i - 1) % mod) % mod;
	}
	cout << ans;

	return 0;
}

