const int mod = 1e9 + 7;

long long inv(long long x){
  long long m = mod, u = 1, v = 0;
  while(m){
    long long t = x / m;
    x -= t * m; swap(x, m);
    u -= t * v; swap(u, v);
  }
  u %= mod;
  if(u < 0) u += mod;
  return u;
}

long long power(long long a, long long e){
  if(e == 0) return 1ll;
  if(e & 1){
    return power(a, e - 1) * a % mod;
  }
  long long re = power(a, e >> 1);
  return re * re % mod;
}

