ll poww(long long a, long long n, long long m)
{
        long long ans = 1;
        long long mul = a;
        while (n != 0)
        {
                if (n % 2)
                {
                        ans = (ans * mul) % m;
                }
                mul = (mul * mul) % m;
                n /= 2;
        }
        return ans;
}
/* 
Fermat's little theorem: 
1) (a/b)%mod= (a*(poww(b,mod-2,mod)))%mod iff a%b==0
2) (a^b)%mod= (a^(b%(mod-1)))%mod iff mod is prime
*/
const int SZ=5e5+100;
ll factorial[SZ];
void precompute()
{
	factorial[0]=1;
	for(int i=1;i<SZ;i++)
	{
		factorial[i]=(factorial[i-1]*i)%MOD;
	}
}
ll InverseEuler(ll n, ll m)
{
    return poww(n, m - 2, m);
}
ll C(ll n, ll r, ll m)
{

    return (factorial[n] * ((InverseEuler(factorial[r], m) * InverseEuler(factorial[n - r], m)) % m)) % m;
}
int32_t main()
{
	ios::sync_with_stdio(0);cin.tie(0);
	precompute();
	int n,k;
	cin>>n>>k;
	if(k>=n-1)
	{
		cout<<C(2*n-1,n-1,MOD)<<endl;
		return 0;
	}
	int ans=0;
	for(int i=0;i<=k;i++)
	{
		ans+=(C(n,i,MOD)*C(n-1,i,MOD))%MOD;
		ans%=MOD;
	}
	cout<<ans<<endl;
}

