		a = a * a % MOD;
		b >>= 1;
	}
	return pow;
}

ll inv_mod(ll n) {
	return pow_mod(n, MOD - 2);
}

int fact_mod(int n) {
	ll fact = 1;
	for (int i = n; i > 0; --i) fact = (fact * i) % MOD;
