ll comb_mod(ll n, ll r) {
  //nCk = nCk-1 * n-k+1/k
	ll comb = 1;
	if (n / 2 < r) return comb_mod(n, n - r);
	else {
		for (ll i = 0; i < r; ++i)
			comb = (comb * (n - i)) % MOD;
		return (comb * inv_mod(fact_mod(r))) % MOD;
	  }
	}

void setComb_mod(vector<ll> &combs, ll n, ll r) {
	//nCk = nCk-1 * n-k+1/k
