	ll comb = 1;
	combs[0] = combs[n] = comb;
	if (n / 2 < r) comb_mod(n, n - r);
	else {
		for (ll i = 1; i <= r; ++i) {
			comb = (comb * (n - i + 1) * inv_mod(i)) % MOD;
			combs[i] = combs[n-i] = comb;
		}
	}
