static constexpr ll size = 1e6;
VL fac(size);
VL finv(size);
VL inv(size);

ll comb(ll a, ll b) {

	static ll n = 0;
	if (n > a) {
		return fac[a] * (finv[b] * finv[a - b] % MOD) % MOD;
	}
	fac[0] = fac[1] = 1;
	finv[0] = finv[1] = 1;
	inv[1] = 1;
	FOR(i, 2, a + 1) {
		inv[i] = MOD - inv[MOD % i] * (MOD / i) % MOD;
		fac[i] = fac[i - 1] * (ll)i % MOD;
		finv[i] = finv[i - 1] * inv[i] % MOD;
	}
	n = a + 1;
	return comb(a, b) % MOD;
}

ll pow(ll a, ll b) {
	ll ans = 1;
	while (b > 0) {
		if (b % 2 == 1) {
			ans *= a;
			ans %= MOD;
		}
		b /= 2;
		a *= a;
		a %= MOD;
	}
	return ans;
}

auto solve(ll n, ll k) {

	ll ans = 0;
	ll t = std::max(n - k, 1LL);
	FOR(i, t, n + 1) {
		ll tmp = comb(n, n - i);
		ll pp = comb(n - 1, n - i);
		ll ad = (tmp * pp) % MOD;
		ans += ad;
		if (ans > MOD) { ans %= MOD; }
	}
	return ans;
}
signed main() {
	ll n, k;
	cin >> n >> k;


	auto ans = solve(n, k);
	cout << ans << endl;

}

