    if (K >= N - 1) { return outln(moc::comb(2 * N - 1, N)); }
    mint ans = 0;
    for (int k = 0; k <= K; k++) { ans += moc::comb(N - 1, k) * moc::comb(N, k); }
    outln(ans);
    return 0;
}

