class binomial_coefficients {
	int MAX_VAL;
	vector<int> fac, mmi;

public:

	binomial_coefficients(){
	}

	binomial_coefficients(int num){
		init(num);
	}

	~binomial_coefficients(){

	}

	void init(int num){
		MAX_VAL = num+1; 

		fac.resize(MAX_VAL);
		mmi.resize(MAX_VAL);

		modular_multiplicatibe_inverse();
	}

	void factorial_mod(){
		 fac[0] = fac[1] = 1;
		for(long long i = 2; i < MAX_VAL; fac[i] %= MOD, i++)
			fac[i] = fac[i - 1] * (i % MOD);
	}

	long long power(long long x, long long n){
		long long ans = 1;
		for(;n;n >>= 1, x *= x, ans %= MOD, x %= MOD)
			if(n&1)ans*=x;
		return ans%MOD;
	}

	void exgcd(int a, int b, int &x, int &y){
		if(b == 0){
			x = 1;
			y = 0;
			return ;
		}
		exgcd(b, a % b, y, x);
		y -= a / b * x;
	}

	void modular_multiplicatibe_inverse(){
		int x, y;  
		exgcd(fac[MAX_VAL - 1], MOD, x, y);
		mmi[MAX_VAL-1] = x;
		// mmi[MAX_VAL-1] = power(fac[MAX_VAL-1], MOD-2);
		for(long long i = MAX_VAL - 2; i >= 0; mmi[i]%=MOD, i--)
			mmi[i] = mmi[i + 1] * ((i + 1) % MOD);
	}

	long long combination(long long n, long long r){
		return n < r ? 0 :fac[n] * (mmi[r] * mmi[n-r] % MOD) % MOD;
	}
};

