using MyModInt = ModInt<uint_fast32_t, uint_fast32_t, uint_fast64_t, MOD>;

MyModInt combination(MyModInt n, MyModInt r)
{
    if (r == 0 || r == n) return 1;

    MyModInt bunbo = 1, bunshi = 1;
    for (int i = n.getI(); i > (n - r).getI(); i--)
    {
        bunshi *= i;
    }
    for (int i = r.getI(); i > 0; i--)
    {
        bunbo *= i;
    }

    return bunshi / bunbo;
}

MyModInt combination(const std::vector<MyModInt> &stock, const std::vector<MyModInt>& inv, int n, int r)
{
    if (r == 0 || r == n) return 1;

    return stock[n] * inv[n-r] * inv[r];
}

void stock_kaijo(std::vector<MyModInt> &stock, std::vector<MyModInt> &inv, int n)
{
    stock.resize(n+1);
    inv.resize(n+1);
    stock[0] = 1;
    inv[0] = 1;
    for (int i = 1; i <= n; i++)
    {
        stock[i] = stock[i - 1] * i;
        inv[i] = stock[i].inv();
    }
}

int keta_k(int n, int k)
{
	int keta = 0;
	while (n)
	{
		n /= k;
		keta++;
	}
	return keta;
}

MyModInt baai(int n, int k)
{
    std::vector<MyModInt> stock, inv;
    stock_kaijo(stock, inv, n);

    MyModInt ans;
    for (int m = 0; m <= k; m++)
    {
        ans += combination(stock, inv, n, m) * combination(stock, inv, n - 1, m);
    }
    return ans;
}

