    long long n, k;
    cin >> n >> k;
    for(long long f = 1; f <= 2 * n; f++){
        memo[f] = f * memo[f - 1] % MOD;
    }
    if(k >= n){
        long long ans = fact(2 * n - 1);
        ans *= inv(fact(n));
        ans %= MOD;
        ans *= inv(fact(n - 1));
        ans %= MOD;
        cout << ans << endl;
        return 0;
    }
    long long ans = 0;
    for(int i = 0; i <= k; i++){
        ans += comb(n, i) * P(n - i, i) % MOD;
        ans %= MOD;
    }

    cout << ans << endl;
    return 0;
}

