//二項係数の計算
const int MAX = 510000;
ll fac[MAX],finv[MAX],inv[MAX];

//テーブルの初期化
void COMinit(){
	fac[0] = fac[1] = 1;//階乗
	finv[0] = finv[1] = 1;//階乗の逆元
	inv[1] = 1;//逆元(1の逆元は1)
	for(int i = 2; i < MAX; i++) {
		fac[i] = fac[i - 1] * i % mod;//累積積的な感じ
		inv[i] = mod - inv[mod % i] * (mod / i) % mod;//inv[i] = iの逆元(mod mod)
		finv[i] = finv[i - 1] * inv[i] % mod;//階乗の逆元の計算
	}
}



ll COM(int n,int k){//二項係数の計算
	if(n < k){
		return 0;
	}
	if (n < 0 || k < 0){
		return 0;
	} 
	return fac[n] * (finv[k] * finv[n - k] % mod) % mod;
}

//繰り返し二乗法
ll mod_pow(ll x,ll n){
	ll res = 1;
	while(n > 0){
		if(n & 1){
			res = res * x % mod;
		}
		x = x * x % mod;
		n >>= 1;
	}
	return res;
}
//階乗の計算
ll mod_fact(ll n){
	if (n != 1LL){
		return (mod_fact(n - 1LL) * n) % mod;
	}
	else{
		return 1LL;
	}
}

ll mod_comb(ll n,ll r){//nが大きくて(10^9)でrが小さい時(10^5)にO(r)で計算できるやつ
	ll a = 1LL;
	for(ll i = 1LL; i <= r; i++) {
		a *= (n - i + 1LL);
		a %= mod;
	}
	ll b = mod_pow(mod_fact(r),mod - 2);//r!の逆元（フェルマーの小定理）
	return (a * b) % mod;
}

int main(){
	ll n,k;cin>>n>>k;
	COMinit();
	ll x = min(n,k);
	ll ans = 0;
	for(ll i = 0LL; i <= x; i++) {
		ans += COM(n,i) * COM(n - 1,i) % mod; 
		ans %= mod;
	}
	cout << ans << endl;
	return 0;
}

