class Combination {
public:
    Combination(int n, int m)
        :fact(n+1)
        , inv_fact(n+1)
        , mod(m) {

        fact[0] = 1;
        for(int i = 1; i <= n; i++){
            fact[i] = fact[i-1] * i % mod;
        }
        inv_fact[n] = power(fact[n], mod-2);
        for(int i = n; i >= 1; i--){
            inv_fact[i-1] = inv_fact[i] * i % mod;
        }
    }

    ll operator()(int n, int r){
        ll temp = fact[n] * inv_fact[n-r] % mod;
        return temp * inv_fact[r] % mod;
    }

private:
    int mod;
    vector<ll> fact, inv_fact;

    ll power(ll a, ll x){
        if(x == 0) return 1;
        if(x % 2) return a * power(a, x-1) % mod;
        return power(a * a % mod, x / 2);
    }
};

