int main()
{
    const ll MOD = 1e9+7;
    ll n,k;
    cin >> n >> k;

    // x^y % m
    auto mpow = [](ll x, ll y, ll m)
    {
        ll ret = 1;
        while(y!=0)
        {
            if(y&1) ret = (ret*x) % m;
            x = (x*x) % m;
            y = y >> 1;
        }
        return ret;
    };

    vector<ll> fac(2*n+1, 1); // n! % MOD
    vector<ll> finv(2*n+1, 1); // 1/k! % MOD = k!^(MOD-2) % MOD
    for(int i=0;i<2*n;++i)
    {
        fac[i+1] = (fac[i]*(i+1)) % MOD;
        finv[i+1] = (finv[i]*mpow(i+1, MOD-2, MOD)) % MOD;
    }

    auto mcomb = [&](ll x, ll y, ll m) {
        if(x == 0 && y == 0) return ll(1);
        if(x < y || x < 0) return ll(0);

        ll kf_inv = (finv[x-y]*finv[y]) % m; // 1/{(x-y)!*y!} % m
        return (fac[x]*kf_inv) % m; // nCk = x!/{(x-y)!*y!}
    };

    if(k >= n-1) {
        cout << mcomb(2*n-1, n-1, MOD) << endl;
        return 0;
    }

    ll ans = 0;
    rep(i,k+1) {
        ans += (mcomb(n,i,MOD) * mcomb(n-1,i,MOD)) % MOD;
        ans %= MOD;
    }

    cout << ans << endl;
    return 0;
}

