void exgcd(ll a,ll b,ll &x,ll &y)
{
    ll t;
    if (b==0) 
     {
     	x=1; y=0;
     }
    else 
    {
    	exgcd(b,a%b,x,y);
    	t=x; x=y; y=t-(a/b)*y;
    }
}
ll c(ll x,ll y)
{
	ll i,k,t,xx,yy;
	k=1;
	for (i=y;i>=y-x+1;i--)
	{
		k=k*i%p;
		k=(k+p)%p;
	}
	t=1;
	for (i=x;i>=1;i--)
	{
		t=t*i%p;
		t=(t+p)%p;
	}
	exgcd(t,p,xx,yy);
	return (xx*k%p+p)%p;
}
ll lucas(ll n,ll m)
{
	if (m==0) return 1;
	else return c(n%p,m%p)*lucas(n/p,m/p)%p;
}
