		ans %= mod;
		cout<<ans<<"\n";
		return 0;
	}
	ll fac[n+1];
	fac[0] = 1;
	fac[1] = 1;
	repa(i,2,n+1){
		fac[i] = fac[i-1]*i;
		fac[i] %= mod;
	}	
	repa(i,1,k+1){
		ll temp = fac[n-1];
		temp *= inverse(fac[i]);
		temp %= mod;
		temp *= inverse(fac[n-1-i]);
		temp %= mod;
		temp *= fac[n];
		temp %= mod;
		temp *= inverse(fac[i]);
		temp %= mod;
		temp *= inverse(fac[n-i]);
		temp %= mod;
		ans += temp;
		ans %= mod;
	}
	cout<<ans;
	return 0;
}

