const int MOD = 1e9 + 7, N = 2e5 + 3;

int add(int a, int b) {
    a += b;
    if (a >= MOD) a -= MOD;
    if (a < 0) a += MOD;
    return a;
}

int mul(int a, int b) {
    return 1LL * a * b % MOD;
}

int binpow(int a, int n) {
    int res = 1;
    while (n) {
        if (n % 2)
            res = mul(res, a);
        a = mul(a, a);
        n /= 2;
    }
    return res;
}

int inv(int x) {
    return binpow(x, MOD - 2);
}

int fact[N];

int C(int n, int k) {
    if (n < k) return 0;
    return mul(fact[n], inv(mul(fact[k], fact[n - k])));
}

