const int MAX = 510000;
const int MOD = 1000000007;

long long fac[MAX];
long long finv[MAX];
long long inv[MAX]; // mod MOD k の逆元 inv[k]

// テーブルを作る前処理
void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;

    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

// 二項係数計算
long long COM(int n, int k){
  if (n < k) return 0;
  if (n < 0 || k < 0) return 0;
  return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

// 順列計算
long long perm(long long a, long long b){
    if(a < b) return 0;
    long long tmp = finv[a-b] % MOD;
    return tmp * fac[a] % MOD;
}

long long modPow(long long x, long long n){
  if(n == 0) return 1;
  if(n % 2 == 0) {
    long long sqrtX = modPow(x,n/2);
    return sqrtX * sqrtX % MOD ;
  }else{
    return x * modPow(x,n-1) % MOD;
  }
}
// n種類のものから重複を許してr個選ぶ場合の数
ll modH(ll n, ll r){
  return COM(n+r-1,n);
}
int main(){
  ios::sync_with_stdio(false);
  cin.tie(0);
  COMinit();
  ll n,k;
  cin >> n >> k;

  mint ans = 0;
  // 0 の個数
  rep(zeroCnt,min(n,k)+1){
    // n-zeroCntは1個以上必要なので、
    // あらかじめ(n-zeroCnt)個配った中から
    // 重複を許して選ぶ
    ll res = modH(n-zeroCnt,n-(n-zeroCnt));
    ans += COM(n,zeroCnt) * res;
  }
  cout << ans << endl;
  return 0;
}

