    fact[i]=fact[i-1]*i%MOD;
    inv[i]=MOD-inv[MOD%i]*(MOD/i)%MOD;
    fact_inv[i]=fact_inv[i-1]*inv[i]%MOD;
  }
}
int nCk(int n,int k){
  assert(!(n<k));
  assert(!(n<0 || k<0));
  return fact[n]*(fact_inv[k]*fact_inv[n-k]%MOD)%MOD;
}
int main(){
  int N,K,ans=0;
  cin>>N>>K;
  init_nCk(N);
  vector<long long> vec(min(N-1,K)+1);
  for(int i=0;i<=min(N-1,K);i++){
    vec.at(i)=nCk(N,i);
  }
  init_nCk(N-1);
  for(int i=0;i<=min(N-1,K);i++){
    vec.at(i)*=nCk(N-1,i);
    vec.at(i)%=MOD;
  }
  for(int i=0;i<=min(N-1,K);i++){
    ans+=vec.at(i);
    ans%=MOD;
  }
  cout<<ans<<endl;
}

