	ll res = 1;
	for (int i = 0; i < r; i++) {//nCrの計算 =   {n (n-1) (n-2)  ... (n-r+1) }   /   { r (r-1) (r-2) ... (r-r+1)}
		res = mul_mod(res, n - i);
		res = div_mod(res, r - i);
	}
	return res;
}

