struct Mod {
    static uint64_t PRIME;
    uint64_t value = 0;
    Mod() : value(0) {}
    Mod(ll v) {
        if (v >= 0) {
            value = v % PRIME;
        } else {
            value = PRIME - (-v) % PRIME;
        }
    }
    Mod operator+(const Mod& rhs) const {
        return Mod(*this) += rhs;
    }
    Mod& operator+=(const Mod& rhs) {
        value += rhs.value;
        if (value >= PRIME) {
            value -= PRIME;
        }
        return *this;
    }
    Mod operator-(const Mod& rhs) const {
        return Mod(*this) -= rhs;
    }
    Mod& operator-=(const Mod& rhs) {
        if (value < rhs.value) {
            value += PRIME;
        }
        value -= rhs.value;
        return *this;
    }
    Mod operator*(const Mod& rhs) const {
        return Mod(*this) *= rhs;
    }
    Mod& operator*=(const Mod& rhs) {
        value = (value * rhs.value) % PRIME;
        return *this;
    }
    Mod inv() const {
        return power(*this, PRIME - 2);
    }
    Mod operator/(const Mod& rhs) const {
        return Mod(*this) /= rhs;
    }
    Mod& operator/=(const Mod& rhs) {
        *this *= rhs.inv();
        return *this;
    }
    static Mod power(Mod rhs, ll exp) {
        Mod ans = 1;
        while (exp > 0) {
            if (exp % 2) {
                ans *= rhs;
            }
            rhs *= rhs;
            exp /= 2;
        }
        return ans;
    }
};
uint64_t Mod::PRIME = 1000000007;

int main() {
    ll N, K;
    cin >> N >> K;
    vector<Mod> fact(N+1);
    fact[0] = 1;
    vector<Mod> fact_inv(N+1);
    fact_inv[0] = 1;
    rep(n,1,N+1) {
        fact[n] = fact[n-1] * n;
        fact_inv[n] = fact_inv[n-1] / n;
    }
    Mod ans = 0;
    rep(a,0,min(K,N-1)+1) {
        ans += fact[N] * fact_inv[a] * fact_inv[N-a] * fact[N-1] * fact_inv[a] * fact_inv[N-1-a];
    }
    cout << ans.value << endl;
}

