const ll nmax = 1e9 + 7;
const ll Mod = 998244353;
const double PI = 2 * asin(1);

ll Pow(ll A, ll N){
  if (N == 0) return 1;
  else{
    if (N % 2 == 0) return Pow(A * A % nmax, N / 2) % nmax;
    else return A * Pow(A * A % nmax, N / 2) % nmax;
  }
}

ll nCr(ll N, ll R){
  ll ans = 1;
  for (ll i = 1; i <= R; i++){
    ans *= N + 1 - i; ans %= nmax;
    ans *= Pow(i, nmax - 2); ans %= nmax;
  }
  return ans;
}

int main(){
  ll N, K; cin >> N >> K;

  if (K >= N - 1){
    cout << nCr(2 * N - 1, N - 1) << endl;
    return 0;
  }

  ll DP[K + 1], DP2[K + 1];
  DP[0] = 1; DP2[0] = 1;
  for (ll i = 1; i < K + 1; i++){
    DP[i] = DP[i - 1] * (N + 1 - i); DP[i] %= nmax;
    DP[i] *= Pow(i, nmax - 2); DP[i] %= nmax;

    DP2[i] = DP2[i - 1] * (N - i); DP2[i] %= nmax;
    DP2[i] *= Pow(i, nmax - 2); DP2[i] %= nmax;
  }

  ll ans = 1;
  for (ll i = 1; i <= K; i++){
    ll now = DP[i] * DP2[i];
    now %= nmax;
    ans += now; ans %= nmax;
  }
  cout << ans << endl;

  return 0;
}

