const int mod = 1000000007;

ll beki(ll x, ll n, const ll &p) {
    ll ret = 1;
    while (n > 0) {
        if (n & 1) (ret *= x) %= p;
        (x *= x) %= p;
        n >>= 1;
    }
    return ret;
}

ll F[700010];
ll Finv[700010];

void init_combination() {
    const int MAX = 700000;
    F[0] = 1;
    for (int i = 1; i <= MAX; i++) {
        F[i] = F[i - 1] * i % mod;
    }
    Finv[MAX] = beki(F[MAX], mod - 2, mod);
    for (ll i = MAX - 1; i >= 0; i--) {
        Finv[i] = Finv[i + 1] * (i + 1) % mod;
    }
    return;
}

void solve() {
    init_combination();
    int n, k;
    cin >> n >> k;
    ll ans = 0;
    for(int i = max(1, n - k); i <= n; i++) {
        ans += F[n] * Finv[i] % mod
                * Finv[n - i] % mod
                * F[n - 1]    % mod
                * Finv[i - 1] % mod
                * Finv[n - i] % mod;
        ans %= mod;
    }
    cout << ans << endl;
    return;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    solve();
    return 0;
}

