    COMinit();
    if(k>=n) cout<<COM(2*n-1, n)<<endl;
    else{
        ll tot=1;
        rep(i, k){
            tot+=COM(n, i+1)*COM(n-1, i+1);
            tot%=MOD;
        }
        cout<<tot%MOD<<endl;
    }

    return 0;
}

