ll invmod(ll a, ll p)
{ // a^-1 mod p
    ll b = p, u = 1, v = 0;
    while (b)
    {
        ll t = a / b;
        a -= t * b;
        swap(a, b);
        u -= t * v;
        swap(u, v);
    }
    u %= p;
    if (u < 0)
        u += p;
    return u;
}

void factmod(ll m)
{
    fact[0] = invfact[0] = 1;
    for (ll i = 1; i < 210000; i++)
    {
        fact[i] = (fact[i - 1] * i) % m;
        invfact[i] = (invfact[i - 1] * invmod(i, m)) % m;
    }
}

ll nCrmod(ll n, ll r, ll m)
{
    return (((fact[n] * invfact[r]) % m) * invfact[n - r]) % m;
}

ll powmod(ll a, ll p, ll m)
{
    ll res = 1, tmp = a;
    while (p != 0)
    {
        if (p % 2)
            res = (res * tmp) % m;
        tmp = (tmp * tmp) % m;
        p /= 2;
    }
    return res;
}
