  ll ret = 1;
  while (k > 0) {
    if (k & 1) {
      ret = ret * n;
      ret %= MOD;
    }
    n = n * n;
    n %= MOD;
    k >>= 1;
  }
  return ret;
}


ll modulo(ll k) {
  while (k < 0) {
    k += MOD;
  }
  return k %= MOD;
}

