// 拡張ユーグリッド互除法
ll extgcd(ll a, ll b, ll &x, ll &y){
    if (b == 0){
        x = 1;
        y = 0;
        return a;
    }
    ll g = extgcd(b, a%b, y, x);
    y -= a/b * x;
    return g;
}

ll gcd(ll a, ll b){
    ll x, y;
    return extgcd(a, b, x, y);
}

// 逆元(mod p)
ll modinv(ll a, ll p){
    ll x, y;
    extgcd(a, p, x, y);
    if (x<0) x += p;
    return x;
}

// 二項係数
#define MAX (ll)2e5
#define MOD (ll)1e9+7
ll fac[MAX+1];
ll finv[MAX+1];

void nCr_init(ll max, ll mod){
    fac[0] = 1;
    finv[0] = 1;
    REP(i, max){ // i=1->max+1 => 0->max
        fac[i+1] = fac[i] * (i+1) % mod;
        finv[i+1] = finv[i] * modinv(i+1, mod) % mod;
    }
}

ll nCr(ll n, ll r, ll mod){
    if (n < r || n < 0 || r < 0) return 0;
    return fac[n] * (finv[r] * finv[n-r] % mod) % mod;
}

ll nHr(ll n, ll r, ll mod){
    return nCr(n+r-1,r,MOD);
}

int main(){
    ll n, k, ans=1;
    cin >> n >> k;
    if(k>n-1) k=n-1;

    nCr_init(n,MOD);
    REP(i,k){
        ans += nCr(n,i+1,MOD) * nHr(n-i-1,i+1,MOD);
        ans %= MOD;
    }
    cout << ans << endl;

    return 0;
}

