template<int SZ> struct Combo {
    ll fac[SZ+1], ifac[SZ+1];

    Combo() {
        fac[0] = ifac[0] = 1;
        for(ll i=1;i< (SZ+1);i++) {
            fac[i] = i*fac[i-1] % mod;
            ifac[i] = inv(fac[i]);
        }
    }

    ll po (ll b, ll p) {
        return !p?1:po(b*b%mod,p/2)*(p&1?b:1)%mod;
    }

    ll inv (ll b) { return po(b,mod-2); }

    ll comb(ll a, ll b) {
        if (a < b) return 0;
        ll tmp = fac[a]*ifac[b] % mod;
        tmp = tmp*ifac[a-b] % mod;
        return tmp;
    }
};
