#include <iostream>
using namespace std;

int N, K;
const long long MOD = 1000000007;
const int MAX = 300000;
long long fac[MAX];
long long finv[MAX];

long long modPow(int a, int n) {
  if (n == 0) return 1;
  if (n % 2 == 0) {
    long long t = modPow(a, n / 2);
    return t * t % MOD;
  }
  return modPow(a, n - 1) * a % MOD;
}

void cominit() {
  fac[0] = 1;
  fac[1] = 1;
  finv[0] = 1;
  finv[1] = 1;
  for (int i = 2; i < MAX; i++) {
    fac[i] = fac[i - 1] * i % MOD;  
    finv[i] = finv[i-1] * (modPow(i, MOD - 2) % MOD) % MOD;
  } 
}

long long comb(int n, int k) {
  if (n < k) return 0;
  if (n < 0 || k < 0) return 0;
  return fac[n] * (finv[k] * finv[n-k] % MOD) % MOD;  
}


void solve() {
  cominit();
  long long ans = 1;
  int max;
  if (N > K) { max = K; }
  else { max = N - 1; }
  for (int i = 1; i <= max; i ++) {
    ans += comb(N, i) * (comb(N - 1, N - i - 1) % MOD) % MOD;
  }

  printf("%lld\n", (ans + MOD) % MOD);
}

int main() {
  cin >> N >> K;

  solve();
}

