int main() {
  ios::sync_with_stdio(0);
  cin.tie(0);
  /* Finding modular inverse for every number modulo M (which must be a prime)
   Here we present a better algorithm with complexity O(m). However for this specific algorithm we require that the modulus m is prime.

We denote by inv[i] the modular inverse of i. Then for i>1 the following equation is valid:

///Principle formula///
inv[i]=−⌊m/i⌋⋅inv[m mod i]mod m

Thus the implementation is very simple:

inv[1] = 1;
for(int i = 2; i < m; ++i)
    inv[i] = (m - (m/i) * inv[m%i] % m) % m;


proof at : https://cp-algorithms.com/algebra/module-inverse.html#mod-inv-all-num
*/
  iv[1]=1;
  for(int i=2; i<4e5; ++i)
    iv[i]=M-M/i*iv[M%i]%M;
  f1[0]=f2[0]=1;
  for(int i=1;i <4e5; ++i) {
    f1[i]=f1[i-1]*i%M;
    f2[i]=f2[i-1]*iv[i]%M;
  }
  int n, k;
  cin >> n >> k;
  /* Main Question's logic
  E. Roaming
  n people, n rooms, k roaming moves, find number of ways of people staying there,

  */
  ll ans=nck(2*n-1, n-1); //Application of star and bars theorem
  //so from k+1 to n-1 we find the number of ways and subtract them, because in the end we only want k strict zeros
  for(++k; k <= n-1; ++k) {
    //k zeros
    //k fit in n-k
    ans=(ans+M-nck(n, k)*nck(n-1, n-k-1)%M)%M;
  }
  cout << ans;
}

#include <bits/stdc++.h>
