void make_table(int N){
    fac[0] = fac[1] = 1;
    for (int i = 2; i <= N; i++) fac[i] = (fac[i - 1] * i) % mod;
    for(int i=0; i<=N; i++) fac_inv[i] = mod_inv(fac[i], mod);
}

int combination(int n, int r, int p){
    return (fac[n] * fac_inv[r]) % p * fac_inv[n-r] % p;
}



