ll RepeatSquare(ll n,ll p,ll m){
  if(p==0)
    return 1;
  if(p%2==0){
    ll t = RepeatSquare(n,p/2,m);
    return t*t % m;
  }
  return n*RepeatSquare(n,p-1,m) % m;
}

ll factrial(ll x,ll y,ll m){
  ll ans=1;
  for(ll i=x; i<=y; i++){
    ans *= i;
    ans %= m;
  }
  return ans;
}

ll combination(ll x,ll y,ll m){
  ll ans=factrial(y-x+1,y,m);
  ans *= RepeatSquare(factrial(1,x,m),m-2,m);
  ans %= m;
  return ans;
}
int main(){
  ll n,k;
  cin >> n >> k;
  if(n<=k+1){
    ll answer;
    answer = combination(n,2*n-1,1000000007);
    cout << answer << endl;
  }
  else{
    ll answer=0;
    for(int i=0; i<=k; i++){
      if(i==0){
        if(k%2==0)
          answer++;
      }
      else{
        answer += (combination(i,n,1000000007)*combination(i,n-1,1000000007));
        answer %= 1000000007;
      }
    }
    cout << answer << endl;
  }
  return 0;
}

