        for (int i = 2; i <= n; i++) {
            fact[i] = fact[i - 1] * i % mod;
            inv[i] = mod - inv[mod % i] * (mod / i) % mod;
            finv[i] = finv[i - 1] * inv[i] % mod;
        }
    }

    ll Comb::res(int n, int k) {
        if (n < k) return 0;
        if (n < 0 || k < 0) return 0;
        return fact[n] * (finv[k] * finv[n - k] % mod) % mod;
    }

    ll Comb::resone(ll n, ll k) {
        ll res = 1;
        for (ll i = 0; i < k; i++) {
            (res *= (n-i)) %= mod;
            (res *= this->powm(i+1, mod-2)) %= mod;
        }
        return res;
    }

}

