    for (int i = st; i >= max(0,n-1-k); --i){
        int a = mncr(n-1,i,MOD,fact,finv);
        int b = mncr(n,i+1,MOD,fact,finv);
        ans = (ans+mmul(a,b,MOD))%MOD;
    }

    //cout <<fixed<<setprecision(16)<< << endl;
    cout<<ans<<endl;
    //if(flag)cout << "Yes" <<endl;
    //else cout << "No" <<endl;

    return 0;
}

