#include <bits/stdc++.h>

using namespace std;
using ll = long long;
using ii = pair<ll, ll>;

const int MAX { 400010 };
const ll MOD { 1000000007 }, oo { 1LL << 62 };

ll fs[MAX], inv[MAX];

ll mod_pow(ll a, ll n)
{
    ll res = 1, base = a;

    while (n)
    {
        if (n & 1)
            res = (res * base) % MOD;

        base = (base * base) % MOD;
        n >>= 1;
    }

    return res;
}

void precomp()
{
    fs[0] = 1;

    for (ll i = 1; i < MAX; ++i)
        fs[i] = (fs[i - 1] * i) % MOD;

    inv[0] = 1;

    for (ll i = 1; i < MAX; ++i)
        inv[i] = mod_pow(fs[i], MOD - 2);
}

ll mod(ll a)
{
    return (((a % MOD) + MOD) % MOD);
}

ll binom(ll n, ll m)
{
    ll res = mod(fs[n] * inv[m]);
    res = mod(res * inv[n - m]);

    return res;
}

ll solve(ll N, ll K)
{
    if (K >= N - 1)
        return binom(2*N - 1, N - 1);

    ll ans = 0;

    for (int k = 0; k <= K; ++k)
    {
        ll x = mod(binom(N - 1, k)*binom(N, k));
        ans = mod(ans + x);
    }

    return ans;                
}

int main()
{
    ios::sync_with_stdio(false);
    precomp();

    ll N, K;
    cin >> N >> K;

    auto ans = solve(N, K);

    cout << ans << '\n';

