static const int mod = 1e9 + 7;

int fast_power(int a, int b) {
  long long p = 1, q = a;
  while (b) {
    if (b & 1) p = p * q % mod;
    q = q * q % mod;
    b >>= 1;
  }
  return p;
}

int c(int n, int k, const vector<int> &f, const vector<int> &g) {
  return 1LL * f[n] * g[k] % mod * g[n - k] % mod;
}

int main() {
  int n, k;
  scanf("%d %d", &n, &k);

  vector<int> f(n + 1), g(n + 1);
  f[0] = 1, g[0] = 1;
  for (int i = 1; i <= n; i++) {
    f[i] = 1LL * f[i - 1] * i % mod;
    g[i] = 1LL * g[i - 1] * fast_power(i, mod - 2) % mod;
  }

  int ans = n > 1 ? 1 : 0;
  for (int i = 1; i <= min(k, n - 1); i++) {
    ans = (ans + 1LL * c(n, i, f, g) * c(n - 1, n - i - 1, f, g) % mod) % mod;
  }
  printf("%d\n", ans);

  return 0;
}

