	else {
		llint ans = 0;
		//table[i]はi!をmodで割った余り
		vllint table(n + 1, 1);
		for (llint i = 0; i < n; i++) {
			if (i == 0)continue;
			table[i + 1] = (llint)table[i] * (i + 1);
			table[i + 1] %= mod;
		}
		for (int i = max(k, n - k); i <= n; i++) {
			llint tmp = table[n - 1] * table[n];
			tmp %= mod;
			llint tmp2 = table[i - 1] * table[i];
			tmp2 %= mod;
			tmp2 *= table[n - i];
			tmp2 %= mod;
			tmp2 *= table[n - i];
			tmp2 %= mod;
			tmp *= modinv(tmp2, mod);
			while (tmp < 0)tmp += mod;
			tmp %= mod;
			ans += tmp;
		}
		cout << ans << endl;
	}
