template<int N, typename T, T M>
struct kaijyo
{
	T mod[N + 1];
	T inv_mod[N + 1];

	constexpr kaijyo() : mod(), inv_mod()
	{
		mod[0] = 1;
		for (int i = 0; i < N; ++i)
		{
			mod[i + 1] = (mod[i] * (i + 1)) % M;
		}
		inv_mod[N] = power(mod[N], M - 2);
		for (int i = N - 1; i >= 0; --i)
		{
			inv_mod[i] = (inv_mod[i + 1] * (i + 1)) % M;
		}
	}

	constexpr T power(T a, T b) const
	{
		T r = 1;
		for (; b; b >>= 1, a = 1ll * a * a % M)
			if (b & 1) r = 1ll * r * a % M;
		return r;
	}

	constexpr T comb(T n, T r) const
	{
		if (r < 0 || r > n || n < 0) return 0;
		return (((mod[n] * inv_mod[r]) % M) * inv_mod[n - r]) % M;
	}
};

constexpr ll MOD = 1e9 + 7;
constexpr kaijyo<500000, ll, MOD> kaijyo1;

int main()
{
	ll n, k;
	cin >> n >> k;
	ll zeromax = min(n, k);
	ll ans = 0;
	//注意：空き室の数は１から、0の場合はまだ計算してない
	for (ll i = 1; i <= zeromax; ++i)
	{
		ll room = n - i;
		ans = (ans + kaijyo1.comb(n, room) * kaijyo1.comb(n - 1, room)) % MOD;
	}
	if (k >= 2)
	{
		ans = (ans + 1) % MOD;
	}
	cout << ans;
	return 0;
}

