  }

  ll P(ll N, ll K)
  {
    if (N < K) return 0;
    if (N < 0 || K < 0) return 0;
    return fac.at(N) * finv.at(N - K) % MOD;
  }

  ll C(ll N, ll K)
  {
    if (N < K) return 0;
    if (N < 0 || K < 0) return 0;
    return fac.at(N) * (finv.at(K) * finv.at(N - K) % MOD) % MOD;
  }

  ll H(ll N, ll K)
  {
    return C(N + K - 1, K);
  }
};

int main()
{
  combination com(400400);

  ll N, K;
  cin >> N >> K;

  if (K >= N - 1)
    FINALANS(com.H(N, N));

  if (K == 1)
    FINALANS(N * (N - 1) % MOD);

  ll ans = 0;
  for (ll k = 0; k <= K; k++)
  {
    ll tmp = com.C(N, k) * com.H(N - k, k) % MOD;
    ans += tmp, ans %= MOD;
  }
  cout << ans << endl;
}

