    rep(i, n_edges){
        ll from, to, c = cost;
        if (cost == -1) in3(from, to, c);
        else in2(from, to);
        from += offset, to += offset;

        graph[from].pb({to, cost});
        if (!directed) graph[to].pb({from, cost});
    }
}

