int modexp(int a, int n) {

    int r = 1;
    while(n) {
        if(n & 1) {
            r = (r * a) % mod;
        }
        a = (a * a) % mod;
        n >>= 1;
    }
    return r;
}

int ncr(int n, int r) {

    if(n < r) {
        return 0;
    }
    int ans = (f[n] % mod * modexp(f[r], mod - 2) % mod * modexp(f[n - r], mod - 2) % mod) % mod;
    return ans ;
}

void solve()
{

    int n, k;
    cin>>n>>k;

    f[0] = 1;
    for(int i = 1; i <= n; i ++) {
        f[i] = f[i - 1] * i;
        f[i] %= mod;
    }

    k = min(k, n - 1);

    int ans = 0;
    for(int i = 0; i <= k; i ++) {
        int t = ncr(n, i);   /// selecting the number of 0's from n numbers
        t = (t % mod * ncr(n - 1, n - i - 1) % mod) % mod;   ///dividing the rest into n - i groups such that each group has at least 1
        ans = (ans + t) % mod;
    }

    cout<<ans;

    cout<<"\n";
    return ;
}

