// Combination
void COMinit(vector<int64_t>& fac, vector<int64_t>& finv, vector<int64_t>& inv) {
  fac[0] = fac[1] = 1;
  finv[0] = finv[1] = 1;
  inv[1] = 1;
  for (int32_t i = 2; i < (int32_t)fac.size(); i++){
      fac[i] = fac[i - 1] * i % MOD;
      inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
      finv[i] = finv[i - 1] * inv[i] % MOD;
  }
  return;
}

int64_t COM(int32_t n, int32_t k, vector<int64_t>& fac, vector<int64_t>& finv) {
  if (n < k) return 0;
  if (n < 0 || k < 0) return 0;
  return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

int main(){
  std::cin.tie(0);
  std::ios::sync_with_stdio(false);

  int64_t n,k;
  cin >> n >> k;
  vector<int64_t> fac(2*n, 0);
  vector<int64_t> finv(2*n, 0);
  vector<int64_t> inv(2*n, 0);
  COMinit(fac, finv, inv);

  int64_t res = 0;
  if (k < n) {
    res = 1;
    for (int64_t i = 1; i <= k; i++) {
      int64_t cmb_empty = COM(n, i, fac, finv);
      cmb_empty %= MOD;
      int64_t a = n - i;
      int64_t H = COM(a + i - 1, i, fac, finv);
      H %= MOD;
      res += (H * cmb_empty) % MOD;
    }
  } else {
    res = COM(2*n - 1, n - 1, fac, finv);
  }

  cout << res << endl;
  return 0;
}

