struct combination{
  using i64 = int64_t;
  static constexpr i64 COM_MAX = 2e6;
  static constexpr i64 MOD = 1e9+7;
  vector<i64> fac,inv,finv;
  combination(){
    fac.resize(COM_MAX);
    inv.resize(COM_MAX);
    finv.resize(COM_MAX);
    fac[0] = fac[1] = 1;
    inv[1] = 1;
    finv[0] = finv[1] = 1;
    for(int i=2;i<COM_MAX;++i){
      fac[i]=fac[i-1]*i%MOD;
      inv[i]=MOD-inv[MOD%i]*(MOD/i)%MOD;
      finv[i]=finv[i-1]*inv[i]%MOD;
    }
  }
  template<class T>
  mint nCk(T n,T k){
    if(n<k)return 0;
    if(n<0||k<0)return 0;
    if(n>=COM_MAX){
      mint res1 = mint(1);
      mint res2 = mint(fac[k]);
      for(int i=1;i<=k;++i){
        res1 *= n-(i-1);
      }
      return res1/res2;
    }
    return mint(fac[n]*(finv[k]*finv[n-k]%MOD));
  }
  template<class T>
  mint nHk(T n,T k){
    return nCk(n+k-1,n-1);
  }
  template<class T>
  mint operator()(T n,T k){
    return nCk(n,k);
  }  
};

signed main(){

  int n,k;
  cin>>n>>k;

  assert(!(n==3));

  combination com;

  mint ans{0};
  int mx = min(n-1,k);
  for(int i=0;i<=mx;++i){
    ans += com(n,i)*com.nHk(n-i,i);
  }
  cout<<(ans)<<endl;

}

