class Combination{
private:
    long long m_mod;
    long long *fac;
    long long *finv;
    long long max_n;
    long long power(long long a, long long b);
    long long ext_gcd(long long a, long long b, long long &x, long long &y);
public:
    Combination(long n, long mod);//max_n, mod
    ~Combination();
    long long comb(long n, long r);
    void fac_vis();
    void finv_vis();
};
long long Combination::power(long long a, long long b){
    if(b == 0){
        return 1ll;
    }else if(b % 2){
        return power(a, b-1) * a % m_mod;
    }else{
        return power(a, b/2) * power(a, b/2) % m_mod;
    }
}
long long ext_gcd(long long a, long long b, long long &x, long long &y){//ax + by = gcd(a, b), returns gcd. |x| + |y| is minimum and x <= y.
    if(b == 0){
        x = 1;
        y = 0;
        return a;
    }
    long d = ext_gcd(b, a % b, y, x);
    y -= a/b * x;
    return d;
}
long long mod(long long a, long long m){
    return (a % m + m) % m;
}
long long modinv(long long a, long long m){
    long long x, y;
    ext_gcd(a, m, x, y);
    return mod(x, m);
}
Combination::Combination(long n, long mod){
    max_n = n;
    m_mod = mod;
    fac = new long long[n+1];
    finv = new long long[n+1];
    fac[0] = finv[0] = 1;
    if(max_n > 0){
        fac[1] = finv[1] = 1;
    }
    for(long long i = 2; i <= max_n; i++){
        fac[i] = fac[i-1] * i % m_mod;
    }
    finv[n] = modinv(fac[n], m_mod);
    for(long long i = max_n-1; i >= 0; i--){
        finv[i] = finv[i+1] * (i+1) % m_mod;
    }
}
Combination::~Combination(){
    delete[] fac;
    delete[] finv;
}
long long Combination::comb(long n, long r){
    if(n < r || n < 0 || r < 0){
        return 0;
    }
    return fac[n] * finv[r] % m_mod * finv[n-r] % m_mod;
}
void Combination::fac_vis(){
    for(int i = 0; i <= max_n; i++){
        printf("%lld ", fac[i]);
    }
    printf("\n");
}
void Combination::finv_vis(){
    for(int i = 0; i <= max_n; i++){
        printf("%lld ", finv[i]);
    }
    printf("\n");
}

const long MOD = 1000000007;

long solve(long n, long k){
    Combination nCr(n, MOD);
    long ans = 0;
    for(long i = std::max(n-k, 1l); i <= n; i++){
        ans += nCr.comb(n-1, i-1) * nCr.comb(n, i) % MOD;
        ans %= MOD;
    }
    return ans;
}

int main(){
    long n, k;
    scanf("%ld%ld", &n, &k);
    printf("%ld\n", solve(n, k));
}

