// a^n mod を計算する
long long modpow(long long a, long long n) {
  long long res = 0;
  if (n == 1) return a;
  res = modpow(a,n/2) * modpow(a,n/2) % mod;
  if (n % 2 == 1) res *= a % mod;
  return res;
}

// a^{-1} mod を計算する
long long modinv(long long a, long long mod) {
  return modpow(a, mod - 2);
}


void calc(){
  nCk[0] = 1;
  n1Ck[0] = 1;
  for (int i=1; i<=N-1; i++){
    nCk[i] = (nCk[i-1]*((N-i+1)%mod)%mod)*modinv(i, mod);
    n1Ck[i] = (n1Ck[i-1]*((N-i)%mod)%mod)*modinv(i, mod);
    nCk[i] %= mod;
    n1Ck[i] %= mod;
  }
  nCk[N] = 1;
  return;
}

int main(){
  scanf("%d",&N);
  long long K;
  scanf("%lld", &K);
  //printf("N=%d, K=%lld\n", N, K);
  calc();
  K = std::min(K, (long long)N-1);
  long long ans = 0;
  for (int i=0; i<=K; i++){
    //printf("ans += %lld*%lld\n",nCk[i], n1Ck[i]);
    ans += (nCk[i]*n1Ck[i])%mod;
    ans %= mod;
  }
  printf("%lld\n", ans);
  return 0;
}

