int pow_mod(ll a, int b) {
	ll pow = 1;
	while (b > 0) {
		if (b & 1) pow = pow * a % MOD;
		a = a * a % MOD;
		b >>= 1;
	}
	return pow;
}

ll inv_mod(ll n) {
	return pow_mod(n, MOD - 2);
