void pre( ll p ) {
	fac_inv[ 0 ] = fac[ 0 ] = 1;
	for( int i = 1; i <= 200000; ++i ) {
		fac[ i ] = fac[ i - 1 ] * i;
		fac[ i ] %= p;
		fac_inv[ i ] = pow_mod( fac[ i ], p - 2, p );
	}
}

ll cnm( ll n, ll m, ll p ) {
	ll res = 1, a, b, c;
	if( n < m )
		return 0;
	if( n == m )
		return 1;

	a = fac[ n ];
	b = fac_inv[ m ];
	c = fac_inv[ n - m ];
	res = ( a * b % p ) * c % p;

	return res;
}

ll pow_mod( ll x, ll y, ll p ) {
	ll res = 1;
	while( y ) {
		if( y & 1 ) {
			res *= x;
			res %= p;
		}
		x *= x;
		x %= p;
		y >>= 1;
	}
	return res;
}

