    if(K>=N-1){
        ans = comb(2*N-1,N-1);
    } else {
        for (int i = 0;i<K+1;i++){
            ans = (ans +(comb(N,i) * comb(N-1,i)% 1000000007))%1000000007;
        }
    }
    cout << ans << endl;
}

