ll f[101010], rf[101010];
ll inv(ll x) {
    ll res = 1;
    ll k = MOD - 2;
    ll y = x;
    while (k) {
        if (k & 1) res = (res * y) % MOD;
        y = (y * y) % MOD;
        k /= 2;
    }
    return res;
}
void init() {
    f[0] = 1;
    for(ll i=1;i<101010;i++){f[i] = (f[i - 1] * i) % MOD;}
    for(ll i=0;i<101010;i++){rf[i] = inv(f[i]);}
}
