void mul_mod(ll& a, ll b){
	a *= b;
	a %= MOD;
}

void add_mod(ll& a, ll b){
	a = (a<MOD)?a:(a-MOD);
	b = (b<MOD)?b:(b-MOD);
	a += b;
	a = (a<MOD)?a:(a-MOD);
}

ll fc[225816]={1ll},nv[225816]={1ll};

ll rwpw(ll a, ll p = MOD-2){
	ll ret = 1ll;
	while(p){
		if(p%2){
			mul_mod(ret,a);
		}
		mul_mod(a,a);
		p /= 2;
	}
	return ret;
}

ll c(int n, int k){
	ll ret = fc[n];
	mul_mod(ret,nv[k]);
	mul_mod(ret,nv[n-k]);
	return ret;
}

int main(void){
	int n,k,i;
	ll ans=0ll,tmp;
	for(i=1; i<225816; ++i){
		fc[i] = fc[i-1];
		mul_mod(fc[i],i);
		nv[i] = rwpw(fc[i]);
	}
	cin >> n >> k;
	for(i=0; i<=k; ++i){
		if(!(i<n)){
			break;
		}
		tmp = c(n-1,n-i-1);
		mul_mod(tmp,c(n,i));
		add_mod(ans,tmp);
	}
