class Combination{
public:
  typedef long long ll;
  ll N;
  ll mod;
  vector<ll> fac;
  vector<ll> finv;
  vector<ll> inv;


  Combination(ll N = 1e6,ll mod = 1e9 + 7): N(N), mod(mod), fac(N+1), finv(N+1), inv(N+1){
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for(Int i = 2; i <= N; i++){
      fac[i] = fac[i-1] * i % mod;
      inv[i] = mod - inv[mod%i] * (mod / i) % mod;
      finv[i] = finv[i-1] * inv[i] % mod;
    }
  }

  function<ll(ll, ll)> mod_pow = [&](ll x, ll y){
      ll res = 1;
      while(y){
        if(y & 1) res = res * x % mod;
        x = x * x % mod;
        y >>= 1;
      }
      return res;
  };

  function<ll(ll)> inv_ = [&](ll x){return mod_pow(x, mod - 2);};

  function<ll(ll,ll)> nCr = [&](ll n,ll r){
    if( n < r ) return 0LL;
    if( n < 0 || r < 0) return 0LL;
    return fac[n] * (finv[r] * finv[n-r] % mod) % mod;
  };

  function<ll(ll,ll)> nCr_ = [&](ll n, ll r){ //O(r + log(mod))
    if( n < r ) return 0LL;
    if( n < 0 || r < 0) return 0LL;
    ll N = 1, K = 1;
    for(Int i=0;i<r;i++){
      N = N * ((n - i) % mod) % mod;
      K = K * ((r - i) % mod) % mod;
    }
    return N * inv_(K) % mod;
  };

  function<ll(ll, ll)> nPr=[&](ll n, ll r){
    if(n < r) return 0LL;
    if(n < 0 || r < 0) return 0LL;
    return fac[n] * finv[n - r] % mod;
  };


  //Combination Comb;
  //auto nCr = Comb.nCr;
