ll comb(ll n, ll k) {
    ll v=1; for(ll i=1; i<=k; i++) v = DIV(MUL(v, n-i+1),i); return v;
}


vector<ll> combs(int n) {
    vector<ll> c(n+1);
    ll x = 1LL, a = n, b = 1;
    c[0] = c[n] = 1;
    for (int k=1; k<n; ++k){
        x = DIV(MUL(x, a--), b++);
        c[k] = x;
    }
    return c;
}



ll solve(int N, int K){

    vll c0 = combs(N), c_1 = combs(N-1);

    auto comb = [&](int n, int k) -> ll {
        if (n == N) return c0[k];
        else if (n == N-1) return c_1[k];
        else return 0;
    };
    auto distribute = [&](int rooms, int balls) -> ll {
        int num_separators = rooms - 1;
        return comb(balls + num_separators, num_separators);
    };

    if (false && K >= N) {
        return distribute(N, N);
    } else {
        ll ans = 0;
        for (int num_empty=0; num_empty<N; ++num_empty) {
            if (num_empty > K) break;
            ll p = comb(N, num_empty);
            ll q = distribute(N-num_empty, num_empty);
            ans += MUL(p, q);
            ans %= MOD;
        }
        return ans;
    }
}

int main() {
    int N, K; scanf("%d %d%*c", &N, &K);
    cout << solve(N, K) << endl;
    return 0;
}

