            long long tmp = modpow(b, k / 2);
            return tmp * tmp % p;
        }
    }

    int modinv(int b){
        return modpow(b, p - 2);
    }

    ModInt operator/(ModInt a){

        ModInt tmp = ModInt(*this);

        tmp.n = tmp.n * modinv(a.n) % tmp.p;
        return tmp;
    }
};

ModInt mypow(ModInt a, int k){
    if(k == 0) return ModInt(1, MODN);

    if(k % 2 == 1){
        ModInt tmp = mypow(a, (k - 1) / 2);
        return tmp * tmp * a;
    }else{
        ModInt tmp = mypow(a, k / 2);
        return tmp * tmp;
    }
}

