/*階乗の逆言求値
フェルマーの小定理：k^{M-1}≡1 (mod M) → k^{-1}≡k^{M-2} (mod M)
(mod p) においてxで割ることと x^(p-2) を掛けることは同じこと
この法則で割る話を掛ける話にすり替える
*/
#define inv(x) powmod(x,mod-2)
//mod付 階乗・階乗の逆元逆数を事前求値initF()
//階乗をO(N)で求めた後、O(logMOD)で逆元を1度求値
//1/x!*x = 1/(x-1)!を利用して戻るようにO(N)で逆元を一通り求める
#define needF 201010
ll f[needF+1], rf[needF+1];//f[x]=x!

void initF() {
    f[0] = 1;
    repd(i,1,needF+1) f[i]=( f[i-1]*i ) % mod;
    rf[needF] = inv(f[needF]);
    rrepd(i, needF-1, 0) rf[i] = (rf[i+1] * (i+1)) % mod;
}
ll nPk(int n, int k) {
    return ( f[n]*rf[n-k] ) % mod;
}
ll nCk(int n, int k) {
    if(n<k)return 0;
    ll bc = ( rf[n-k]*rf[k] ) % mod;
    return (f[n]*bc) % mod;
}
