    cin >> n >> k;
    if(k>n){
        ans = comb(2*n-1,n-1);
    } else {
        for (int i = 0;i<=k;i++){
            ans = (ans +(comb(n-1,i) * comb(n,i) % 1000000007))%1000000007;
        }
    }
    cout << ans << endl;
}

