long long modpow(long long x, long long n) {
    long long res = 1;
    while (n > 0) {
        if (n & 1) { 
            res *= x;
            res %= mod;
        }
        x *= x;
        x %= mod;
        n >>= 1;
    }
    return res;
}

// a^{-1} mod を計算する
long long modinv(long long a, long long mod) {
  long long res = 0;
  return modpow(a, mod - 2);
}


void calc(){
  nCk[0] = 1;
  n1Ck[0] = 1;
  for (int i=1; i<=N-1; i++){
    nCk[i] = (nCk[i-1]*((N-i+1)%mod)%mod)*modinv(i, mod);
    n1Ck[i] = (n1Ck[i-1]*((N-i)%mod)%mod)*modinv(i, mod);
    nCk[i] %= mod;
    n1Ck[i] %= mod;
  }
  nCk[N] = 1;
  return;
}

