#include <bits/stdc++.h>
using namespace std;

long long MOD=1000000007;

long long fac[2000002],finv[2000002],inv[2000002];

void COMinit(){
	fac[0]=fac[1]=1;
	finv[0]=finv[1]=1;
	inv[1]=1;
	for(int i=2;i<2000002;i++){
		fac[i]=fac[i-1]*i%MOD;
		inv[i]=MOD-inv[MOD%i]*(MOD/i)%MOD;
		finv[i]=finv[i-1]*inv[i]%MOD;
	}
}

long long COM(int n,int k){
	if(n<k)return 0;
	if(n<0 || k<0)return 0;
	return fac[n]*(finv[k]*finv[n-k]%MOD)%MOD;
}

int main(){
	COMinit();
	int n,k;
	cin >> n >> k;

	long long ans=0;

	for(int i=0;i<=min(n,k);i++){
		long long add=COM(n,i);
		add*=COM(n-i-1+i,i);
		add%=MOD;
		ans+=add;
		ans%=MOD;
	}

	cout << ans << endl;
	return 0;
}

