		m = n * (n - 1) % M;
	else {
		for (long long i = 1; i <= k; i++) {
			t = i;
			v = 1;

			for (int j = 0; (1ull << j) < M - 1; j++) {
				if ((1ull << j) & (M - 2))
					v = v * t % M;

				t = t * t % M;
			}

			v = v * v % M;
			u = ((u * (n - i + 1) % M) * (n - i) % M) * v % M;
			m = (m + u) % M;
		}
	}

	cout << m << endl;

	return 0;
}

