    ll POW(ll a, ll b){
        ll res = 1;
        while(b > 0){
            if(b & 1){
                res = res * a % mod;
            }
            a = a * a % mod;
            b >>= 1;
        }
        return res;
    }

    ll combin(int n, int k){
        if(n < 0 || k < 0 || n < k){
            return 1;
        }
        return fact[n] * POW(fact[k] * fact[n-k] % mod, mod - 2) % mod;
    }

    ll moddiv(ll a, ll b){
        return a % MOD * POW(b, mod - 2) % MOD;
    }
};

signed main(){
    ll n, k;
    cin >> n >> k;

    Combination C(2*n, MOD);
    ll ans = 0;

    REP(i, n){
        if(i > k) break;
        ll cnt = C.combin(n, i);
        cnt *= C.combin(n-1, i);
        cnt %= MOD;
        ans += cnt;
        ans %= MOD;
    }

    cout << ans << endl;

    return 0;
}

