long powmod(long n, long k, long mod) {
  if (k == 0)
    return 1;
  long t = powmod(n, k / 2, mod);
  t = (t * t) % mod;
  if (k % 2 == 1)
    t = (t * n) % mod;
  return t;
}

long fact[200001]; //fact[i] = i! % mod (0<=i<=n)
long fact_rec[200001]; //fact_rec[i] = (i!)^-1 % mod
long rec[200001]; //rec[i] = i^-1 % mod (i > 0)
void factini(long n, long mod) {
  fact[0] = fact_rec[0] = rec[0] = 1;
  fact[1] = fact_rec[1] = rec[1] = 1;
  for (int i = 2; i <= n; i++) {
    fact[i] = (fact[i - 1] * i) % mod;
    rec[i] = (rec[mod % i] * (mod - mod / i)) % mod;
    fact_rec[i] = (fact_rec[i - 1] * rec[i]) % mod;
  }
}

long combmod(long n, long k, long mod) {
  return (((fact[n] * fact_rec[k]) % mod) * fact_rec[n - k]) % mod;
}

long vnummod(long n, long k, long mod) {
  long sum = 0;
  long lim = (n - 1 < k) ? n - 1 : k;
  for (long m = 0; m <= lim; m++) {
    long t = combmod(n, m, mod);
    t = (t * t) % mod;
    t = (t * (n - m)) % mod;
    sum = (sum + t) % mod;
  }
  sum = (sum * rec[n]) % mod;
  return sum;
}


