ll qmi(ll m, ll k, ll p)
{
    ll res = 1 % p, t = m;
    while (k)
    {
        if (k&1) res = res * t % p;
        t = t * t % p;
        k >>= 1;
    }
    return res;
}
ll inv(ll x, ll p)
{
    return qmi(x, p - 2, p);
}
ll C(ll n, ll m, ll p)
{
    if(m > n)return 0;
    ll up = 1, down = 1;
    for(int i = n - m + 1; i <= n; i++)up = up * i % p;
    for(int i = 1; i <= m; i++)down = down * i % p;
    return up * inv(down, p) % p;
}
ll Lucas(ll n, ll m, ll p)
{
    if(m == 0)return 1;
    return C(n % p, m % p, p) * Lucas(n / p, m / p, p) % p;
}
ll A[200020];
void init() {
    A[0] = A[1] = 1;
    for (int i = 2; i <= 200000; i++) {
        A[i] = A[i - 1] * i % mod;
    }
}
