ll mpow(ll base, ll num)
{
    if (num == 0)
        return 1;
    ll prev = mpow(base, num / 2);
    if (num % 2 == 0)
    {
        return (prev * prev) % MOD;
    }
    else
    {
        return ((prev * base) % MOD * prev) % MOD;
    }
}

