    vector<ModInt> facts(n + 1), facts_inv(n + 1);
    facts[0] = 1;
    for(int i = 1; i <= n; i++){
      facts[i] = facts[i - 1] * i;
    }
    facts_inv[n] = facts[n].inv(); // 1 / (n!)
    for(int i = n - 1; i >= 0; i--){
