LL fp(LL a, LL n){
    if(n== 0)
        return 1;

    LL h = fp(a , n / 2);
    h = h*h %P;
    if(n&1){
        h = h * a %P;
    }

    return h;
}

vector<LL> fac(200010);
LL C(LL m, LL n){
    return fac[m] * fp(fac[m-n], P-2) % P * fp(fac[n], P-2) % P;
