    cin >> N >> K;

    Combination cm = Combination(2 * N + 5, MOD);

    ll ans = 0;
    for(int i = 1; i <= N; i++) {
        if(K >= N - i) {
            ans += cm.get(N, i) * cm.get(N - 1, i - 1);
            ans %= MOD;
        }
    }

    cout << ans << endl;
    return 0;
}

