    static long long memo[200100] = {0};
    if(memo[n] != 0) return memo[n];
    long long ans = 1;
    for(long long m = 1; m <= n; m++){
        ans *= m;
        ans %= MOD;
    }
    return memo[n] = ans;
}

long long comb(long long n, long long k){
    long long ans = fact(n);
    ans *= inv(fact(n - k));
    ans %= MOD;
    ans *= inv(fact(k));
    ans %= MOD;
    return ans;
}

long long P(long long n, long long k){
    return comb(n + k - 1, k);
}

