#define p 1000000007
#define N 200005

inline int add(int x, int y) { return (x += y) >= p ? x - p : x; }
inline int mul(int x, int y) { return (long long)x * y % p; }
inline int power(int x, int y) { int ans = 1; for (; y; y >>= 1) { if (y & 1) ans = mul(ans, x); x = mul(x, x); } return ans; }

int sum[N], inv[N];

int main() {
    int n, k;
    scanf("%d%d", &n, &k);
    k = std::min(k, n);
    sum[n + 1] = 1;
    for (int i = n; i >= n - k; --i) sum[i] = mul(sum[i + 1], i);
    int fac = 1;
    for (int i = 1; i <= k; ++i) fac = mul(fac, i);
    inv[k] = power(fac, p - 2);
    for (int i = k; i; --i) inv[i - 1] = mul(inv[i], i);
    int invn = power(n, p - 2);
    int ans = 0;
    for (int i = 0; i <= k; ++i) ans = add(ans, mul(mul(sum[n - i + 1], inv[i]), mul(mul(sum[n - i], invn), inv[i])));
    printf("%d\n", ans);
    return 0;
}

