    for (long long i = 2; i <= n; i++) {
        factorial[i] = factorial[i - 1] * i % MOD;
        inv[i] = (-MOD / i + MOD) * inv[MOD % i] % MOD;
        ifactorial[i] = ifactorial[i - 1] * inv[i] % MOD;
    }
    auto C = [&](long long n, long long k)->long long {
    	return factorial[n] * ifactorial[n - k] % MOD * ifactorial[k] % MOD;
    };
	for (long long i = 0; i <= min(n - 1, k); i++) {
		result = (result + C(n, i) * C(n - 1, i) % MOD) % MOD;
	}
