ll choose(ll n, ll k, ll mod) {
  ll x = 1, y = 1;

  rep(i, k) {
    x *= (n - i) % mod;
    x %= mod;
    y *= (i + 1) % mod;
    y %= mod;
  }

  return x * modpow(y, mod - 2, mod) % mod;
}

