const int MAXN = (int)2e5 + 7;
const int MOD  = (int)1e9 + 7;
int add(int x, int y) {
	return (x + y >= MOD ? x + y - MOD : x + y);
}
int mult(int x, int y) {
	return (x * 1LL * y) % MOD;
}
int binpow(int x, int y) {
	if(x == 1 || y == 0) return 1;
	if(x == 0) return 0;
	int rez = binpow(x, y/2);
	rez = mult(rez, rez);
	if(y&1) rez = mult(rez, x);
	return rez;
}
int divide(int x, int y) {
	return mult(x, binpow(y, MOD - 2));
}
int F[MAXN], invF[MAXN];
void init() {
	F[0] = 1;
	for(int i = 1; i < MAXN; ++i) F[i] = mult(i, F[i - 1]);
	invF[MAXN - 1] = divide(1, F[MAXN - 1]);
	for(int i = MAXN - 2; i >= 0; --i) invF[i] = mult(i + 1, invF[i + 1]);
}
int choose(int n, int k) {
	if(k > n) return 0;
	int rez = F[n];
	rez = mult(rez, invF[k]);
	rez = mult(rez, invF[n - k]);
	return rez;
}
void solve() {
	init();
	int n = fetch<int>();
	int k = fetch<int>();
	int answ = 0;
	for(int i = 0; i < n && i <= k; ++i) {
		int loc = choose(n, i);
		loc = mult(loc, choose(n - 1, n - i - 1));
		//dout << i << ": " << loc << '\n';
		answ = add(answ, loc);
	}
	cout << answ << '\n';
}

