ll ksm(ll x,ll y){
    ll res=1;
    while(y){
        if(y&1) res=res*x%mod;
        x=x*x%mod;
        y>>=1;
    }
    return res%mod;
}
ll cal(ll n,ll m){
    ll sum1=1;
    ll sum2=1;
    for(ll i=1;i<=m;i++) sum1=sum1*i%mod;
    for(ll i=n;i>=n-m+1;i--) sum2=sum2*i%mod;
    return sum2*ksm(sum1,mod-2)%mod;
}
int  main(){
    ll n,k;
    cin>>n>>k;
    if(n-k<=1) {
        cout<<cal(2*n-1,n-1)%mod<<endl;
    }
