        ll toll=cal(2*n-1,n-1)%mod;
        ll tmp1=cal(n,1)%mod;
        ll tmp2=1;
        toll=(toll-tmp1*tmp2%mod+mod)%mod;
        for(ll i=2;i<n-k;i++){
            tmp1=tmp1*(n-i+1)%mod;
            tmp1=tmp1*ksm(i,mod-2)%mod;
            tmp2=tmp2*(n-i+1)%mod;
            tmp2=tmp2*ksm(i-1,mod-2)%mod;
            toll=(toll-tmp1*tmp2%mod+mod)%mod;
        }
