ll modbeki(ll x, ll n){
  ll res = 1LL;
  while(n > 0){
    if(n & 1){
      res *= x % MOD;
      res %= MOD;
    }
    x = x * x % MOD;
    n >>= 1;
  }
  return res % MOD;
}

int main(){
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  ll n, k;
  cin >> n >> k;

  vll fact(2*n+1), ifact(2*n+1);
  fact.at(0) = 1LL;
  for(int i = 1; i <= 2*n; i++){
    fact.at(i) = fact.at(i-1) * i % MOD;
  }
  for(int i = 1; i <= 2*n; i++){
    ifact.at(i) = modbeki(fact.at(i), MOD-2);
  }
  auto ncr = [&](ll a, ll b){
    if(b == a || b == 0) return 1LL;
    return fact.at(a) * ifact.at(a-b) % MOD * ifact.at(b) % MOD;
  };
  auto nhr = [&](ll a, ll b){
    return ncr(a+b-1, b);
  };

  if(k >= n-1){
    cout << nhr(n+1, n-1) << endl;
    return 0;
  }
  if(k == 1){
    cout << ncr(n, 1LL) * ncr(n-1LL, 1LL) << endl;
    return 0;
  }
  ll ans = 0LL;
  for(int i = 0; i <= k; i++){
    ans += ncr(n, i) * nhr(n-i, i);
  }
  cout << ans << endl;
}

