long long int egcd(long long int a,long long int b,long long int &x,long long int &y)
{
    if (a == 0)
    {
        x = 0;
        y = 1;
        return b;
    }
    long long int x1, y1;
    long long int d = egcd(b % a, a, x1, y1);
    x = y1 - (b / a) * x1;
    y = x1;
    return d;
}
