        fact[0] = 1;
        for (i64 i = 1; i <= n + k; ++i) {
            fact[i] = (fact[i - 1] * i) % MOD;
        }
        i64 ans = fact[n + k];
        ans *= mod_pow(fact[k], MOD - 2, MOD);
        ans %= MOD;
        ans *= mod_pow(fact[n], MOD - 2, MOD);
        ans %= MOD;
        cout << ans << endl;
    } else {
        // 作れない組み合わせを引いていく
        i64 a = k;
        k = n - 1;
        vector<i64> fact(n + k + 1);
        fact[0] = 1;
        for (i64 i = 1; i <= n + k; ++i) {
            fact[i] = (fact[i - 1] * i) % MOD;
        }
        i64 ans = fact[n + k];
        ans *= mod_pow(fact[k], MOD - 2, MOD);
        ans %= MOD;
        ans *= mod_pow(fact[n], MOD - 2, MOD);
        ans %= MOD;

        for (i64 i = 1; i <= n - a - 1; ++i) {
            // nCi
            i64 nci = fact[n];
            nci *= mod_pow(fact[i], MOD - 2, MOD);
            nci %= MOD;
            nci *= mod_pow(fact[n - i], MOD - 2, MOD);
            nci %= MOD;
            //
            i64 juhuku = fact[i + i - 1];
            juhuku *= mod_pow(fact[i], MOD - 2, MOD);
            juhuku %= MOD;
            juhuku *= mod_pow(fact[i - 1], MOD - 2, MOD);
            juhuku %= MOD;
            nci *= juhuku;
            nci %= MOD;
            ans -= nci;
            if (ans < 0) ans += MOD;
        }
