long long modinv(long long a) { long long b = MOD, u = 1, v = 0; while (b) { long long t = a / b; a -= t * b; swap(a, b); u -= t * v; swap(u, v); } u %= MOD; if (u < 0) u += MOD; return u; }
long long modadd(long long a, long long b) { return (a % MOD + b % MOD) % MOD; }
long long modmult(long long a, long long b) { return (a % MOD) * (b % MOD) % MOD; }
long long modsub(long long a, long long b) { long long c = a % MOD - b % MOD; if (c < 0) return c + MOD; else return c;}
long long moddiv(long long a, long long b) { return (a % MOD * modinv(b % MOD)) % MOD; }
long long modpow(long long a, long long n) { long long ret = 1; while (n > 0) {  if (n & 1) ret = modmult(ret, a); a = modmult(a, a); n >>= 1; } return ret; }
long long modcomb(long long n, long long r) { if (n < r || n < 0 || r < 0) return 0; long long ret = 1; if (r > n / 2) r = n - r; loop(i, r) ret = modmult(ret, n-i); loop(i, r) ret = moddiv(ret, i+1); return ret; }
long long modhcomb(long long n, long long r) { return modcomb(n + r - 1, r); }

long long fac_arr[MOD_MAX], finv_arr[MOD_MAX], inv_arr[MOD_MAX];
void modcomb_init() { fac_arr[0] = fac_arr[1] = 1; finv_arr[0] = finv_arr[1] = 1; inv_arr[1] = 1; for (int i = 2; i < MOD_MAX; i++){ fac_arr[i] = fac_arr[i - 1] * i % MOD; inv_arr[i] = MOD - inv_arr[MOD%i] * (MOD / i) % MOD; finv_arr[i] = finv_arr[i - 1] * inv_arr[i] % MOD; } }
long long modcomb_fast(int n, int k){ if (n < k || n < 0 || k < 0) return 0; return fac_arr[n] * (finv_arr[k] * finv_arr[n - k] % MOD) % MOD; }
long long modhcomb_fast(long long n, long long r) { return modcomb_fast(n + r - 1, r); }

