int F[maxn + 5], Finv[maxn + 5], inv[maxn + 5];
void init()
{
    inv[1] = 1;
    for (int i = 2; i < maxn; i++) {
        inv[i] = (mod - mod / i) * (LL)1 * inv[mod % i] % mod;
    }
    F[0] = Finv[0] = 1;
    for (int i = 1; i < maxn; i++) {
        F[i] = F[i - 1] * LL(1) * i % mod;
        Finv[i] = Finv[i - 1] * LL(1) * inv[i] % mod;
    }
}
int comb(int n, int m)
{ //comb(n, m)就是C(n, m)
    if (m < 0 || m > n)
        return 0;
    return F[n] * LL(1) * Finv[n - m] % mod * Finv[m] % mod;
}

