const int MOD = 1e9 + 7;

long long exp_mod(int a, int b, int m) {  // return a^b mod m
    long long ans = 1;
    long long tmp = a;
    while (b) {
        if (b & 1) {
            ans = (ans * tmp) % m;
        }
        b >>= 1;
        tmp = (tmp * tmp) % m;
    }
    return ans;
}

long long inv(int a, int m) {  // return a-1
    return exp_mod(a, m - 2, m);
}

long long ncr_mod(int n, int r, int m) {  // return nCr mod m
    long long ret = 1;
    for (int i = 0; i < r; ++i) {
        ret = (ret * (n - i)) % m;
        ret = (ret * inv(1 + i, m)) % m;
    }
    return ret;
}

long long nhr_mod(int n, int r, int m) {  // return nHr mod m
    return ncr_mod(n + r - 1, r, m);
}

int main() {
    int n, k;
    cin >> n >> k;
    long long ans = nhr_mod(n, n, MOD);
    for (int i = k + 1; i < n; ++i) {
        ans = (ans - ncr_mod(n, i, MOD) * nhr_mod(n - i, i, MOD) % MOD + MOD) % MOD;
    }
    cout << ans << endl;
    return 0;
}

