using namespace std;
using LLONG = long long;
const LLONG MOD = 1000000007;

class ModCalc
{
    LLONG m_mod;
    vector<LLONG> m_fac;
    vector<LLONG> m_ifac;

public:

    ModCalc(const LLONG mod)
    {
        m_mod = mod;
    }

    ModCalc(const int max, const LLONG mod)
    {
        m_mod = mod;
        m_fac = vector<LLONG>(max + 1);
        m_ifac = vector<LLONG>(max + 1);
        m_fac[0] = m_ifac[0] = 1;
        for (int i = 0; i < max; ++i)
        {
            m_fac[i + 1] = m_fac[i] * (i + 1) % mod;    // n! (mod M)
            m_ifac[i + 1] = m_ifac[i] * ModPow(i + 1, mod - 2) % mod;   // k!^(M-2) (mod M)
        }
    }

    const LLONG ModAdd(LLONG a, LLONG b) const
    {
        return (a + b) % m_mod;
    }

    const LLONG ModSubtract(LLONG a, LLONG b) const
    {
        LLONG diff = a - b;
        return diff >= 0 ? diff : diff + m_mod;
    }

    const LLONG ModMulti(LLONG a, LLONG b) const
    {
        LLONG prod = a * b % m_mod;
        return prod >= 0 ? prod : prod + m_mod;
    }

    const LLONG ModDiv(LLONG a, LLONG b) const
    {
        LLONG c = m_mod, u = 1, v = 0;
        while (c)
        {
            LLONG t = b / c;
            b -= t * c; swap(b, c);
            u -= t * v; swap(u, v);
        }
        u %= m_mod;
        if (u < 0) u += m_mod;
        return (a % m_mod) * u % m_mod;
    }

    const LLONG ModPow(LLONG x, LLONG n) const
    {
        LLONG ret = 1;
        while (n != 0)
        {
            if (n & 1) ret = ret * x % m_mod;
            x = x * x % m_mod;
            n = n >> 1;
        }
        return ret;
    }

    const LLONG ModComb(LLONG n, LLONG r) const
    {
        if (n == 0 && r == 0) return 1;
        if (n < r || n < 0) return 0;
        LLONG tmp = m_ifac[n - r] * m_ifac[r] % m_mod;
        return tmp * m_fac[n] % m_mod;
    }
};

int main()
{
    LLONG n, k; cin >> n >> k;
    // k >= n の場合は、全ての人が任意の部屋に行くことができる
    // 従ってあり得る人数の組み合わせは(2n-1)Cn：O(n = 2*10^5)
    if (k >= n)
    {
        LLONG ans = 1LL;
        ModCalc mod(MOD);
        for (LLONG r = 1LL; r <= n; ++r)
        {
            ans = mod.ModMulti(ans, n * 2LL - 1LL - r + 1LL);
            ans = mod.ModDiv(ans, r);
        }
        cout << ans << endl;
    }
    // k < n(<= 2*10^5) の場合
    else
    {
        LLONG ans = 1LL;
        ModCalc mod(2 * 10001, MOD);
        for (LLONG r = 1LL; r <= k; ++r)
        {
            // 空になる部屋の選び方＝nCr
            // ２人以上になる部屋の選び方=(n-r+p-1)Cp
            LLONG minus = mod.ModComb(k, r);
            LLONG tmp = 0LL;
            for (LLONG p = 1LL; p <= min(k - r, r); ++p)
            {
                LLONG plus = mod.ModComb(k - r + p - 1LL, p);
                tmp = mod.ModAdd(tmp, plus);
            }
            tmp = mod.ModMulti(minus, tmp);
            ans = mod.ModAdd(ans, tmp);
        }
        cout << ans << endl;
    }
}

