int const MOD = 1000000007;

vector<ll> factorials;
void init_factorial(int N)
{
    factorials.assign(N+1, 1);
    rep(i, 2, N+1)
    {
        factorials[i] = factorials[i-1] *i;
        factorials[i] %= MOD;
    }
}

ll power_mod(ll n, ll m)
{
    ll res = 1;
    ll base = n;
    while (m > 0)
    {
        if (m&1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        m >>= 1;
    }
    return res;
}

ll inv_mod(ll n)
{
    return power_mod(n, MOD-2);
}

ll comb(ll n, ll m)
{
    m = min(m, n-m);
    ll res = factorials[n];
    res *= inv_mod(factorials[n-m]);
    res %= MOD;
    res *= inv_mod(factorials[m]);
    res %= MOD;
    return res;
}

ll dup_comb(ll n, ll m)
{
    return comb(n+m-1, n-1);
}

int main()
{
    init_factorial(1000000);

    int n, k;
    cin >> n >> k;

    ll res = 0;
    rep(i, 0, min(k, n-1)+1)
    {
        ll now = comb(n, i)*dup_comb(n-i, i);
        now %= MOD;
        res += now;
        res %= MOD;
        debug(i, comb(n, i), dup_comb(n-i, i), now);
    }
    cout << res << endl;
    return 0;
}

