int base = 1e9 + 7;

ll invmod(ll p, ll q) {
  ll r = 1;
  while (q) {
    if (q&1) r = (r*p) % base;
    p = p*p % base;
    q >>= 1;
  }
  return r;
}

ll combimod(ll n, ll m, vector<ll> inv) {
  ll t = 1;
  while (m) {
    t = t * n % base;
    t = t * inv[m] % base;
    n--; m--;
  }
  return t;
}

int main() {
  ll n, k; cin >> n >> k;
  vector<ll> inv(n);
  for (int i = 0; i < n; ++i) inv[i] = invmod(i, base-2);

  int N = min(n-1, k);
  int m = n;
  ll total = 0, combi1 = 1, combi2 = 1;
  for (int i = 0; i <= N; ++i) {
    ll t = combi1 * combi2 % base;
    total = (total + t) % base;

    combi1 = combi1 * m % base * inv[i+1] % base;
    combi2 = combi2 * (m-1) % base * inv[i+1] % base;
    m--;
  }

  cout << total << endl;
}

