        if(k%2 == 1) cout << nCk_mod<long long>(2*n-1, n-1, MOD)-1 << endl;
        return 0;
    } 
    */

    vector<long long> nC(n+1, 1), n_1C(n+1, 1);
    FOR(i, 1, n+1){
        n_1C[i] = ((n-i)*n_1C[i-1])%MOD*pow_mod<long long>(i, MOD-2, MOD);
        n_1C[i] %= MOD;
    }
    FOR(i, 1, n+1){
        nC[i] = n_1C[i-1] + n_1C[i];
        nC[i] %= MOD;
    }

    long long ans = 0;
    FOR(i, 1, min(n, k+1)){
        ans += nC[i]*n_1C[n-i-1];
        ans %= MOD;
    }
    if(k%2 == 0) cout << (ans+1)%MOD << endl;
    else cout << ans << endl;

    return 0;
}

