#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

const int MAX = 510000;
const int MOD = 1000000007;

long long fac[MAX], finv[MAX], inv[MAX];

// テーブルを作る前処理
void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

// 二項係数計算
long long COM(int n, int k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

//これを使うときにはCOMinit();を忘れずに

int main(void){
    int N, K; cin >> N >> K;
    K = min(N-1, K);
    COMinit();
    //0..K部屋の空きができる
    //n部屋にr人を分ける（1人もいなくても構わない）
    //(n-1+r)Cr
    ll ans = 0;
    for(int i = 0; i <= K; i++){
        ll keisuu = COM(N, i);
        ll people = i;
        ans = (ans + keisuu*COM((N-i)-1+people, people)) % MOD;
    }
    cout << ans << endl;
}

