        fac[i] = fac[i-1] * i % mod;
        inv[i] = mod - inv[mod % i] * (mod / i) % mod;
        facinv[i] = facinv[i-1] * inv[i] % mod;
    }
}

ll modinv(ll a){
    if(a==0) abort();
    ll b = mod, u = 1, v = 0;
    while(b){
        ll t = a/b;
        a -= t * b; swap(a,b);
        u -= t * v; swap(u,v);
    }
    u %= mod;
    if(u<0) u += mod;
    return u;
}

ll modcomb(ll n, ll k){
    if(n<0||k<0||n<k) return 0;
    return fac[n] * facinv[k] % mod * facinv[n-k] % mod;
}

int main(){
  modcalc();

  int n,k; cin>>n>>k;
  ll ans = 0;
  k = min(k,n-1);
  rep(i,k+1){
    ans += modcomb(n,i) * modcomb(n-1,n-i-1);
    ans %= mod;
  }
  cout << ans << endl;
}

