const int MAXN = 234567;
const LL MOD = (LL)1e9 + 7;
LL fac[MAXN], invfac[MAXN];

LL add(LL a, LL b) {
    LL sum = (a + b);
    if (sum >= MOD) sum -= MOD;
    return sum;
}

LL mul(LL a, LL b) {
    return (a * b) % MOD;
}

LL qpow(LL n, LL k) {
    LL base = n, ans = 1;
    while (k) {
        if (k & 1) ans = mul(ans, base);
        base = mul(base, base);
        k >>= 1;
    }
    return ans;
}

void init() {
    fac[0] = invfac[0] = fac[1] = invfac[1] = 1;
    for (int i = 2; i < MAXN; i++)
        fac[i] = mul(fac[i - 1], i);
    invfac[MAXN - 1] = qpow(fac[MAXN - 1], MOD - 2);
    for (int i = MAXN - 2; i >= 1; i--)
        invfac[i] = mul(invfac[i + 1], i + 1);
}

LL C(int n, int m) {
    if (m > n) return 0;
    LL ans = mul(fac[n], invfac[m]);
    return mul(ans, invfac[n - m]);
}

LL H(int a, int b) {
    LL ans = fac[a + b - 1];
    ans = mul(ans, invfac[a]);
    return mul(ans, invfac[b - 1]);
}

int main() {
    init();
    int N, K;
    scanf("%d %d", &N, &K);
    LL ans = 0;
    for (int i = 0; i <= min(N - 1, K); i++) {
        LL cur_ans = C(N, i);
        LL offs = H(i, N - i);
        ans = add(ans, mul(cur_ans, offs));
    }
    printf("%lld\n", ans);
    return 0;
}

