ll fastPow(ll a, ll b){
    if (!b) {
        return 1;
    }

    ll sq=fastPow(a, (b>>1LL));
    sq*=sq;

    if (b&1) {
        sq%=MOD;
        sq*=a;
    }

    return sq%MOD;
}

