using namespace std;
using ll = long long;

const int maxn = 200000 + 10;
int fac[maxn], invfac[maxn];

#define MOD 1000000007
long long qpow(long long a, long long b){
    long long s = 1;
    while (b > 0) {
        if (b & 1)s = s * a % MOD;
        a = a * a % MOD;
        b >>= 1;
    }
    return s;
}
void init() {
    int n = maxn - 1;
    fac[0] = 1;
    for (int i = 1; i <= n; ++i)
        fac[i] = 1ll * fac[i - 1] * i % MOD;
    invfac[n] = qpow(fac[n], MOD - 2);
    for (int i = n - 1; i >= 0; --i) {
        invfac[i] = 1ll * invfac[i + 1] * (i + 1) % MOD;
    }
}
long long comb(int n, int m) {
    if (n < m) return 0;
    return 1ll * fac[n] * invfac[m] % MOD * invfac[n - m] % MOD;
}
ll comb_rep(int n, int m){ //重複組み合わせ
  return comb(n+m-1, m);
}


int main(){
  init();
  ll n, k;
  cin >> n >> k;
  ll ans = 0;
  for(int i = 0; i <= min(n-1, k); i++){
    ans += comb(n, i) * comb_rep(n-i, i);
    ans %= MOD;
  }
  cout << ans << endl;
}

