const int M = 1e9+7, F = 4e5;
int add(int a, int b){ return a+b < M ? a+b : a+b-M; }
int sub(int a, int b){ return a-b >= 0 ? a-b : a-b+M; }
int mul(int a, int b){ return int(ll(a)*b % M); }
ll pot(ll b, ll e){ // O(log e)
	if(!e) return 1;
	ll q = pot(b, e/2); q = mul(q, q);
	return (e & 1 ? mul(b, q) : q);
}
int inv(int x){ return pot(x, M-2); }
int divide(int a, int b) { return mul(a, inv(b)); }
int fact[F+1];
int choose(int n, int c){
    return divide(fact[n], mul(fact[n-c], fact[c]));
}
int k_tuples_of_non_neg_int_whose_sum_is_n(int k, int n){ 
    return choose(n+k-1, n); 
}
int k_tuples_of_pos_int_whose_sum_is_n(int k, int n){ 
    return choose(n-1, k-1); 
}

int main() {
    ios_base::sync_with_stdio(0), cin.tie(0);

    fact[0] = 1;
    forsn(i,1,F+1) fact[i] = mul(i, fact[i-1]);

    int n,k; cin >> n >> k;
    int r = k_tuples_of_non_neg_int_whose_sum_is_n(n,n);
    if(k < n) forsn(i,1,n-k){
        int x = k_tuples_of_pos_int_whose_sum_is_n(i,n);
        r = sub(r, mul(x, choose(n,i)));
    }
    cout << r << endl;
    return 0;
}

