const int N = 2000000;
int Fac[N];
inline void Prepare()
{
	Fac[0]=1;
	for(int i=1;i<=1000000;++i)
		Fac[i]=i*Fac[i-1]%Mod;	
}
inline int C(int n,int m)
{

	return Fac[n]*Inv(Fac[n-m]*Fac[m])%Mod;
}
