long long gya(long long a) { //逆元を求める
  long long m=1000000007, b=m, u=1, v=0, c, t;
  while(b){
    t=a / b; //何これ
    a-=t * b, u-=t * v; //何これ
    c=a, a=b, b=c, c=u, u=v, v=c; //swap
  }
  return (u + m) % m;
}
long long com(long long b, long long d) { //bCd
  int i, mod=1000000007;
  long long ret=1, ret2=1, tmp=1;

  if(mem[b - 1] == 0){
    for(i=1; i <= b; i++)
      ret=ret * i % mod;
    mem[b - 1]=ret;
  }else ret=mem[b - 1];

  if(mem[b - d - 1] == 0){
    for(i=1; i <= b - d; i++)
      ret2=ret2 * i % mod;
    mem[b - d - 1]=ret2;
  }else ret2=mem[b - d - 1];

  if(mem[d - 1] == 0){
    for(i=1; i <= d; i++)
      tmp=tmp * i % mod;
    mem[d - 1]=tmp;
  }else tmp=mem[d - 1];

  //printf("ret=%10lld \t ret2=%10lld \t tmp=%10lld\n", ret,ret2, tmp);
  return ret * gya(tmp * ret2 % mod) % mod;
}

