#include <stdio.h>

#define MOD 1000000007
#define AMAX (2<<17)

int N,K;
long F[AMAX];
long I[AMAX];

long powmod( long, long );

/***********************************************************
    階乗と逆数のテーブル生成
***********************************************************/
void maketable()
{
    // 階乗を計算し記録
    F[0] = 1;
    for( int i=1; i<=N+1; i++ )
        F[i] = (long long) F[i-1] * i % MOD;

    // 階乗の逆数を計算し記録
    I[N] = powmod( F[N], MOD -2 );
    for( int i=N-1; i>=0; i-- )
        I[i] = (long long) I[i+1] * (i+1) % MOD;
}

/***********************************************************
    べき乗＋剰余
***********************************************************/
long powmod( long a, long b )
{
    long long ret = 1;

    while( b ) {
        if( b & 1 ) ret = ret * a % MOD;
        b >>= 1;
        a = (long long)a * a % MOD;
    }

    return( ret );
}

/***********************************************************
    組合せ＋剰余
***********************************************************/
long combination( long n, long r )
{
    long long ret;

    ret = F[n];
    ret = (ret * I[n-r]) % MOD;
    ret = (ret * I[r]) % MOD;

    return( ret );
}

/***********************************************************

***********************************************************/
int main( int argc, char *argv[] )
{
    // 問題を読み取る
    scanf( "%d%d", &N, &K );

    // 階乗と逆数のテーブルを生成
    maketable();

    // ΣnCr * n-1Cr を計算
    long long ans = 0;
    for(long i=0;i<N&&i<=K;i++) {
//        ans += F[N] * F[N-1] % MOD * I[N-i] % MOD * I[i] % MOD * I[N-1-i] % MOD * I[i] % MOD;
        ans += (long long) combination( N, i ) * combination( N-1, i ) % MOD;
    }

//    while( ans < 0 ) ans += MOD;
    ans %= MOD;

    printf( "%ld\n", (long)ans );
}

