fun minus(a: Int, b: Int): Int {
    return (a - b + mod) % mod
}

fun c(n: Int, k: Int): Long {
    var res = (fact[n] * inv(fact[k])) % mod
    res = (res * inv(fact[n - k])) % mod
    return res
}

fun inv(x: Long): Long {
    return pow(x, mod - 2)
}

fun pow(a: Long, x: Int): Long {
    var a = a
    var x = x
    var res = 1L
    while (x > 0) {
        if (x % 2 == 1) res = (res * a) % mod
        x /= 2
        a = (a * a) % mod
    }

    return res
}

