        }

        if(k >= n-1){
            long ans = 1;
            for (int i = 0; i < n-1; i++) {
                ans *= n*2-1-i;
                ans %= DIV;
                ans *= inv[i+1];
                ans %= DIV;
            }
            System.out.println(ans);
        }else{
            long ans = 1;
            long ans0 = 1;
            long ans1 = 1;
            for (int i = 1; i <= k; i++) {
                ans0 *= n-i+1;
                ans0 %= DIV;
                ans0 *= inv[i];
                ans0 %= DIV;

                ans1 *= n-i;
                ans1 %= DIV;
                ans1 *= inv[i];
