                long ans2 = (ans0 * ans1) % DIV;
                ans += ans2;
                ans %= DIV;
            }
            System.out.println(ans);
        }
    }


    static long modinv(long a, long m){
        long b = m, u = 1, v = 0;
        while(b > 0){
            long t = a / b;
            a -= t * b;
            long tmp = a;
            a = b;
            b = tmp;
            u -= t * v;
            tmp = u;
            u = v;
            v = tmp;
        }
        u %= m;
        if (u < 0) u += m;
        return u;
    }



    private static class FastScanner {
        private final InputStream in = System.in;
