			combi = (combi * (n - i)) % MOD;
			combi = (combi * (new BigInteger(Integer.toString(i + 1))).modInverse(BMOD).longValue()) % MOD;

			long h = (combi * (n - i - 1)) % MOD;
			h = (h * NINV) % MOD;

			long p = (combi * h) % MOD;
			ans = (ans + p) % MOD;
		}

