public class Main {

    public static void main(String[] args) throws Exception {
        try (Scanner sc = new Scanner(System.in)) {
            long MOD = 1000000007;

            int N = sc.nextInt();
            int K = sc.nextInt();

            long[] fact = new long[N + 1];
            fact[0] = 1;
            for (int i = 1; i <= N; i++) {
                fact[i] = fact[i - 1] * i % MOD;
            }

            long ans = 0;
            for (int i = 0; i <= K; i++) {
                if (N - i <= 0) {
                    break;
                }

                ans = (ans + combination(fact, N, N - i, MOD) * combination(fact, N - 1, i, MOD)) % MOD;
            }

            System.out.println(ans);
        }
    }

    static long combination(long[] fact, int N, int K, long MOD) {
        long comb = fact[N];
        long factK = fact[K];
        long factM = fact[N - K];

        long m = MOD - 2;
        while (m > 0) {
            if (m % 2 == 1) {
                comb = comb * factK % MOD;
                comb = comb * factM % MOD;
                m--;
            }

            factK = factK * factK % MOD;
            factM = factM * factM % MOD;
            m = m / 2;
        }

        return comb;
    }

}

