    static MyReader in = new MyReader();

    public static void main(String[] args){       
        ModOp.init();
        int n, k; {int[] a = in.ii(); n = a[0]; k = a[1];}
        int max = Math.min(n-1, k);
        long ans = 0;
        for(int i = 0; i <= max; i++){
            ans = (ans + ModOp.com(n, i) * ModOp.com(n-1, i)) % ModOp.MOD;
        }
        out.println(ans);
    }

    static class ModOp {
        final static long MOD = 1_000_000_007;
        final static int MAX = 200_000;
        static long[] fact;
        static long[] factInv;
        static long[] inv;

        static long pow(long a, long b){
            long ret = 1;
            while(b > 0){
                if(b%2 == 1){
                    ret = ret*a%MOD;
                }
                a = a*a%MOD;
                b /= 2;
            }
            return ret;
        }

        static long mul(int s, int e){
            long ret = 1;
            for(int i = s; i <= e; i++){
                ret = ret*i%MOD;
            }
            return ret;
        }

        static long fact(int n){
            return mul(1, n);
        }

        static long nCr(int n, int r){
            return mul(n-r+1, n) * pow(fact(r), MOD-2) % MOD;
        }

        static void init() {
            fact = new long[MAX+1];
            factInv = new long[MAX+1];
            inv = new long[MAX+1];
            fact[0] = fact[1] = factInv[0] = factInv[1] = inv[1] = 1;
            for (int i = 2; i <= MAX; i++){
                fact[i] = fact[i - 1] * i % MOD;
                inv[i] = MOD - inv[(int)(MOD%i)] * (MOD / i) % MOD;
                factInv[i] = factInv[i - 1] * inv[i] % MOD;
            }
        }

        static long com(int n, int k){
            return n < k || n < 0 || k < 0 ? 0 : 
                   fact[n] * (factInv[k] * factInv[n - k] % MOD) % MOD;
        }

    }

