import java.util.*;
import java.util.stream.Collectors;
import java.io.*;
import java.nio.charset.StandardCharsets;

public class Main {
	static long MOD = 1000000007L;

	static class Combination {
		long n;
		long[] array;

		public Combination(long n) {
			this.n = n;
			this.array = new long[(int) (n + 1)];
			array[0] = 0L;
			array[1] = 1L;
			for (long i = 2; i <= n; ++i) {
				int index = (int) i;
				array[index] = array[index - 1] * i % MOD;
			}

		}

		static long pow(long base, long n) {
			long result = 1L;
			long y = base;
			long times = n;
			while (times != 0) {
				if ((times & 1L) > 0) {
					result = (result * y) % MOD;
				}
				y = (y * y) % MOD;
				times /= 2;
			}
			return result;
		}

		static long inv(long val) {
			long result = 1L;
			long k = MOD - 2L;
			long y = val;
			while (k != 0) {
				if ((k & 1L) > 0) {
					result = (result * y) % MOD;
				}
				y = (y * y) % MOD;
				k /= 2;
			}
			return result;
		}

		static long simpleCombi(long n, long c) {
			long result = 1L;
			if (c == 0 || c == n) {
				return 1L;
			}
			if (c > n / 2) {
				return simpleCombi(n, n - c);
			}
			for (long i = n; i > n - c; --i) {
				result *= i;
				result %= MOD;
			}
			for (long i = c; i > 0; --i) {
				result *= inv(i);
				result %= MOD;
			}
			return result;

		}

		long calcCombi(long c) {
			if (c == 0) {
				return 1L;
			}
			// まず階乗の配列を計算する
			long val = array[(int) (n)];
			val *= inv(array[(int) (n - c)]);
			val %= MOD;
			val *= inv(array[(int) (c)]);
			val %= MOD;
			return val;
		}

	}

	int n;
	long k;
	Map<Long, Combination> combiMap = new HashMap<>();
	long result = 0L;

	public static void main(String[] args) throws IOException {
		InputStreamReader reader = new InputStreamReader(System.in, StandardCharsets.UTF_8);
		BufferedReader in = new BufferedReader(reader);
		Main ins = new Main(in);
		ins.calc();
		ins.showResult();
	}

	Combination getCombi(Long n) {
		if (!combiMap.containsKey(n)) {
			combiMap.put(n, new Combination(n));
		}
		return combiMap.get(n);
	}

	Main(BufferedReader in) throws IOException {
		String[] tokens = in.readLine().split(" ");
		n = Integer.parseInt(tokens[0]);
		k = Long.parseLong(tokens[1]);
	}

	long sub(long n, long m) {
		long val = getCombi(n).calcCombi(m);
		val *= getCombi(n - 1).calcCombi((n - m) - 1) % MOD;
		return val;
	}

	void calc() {
		result = 1;
		for (long i = 1; i <= Math.min(k, n - 1); ++i) {
			result += sub(n, i);
			result %= MOD;
		}
	}

	void showResult() {
		System.out.println(result);
	}

}

import java.util.Scanner;

public class Main {
    static int MAX_FAC = 400001;
    static long FAC[] = new long[MAX_FAC];
    static long INV_FAC[] = new long[MAX_FAC];
    private static long MOD = 1_000_000_007;
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        long k = sc.nextLong();
        long ans=0;
        initFAC();
        if(k==1){
            ans = (n*(n-1)) % MOD;
        }else{
            for(long i=1;i<=Math.min(k, n-1);i++){
                //System.out.println(bara((int)n, (int)(n-i)) + ":" + comb((int)n, (int)i));
                ans += ((bara((int)n, (int)(n-i)) * comb((int)n, (int)i)) % MOD);
                ans %= MOD;
            }
            ans ++;
            ans %= MOD;
        }
        System.out.println(ans);
    }
    static long comb(int n, int k){
        return (((FAC[n] * INV_FAC[n-k]) % MOD) * INV_FAC[k]) % MOD;
    }

    static void initFAC(){
        FAC[0]=1;
        INV_FAC[0] = modinv(FAC[0]);
        for(int i=1;i<MAX_FAC;i++){
            FAC[i]=(i*FAC[i-1]) % MOD;
            INV_FAC[i] = modinv(FAC[i]);
        }
    }
    static long modpow(long a, long b){
        if(b == 1){return a % MOD;}
        if(b == 0){return 1;}
        long res = b/2;
        long rem = b%2;
        long p = modpow(a, res) % MOD;
        if(rem == 1){
            return (((p*p) % MOD) * a) % MOD;
        }else{
            return (p*p) % MOD;
        }
    }

    static long modinv(long a){
        return modpow(a, MOD-2);
    }

    private static long bara(int n, int k){
        return comb(n-1, k-1);
    }

}

