		int n = sc.nextInt();
		int k = sc.nextInt();
		k = Math.min(k, n - 1);
		init(n);
		long ans = 0;
		for (int i = 0; i <= k; i++)
			ans = (ans + ch(n, i) * ch(n - 1, i)) % MD;
		println(ans);
	}
