		}
		return tmp;
	}

	public static long pow (long a, int j) {
	    long res=1;
	    while (j>0) {
	        if ((j-j/2*2)==1) {
	            res=(res*a)%mod;
	        }
	        a=(a*a)%mod;
	        j>>=1;
	    }
	    return res;
	}

