		long ans = 0L;

		for(int m = 0;m<Math.min(n, k+1);m++){

			long cmb = hz_COM(fac, finv, n, m, MOD) * hz_COM(fac, finv, n-1, n-m-1, MOD) % MOD;
			ans = (ans + cmb) % MOD;
		}

		System.out.println(ans);
	}
}

import java.util.Scanner;

public class Main {
    private static final int MOD = 1_000_000_007;

    public static void main(final String[] args) {
        final Scanner scanner = new Scanner(System.in);
        final int n = scanner.nextInt();
        final int k = scanner.nextInt();

        final CombinationCalculator comb = new CombinationCalculator(2 * n, MOD).init();
        long sum = 0;
        for (int i = 0; i < Math.min(n, k + 1); i++) {
            sum += comb.calc(n, i) * comb.calc(n - 1, n - i - 1);
            sum %= MOD;
        }

        System.out.println(sum);
    }

    private static class CombinationCalculator {
        private final int size;
        private final int mod;
        private final long[] factorials;
        private final long[] invertedElements;
        private final long[] invertedFactorials;

        CombinationCalculator(final int size, final int mod) {
            this.size = size;
            this.mod = mod;
            this.factorials = new long[size];
            this.invertedElements = new long[size];
            this.invertedFactorials = new long[size];
        }

        CombinationCalculator init() {
            factorials[0] = 1;
            factorials[1] = 1;
            invertedFactorials[0] = 1;
            invertedFactorials[1] = 1;
            invertedElements[1] = 1;
            for (int i = 2; i < size; i++) {
                factorials[i] = factorials[i - 1] * i % mod;
                invertedElements[i] = mod - invertedElements[mod % i] * (mod / i) % mod;
                invertedFactorials[i] = invertedFactorials[i - 1] * invertedElements[i] % mod;
            }
            return this;
        }

        long calc(final int n, final int k) {
            return factorials[n] * (invertedFactorials[k] * invertedFactorials[n - k] % mod) % mod;
        }
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.Scanner;

public class Main {
    private long fac[];
    private long finv[];
    private long inv[];
    private static int MAX_LEN = 510000;
    private static int MOD = 1000000007;
    public static void main(String[] args) {
        Main main = new Main();
        main.COMinit();
        main.solve();
    }

    public void solve() {
        Scanner scan = new Scanner(new BufferedReader(new InputStreamReader(System.in)));
        int N = scan.nextInt();
        int K = scan.nextInt();
        long ans = 0;
        for (int i = 0; i <= Math.min(N,K); i++) {
            long t1 = COM(N, i);
            // N-i個に1以上を配置して和をnにする
            // N-i個に0以上を配置して和をn-(n-i)=iにする
            long t2 = COM(i+(N-i-1),i);
            ans += t1 * t2;
            ans %= MOD;
        }
        System.out.println(ans);
    }
    void COMinit() {
        this.fac = new long[MAX_LEN];
        this.finv = new long[MAX_LEN];
        this.inv = new long[MAX_LEN];
        this.fac[0] = this.fac[1] = 1;
        this.finv[0] = this.finv[1] = 1;
        this.inv[1] = 1;
        for (int i = 2; i < MAX_LEN; i++) {
            fac[i] = fac[i-1] * i % MOD;
            inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
            finv[i] = finv[i-1] * inv[i] % MOD;
        }
    }
    long COM(int n, int k) {
        if (n < k) {
            return 0;
        };
        if (n <0 || k < 0) {
            return 0;
        }
        return fac[n] * (finv[k] * finv[n - k]%MOD)%MOD;
    }
}

import java.util.Scanner;

public class Main {
    static int mod = 1000000007;
    static long[] nFactorial;
    public static void main(String[] args) {
        Scanner cin = new Scanner(System.in);

        int n, k;

        n = cin.nextInt();
        k = cin.nextInt();

        if (k >= n - 1) {
            System.out.println(choose(2 * n - 1, n -1));
        } else {
            long sum = 0;
            nFactorial = new long[n];
            fill();
            for (int i = 0; i <= k; i++) {
                sum = (sum + term(n, i)) % mod;
                sum %= mod;
            }
            System.out.println(sum);
        }
    }

    public static long pow(long n, int m) {
        long prod = 1;
        while (m > 0) {
            if ((m & 1) == 1) {
                prod = (prod * n) % mod;
            }
            n = (n*n) % mod;
            m >>= 1;
        }
        return prod;
    }

    public static void fill () {
        nFactorial[0] = 1;
        for (int i = 1; i < nFactorial.length; i++) {
            nFactorial[i] = (nFactorial[i - 1] * i) % mod;
        }
    }

    public static long choose(int a, int b) {
        long numerator = 1;
        long denominator = 1;
        for (int i = 1; i <= b; i++) {
            numerator *= a - i + 1;
            denominator *= b - i + 1;
            numerator %= mod;
            denominator %= mod;
        }
        return (numerator * pow(denominator, mod - 2)) % mod;
    }

    public static long term(int n, int i) {
        long numerator = 1;
        long denominator = 1;
        numerator = (n * pow(nFactorial[n - 1], 2)) % mod;
        denominator = (((n - i) * pow(nFactorial[i], 2)) % mod * pow(nFactorial[n - i - 1], 2)) % mod;
        return (numerator * pow(denominator, mod - 2)) % mod;
    }
}

