public void solve() {
	int num = ni();
	int kk = ni();
	if(kk >= num - 1) {
		prtln(H(num, num));
		return;
	}else {
		long ans = 0;
		for(int i = kk; i >= 0; i --) {
			long tmp = H(num - i, i);
			tmp *= C(num, i);
			tmp = mod(tmp);
			ans += tmp;
			ans = mod(ans);
		}
		prtln(ans);
	}
