//			tr(">", e, ans);
		}
		out.println(ans);
	}

	private long com(int n, int c) {
//		tr(n, c);
		return p[n] * invP[c] % MOD * invP[n - c] % MOD;
	}

	long power(long a, long b) {
		long x = 1, y = a;
		while (b > 0) {
			if (b % 2 != 0) {
				x = (x * y) % MOD;
			}
			y = (y * y) % MOD;
			b /= 2;
		}
		return x % MOD;
	}

	private long gcd(long a, long b) {
		while (a != 0) {
			long tmp = b % a;
			b = a;
			a = tmp;
		}
		return b;
	}

