        int n = sc.nextInt();
        int k = sc.nextInt();
        long res = 0;
        long[] fact = new long[n + 1];
        fact[0] = 1;
        for (int i = 0; i < n; i++) {
            fact[i + 1] = fact[i] * (i + 1) % m;
        }
        for (int i = 0; i <= Math.min(n - 1, k); i++) {
            res += (fact[n] * MyMath.modinv(fact[n - i] * fact[i], m)) % m * fact[n - 1] % m
                    * MyMath.modinv(fact[i] * fact[n - i - 1], m) % m;
            res %= m;
        }

        out.println(res);

