	private void solve(FastIO io, String[] args) {
		/*
		 * author: 31536000
		 * AtCoder Beginner Contest 156 E問題
		 * 考察メモ
		 * これ、よく考えるとある組合せが可能かどうかだけ判定すれば良いことが分かる
		 * kが十分に大きい時、任意の組み合わせが可能
		 * これは、n人をn-1個の仕切りで分断する問題なので重複組み合わせ
		 * そうでない(kがある程度小さい)ケースを考える
		 * これは、一定以上の大きさの分け方が禁止されているので、それを除外する
		 * これは、人がいる部屋はn-k部屋以上と解釈すれば良い
		 * よってこれを全部足していけば良い
		 * 人がいる部屋の決め方: _nC_i
		 * この時の選び方: n人をi部屋に割り当てる方法なので重複組み合わせではい
		 *
		 */
		int n = io.nextInt(), k = io.nextInt();
		k = Math.min(n, k);
		ModUtility mod = new ModUtility(new Prime(1_000_000_007), n);
		ModInteger ans = mod.create();
		for (int i = Math.max(1, n - k);i <= n;++ i) ans.addEqual(mod.multiply(mod.combination(n, i), mod.multichoose(i, n - i)));
		io.println(ans);

	}

