class Solver {
  final int n, k;
  ModCalculator mc;

  Solver(int n, int k) {
    this.n = n;
    this.k = k;
  }

  public long solve() {
    mc = new ModCalculator(1_000_000_007L);
    long answer = mc.getC(n + n - 1, n - 1);
    for (int i = 1; i <= n - k - 1; i++) {
      long v1 = mc.getC(n, i);
      long v2 = mc.getC(n - i + i - 1, i - 1);
//      System.err.printf("%d %d\n", v1, v2);
      answer = mc.sub(answer, mc.mul(v1, v2));
    }
    return answer;
  }
}

