		// 計算
		long result = 0;
		Combination comb = new Combination(n);
		for(int i = 0; i <= min(k, n-1); i++){
		    long temp = 0;
		    temp += comb.combination(n, i);
		    temp %= MOD;
		    temp *= comb.combination(n-1, n-i-1);
