			fact[i] = (fact[i - 1] * i) % r;
			inv[i] = r - (inv[r % i] * (r / i)) % r;
			finv[i] = (finv[i - 1] * inv[i]) % r;
		}
	}

	public static int comb(int n, int k) {
		if(n < k)return 0;
		if(k < 0 || n < 0)return 0;
		if(k == 0)return 1;

		return (int)((fact[n] * (finv[k] * finv[n - k] % r)) % r);
	}

