        long factn = 1, factnm1 = 1;
        long[] invfact = new long[n + 1];
        invfact[0] = 1;
        for (int i = 1; i <= n; i++) {
            factn = factn * i % MOD;
            if (i == n - 1) factnm1 = factn;
            invfact[i] = invfact[i - 1] * powm(i, MOD - 2) % MOD;
        }
        long res = 0;
        for (int i = 0; i <= k; i++) {
            long c1 = factn * invfact[i] % MOD * invfact[n - i] % MOD;
            long c2 = factnm1 * invfact[i] % MOD * invfact[n - 1 - i] % MOD;
            res = res + c1 * c2 % MOD;
            res %= MOD;
        }
        out.println(res);
    }

    private int gcd(int a, int b) {
        while (true) {
            if (b == 0) return a;
            int tmp = a;
            a = b;
            b = tmp % b;
        }
    }

    private long powm(long x, long p) {
