public class Mint
{
    public const long Mod = (long)1e9 + 7;
    public long Number { get; private set; }
    public Mint Inv => Pow(Mod - 2);

    public Mint(long number = 0)
    {
        Number = (number % Mod + Mod) % Mod;
    }

    public Mint Pow(long t)
    {
        if (t == 0)
        {
            return new Mint(1);
        }

        var result = Pow(t >> 1);
        result *= result;

        if ((t & 1) > 0)
        {
            result *= this;
        }

        return result;
    }

    public static Mint Combination(Mint m, Mint n)
        => Permutation(m, n) / Permutation(n, n);

    public static Mint Permutation(Mint m, Mint n)
        => n.Number == 0 ? new Mint(1) : Enumerable.Range(m - n + 1, n).Select(target => new Mint(target)).Aggregate((a, b) => a * b);

    public static Mint operator +(Mint m) => m;
    public static Mint operator -(Mint m) => new Mint(-m.Number);
    public static Mint operator +(Mint a, Mint b) => new Mint(a.Number + b.Number);
    public static Mint operator -(Mint a, Mint b) => new Mint(a.Number - b.Number);
    public static Mint operator *(Mint a, Mint b) => new Mint(a.Number * b.Number);
    public static Mint operator /(Mint a, Mint b) => a * b.Inv;
    public static implicit operator Mint(long i) => new Mint(i);
    public static implicit operator Mint(int i) => new Mint(i);
    public static implicit operator long(Mint m) => m.Number;
    public static implicit operator int(Mint m) => (int)m.Number;
    public override string ToString() => Number.ToString();
}

