    class Program
    {
        static void Main(string[] args)
        {
            var n = RInt;
            var K = RInt;

            long mod = 1000000007;

            long ans = 0;
            if (K >= n - 1)
            {
                ans = nCk(2 * n - 1, n - 1, mod);
                Console.WriteLine(ans);
                return;
            }

            for (int i = 0; i <= K; i++)
            {
                ans += nCk(n - 1, i, mod) * nCk(n, i, mod);
            }

            Console.WriteLine(ans);
        }

        /// <summary>
        /// a^n (mod p)
        /// nが非常に大きい時に有効
        /// </summary>
        /// <param name="a"></param>
        /// <param name="n"></param>
        /// <param name="mod"></param>
        /// <returns></returns>
        public static long ModPow(long a, long n, long p)
        {
            if (n == 0) return 1;
            if (n == 1) return a % p;
            if (n % 2 == 1) return (a * ModPow(a, n - 1, p)) % p;

            long t = ModPow(a, n / 2, p);
            return (t * t) % p;
        }

        /// <summary>
        /// 組み合わせ個数
        /// </summary>
        /// <param name="n"></param>
        /// <param name="k"></param>
        /// <param name="p"></param>
        /// <returns></returns>
        public static long nCk(long n, long k, long p)
        {
            long ans = 1;
            k = Math.Min(k, n - k);
            for (long i = n; i > n - k; i--)
            {
                ans = (ans * i) % p;
            }

            for (long i = 1; i <= k; i++)
            {
                ans = (ans * ModPow(i, p - 2, p)) % p;
            }

            return ans;
        }


    }

    /// <summary>
    /// Mod計算型 若干遅いかも
    /// </summary>
    public struct Mlong
    {
        long _v;
        const long mod = 998244353;
        public Mlong(long n = 0) { _v = n % mod; }

        public static implicit operator Mlong(long _x) => new Mlong(_x);
        public static implicit operator long(Mlong _x) => _x._v;
        public static Mlong operator +(Mlong m1, Mlong m2) { long m = m1._v + m2._v; return m >= mod ? m - mod : m; }
        public static Mlong operator -(Mlong m1, Mlong m2) { long m = m1._v - m2._v; return m >= 0 ? m : m + mod; }
        public static Mlong operator *(Mlong m1, Mlong m2) => m1._v * m2._v % mod;
        public static Mlong operator /(Mlong m1, Mlong m2) => m1._v * ModPow(m2._v, mod - 2) % mod;

        public static long ModPow(long a, long n)
        {
            if (n == 0) return 1;
            if (n % 2 == 1) return a * ModPow(a, n - 1) % mod;

            long t = ModPow(a, n / 2);
            return t * t % mod;
        }
    }
}

