    static long CombinationMod(long m, long n, long mod) {
    Func<long, long, long> ModPow = (x1, x2) => {
        long ans = 1;
        while (x2 > 0) {
            if (x2 % 2 == 1) {
                ans = (ans * x1) % mod;
            }
            x1 = (x1 * x1) % mod;
            x2 /= 2;
        }
        return ans % mod;
    };
    Func<long, long> ModFact = (x1) => {
        long ans = 1;
        for (long i = x1; i > 0; i--)
            ans = (ans * i) % mod;
        return ans;
    };

    var a = ModFact(m);
    var b = (ModFact(n) * ModFact(m-n)) % mod;
    long bb = ModPow(b, mod - 2);
    return (a * bb) % mod;
}
