			//入力
			string[] input = Console.ReadLine().Split(' ');
			long n = long.Parse(input[0]);
			long k = long.Parse(input[1]);

			long MOD = 1000000000 + 7;
			long sum = 0;

			//下準備
			nCk com = new nCk();
			com.fac = new long[n + 1];
			com.inv = new long[n + 1];
			com.finv = new long[n + 1];
			com.mod = MOD;
            com.max = n + 1;

			//メモ作成
			com.com_init();

            //最大の部屋の数を考える
            long m = n;
          　if(n > k)
                m = k + 1;

			//nCm×n-mHm = nCm×n-1Cn-m-1の和を出す
			for(long i = 0;i < m;i++)
			{
				sum += com.com(n, i) * com.com(n - 1, n - i - 1) % MOD;
				sum %= MOD;
			}

			//出力
			Console.WriteLine(sum);

		}

	}

	class nCk
	{
		public long mod;
		public long max;
		public long[] fac;
		public long[] inv;
		public long[] finv;


		//メモ作成
		public void com_init()
		{
			fac[0] = 1;
			fac[1] = 1;
			finv[0] = 1;
			finv[1] = 1;
			inv[1] = 1;
			for(long i = 2;i < max;i++)
			{
				fac[i] = i * fac[i - 1] % mod;
				inv[i] = mod - inv[mod % i] * (mod / i) % mod;
				finv[i] = finv[i - 1] * inv[i] % mod;
			}
		}

		//二項計算
		public long com(long n,long k)
		{
			if (n < 0 || k < 0)
				return 0;
			if (n < k)
				return 0;
			return fac[n] * (finv[n - k] * finv[k] % mod) % mod;
		}

	}

