public class Factorical
{
  public long[] Fact;
  public long[] invFact;
  public Factorical(long N, long MOD = 1000000007)
  {
    Fact = new long[N + 1];
    invFact = new long[N + 1];
    Fact[0] = 1;
    for (long i = 1; i <= N; ++i)
    {
      Fact[i] = Fact[i - 1] * i % MOD;
    }
    invFact[N] = Power(Fact[N], MOD - 2);
    for (long i = N; i > 0; --i)
    {
      invFact[i - 1] = invFact[i] * i % MOD;
    }
  }
  public long Comb(long n, long r, long MOD = 1000000007) => Fact[n] * invFact[r] % MOD * invFact[n - r] % MOD;
}

public static class Math2
{
  public const int INF = 1 << 29;
  public const long INFL = 1L << 60;
  public const long MOD = 1000000007;
  public const int MOD2 = 998244353;

  public static long Power(long a, long b, long MOD = 1000000007)//i^N
  {
    long res = 1;
    while (b > 0)
    {
      if ((b & 1) != 0) res = res * a % MOD;
      a = a * a % MOD;
      b >>= 1;
    }
    return res;
  }
  public static long Power2(long a, long b)//i^N
  {
    long res = 1;
    while (b > 0)
    {
      if ((b & 1) != 0) res = res * a;
      a = a * a;
      b >>= 1;
    }
    return res;
  }
  public static long GCD(long a, long b)
  {
    while (b > 0)
    {
      var r = a % b;
      a = b;
      b = r;
    }
    return a;
  }
  public static long LCM(long a, long b) => (b / GCD(a, b)) * a;
  public static long Comb(long n, long r, int MOD = 1000000007)
  {
    long ret = 1;
    long x = 1;
    for (long i = n; i >= n - r + 1; --i)
    {
      ret = ret / x * i;
      ret %= MOD;
      x++;
    }
    return ret;
  }
  public static long Comb2(long n, long r)
  {
    long Nume = 1;
    long Deno = 1;

    if (r > n - r) r = n - r;
    for (long i = 1; i <= r; ++i)
    {
      Deno *= i;
      Nume *= n - i + 1;
    }
    return Nume / Deno;
  }
}
