public class Solver
{
	public void Solve()
	{
		long n = GetLong();
		long k = GetLong();

		MInt.InitTable(n);
		var ans = new MInt(0);
		for(long i = 0; i <= Min(n - 1, k); i++)
			ans += MInt.MComb(n, i) * MInt.MComb(n - 1, i);

		WriteLine(ans.Val);		
	}
