func multiCombMod(n, k int) int {
	return combMod(n+k-1, k)
}

func combMod(n, k int) int {
	if k == 0 {
		return 1
	}

	res := n
	div := k
	for i := 1; i < k; i++ {
		res = res * (n - i) % MOD
		div = div * (k - i) % MOD
	}
	div = modPow(div, MOD-2)
	return res * div % MOD
}

func modPow(a, n int) int {
	if n == 0 {
		return 1
	}
	res := 1
	for p := n; p > 0; p >>= 1 {
		if p&1 == 1 {
			res = res * a % MOD
		}
		a = a * a % MOD
	}
	return res
}

