func max(l []int) (int, int) {
	idx := 0
	ans := l[idx]
	for i, n := range l {
		if n > ans {
			idx = i
			ans = n
		}
	}
	return idx, ans
}

func min(l []int) (int, int) {
	idx := 0
	ans := l[idx]
	for i, n := range l {
		if n < ans {
			idx = i
			ans = n
		}
	}
	return idx, ans
}
func mul(a int64, b int64) int64 {
	return (a * b) % mod
}

func power(x int64, y int64) int64 {
	if y == 0 {
		return 1
	} else if y%2 == 0 {
		ans := int64(power(x, y/2)) % mod
		ans = mul(ans, ans)
		return ans
	} else {
		ans := int64(power(x, y/2)) % mod
		ans = mul(mul(ans, ans), x)
		return ans
	}
}

var mod = int64(1000000007)

func comb(n int, k int) int64 {
	x := int64(1)
	y := int64(1)
	for i := 0; i < k; i++ {
		x = mul((int64(n - i)), x)
		y = mul(int64(i+1), y)
	}
	invy := power(y, mod-2)
	return mul(x, invy)
}

