		ModInt.cacheFactorial(n.value, m);

		let result = modint(1);
		result = result.mul(this.factorial_cache[m][n.value]);
		result = result.div(this.factorial_cache[m][k.value]);
		result = result.div(this.factorial_cache[m][n.value - k.value]);
		return result;
	}

