        if (n & 1) res = res * a;
        a = a * a;
        n >>= 1;
    }
    return res;
}

Unqual!M powmod(A,N,M)(A _a, N _n, M mod)
{
    Unqual!A a = _a;
    Unqual!N n = _n;
