Unqual!M mod(N,M)(N n, M mod) pure @nogc
if(isIntegral!N&&isIntegral!M)
{
    return (n%mod+mod)%mod;
}

long pow(long a, long n) {
    long res = 1;
    while (n > 0) {
        if (n & 1) res = res * a;
        a = a * a;
        n >>= 1;
    }
    return res;
}

Unqual!M powmod(A,N,M)(A _a, N _n, M mod)
{
    Unqual!A a = _a;
    Unqual!N n = _n;
    M res = 1;
    while (n > 0) {
        if (n & 1) res = res * a % mod;
        a = a * a % mod;
        n >>= 1;
    }
    return res;
}

