alias MInt = ModInt!(mod);
alias MComb = ModComb!(mod);

struct ModInt(long modulus)
{
    long value;
    this(long value) {this.value = (value + modulus) % modulus;}
    string toString() {return this.value.to!string;}
    ModInt opBinary(string op)(long rhs) if (op == "+" || op == "-" || op == "*") {return typeof(this)(mixin("(this.value "~op~" (rhs % modulus) + modulus) % modulus"));}
    ModInt opBinaryRight(string op)(long lhs) if (op == "+" || op == "-" || op == "*") {return opBinary!(op)(lhs);}
    ModInt opBinary(string op)(ModInt that) if (op == "+" || op == "-" || op == "*") {return typeof(this)(mixin("(this.value "~op~" that.value + modulus) % modulus"));}
    ModInt opBinary(string op)(long divisor) if (op == "/") {return this.value * modPow(divisor, modulus-2);}
    ModInt opBinaryRight(string op)(long dividend) if (op == "/") {return ModInt(dividend).value * modPow(this.value, modulus-2);}
    ModInt opBinary(string op)(ModInt that) if (op == "/") {return this.value * modPow(that.value, modulus-2);}
    ModInt opBinary(string op)(long exponent) if (op == "^^") {return modPow(this.value, exponent);}
    ModInt opBinaryRight(string op)(long base) if (op == "^^") {return modPow(base, this.value);}
    ModInt opBinary(string op)(ModInt that) if (op == "^^") {return modPow(this.value, that.value);}
    ModInt opOpAssign(string op)(long rhs) {return this = opBinary!(op)(rhs);}
    ModInt opOpAssign(string op)(ModInt that) {return this = opBinary!(op)(that);}
    ModInt modPow(long base, long exponent)
    {
        ModInt result = 1;
        while (exponent > 0)
        {
            if (exponent & 1) result = result * base;
            base = base * base % modulus;
            exponent >>= 1;
        }
        return result;
    }
}

struct ModComb(long modulus)
{
    private alias M = ModInt!(modulus);
    M[] fac, inv, finv;
    this(long limit)
    {
        fac.length = limit + 1;
        inv.length = limit + 1;
        finv.length = limit + 1;
        fac[0] = fac[1] = M(1L);
        finv[0] = finv[1] = M(1L);
        inv[1] = M(1L);
        foreach (i; 2 .. limit+1)
        {
            fac[i] = fac[i-1] * i;
            inv[i] = M(modulus) - inv[modulus%i] * (modulus / i);
            finv[i] = finv[i-1] * inv[i];
        }
    }
    M comb(long whole, long part)
    in
    {
        assert(whole < fac.length);
        assert(part < fac.length);
    }
    body
    {
        if (whole < part) return M(0);
        if (whole < 0 || part < 0) return M(0);
        return fac[whole] * finv[part] * finv[whole-part];
    }
    M comb(M whole, M part)
    {
        return comb(whole.value, part.value);
    }
}

