        if times == 0:
            return ModInt(1, self.mod)

        x = self.pow(times // 2)
        x *= x
        if times % 2:
            x *= self

        return x

    def inverse(self):
        return self.pow(self.mod - 2)

    def __truediv__(self, other):
        num = self * other.inverse()
        return ModInt(num, self.mod)


