const R: u64 = 1000000007;

fn pow(n: u64, r: u64) -> u64 {
    let mut ret = 1;
    if r > 0 {
        ret = pow(n, r / 2);
        ret = ret * ret % R;
        if r % 2 == 1 {
            ret = ret * n % R;
        }
    }
    ret
}

fn main() {
    let nk: Vec<u64> = read_vec();
    let n = nk[0];
    let k = nk[1];

    let mut ans = 0;

    if k <= n - 2 {
        let mut a = n;
        let mut b = 1;
        for l in 2..n + 1 {
            a = (a * (n - l + 1)) % R;
            a = (a * pow(l, R - 2)) % R;
            b = (b * (n - l + 1)) % R;
            b = (b * pow(l - 1, R - 2)) % R;
            if l >= n - k {
                ans = (ans + ((a * b) % R)) % R;
            }
        }
    } else {
        ans = 1;
        for i in n + 1..2 * n {
            ans = (ans * i) % R;
        }
        for i in 1..n {
            ans = (ans * pow(i, R - 2)) % R;
        }
    }

    println!("{}", ans);
}

