fn solve() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let n: usize = sc.read();
    let k: usize = sc.read();
    let mod_util = ModUtil::new(4000010, 1e9 as usize + 7);
    let mut result = if k % 2 == 0 {
        ModInt::new(1)
    } else {
        ModInt::new(0)
    };
    for i in 1..n {
        if i > k {
            break;
        }
        let num = n - i;
        let rest = n - num;
        let mut tmp = ModInt::new(mod_util.combination(n, i));
        let mut tmp1 = ModInt::new(mod_util.combination(rest + num - 1, rest));
        result += tmp * tmp1;
        //n!
        //i!(k-i)!
    }
    println!("{}", result.0);
}

