fn pow(a: i64, n: i64, m: i64) -> i64 {
    if n == 0 {
        return 1;
    }
    if n % 2 == 0 {
        let t = pow(a, n / 2, m);
        return t * t % m;
    }
    return a * pow(a, n - 1, m) % m;
}

fn ncr(n: i64, r: i64, fact: &mut Vec<i64>, factinv: &mut Vec<i64>, m: i64) -> i64 {
    return fact[n as usize] * factinv[r as usize] % m * factinv[(n - r) as usize] % m;
}

