const MODULO: i64 = 1_000_000_007;

fn solve(input: &str) -> i64 {
    let mut iter = input.split_whitespace().map(|w| w.parse().unwrap());
    let n: i64 = iter.next().unwrap();
    let k: i64 = iter.next().unwrap();
    if k >= n - 1 {
        binom(2 * n - 1, n - 1)
    } else {
        let mut factorial = vec![0; (n + 1) as usize];
        factorial[0] = 1;
        for i in 1..n + 1 {
            factorial[i as usize] = i * factorial[(i - 1) as usize] % MODULO;
        }
        let inverse_factorial: Vec<i64> = factorial.iter().map(|&x| inverse(x)).collect();
        let binom = |a: i64, b: i64| {
            let mut ans = factorial[a as usize];
            ans = ans * inverse_factorial[b as usize] % MODULO;
            ans = ans * inverse_factorial[(a - b) as usize] % MODULO;
            ans
        };
        let mut ans = 0;
        for m in 0..k + 1 {
            ans = (ans + binom(n - 1, n - m - 1) * binom(n, m) % MODULO) % MODULO;
        }
        ans
    }
}

fn power(base: i64, exponent: i64) -> i64 {
    let mut acc = 1;
    let mut base = base;
    let mut exponent = exponent;
    while exponent != 0 {
        if exponent & 1 == 1 {
            acc = acc * base % MODULO;
        }
        base = base * base % MODULO;
        exponent >>= 1;
    }
    acc
}

fn inverse(x: i64) -> i64 {
    power(x, MODULO - 2)
}

fn binom(n: i64, k: i64) -> i64 {
    let mut numer = 1;
    let mut denom = 1;
    for i in 0..k {
        numer = numer * (n - i) % MODULO;
        denom = denom * (k - i) % MODULO;
    }
    numer * inverse(denom) % MODULO
}

