type BoxResult<T> = Result<T, Box<std::error::Error>>;

const MOD: u64 = 1_000_000_000 + 7;

fn main() {
    let mut scanner = Scanner::new(stdin());
    let (n, k) = scanner.read_two::<usize, usize>().unwrap();
    let invs = (1..(n + 1)).map(|i| power(i as u64, MOD - 2, MOD)).collect::<Vec<_>>();
    let combi1 = combis(n as u64, n as u64, &invs);
    let combi2 = combis(n as u64 - 1, n as u64 - 1, &invs);
    let mut ans = 0;
    for i in 0..min(k + 1, n) {
        ans += (combi1[i] * combi2[n - 1 - i]) % MOD;
        ans %= MOD;
    }
    println!("{}", ans);
}

fn combis(n: u64, k: u64, invs: &[u64]) -> Vec<u64> {
    (0..(k + 1)).scan(1, |state, val| {
        if val > 0 {
            *state = (*state * (n - val + 1)) % MOD;
            *state = (*state * invs[val as usize - 1]) % MOD;
        }
        Some(*state)
    }).collect()
}

fn power(x: u64, mut k: u64, modulo: u64) -> u64 {
    let mut pows = vec![x];
    for i in 0..63 {
        let square = (pows[i] * pows[i]) % modulo;
        pows.push(square);
    }
    let mut pow = 1;
    for i in 0..64 {
        let flag = k & 1;
        k >>= 1;
        if flag == 1 {
            pow = (pow * pows[i]) % modulo;
        }
    }
    pow
}

