}

fn answer(n: u64, k: u64, m: u64) -> u64 {
    // if k == 0 {
    //     println!("1");
    //     return;
    // }

    let mut total = modulo::comb(n + n - 1, n - 1, m);
    if k >= n - 1 {
        return total;
    }

    // if k == 1 {
    //     total -= 1;
    // }

    for l in (k + 1)..n {
        let exists = n - l;
        let mut count = modulo::comb(n - exists + exists - 1, exists - 1, m);
        count = modulo::mul(count, modulo::comb(n, exists, m), m);
        total = modulo::sub(total, count, m);
    }
    total
}

