pub struct ModComb {
    max: usize,
    fac: Vec<ModInt>,
    finv: Vec<ModInt>,
}

impl ModComb {
    pub fn new(max: usize) -> Self {
        let mut fac = vec![ModInt::zero(); max + 1];
        let mut finv = vec![ModInt::zero(); max + 1];
        let mut inv = vec![ModInt::zero(); max + 1];
        fac[0] = ModInt::one();
        fac[1] = ModInt::one();
        finv[0] = ModInt::one();
        finv[1] = ModInt::one();
        inv[1] = ModInt::one();
        let modulo = ModInt::MOD as usize;
        for i in 2..=max {
            fac[i] = fac[i - 1] * ModInt::from(i);
            inv[i] =
                ModInt::from(ModInt::from(modulo) - (inv[modulo % i] * ModInt::from(modulo / i)));
            finv[i] = finv[i - 1] * inv[i]
        }
        Self { max, fac, finv }
    }

    pub fn comb(&self, n: usize, k: usize) -> ModInt {
        if n > self.max {
            panic!();
        }
        if n < k {
            return ModInt::zero();
        }
        self.fac[n] * self.finv[k] * self.finv[n - k]
    }
}

fn solve() {
    input! {
        n: usize, k: usize
    };

    let k = n.min(k);
    let comb = ModComb::new(n + n);
    let mut res = ModInt::zero();
    for k in 0..=k {
        if n - k > 0 {
            res += comb.comb(n, k) * comb.comb(n - 1, n - k - 1);
        }
    }
    println!("{}", res);
}

fn main() {
    std::thread::Builder::new()
        .name("big stack size".into())
        .stack_size(256 * 1024 * 1024)
        .spawn(|| {
            solve();
        })
        .unwrap()
        .join()
        .unwrap();
}

