use proconio::input;

use num_traits::{pow, One};
use std::ops::{Add, Div, Mul, Sub};

const MODULUS: usize = 1000000007;

fn main() {
    input! {
        n :usize,
        mut k :usize
    }

    // prepare a table of factorials
    let mut fac_vec: Vec<ModP> = Vec::new();
    let mut fac_inv_vec: Vec<ModP> = Vec::new();
    fac_vec.push(ModP(1));
    fac_inv_vec.push(ModP(1));
    for i in 1..(n + 1) {
        fac_vec.push(ModP(i) * fac_vec[i - 1]);
        fac_inv_vec.push(ModP(1) / fac_vec[i]);
    }
    let fac_vec = fac_vec;
    let fac_inv_vec = fac_inv_vec;

    // normalize k
    if k >= n {
        k = n - 1;
    }
    let k = k;

    let mut total = ModP(0);
    for i in 0..(k + 1) {
        let thispart = fac_vec[n]
            * fac_inv_vec[i]
            * fac_inv_vec[n - i]
            * fac_vec[n - 1]
            * fac_inv_vec[n - i - 1]
            * fac_inv_vec[i];
        total = total + thispart;
    }

    println!("{}", total.0);
}

#[derive(Clone, Copy, PartialEq, Debug)]
struct ModP(usize);

impl One for ModP {
    fn one() -> Self {
        return ModP(1);
    }
}
impl Add for ModP {
    type Output = Self;
    fn add(self, rhs: Self) -> Self {
        return ModP((self.0 + rhs.0) % MODULUS);
    }
}
impl Sub for ModP {
    type Output = Self;
    fn sub(self, rhs: Self) -> Self {
        return ModP((self.0 + MODULUS - rhs.0) % MODULUS);
    }
}
impl Mul for ModP {
    type Output = Self;
    fn mul(self, rhs: Self) -> Self {
        return ModP((self.0 * rhs.0) % MODULUS);
    }
}
impl Div for ModP {
    type Output = Self;
    fn div(self, rhs: Self) -> Self {
        if rhs.0 == 0 {
            panic!("Tried to divide by ModP(0)!");
        }
        let rhs_inv = pow(rhs, MODULUS - 2);
        return self * rhs_inv;
    }
}

