const MOD: i64 = 1_000_000_000 + 7;

#[fastout()]
fn main() {
    input! {
        n:usize,k:usize
    }
    // n-1 <=k のように、kが十分大きければ、全パターン。
    // すなわち n人と仕切りn-1で組み合わせなので、2n-1 choose n-1
    let mut fact = vec![1i64; n + 1];
    let mut ifact = vec![1i64; n + 1];
    for i in 1..=n as usize {
        fact[i] = fact[i - 1] * (i as i64) % MOD;
        ifact[i] = modInv(fact[i]);
    }
    let choose = |n, r| fact[n] * ifact[n - r] % MOD * ifact[r] % MOD;
    //if n - 1 <= k {
    //    let ans: i64 = choose(2 * n - 1, n - 1);
    //    println!("{}", ans);
    //    return;
    //}
    // k < n-1 の時は、0人の部屋の数を i とすると、0の位置がchoose(n,i)
    // i人がn-i個の部屋に分散したと考えるとその分け方は、H(n-i,i) =　choose(n-i+i-1,n-i-1)
    let mut ans = 0;
    for i in 0..=std::cmp::min(k, n - 1) {
        let tmp = choose(n, i) * choose(n - 1, n - i - 1) % MOD;
        //println!("i={}, choose={}", i, tmp);
        ans = (ans + tmp) % MOD;
    }
    println!("{}", ans);
}

fn modPow(x: i64, a: i64) -> i64 {
    if a == 0 {
        1
    } else {
        if a % 2 != 0 {
            modPow(x, a - 1) * x % MOD
        } else {
            let y = modPow(x, a / 2);
            y * y % MOD
        }
    }
}
fn modInv(x: i64) -> i64 {
    modPow(x, MOD - 2) % MOD
}

