const MOD: i64 = 1_000_000_007;

fn extgcd(a: i64, b: i64, x: &mut i64, y: &mut i64) -> i64 {
    let mut d = a;
    if b != 0 {
        d = extgcd(b, a % b, y, x);
        *y -= (a / b) * (*x);
    } else {
        *x = 1; *y = 0;
    }
    d
}

fn mod_inverse(a: i64, m: i64) -> i64 {
    let mut x = 0;
    let mut y = 0;
    extgcd(a, m, &mut x, &mut y);
    (m + x % m) % m
}

fn mod_fact(n: i64, p: i64, e: &mut i64, fact: &Vec<i64>) -> i64 {
    *e = 0;
    if n == 0 {
        return 1;
    }

    let res = mod_fact(n/p, p, e, fact);
    *e += n/p;
    if (n/p %2 != 0) {
        return res * (p - fact[(n%p) as usize]) % p;
    }
    res * fact[(n%p) as usize] % p
}

fn mod_comb(n: i64, k: i64, memo: &Vec<i64>) -> i64 {
    if n < 0 || k < 0 || n < k {
        return 0;
    }
    let mut e1 = 0;
    let mut e2 = 0;
    let mut e3 = 0;
    let a1 = memo[n as usize];
    let a2 = memo[k as usize];
    let a3 = memo[(n-k) as usize];
    if e1 > e2 + e3 {
        return 0;
    }
    a1 * mod_inverse(a2 * a3 % MOD, MOD) % MOD
}


fn main() {
    let line: Vec<usize> = read_line().split_whitespace().map(|s| s.parse().unwrap()).collect();
    let n = line[0];
    let k = line[1];
    let mut memo = vec![0i64; 400_010];
    memo[0] = 1;
    memo[1] = 1;
    for i in 2..memo.len() {
        memo[i] = (memo[i-1] * (i as i64)) % MOD;
    }

    let mut ans = 0;
    if k >= n-1 {
        ans = mod_comb((2 * n -1) as i64, (n-1) as i64, &memo);
    } else {
        for i in 0..k+1 {
            ans += mod_comb(n as i64, i as i64, &memo) * mod_comb((n - 1) as i64, i as i64, &memo) % MOD;
            ans %= MOD;
        }
    }
    println!("{}", ans);
}

