    let mut ans = Modulo(0);

    let max_idx = max(n, k) as usize + 1;
    let mut fact = vec![Modulo(1); max_idx];
    for i in 1..max_idx {
        fact[i] = fact[i - 1] * Modulo(i as i64);
    }
    let mut inv_fact = vec![Modulo(1); max_idx];
    for i in 1..max_idx {
