        if i == 0 {
            ans += 1;
            continue;
        }
        let coef1 = mod_comb(n as usize, i as usize, &fact, &inv_fact);
        let coef2 = mod_comb(n as usize - 1, i as usize, &fact, &inv_fact);
        ans += coef1 * coef2;
