    use std::io::Read;
    let mut input = String::new();
    std::io::stdin().read_to_string(&mut input).unwrap();
    println!("{}", solve(&input));
}

const MODULO: i64 = 1_000_000_007;

fn solve(input: &str) -> i64 {
    let mut iter = input.split_whitespace().map(|w| w.parse().unwrap());
    let n: i64 = iter.next().unwrap();
    let k: i64 = iter.next().unwrap();
    if k >= n - 1 {
        binom(2 * n - 1, n - 1)
    } else {
        let mut ans = 0;
        for m in 0..k + 1 {
            ans = (ans + binom(n - 1, n - m - 1) * binom(n, m) % MODULO) % MODULO;
        }
        ans
    }
}

fn power(base: i64, exponent: i64) -> i64 {
    let mut acc = 1;
    let mut base = base;
    let mut exponent = exponent;
    while exponent != 0 {
        if exponent & 1 == 1 {
            acc = acc * base % MODULO;
        }
        base = base * base % MODULO;
        exponent >>= 1;
    }
    acc
}

fn inverse(x: i64) -> i64 {
    power(x, MODULO - 2)
}

fn binom(n: i64, k: i64) -> i64 {
    let mut numer = 1;
    let mut denom = 1;
    for i in 0..k {
        numer = numer * (n - i) % MODULO;
        denom = denom * (k - i) % MODULO;
    }
    numer * inverse(denom) % MODULO
}

use std::io;
use std::str::FromStr;

static MOD: u64 = 1_000_000_007;

fn input_tuple() -> (u64, u64) {
    let mut line: String = String::new();
    io::stdin().read_line(&mut line);
    let vec: Vec<u64> = line.split_whitespace().map(|s| s.parse().unwrap()).collect();
    (vec[0], vec[1])
}

fn binary_power(x: u64, n: u64) -> u64 {
    if n == 0 {
      return 1;
    }
    if n % 2 == 0 {
      return (binary_power(x, n / 2) % MOD).pow(2) % MOD;
    } else {
      return binary_power(x, n - 1) % MOD * x % MOD;
    }
}

fn inverse_mod(n: u64) -> u64 {
    binary_power(n, MOD-2)
}  

fn combination(n: u64, mut m: u64) -> u64 {
    if n < m {
        return 0;
    }

    if m > n - m {
        m = n - m
    }

    let mut ret = 1u64;
    for i in 0..m {
        ret %= MOD;
        ret *= n - i;        
    }
    ret %= MOD;

    let mut div = 1u64;
    for i in 1..(m+1) {
        div %= MOD;
        div *= i;
    }
    div %= MOD;

    // println!("{}, {}", ret, div);
    ret * inverse_mod(div) % MOD
}

fn main() {
    let (n, k) = input_tuple();
    if k >= n {
        // 全組み合わせ
        println!("{}", combination(n * 2 - 1, n - 1));
        return;
    }
    let mut sum = 0;
    let mut c1 = combination(n, n - k);
    let mut c2 = combination(n - 1, k);
    for i in (n-k)..(n+1) {
        // println!("{}, {}", c1, c2);
        sum = sum + c1 % MOD * c2 % MOD;
        sum %= MOD;

        c1 = c1 * (n - i) % MOD * inverse_mod(i + 1) % MOD;
        c2 = c2 * (n - i) % MOD * inverse_mod(i) % MOD;
    }
    println!("{}", sum);
}

#[allow(unused_imports)]
use std::cmp;
use std::io::Write;

// Input macro from https://qiita.com/tanakh/items/0ba42c7ca36cd29d0ac8
macro_rules! input {
  (source = $s:expr, $($r:tt)*) => {
    let mut iter = $s.split_whitespace();
    input_inner!{iter, $($r)*}
  };
  ($($r:tt)*) => {
    let s = {
      use std::io::Read;
      let mut s = String::new();
      std::io::stdin().read_to_string(&mut s).unwrap();
      s
    };
    let mut iter = s.split_whitespace();
    input_inner!{iter, $($r)*}
  };
}

macro_rules! input_inner {
  ($iter:expr) => {};
  ($iter:expr, ) => {};

  ($iter:expr, $var:ident : $t:tt $($r:tt)*) => {
    let $var = read_value!($iter, $t);
    input_inner!{$iter $($r)*}
  };
}

macro_rules! read_value {
  ($iter:expr, ( $($t:tt),* )) => {
    ( $(read_value!($iter, $t)),* )
  };

  ($iter:expr, [ $t:tt ; $len:expr ]) => {
    (0..$len).map(|_| read_value!($iter, $t)).collect::<Vec<_>>()
  };

  ($iter:expr, chars) => {
    read_value!($iter, String).chars().collect::<Vec<char>>()
  };

  ($iter:expr, usize1) => {
    read_value!($iter, usize) - 1
  };

  ($iter:expr, [ $t:tt ]) => {{
    let len = read_value!($iter, usize);
    (0..len).map(|_| read_value!($iter, $t)).collect::<Vec<_>>()
  }};

  ($iter:expr, $t:ty) => {
    $iter.next().unwrap().parse::<$t>().expect("Parse error")
  };
}

const MOD: i64 = 1_000_000_007;

#[derive(Copy, Clone, Hash, Debug)]
struct ModInt {
  x: i64
}
impl ModInt {
  fn new(x: i64) -> Self {
    let x = x % MOD;
    ModInt {
      x: if x < 0 {
        x + MOD
      } else {
        x
      }
    }
  }
  fn pow(self, e: i64) -> Self {
    if e == 0 {
      Self::new(1)
    } else if e % 2 == 1 {
      self.pow(e - 1) * self
    } else {
      let y = self.pow(e / 2);
      y * y
    }
  }
  #[allow(dead_code)]
  fn inv(self) -> Self {
    self.pow(MOD - 2)
  }
  #[allow(dead_code)]
  fn fact(n: usize) -> Vec<Self> {
    let mut ret = vec![0.into(); n+1];
    ret[0] = 1.into();
    for i in 1 .. n + 1 {
      ret[i] = ret[i-1] * i as i64;
    }
    ret
  }
  #[allow(dead_code)]
  fn inv_fact(fact: &Vec<Self>) -> Vec<Self> {
    let n = fact.len() - 1;
    let mut ret = vec![0.into(); n+1];
    ret[n] = fact[n].inv();
    for i in (0 .. n).rev() {
      ret[i] = ret[i+1] * (i + 1) as i64;
    }
    ret
  }
}
