use std::io::{stdin, Read, StdinLock};
use std::str::FromStr;

#[allow(dead_code)]
struct Scanner<'a> {
    cin: StdinLock<'a>,
}
#[allow(dead_code)]
impl<'a> Scanner<'a> {
    fn new(cin: StdinLock<'a>) -> Scanner<'a> {
        Scanner { cin: cin }
    }

    fn read<T: FromStr>(&mut self) -> Option<T> {
        let token = self
            .cin
            .by_ref()
            .bytes()
            .map(|c| c.unwrap() as char)
            .skip_while(|c| c.is_whitespace())
            .take_while(|c| !c.is_whitespace())
            .collect::<String>();
        token.parse::<T>().ok()
    }

    fn input<T: FromStr>(&mut self) -> T {
        self.read().unwrap()
    }

    fn vec<T: FromStr>(&mut self, len: usize) -> Vec<T> {
        (0..len).map(|_| self.input()).collect()
    }

    fn mat<T: FromStr>(&mut self, row: usize, col: usize) -> Vec<Vec<T>> {
        (0..row).map(|_| self.vec(col)).collect()
    }
}

fn main() {
    let cin = stdin();
    let cin = cin.lock();
    let mut sc = Scanner::new(cin);

    const MOD: usize = 1_000_000_007;
    let n: usize = sc.input();
    let k: usize = sc.input();

    let com = Combination::new(1_000_000, MOD);

    if k >= n {
        // 任意の配置が可能
        let ans = com.com(2 * n - 1, n); // nHn
        println!("{}", ans);
    } else if k == 1 {
        println!("{}", n * (n - 1) % MOD);
    } else {
        // 0人になる部屋がm(0..=k)個あるとすると、m人が残りのn - m部屋に散らばる。
        let mut ans = 0usize;

        for i in 0..=k {
            let room = n - i;
            ans = ans + com.com(n, i) * com.com(i + room - 1, i) % MOD;
        }
        println!("{}", ans);
    }
}

struct Combination {
    max_n: usize,
    modulo: usize,
    fac: Vec<usize>,
    finv: Vec<usize>,
    inv: Vec<usize>,
}

impl Combination {
    fn new(max_n: usize, modulo: usize) -> Self {
        let mut fac = vec![0; max_n];
        let mut finv = vec![0; max_n];
        let mut inv = vec![0; max_n];
        fac[0] = 1;
        fac[1] = 1;
        finv[0] = 1;
        finv[1] = 1;
        inv[1] = 1;
        for i in 2..max_n {
            fac[i] = fac[i - 1] * i % modulo;
            inv[i] = modulo - inv[modulo % i] * (modulo / i) % modulo;
            finv[i] = finv[i - 1] * inv[i] % modulo;
        }
        Self {
            max_n,
            modulo,
            fac,
            finv,
            inv,
        }
    }

    fn com(&self, n: usize, k: usize) -> usize {
        if n < k || n < 0 || k < 0 {
            0
        } else {
            self.fac[n] * (self.finv[k] * self.finv[n - k] % self.modulo) % self.modulo
        }
    }
}

use std::io;
use io_ext::Reader;
use parse::ParseAll;

fn main() {
    let stdin = io::stdin();
    let mut r = Reader::new(stdin.lock());
    let (n, k): (u64, u64) = r.read_line().split_whitespace().parse_all();
    let m = 1000000007;
    println!("{}", answer(n, k, m));
}

fn answer(n: u64, k: u64, m: u64) -> u64 {
    // if k == 0 {
    //     println!("1");
    //     return;
    // }

    let mut total = modulo::comb(n + n - 1, n - 1, m);
    if k >= n - 1 {
        return total;
    }

    // if k == 1 {
    //     total -= 1;
    // }

    for l in (k + 1)..n {
        let exists = n - l;
        let mut count = modulo::comb(n - exists + exists - 1, exists - 1, m);
        count = modulo::mul(count, modulo::comb(n, exists, m), m);
        total = modulo::sub(total, count, m);
    }
    total
