    }
    let (fac, invfac) = fact_init(2 * n + 1);
    if k >= n as i64 - 1 {
        puts!("{}\n", fac[2 * n - 1] * invfac[n - 1] * invfac[n]);
        return;
    }
    if k == 0 {
        puts!("1\n");
        return;
    }
    if k == 1 {
        puts!("{}\n", ModInt::new((n * (n - 1)) as i64));
        return;
    }
    let mut tot = ModInt::new(0);
    for i in 0..k as usize + 1 {
        let tmp = fac[n] * invfac[i] * invfac[n - i];
        let tmp = tmp * fac[n - 1] * invfac[i] * invfac[n - i - 1];
        tot += tmp;
    }
    puts!("{}\n", tot);
}

