fn solve() {
    input! {
        n: usize,
        k: usize
    }

    let mut ans = 0;

    // 0人の部屋の数は最大でkが無限ならn-1個、kを考慮するとmin(n-1,k)
    // 最小で0
    let max_zero = cmp::min(n - 1, k);

    let mut zero_pattern = combination_mod(n as u64, 0, LARGE_PRIME);
    let mut people_pattern: u64 = combination_mod((n - 1) as u64, 0, LARGE_PRIME);

    ans += zero_pattern * people_pattern;
    ans %= LARGE_PRIME;

    for i in 1..max_zero + 1 {
        zero_pattern *= inverse_mod(i as u64, LARGE_PRIME);
        zero_pattern %= LARGE_PRIME;
        zero_pattern *= (n as u64 - i as u64 + 1);
        zero_pattern %= LARGE_PRIME;

        people_pattern *= inverse_mod(i as u64, LARGE_PRIME);
        people_pattern %= LARGE_PRIME;
        people_pattern *= (n as u64 - i as u64);
        people_pattern %= LARGE_PRIME;

        ans += zero_pattern * people_pattern;
        ans %= LARGE_PRIME;
    }

    println!("{}", ans);
}

