    }

    let mut ans = 0;
    if k >= n-1 {
        ans = mod_comb((2 * n -1) as i64, (n-1) as i64, &memo);
    } else {
        for i in 0..k+1 {
            ans += mod_comb(n as i64, i as i64, &memo) * mod_comb((n - 1) as i64, i as i64, &memo) % MOD;
            ans %= MOD;
        }
    }
