    }

    let MOD = 1_000_000_007;

    let mut fact: Vec<i64> = vec![0; 202020];
    let mut factinv: Vec<i64> = vec![0; 202020];
    fact[0] = 1;
    factinv[0] = 1;
    for i in 1..202020 {
        fact[i] = fact[i - 1] * i as i64 % MOD;
        factinv[i] = pow(fact[i], MOD - 2, MOD);
    }

    let mut ans: i64 = 0;
    for i in 0..(min(k, n - 1) + 1) {
        ans +=
            ncr(n, i, &mut fact, &mut factinv, MOD) * ncr(n - 1, i, &mut fact, &mut factinv, MOD);
        ans %= MOD;
    }

    println!("{}", ans);
}
