fn binary_power(x: u64, n: u64) -> u64 {
    if n == 0 {
      return 1;
    }
    if n % 2 == 0 {
      return (binary_power(x, n / 2) % MOD).pow(2) % MOD;
    } else {
      return binary_power(x, n - 1) % MOD * x % MOD;
    }
}

fn inverse_mod(n: u64) -> u64 {
    binary_power(n, MOD-2)
} 

fn combination(n: u64, m: u64, fact: &Vec<u64>, finv: &Vec<u64>) -> u64 {
    fact[n as usize] * finv[m as usize] % MOD * finv[(n-m) as usize] % MOD
}

fn main() {
    let (n, k) = input_tuple();
    let mut fact: Vec<u64> = Vec::new();
    let mut finv: Vec<u64> = Vec::new();
    fact.push(1);
    fact.push(1);
    finv.push(inverse_mod(1));
    finv.push(inverse_mod(1));
    for i in 2..n*2 {
        fact.push(fact[i as usize - 1] * i % MOD);
        finv.push(inverse_mod(fact[i as usize]));
    }
    // println!("{:?}", fact);
    // println!("{:?}", finv);
    if k >= n {
        // 全組み合わせ
        println!("{}", combination(n * 2 - 1, n - 1, &fact, &finv));
        return;
    }
    let mut sum = 0;
    for i in (n-k)..(n+1) {
        sum += combination(n, i, &fact, &finv) * combination(i + n - i - 1, n - i, &fact, &finv);
        sum %= MOD;
    }
    println!("{}", sum);
}

