    }

    let mut ans = ModInt::new(0);
    let mut cmb = Combination::new(200005);
    for i in 0..min(N, K + 1) {
        let a = cmb.gen(N, i);
        let b = cmb.gen(N - 1, i);
        ans = ans + (a * b);
    }

    echo!(ans.to_string());
}

